	/**
	 * Internal entry point for user-mutation API methods. Runs the command
	 * via {@link com.goalplanner.command.CommandHistory#execute} so it lands on the undo stack.
	 */
	public boolean executeCommand(com.goalplanner.command.Command cmd)
	{
		boolean ok = commandHistory.execute(cmd);
		if (ok) fireIfNotInCompound();
		return ok;
	}

	/**
	 * Fire the UI refresh callback unless we're inside a compound
	 * transaction. All mutation paths should use this instead of calling
	 * onGoalsChanged.run() directly to avoid per-sub-command rebuilds.
	 */
	void fireIfNotInCompound()
	{
		if (!commandHistory.isInCompound()) pruneSelectionThenFireGoalsChanged();
	}

	/** Fire the UI refresh callback (goes through the debounce timer). */
	public void fireGoalsChanged()
	{
		pruneSelectionThenFireGoalsChanged();
	}

	/**
	 * Drop selected ids whose goal no longer exists, then fire the goals-changed
	 * refresh (and a selection-changed refresh if the prune removed anything).
	 * The seed/import gestures select the goals they create directly on
	 * {@link #selectedGoalIds}; undoing one removes those goals from the store
	 * but not the selection, leaving a stale "N selected" count of ids that no
	 * longer exist. Reconciling here keeps the selection honest after any
	 * goal-set change (undo, redo, removal).
	 */
	private void pruneSelectionThenFireGoalsChanged()
	{
		boolean selectionChanged = selectedGoalIds.removeIf(id -> goalStore.findGoalById(id) == null);
		onGoalsChanged.run();
		if (selectionChanged) onSelectionChanged.run();
	}

	@Override public boolean canUndo() { return commandHistory.canUndo(); }
	@Override public boolean canRedo() { return commandHistory.canRedo(); }
	@Override public String peekUndoDescription() { return commandHistory.peekUndoDescription(); }
	@Override public String peekRedoDescription() { return commandHistory.peekRedoDescription(); }

	@Override
	public boolean undo()
	{
		goalStore.suspendSave();
		boolean ok = commandHistory.undo();
		goalStore.resumeSave();
		if (ok) pruneSelectionThenFireGoalsChanged();
		return ok;
	}

	@Override
	public boolean redo()
	{
		goalStore.suspendSave();
		boolean ok = commandHistory.redo();
		goalStore.resumeSave();
		if (ok) pruneSelectionThenFireGoalsChanged();
		return ok;
	}

	@Override public void beginCompound(String description)
	{
		commandHistory.beginCompound(description);
		goalStore.suspendSave();
	}
	@Override public void endCompound()
	{
		commandHistory.endCompound();
		if (!commandHistory.isInCompound())
		{
			goalStore.resumeSave();
			pruneSelectionThenFireGoalsChanged();
		}
	}

	// =====================================================================
	// Selection (Phase 5) - ephemeral, not persisted
	// =====================================================================

	@Override
	public boolean replaceGoalSelection(Collection<String> goalIds)
	{
		log.debug("API.internal replaceGoalSelection(size={})", goalIds == null ? 0 : goalIds.size());
		Set<String> next = new LinkedHashSet<>();
		if (goalIds != null) next.addAll(goalIds);
		if (next.equals(selectedGoalIds)) return false;
		selectedGoalIds.clear();
		selectedGoalIds.addAll(next);
		if (!commandHistory.isInCompound()) onSelectionChanged.run();
		return true;
	}

	@Override
	public boolean addToGoalSelection(String goalId)
	{
		log.debug("API.internal addToGoalSelection(goalId={})", goalId);
		if (goalId == null) return false;
		if (!selectedGoalIds.add(goalId)) return false;
		if (!commandHistory.isInCompound()) onSelectionChanged.run();
		return true;
	}

	@Override
	public boolean removeFromGoalSelection(String goalId)
	{
		log.debug("API.internal removeFromGoalSelection(goalId={})", goalId);
		if (goalId == null) return false;
		if (!selectedGoalIds.remove(goalId)) return false;
		if (!commandHistory.isInCompound()) onSelectionChanged.run();
		return true;
	}

	@Override
	public boolean clearGoalSelection()
	{
		log.debug("API.internal clearGoalSelection()");
		if (selectedGoalIds.isEmpty()) return false;
		selectedGoalIds.clear();
		if (!commandHistory.isInCompound()) onSelectionChanged.run();
		return true;
	}

	/**
	 * Auto-deselect rule: any single-target mutation on a goal that isn't
	 * a member of the active multi-selection clears the selection first.
	 * Keeps the user's "active set" coherent - acting on something outside
	 * the current selection invalidates the prior selection. Called at the
	 * top of every public single-target mutation. Skipped for: bulk
	 * methods (Set<id>), two-id relation methods, recordGoalProgress
	 * (auto-tracked from game events, not user-initiated), and selection
	 * methods themselves.
	 */
	private void autoDeselectIfNotMember(String goalId)
	{
		if (goalId == null) return;
		if (selectedGoalIds.isEmpty()) return;
		if (selectedGoalIds.contains(goalId)) return;
		clearGoalSelection();
	}

	/**
	 * Post-creation selection rule: after an addXxxGoal call succeeds,
	 * the new goal becomes the active selection unless the creation flow
	 * already arranged for it (e.g. quest gesture-select includes the
	 * parent goal alongside seeded prerequisite goals). The contains()
	 * guard preserves those richer selections. Combined with the
	 * auto-deselect rule, every "add a goal" gesture ends with the new
	 * goal as part of the active selection - no stale prior selection
	 * lingers, no need for callers to manage selection by hand.
	 */
	private void selectAfterCreate(String newGoalId)
	{
		if (newGoalId == null) return;
		if (selectedGoalIds.contains(newGoalId)) return;
		replaceGoalSelection(Collections.singleton(newGoalId));
	}

	@Override
	public Set<String> getSelectedGoalIds()
	{
		return Collections.unmodifiableSet(selectedGoalIds);
	}

	@Override
	public int selectAllInSection(String sectionId)
	{
		log.debug("API.internal selectAllInSection(sectionId={})", sectionId);
		if (sectionId == null) return 0;
		int added = 0;
		for (Goal g : goalStore.getGoals())
		{
			if (sectionId.equals(g.getSectionId()))
			{
				if (selectedGoalIds.add(g.getId())) added++;
			}
		}
		if (added > 0 && !commandHistory.isInCompound()) onSelectionChanged.run();
		return added;
	}

	@Override
	public int deselectAllInSection(String sectionId)
	{
		log.debug("API.internal deselectAllInSection(sectionId={})", sectionId);
		if (sectionId == null) return 0;
		int removed = 0;
		for (Goal g : goalStore.getGoals())
		{
			if (sectionId.equals(g.getSectionId()))
			{
				if (selectedGoalIds.remove(g.getId())) removed++;
			}
		}
		if (removed > 0 && !commandHistory.isInCompound()) onSelectionChanged.run();
		return removed;
	}

	// =====================================================================
	// Internal helpers
	// =====================================================================

	Goal findGoal(String goalId)
	{
		return goalStore.findGoalById(goalId);
	}
}

package com.goalplanner.api;
import java.util.Collection;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Internal-only mutation API. NOT bound publicly via {@code Plugin.configure}.
 * Used by the goal tracker plugin's own UI (panel, right-click handlers) so
 * those code paths go through a single canonical mutation surface, but external
 * consumer plugins cannot reach these methods.
 *
 * <p>Operations exposed here are either:
 * <ul>
 *   <li><b>Layout-coupled</b> - section reorder, where ordering semantics are
 *       coupled to the panel layout (external plugins shouldn't shuffle the
 *       user's UI), or</li>
 *   <li><b>Destructive bulk ops</b> - clear-all, where exposure to external
 *       plugins is too dangerous</li>
 * </ul>
 */
public interface GoalPlannerInternalApi
{
	/**
	 * Move a goal within its current section. The new global index must be within
	 * the goal's current section's bounds (cross-section moves are not supported by
	 * this method - they require explicit section reassignment which is Phase 2).
	 *
	 * @return true if the move happened, false if newGlobalIndex is out of bounds
	 *         or the goal doesn't exist
	 */
	boolean moveGoal(String goalId, int newGlobalIndex);

	/**
	 * Move a goal to a specific position within a section. Combines
	 * {@link #moveGoalToSection} + an in-section reorder. Used by the
	 * Contextual Add Goal flow to drop newly-created goals at
	 * the user's chosen anchor point. Position is 0-based within the
	 * section's goal list (0 = top, size = bottom). Position values out
	 * of range are clamped.
	 *
	 * @return true if either the section OR the position changed
	 */
	boolean positionGoalInSection(String goalId, String sectionId, int positionInSection);

	// ---------------------------------------------------------------------
	// Undo / redo
	// ---------------------------------------------------------------------

	/** True if there is at least one user action available to undo. */
	boolean canUndo();

	/** True if there is at least one undone action available to redo. */
	boolean canRedo();

	/** Short user-facing description of the next undo target, or null if empty. */
	String peekUndoDescription();

	/** Short user-facing description of the next redo target, or null if empty. */
	String peekRedoDescription();

	/**
	 * Reverse the most recent user action. No-op if the undo stack is empty
	 * or the revert fails (the failed entry is silently dropped from history).
	 *
	 * @return true if an action was successfully reverted
	 */
	boolean undo();

	/**
	 * Re-apply the most recently undone user action.
	 *
	 * @return true if an action was successfully re-applied
	 */
	boolean redo();

	/**
	 * Begin a compound command. Subsequent user-mutation API calls collect
	 * into a single undo entry instead of pushing individually. Pair with
	 * {@link #endCompound()} to close. Used by multi-step flows like
	 * "create goal and immediately reposition" where the user expects one
	 * undo to fully reverse the operation.
	 */
	void beginCompound(String description);

	/** Close the current compound and push it as one undo entry. */
	void endCompound();

	/**
	 * Remove all goals from the store. Backs the Clear All UI button. Idempotent.
	 */
	void removeAllGoals();

	/**
	 * Set a section's collapsed state. Backs the section header chevron toggle.
	 *
	 * @return true if the state changed, false if no such section or already in
	 *         the requested state
	 */
	boolean setSectionCollapsed(String sectionId, boolean collapsed);

	/**
	 * Flip a section's collapsed state. Convenience over {@link #setSectionCollapsed}
	 * - callers don't need to know the current state.
	 *
	 * @return the new collapsed state (true = now collapsed, false = now expanded);
	 *         returns the unchanged state if the section doesn't exist
	 */
	boolean toggleSectionCollapsed(String sectionId);

	/** Toggle a goal's nested-prerequisite collapse state (persisted per profile).
	 *  Returns true if a goal was found and toggled. */
	boolean toggleGoalNestCollapsed(String goalId);

	/**
	 * Set a section's per-section override for the nested ("Indent dependencies")
	 * view: {@code null} = follow the global default, {@code TRUE} = always
	 * nested, {@code FALSE} = never nested. View preference only - does not alter
	 * goal data.
	 *
	 * @return true if the override changed, false if no such section or already in
	 *         the requested state
	 */
	boolean setSectionNestedOverride(String sectionId, Boolean value);

	/**
	 * Seed an existing quest goal's requirement tree into its own section, linked
	 * beneath it, as one undo. {@code includeMet=false} adds only unmet
	 * requirements; {@code true} adds the whole tree. No-op (returns 0) for
	 * non-quest goals or quests without requirement data.
	 *
	 * @return number of prerequisite goals seeded (created or reused), excluding the root
	 */
	int seedRequirementsForGoal(String goalId, boolean includeMet);

	// ---------------------------------------------------------------------
	// User-defined section CRUD (Phase 2)
	// ---------------------------------------------------------------------

	/**
	 * Create a user-defined section. Inserted at the bottom of the user-section
	 * band, just above the Completed built-in. Idempotent on case-insensitive
	 * name match: returns the existing section's id if a user section with the
	 * same name already exists.
	 *
	 * @param name display name; trimmed; must be non-empty after trim, max 40
	 *             characters, and not collide with built-in names
	 *             ("Incomplete"/"Completed", case-insensitive)
	 * @return section id (newly created or existing)
	 * @throws IllegalArgumentException if the name is invalid
	 */
	String createSection(String name);

	/**
	 * Rename a user-defined section. Built-in sections cannot be renamed.
	 *
	 * @return true if renamed, false on: not found, built-in, invalid name,
	 *         duplicate name, or no-op (same name)
	 */
	boolean renameSection(String sectionId, String newName);

	/**
	 * Delete a user-defined section AND the goals in it (a section owns its
	 * goals). Completed goals previously archived out of the section are kept
	 * as plain history. Built-in sections cannot be deleted. Undoable - one
	 * undo restores the section, its goals, and their dependency edges.
	 *
	 * @return true if deleted, false if not found or built-in
	 */
	boolean deleteSection(String sectionId);

	/**
	 * Delete a user-defined section, optionally sparing its goals.
	 *
	 * @param moveGoalsToDefault true relocates the section's goals to the
	 *        default Incomplete/Completed buckets instead of deleting them
	 *        (the pre-deletion behavior); false deletes them with the section
	 * @return true if deleted, false if not found or built-in
	 */
	boolean deleteSection(String sectionId, boolean moveGoalsToDefault);

	/**
	 * Reorder a user-defined section to a new position WITHIN the user-section
	 * band. {@code newUserIndex} is 0-based among user sections only; built-ins
	 * are not counted. Out-of-range values are clamped. Built-in sections
	 * cannot be reordered.
	 *
	 * @return true if reordered, false on: not found, built-in, or no-op
	 */
	boolean reorderSection(String sectionId, int newUserIndex);

	/**
	 * Move a goal to a different section. The goal is appended at the end of
	 * the destination section. If the goal is COMPLETE, the move is rejected
	 * unless the destination is the Completed section (reconcile would just
	 * pull it back otherwise).
	 *
	 * @return true if moved, false on: unknown goal id, unknown section id,
	 *         no-op (already in that section), or complete-goal-to-non-completed
	 */
	boolean moveGoalToSection(String goalId, String sectionId);

	/**
	 * Delete all user-defined sections in one shot. Goals belonging to deleted
	 * sections are reassigned to the end of Incomplete (reconcile then pulls
	 * any completed ones to Completed). Built-in sections are preserved.
	 * Idempotent - safe to call when no user sections exist.
	 *
	 * @return number of sections deleted
	 */
	int removeAllUserSections();

	/**
	 * Delete every user section that holds no goals. Built-in sections are
	 * preserved. Undoable as one step. Idempotent.
	 *
	 * @return number of empty sections deleted
	 */
	int removeEmptyUserSections();

	/**
	 * Complete wipe: delete every goal (any status, completed included) and every
	 * user section. Built-in sections remain (empty). Undoable as one step.
	 */
	void removeAllGoalsAndSections();

	// ---------------------------------------------------------------------
	// Color overrides (Phase 3)
	// ---------------------------------------------------------------------

	/**
	 * Set a section's color override. Works on user-defined and built-in
	 * sections alike. Pass -1 to clear the override and revert to the
	 * neutral default.
	 *
	 * @param colorRgb packed 0xRRGGBB, or -1 to clear the override
	 * @return true if the color changed, false on: not found or no-op
	 */
	boolean setSectionColor(String sectionId, int colorRgb);

	/**
	 * Set a user section's completed-archiving override: {@code null} inherits the
	 * global default, {@code TRUE} forces archive-to-Completed, {@code FALSE}
	 * forces keep-inline. When the effective decision becomes "archive," existing
	 * completed goals are swept out immediately. Built-ins can't be set. Undoable.
	 *
	 * @return true if the override changed, false on: not found, built-in, or no-op
	 */
	boolean setSectionAutoArchiveOverride(String sectionId, Boolean value);

	/** The global completed-archiving default (true = archive, false = keep inline). */
	boolean isAutoArchiveDefault();

	/** Set the global completed-archiving default (the plugin syncs this from config). */
	void setAutoArchiveDefault(boolean value);

	/**
	 * Set a goal's background color override. Works on all goal types -
	 * the override survives rebuilds because it's persisted on the goal model.
	 * Pass -1 to clear the override and revert to the GoalType default color.
	 *
	 * @param colorRgb packed 0xRRGGBB, or -1 to clear the override
	 * @return true if the color changed, false on: not found or no-op
	 */
	boolean setGoalColor(String goalId, int colorRgb);

	/**
	 * Toggle a goal's optional state.
	 *
	 * @return true if the state changed, false on: not found
	 */
	boolean setGoalOptional(String goalId, boolean optional);

	/**
	 * Set a tag's color override. Works on default and custom tags alike.
	 * Pass -1 to clear the override and revert to the TagCategory default.
	 *
	 * @param colorRgb packed 0xRRGGBB, or -1 to clear the override
	 * @return true if the color changed, false on: goal or tag not found,
	 *         or no-op
	 */
	boolean setTagColor(String goalId, String tagLabel, int colorRgb);

	// ---------------------------------------------------------------------
	// Tracker write path (Phase 4)
	// ---------------------------------------------------------------------

	/**
	 * Record a new progress value for a goal from a tracker loop.
	 *
	 * <p>Semantics:
	 * <ul>
	 *   <li>If {@code newValue} equals the goal's current value, no-op.</li>
	 *   <li>Otherwise sets {@code currentValue = newValue}.</li>
	 *   <li>If the new value meets target and the goal was NOT complete,
	 *       stamps {@code completedAt} and sets status to COMPLETE.</li>
	 *   <li>If the new value is below target and the goal WAS complete
	 *       (rare - happens on custom toggle or target change), clears
	 *       {@code completedAt} and reverts status to ACTIVE.</li>
	 * </ul>
	 *
	 * <p><b>Does NOT save, reconcile, or fire onGoalsChanged.</b> Trackers
	 * run in batches on each game tick; the plugin's GameTick handler
	 * performs a single {@code goalStore.save() + reconcileDerivedSections()
	 * + panel.rebuild()} once at the end of each tick if anything updated.
	 * Firing the callback per goal would defeat the over-querying cleanup
	 *
	 *
	 * @return true if the goal was mutated, false if no change
	 */
	boolean recordGoalProgress(String goalId, int newValue);

	// ---------------------------------------------------------------------
	// Selection (Phase 5) - ephemeral, not persisted
	// ---------------------------------------------------------------------

	/**
	 * Replace the current selection with exactly this set of goal ids.
	 * Used by single-click "select only this card" semantics. Pass an empty
	 * collection to clear selection.
	 *
	 * @return true if the selection actually changed
	 */
	boolean replaceGoalSelection(Collection<String> goalIds);

	/**
	 * Add a single goal id to the current selection (no-op if already in).
	 * Used by cmd/ctrl-click "add to multi-selection" semantics.
	 *
	 * @return true if the goal was newly added
	 */
	boolean addToGoalSelection(String goalId);

	/**
	 * Remove a single goal id from the current selection (no-op if not in).
	 * Used by cmd/ctrl-click on an already-selected card.
	 *
	 * @return true if the goal was removed
	 */
	boolean removeFromGoalSelection(String goalId);

	/**
	 * Clear the entire selection. Used by single-click on an already-selected
	 * card per the click semantics.
	 *
	 * @return true if the selection was non-empty before
	 */
	boolean clearGoalSelection();

	/** @return an unmodifiable snapshot of the currently-selected goal ids. */
	Set<String> getSelectedGoalIds();

	/**
	 * Add every goal currently in the given section to the selection. Existing
	 * selection is preserved (additive); use {@link #clearGoalSelection()}
	 * first if you want to replace it. Used by the section header right-click
	 * "Select All in Section" entry.
	 *
	 * @return the number of goals newly added to the selection
	 */
	int selectAllInSection(String sectionId);

	/**
	 * Remove every goal currently in the given section from the selection.
	 * Symmetric counterpart to {@link #selectAllInSection(String)}; lets the
	 * section header right-click toggle between select-all and deselect-all
	 * based on whether the section is fully selected.
	 *
	 * @return the number of goals removed from the selection
	 */
	int deselectAllInSection(String sectionId);

	/**
	 * Add a tag with an explicit category. The public {@link GoalPlannerApi#addTag}
	 * forces every external-API tag to {@link com.goalplanner.model.TagCategory#OTHER}
	 * because external consumers don't have a stable contract for the category enum.
	 * The plugin's own UI needs to preserve user-picked categories from the Add Tag
	 * dialog (BOSS/RAID/CLUE/etc), so it uses this internal variant.
	 *
	 * @param goalId target goal id
	 * @param label tag label; trimmed; must be non-empty
	 * @param categoryName one of the {@link com.goalplanner.model.TagCategory} enum names
	 * @return true if the tag was added, false on: not found, blank label,
	 *         unknown category
	 */
	boolean addTagWithCategory(String goalId, String label, String categoryName);

	// ---------------------------------------------------------------------
	// Tag entity CRUD
	// ---------------------------------------------------------------------

	/**
	 * Snapshot of every tag in the store. Includes both system and user tags
	 * across all categories. Used by the tag management UI.
	 */
	List<TagView> queryAllTags();

	/**
	 * Free-text search across goals. Case-insensitive partial substring match
	 * with OR semantics across these fields:
	 * <ul>
	 *   <li>Goal name and description</li>
	 *   <li>Any tag label on the goal</li>
	 *   <li>Tag category display names of any tag on the goal</li>
	 *   <li>{@link com.goalplanner.model.GoalType#getDisplayName()}</li>
	 *   <li>The title of the section the goal belongs to</li>
	 * </ul>
	 *
	 * <p>An empty or null query returns every goal in canonical order - this
	 * matches {@link #queryAllGoals()} and lets the UI use one render path.
	 *
	 * @param query free-text search; null/blank returns all goals
	 * @return filtered list of GoalViews in canonical order
	 */
	List<GoalView> searchGoals(String query);

	// ---------------------------------------------------------------------
	// Bulk multi-selection actions
	// ---------------------------------------------------------------------

	/**
	 * True if the goal has diverged from its defaults - either its tagIds set
	 * differs from defaultTagIds, or it has a custom color override. Used to
	 * gate the (single + bulk) Restore Defaults menu items.
	 */
	boolean isGoalOverridden(String goalId);

	/**
	 * Reset every eligible goal in the selection back to its defaults: tagIds
	 * = defaultTagIds, customColorRgb = -1. Ineligible goals (none of those
	 * are overridden) are skipped silently. Fires a single onGoalsChanged at
	 * the end.
	 *
	 * @return number of goals actually changed
	 */
	int bulkRestoreDefaults(Set<String> goalIds);

	/**
	 * Remove a tag from every selected goal where it is both present and
	 * removable. CUSTOM goals can drop any tag; non-CUSTOM goals can only
	 * drop tags NOT in defaultTagIds. Skips silently otherwise. Fires a
	 * single onGoalsChanged.
	 *
	 * @return number of goals from which the tag was removed
	 */
	int bulkRemoveTagFromGoals(Set<String> goalIds, String tagId);

	/**
	 * Remove a batch of goals as a single atomic command. Unlike calling
	 * {@link #removeGoal} in a compound loop, this captures every goal's
	 * original priority BEFORE any removals so undo restores them to their
	 * exact original positions (no collapsing at an intermediate index).
	 *
	 * @return number of goals actually removed
	 */
	int bulkRemoveGoals(Set<String> goalIds);

	/**
	 * Clear completion on every completed goal in the selection, as one undoable
	 * step. Recovery for goals completed against the wrong account: trackers
	 * re-derive from live state on the next drain.
	 *
	 * @return how many goals were reopened
	 */
	int bulkMarkIncomplete(Set<String> goalIds);

	/**
	 * Move a batch of goals into the same target section as a single atomic
	 * command. Captures every goal's original section + priority upfront so
	 * undo restores them to their exact original positions.
	 *
	 * @return number of goals actually moved
	 */
	int bulkMoveGoalsToSection(Set<String> goalIds, String targetSectionId);

	/**
	 * For a set of selected goals, return every removable tag (deduped) with
	 * a count of how many goals in the selection have it (and where it's
	 * removable). Sorted by count descending then by label ascending. Used
	 * to populate the bulk Remove Tag dropdown.
	 */
	List<TagRemovalOption> getRemovableTagsForSelection(Set<String> goalIds);

	/**
	 * Lightweight DTO returned by {@link #getRemovableTagsForSelection}.
	 */
	final class TagRemovalOption
	{
		public final String tagId;
		public final String label;
		public final int count;

		public TagRemovalOption(String tagId, String label, int count)
		{
			this.tagId = tagId;
			this.label = label;
			this.count = count;
		}
	}

	/**
	 * Create a user tag (idempotent on case-insensitive label+category match).
	 *
	 * @return tag id (newly created or existing)
	 * @throws IllegalArgumentException if label is invalid
	 */
	String createUserTag(String label, String categoryName);

	/**
	 * Rename a tag entity. Affects every goal that references it. System tags
	 * cannot be renamed (returns false).
	 *
	 * @return true if renamed, false on: not found, system tag, invalid name,
	 *         duplicate name, or no-op
	 */
	boolean renameTag(String tagId, String newLabel);

	/**
	 * Recolor a tag entity. Affects every goal that references it. System tags
	 * in the SKILLING category are fully read-only (skill icons); other system
	 * tags can be recolored. Pass -1 to clear the override.
	 *
	 * @return true if changed, false on: not found, read-only, or no-op
	 */
	boolean recolorTag(String tagId, int colorRgb);

	/**
	 * Delete a tag entity. Cascades to remove the reference from every goal.
	 * System tags cannot be deleted (returns false) - they're auto-attached
	 * by goal creation flows.
	 *
	 * @return true if deleted, false on: not found or system tag
	 */
	boolean deleteTag(String tagId);

	/**
	 * Set a per-category color override. Affects every tag in
	 * the given category. SKILLING is read-only (returns false) - skill icon
	 * tags ignore the category color anyway.
	 *
	 * @param categoryName one of the TagCategory enum names (excluding SKILLING)
	 * @param colorRgb packed 0xRRGGBB; -1 to clear the override and revert
	 *                 to the TagCategory default
	 * @return true if the color changed
	 */
	boolean setCategoryColor(String categoryName, int colorRgb);

	/** Equivalent to {@link #setCategoryColor(String, int)} with -1. */
	boolean resetCategoryColor(String categoryName);

	/** Current packed RGB for a category (override if set, else enum default). */
	int getCategoryColor(String categoryName);

	/** Enum default packed RGB for a category. */
	int getCategoryDefaultColor(String categoryName);

	/** True if the category has a user override set. */
	boolean isCategoryColorOverridden(String categoryName);

	/**
	 * Set an icon on a tag. Works on any tag including system tags.
	 * Pass null or empty to clear. The iconKey is resolved at render time:
	 * Skill enum names go to SkillIconManager; everything else looks up
	 * {@code /icons/<key>.png} from the bundled classpath resources. Icons
	 * entirely replace the colored pill rendering.
	 *
	 * @return true if the icon changed
	 */
	boolean setTagIcon(String tagId, String iconKey);

	/** Equivalent to {@link #setTagIcon(String, String)} with null. */
	boolean clearTagIcon(String tagId);

	// =====================================================================
	// Relations
	// Goal-to-goal "requires" edges forming a DAG. Relations cross sections
	// freely; topo sort is per-section (session 2).
	// =====================================================================

	/**
	 * Add an edge: {@code fromGoalId} requires {@code toGoalId}. Rejects
	 * self-loops, missing goals, duplicates, and any edge that would
	 * create a cycle. Undoable.
	 *
	 * @return true if the edge was added
	 */
	boolean addRequirement(String fromGoalId, String toGoalId);

	/**
	 * Remove an existing {@code fromGoalId → toGoalId} edge. Undoable.
	 *
	 * @return true if the edge existed and was removed
	 */
	boolean removeRequirement(String fromGoalId, String toGoalId);

	/**
	 * Get the goals that {@code goalId} requires (outgoing edges).
	 */
	List<String> getRequirements(String goalId);

	/**
	 * Get the goals that require {@code goalId} (incoming edges, derived
	 * by scanning all goals).
	 */
	List<String> getDependents(String goalId);

	/**
	 * Return value from {@link #findOrCreateRequirement}. {@code goalId} is
	 * the id of the goal that now satisfies the template (either an
	 * existing one that matched structurally, or a newly-created seed).
	 * {@code wasCreated} distinguishes the two cases so callers can build
	 * the correct undo inverse - link-only if false, delete-seed-plus-link
	 * if true.
	 */
	final class FindOrCreateResult
	{
		public final String goalId;
		public final boolean wasCreated;

		public FindOrCreateResult(String goalId, boolean wasCreated)
		{
			this.goalId = goalId;
			this.wasCreated = wasCreated;
		}
	}

	/**
	 * Return the goals in the given section sorted topologically by their
	 * relation DAG, with priority as a tiebreaker within each topological
	 * tier. Leaves (goals with no in-section requirements) come first;
	 * their dependents follow after.
	 *
	 * <p>Only edges where BOTH endpoints are in the section are considered
	 * for ordering - cross-section requirements are still visible in the
	 * hover tooltip but don't affect the sort. This matches the design
	 * decision from the relation Q&amp;A: topo sort is per-section.
	 *
	 * <p>If the graph contains a cycle (shouldn't happen post-scrub), the
	 * remaining goals are emitted in priority order as a fallback so the
	 * panel still renders.
	 *
	 * @param sectionId the section to sort
	 * @return ordered list of GoalViews, or empty list if section is unknown
	 */
	List<com.goalplanner.api.GoalView> queryGoalsTopologicallySorted(String sectionId);

	/**
	 * Topo-sort ALL sections in one pass. Returns a map of sectionId →
	 * sorted GoalView list.
	 */
	Map<String, List<com.goalplanner.api.GoalView>> queryAllGoalsTopologicallySorted();

	/**
	 * Resolve a requirement template to a concrete goal id, creating a
	 * seed goal if no existing goal satisfies the template structurally.
	 *
	 * <p>"Satisfies" uses the per-type rules in
	 * {@link com.goalplanner.persistence.GoalStore#findMatchingGoal}: skill
	 * and item goals use numeric "target ≥" comparison; quests/diaries/CAs/
	 * custom use case-insensitive name equality (CAs prefer caTaskId).
	 *
	 * <p>If a new seed is created, it's marked {@code autoSeeded=true} for
	 * the future absorption rule (session 2) and added to the store in the
	 * specified section (or Incomplete if {@code preferredSectionId} is
	 * null). Undoable - link-only on existing match, or compound (create +
	 * link) on no-match.
	 *
	 * @param template           a Goal object describing WHAT the caller needs;
	 *                           only identity + target fields are consulted
	 * @param preferredSectionId section for the seed goal if created, or null
	 *                           for Incomplete
	 * @return the resolved goal id + whether it was newly created, or null
	 *         if the template is invalid
	 */
	FindOrCreateResult findOrCreateRequirement(
		com.goalplanner.model.Goal template, String preferredSectionId);

	/**
	 * Resolve the pre-defined requirements for a quest against the current
	 * player state, returning goal templates for every unmet prereq plus
	 * bookkeeping for skipped/stubbed entries.
	 *
	 * <p>Thin wrapper around
	 * {@link com.goalplanner.data.QuestRequirementResolver#resolve(net.runelite.api.Quest,
	 * net.runelite.api.Client)}. Exists on the internal API so plugin-side
	 * consumers route quest-requirement queries through the same choke
	 * point as every other mutation - keeps the plugin code free of
	 * direct references to the data layer and lets future behavioral
	 * changes (caching, filtering, pluggable data source) live in one
	 * place.
	 *
	 * <p>Intended callers: the "Add Goal with Requirements" menu handler
	 * in {@code GoalPlannerPlugin}, and any future UI (right-click
	 * preview tooltip, settings page, etc.) that needs to reason about
	 * quest prereqs without building them into goals.
	 *
	 * @param quest the quest to look up; may be null (returns an empty
	 *              {@code Resolved})
	 * @return an always-non-null {@code Resolved} - empty when the quest
	 *         is null, not in the data table, or the player already meets
	 *         every requirement
	 */
	com.goalplanner.data.QuestRequirementResolver.Resolved resolveQuestRequirements(
		net.runelite.api.Quest quest);
}

package com.goalplanner.api;

import com.goalplanner.model.AccountMetric;
import com.goalplanner.model.Goal;
import com.goalplanner.model.GoalType;
import com.goalplanner.model.Section;
import com.goalplanner.model.Tag;
import com.goalplanner.model.TagCategory;

import java.util.ArrayList;
import java.util.List;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Experience;
import java.awt.Color;
import java.time.Instant;
import java.time.ZoneId;
import java.util.ArrayDeque;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;

/**
 * Encapsulates goal/section query methods extracted from {@link GoalPlannerApiImpl}.
 * Package-private - only {@link GoalPlannerApiImpl} instantiates and delegates to this.
 */
@Slf4j
class GoalQueryService
{
	/** Neutral default section header color (matches SectionHeaderRow BORDER_COLOR). */
	static final int SECTION_DEFAULT_COLOR_RGB = (60 << 16) | (60 << 8) | 60;

	private final GoalPlannerApiImpl api;

	GoalQueryService(GoalPlannerApiImpl api)
	{
		this.api = api;
	}

	/**
	 * Get a fresh GoalView for a single goal by ID. O(1) goal lookup
	 * + O(relations) view construction. Used for incremental card updates.
	 */
	GoalView queryGoalView(String goalId)
	{
		if (goalId == null) return null;
		Goal g = api.goalStore.findGoalById(goalId);
		if (g == null) return null;
		return toGoalView(g);
	}

	List<GoalView> queryAllGoals()
	{
		log.debug("API.public queryAllGoals()");
		// Ensure the flat list is in canonical (section.order, priority) order before snapshot.
		api.goalStore.normalizeOrder();
		List<Goal> source = api.goalStore.getGoals();
		List<GoalView> out = new ArrayList<>(source.size());
		for (Goal g : source)
		{
			out.add(toGoalView(g));
		}
		return out;
	}

	List<GoalView> searchGoals(String query)
	{
		log.debug("API.internal searchGoals(query={})", query);
		List<GoalView> all = queryAllGoals();
		if (query == null) return all;
		String needle = query.trim().toLowerCase();
		if (needle.isEmpty()) return all;

		// Phase 1: find direct matches.
		Set<String> matchedIds = new LinkedHashSet<>();
		Map<String, GoalView> viewById = new LinkedHashMap<>();
		for (GoalView gv : all)
		{
			viewById.put(gv.id, gv);
			if (matchesSearch(gv, needle)) matchedIds.add(gv.id);
		}

		// Phase 2: expand to include the full relation tree (both directions)
		// for every direct match. BFS from each matched goal.
		Set<String> expanded = new LinkedHashSet<>(matchedIds);
		ArrayDeque<String> queue = new ArrayDeque<>(matchedIds);
		while (!queue.isEmpty())
		{
			String id = queue.poll();
			Goal g = api.goalStore.findGoalById(id);
			if (g == null) continue;
			// Walk outgoing edges (requirements)
			if (g.getRequiredGoalIds() != null)
			{
				for (String reqId : g.getRequiredGoalIds())
				{
					if (expanded.add(reqId)) queue.add(reqId);
				}
			}
			// Walk incoming edges (dependents)
			for (String depId : api.goalStore.getDependents(id))
			{
				if (expanded.add(depId)) queue.add(depId);
			}
		}

		// Phase 3: return all expanded goals in canonical order.
		List<GoalView> out = new ArrayList<>();
		for (GoalView gv : all)
		{
			if (expanded.contains(gv.id)) out.add(gv);
		}
		return out;
	}

	/**
	 * Pure match check used by {@link #searchGoals(String)}. Pulled out for
	 * unit-testability and to keep the loop body trivial. The needle is
	 * pre-lowercased and pre-trimmed by the caller.
	 */
	private boolean matchesSearch(GoalView gv, String needle)
	{
		if (gv.name != null && gv.name.toLowerCase().contains(needle)) return true;
		if (gv.description != null && gv.description.toLowerCase().contains(needle)) return true;
		// GoalType display name (e.g. "Combat Achievement", "Skill")
		try
		{
			String typeDisplay = com.goalplanner.model.GoalType.valueOf(gv.type).getDisplayName();
			if (typeDisplay.toLowerCase().contains(needle)) return true;
		}
		catch (IllegalArgumentException ignored) {}
		// Section title
		if (gv.sectionId != null)
		{
			com.goalplanner.model.Section sec = api.goalStore.findSection(gv.sectionId);
			if (sec != null && sec.getName() != null
				&& sec.getName().toLowerCase().contains(needle)) return true;
		}
		// Tags: labels + category display names. defaultTags + customTags cover all.
		if (matchesAnyTag(gv.defaultTags, needle)) return true;
		if (matchesAnyTag(gv.customTags, needle)) return true;
		return false;
	}

	private boolean matchesAnyTag(List<TagView> tags, String needle)
	{
		if (tags == null) return false;
		for (TagView t : tags)
		{
			if (t.label != null && t.label.toLowerCase().contains(needle)) return true;
			if (t.category != null)
			{
				try
				{
					String catDisplay = TagCategory.valueOf(t.category).getDisplayName();
					if (catDisplay.toLowerCase().contains(needle)) return true;
				}
				catch (IllegalArgumentException ignored) {}
			}
		}
		return false;
	}

	List<SectionView> queryAllSections()
	{
		log.debug("API.public queryAllSections()");
		List<Section> source = new ArrayList<>(api.goalStore.getSections());
		source.sort(Comparator.comparingInt(Section::getOrder));
		List<SectionView> out = new ArrayList<>(source.size());
		for (Section s : source)
		{
			out.add(toSectionView(s));
		}
		return out;
	}

	GoalView toGoalView(Goal g)
	{
		GoalView v = new GoalView();
		v.id = g.getId();
		v.type = g.getType().name();
		v.name = g.getName();
		v.description = g.getDescription();
		// Period-relative for repeatable goals, identical to the raw values for
		// everything else. Mapped here rather than in the renderers so the card
		// text, the progress bar and the tooltip all agree without each one
		// having to know about repeatChunk.
		v.currentValue = g.getDisplayCurrent();
		v.targetValue = g.getDisplayTarget();
		v.repeatChunk = g.getRepeatChunk();
		v.repeatEvery = g.getRepeatEvery().name();
		if (g.isRepeating())
		{
			Instant end = api.nextBoundaryFn.apply(g.getRepeatEvery());
			v.resetsAt = end != null ? end.toEpochMilli() : 0L;
			// Time REMAINING, not the wall-clock deadline. "by 00:00" says when
			// the period ends but not whether you have ten minutes or ten hours,
			// which is the only part you act on.
			v.resetsAtLabel = end == null ? ""
				: com.goalplanner.util.RepeatSchedule.formatCountdown(
					end.toEpochMilli() - System.currentTimeMillis());
			// Rendered in the PLAYER'S zone, not the boundary's. The default
			// boundary is 00:00 UTC, so formatting it in the boundary zone shows
			// "00:00" to someone whose daily actually returns at 17:00 local - a
			// bare clock time reads as local, so that is just wrong. The instant
			// is identical either way; only the zone it is displayed in changes.
			v.resetsAtClock = com.goalplanner.util.RepeatSchedule.formatDeadline(
				end, ZoneId.systemDefault(), g.getRepeatEvery());
		}
		v.completedAt = g.getCompletedAt();
		v.sectionId = g.getSectionId();
		v.spriteId = g.getSpriteId();
		v.selected = api.selectedGoalIds.contains(g.getId());
		v.optional = g.isOptional();
		v.nestCollapsed = g.isNestCollapsed();
		v.blockedRequirements = api.blockedRequirements(g.getId());

		// Background color: type default + optional user override. DTO carries both
		// so consumers can show "reset to default" affordances with the right preview.
		Color typeC = g.getType().getColor();
		int typeRgb = (typeC.getRed() << 16) | (typeC.getGreen() << 8) | typeC.getBlue();
		v.defaultBackgroundColorRgb = typeRgb;
		if (g.getCustomColorRgb() >= 0)
		{
			v.backgroundColorRgb = g.getCustomColorRgb();
			v.backgroundColorOverridden = true;
		}
		else
		{
			v.backgroundColorRgb = typeRgb;
			v.backgroundColorOverridden = false;
		}

		// Tag splitting: defaultTagIds is the snapshot from creation; the rest of
		// tagIds are user-added. Each id is dereferenced via the tag store.
		List<String> defaultIds = g.getDefaultTagIds() != null ? g.getDefaultTagIds() : Collections.emptyList();
		List<String> allIds = g.getTagIds() != null ? g.getTagIds() : Collections.emptyList();

		v.defaultTags = new ArrayList<>();
		for (String id : defaultIds)
		{
			Tag tag = api.goalStore.findTag(id);
			if (tag != null) v.defaultTags.add(api.tagService.toTagView(tag));
		}

		v.customTags = new ArrayList<>();
		for (String id : allIds)
		{
			if (defaultIds.contains(id)) continue;
			Tag tag = api.goalStore.findTag(id);
			if (tag != null) v.customTags.add(api.tagService.toTagView(tag));
		}

		// Resolve relations for the card hover tooltip.
		// Skill-chain edges (same skill, different level) are internal
		// bookkeeping and excluded from the display lists.
		v.requiresNames = new ArrayList<>();
		if (g.getRequiredGoalIds() != null)
		{
			for (String reqId : g.getRequiredGoalIds())
			{
				Goal req = api.findGoal(reqId);
				if (req == null || req.getName() == null) continue;
				if (isSkillChainEdge(g, req)) continue;
				v.requiresNames.add(toRelationView(req));
			}
		}
		// OR-prereqs: displayed with "(or)" suffix so the user sees the
		// difference between AND and OR edges.
		v.orRequiresNames = new ArrayList<>();
		if (g.getOrRequiredGoalIds() != null)
		{
			for (String reqId : g.getOrRequiredGoalIds())
			{
				Goal req = api.findGoal(reqId);
				if (req == null || req.getName() == null) continue;
				v.orRequiresNames.add(toRelationView(req));
			}
		}
		v.requiredByNames = new ArrayList<>();
		v.orRequiredByNames = new ArrayList<>();
		for (Goal other : api.goalStore.getGoals())
		{
			if (other.getId().equals(g.getId())) continue;
			if (other.getRequiredGoalIds() != null
				&& other.getRequiredGoalIds().contains(g.getId())
				&& other.getName() != null)
			{
				if (isSkillChainEdge(other, g)) continue;
				v.requiredByNames.add(toRelationView(other));
			}
			// OR-edges: the parent shows as "Required by" (it requires
			// this goal), and the sibling OR-prereqs show as "Also
			// Completed By" (completing any one of them satisfies the
			// parent).
			if (other.getOrRequiredGoalIds() != null
				&& other.getOrRequiredGoalIds().contains(g.getId())
				&& other.getName() != null)
			{
				// Parent goes into requiredByNames
				v.requiredByNames.add(toRelationView(other));
				// Sibling OR-prereqs go into orRequiredByNames
				for (String siblingId : other.getOrRequiredGoalIds())
				{
					if (siblingId.equals(g.getId())) continue;
					Goal sibling = api.findGoal(siblingId);
					if (sibling != null && sibling.getName() != null)
					{
						v.orRequiredByNames.add(toRelationView(sibling));
					}
				}
			}
		}

		// Type-specific attributes
		v.attributes = new HashMap<>();
		switch (g.getType())
		{
			case SKILL:
				if (g.getSkillName() != null) v.attributes.put("skillName", g.getSkillName());
				break;
			case QUEST:
				if (g.getQuestName() != null) v.attributes.put("questName", g.getQuestName());
				if (g.getTooltip() != null) v.attributes.put("tooltip", g.getTooltip());
				break;
			case DIARY:
				v.attributes.put("area", g.getName());
				if (g.getDescription() != null && g.getDescription().endsWith(" Achievement Diary"))
				{
					String tier = g.getDescription().substring(
						0, g.getDescription().length() - " Achievement Diary".length()).toUpperCase();
					v.attributes.put("tier", tier);
				}
				if (g.getVarbitId() > 0) v.attributes.put("varbitId", g.getVarbitId());
				if (g.getTooltip() != null) v.attributes.put("tooltip", g.getTooltip());
				break;
			case ITEM_GRIND:
				if (g.getItemId() > 0) v.attributes.put("itemId", g.getItemId());
				break;
			case COMBAT_ACHIEVEMENT:
				if (g.getCaTaskId() >= 0) v.attributes.put("caTaskId", g.getCaTaskId());
				if (g.getDescription() != null && g.getDescription().endsWith(" Combat Achievement"))
				{
					String tier = g.getDescription().substring(
						0, g.getDescription().length() - " Combat Achievement".length()).toUpperCase();
					v.attributes.put("tier", tier);
				}
				// Monster name lives in the BOSS/RAID tag, not its own field
				for (String id : allIds)
				{
					Tag tag = api.goalStore.findTag(id);
					if (tag != null && (tag.getCategory() == TagCategory.BOSS || tag.getCategory() == TagCategory.RAID))
					{
						v.attributes.put("monster", tag.getLabel());
						break;
					}
				}
				if (g.getTooltip() != null) v.attributes.put("tooltip", g.getTooltip());
				break;
			case ACCOUNT:
				if (g.getAccountMetric() != null)
				{
					v.attributes.put("accountMetric", g.getAccountMetric());
					try
					{
						AccountMetric m = AccountMetric.valueOf(g.getAccountMetric());
						String resolvedIconKey = m.resolveIconKeyForTarget(g.getTargetValue());
						if (resolvedIconKey != null)
						{
							v.attributes.put("iconKey", resolvedIconKey);
						}
						// Icons derive from the METRIC, not the creation path:
						// goals that arrived without a persisted sprite (share
						// imports, API callers) render the same icon a
						// plugin-created goal would.
						if (v.spriteId == 0)
						{
							v.spriteId = m.resolveSpriteForTarget(g.getTargetValue());
						}
					}
					catch (IllegalArgumentException ignored) {}
				}
				break;
			case BOSS:
				if (g.getBossName() != null) v.attributes.put("bossName", g.getBossName());
				if (g.getItemId() > 0) v.attributes.put("itemId", g.getItemId());
				break;
			case CUSTOM:
				if (g.getItemId() > 0) v.attributes.put("itemId", g.getItemId());
				break;
			default:
				break;
		}

		return v;
	}

	/**
	 * True when both goals are implicit chain links that should not
	 * clutter the tooltip: same-skill edges (40 Prayer → 60 Prayer)
	 * or same-metric account edges (96 Combat → 126 Combat).
	 */
	static boolean isSkillChainEdge(Goal a, Goal b)
	{
		if (a.getType() == GoalType.SKILL && b.getType() == GoalType.SKILL)
		{
			return a.getSkillName() != null && a.getSkillName().equals(b.getSkillName());
		}
		if (a.getType() == GoalType.ACCOUNT && b.getType() == GoalType.ACCOUNT)
		{
			return a.getAccountMetric() != null && a.getAccountMetric().equals(b.getAccountMetric());
		}
		return false;
	}

	static GoalView.RelationView toRelationView(Goal g)
	{
		String skillName = null;
		int targetLevel = 0;
		if (g.getType() == GoalType.SKILL && g.getSkillName() != null)
		{
			skillName = g.getSkillName();
			targetLevel = Experience.getLevelForXp(g.getTargetValue());
		}
		return new GoalView.RelationView(g.getName(), skillName, targetLevel, g.isOptional());
	}

	static SectionView toSectionView(Section s)
	{
		SectionView v = new SectionView();
		v.id = s.getId();
		v.name = s.getName();
		v.order = s.getOrder();
		v.collapsed = s.isCollapsed();
		v.builtIn = s.isBuiltIn();
		v.kind = s.getBuiltInKind() != null ? s.getBuiltInKind().name() : null;
		v.autoArchiveOverride = s.getAutoArchiveOverride();
		v.nestedOverride = s.getNestedOverride();
		v.defaultColorRgb = SECTION_DEFAULT_COLOR_RGB;
		if (s.getColorRgb() >= 0)
		{
			v.colorRgb = s.getColorRgb();
			v.colorOverridden = true;
		}
		else
		{
			v.colorRgb = SECTION_DEFAULT_COLOR_RGB;
			v.colorOverridden = false;
		}
		return v;
	}

	List<GoalView> queryGoalsTopologicallySorted(String sectionId)
	{
		log.debug("API.internal queryGoalsTopologicallySorted(sectionId={})", sectionId);
		if (sectionId == null) return new ArrayList<>();
		List<Goal> sectionGoals = new ArrayList<>();
		for (Goal g : api.goalStore.getGoals())
		{
			if (sectionId.equals(g.getSectionId())) sectionGoals.add(g);
		}
		return topoSortSection(sectionGoals, sectionId);
	}

	/**
	 * Topo-sort ALL sections in one pass. Returns a map of sectionId →
	 * sorted GoalView list. Avoids repeated scans of the goals list.
	 */
	Map<String, List<GoalView>> queryAllGoalsTopologicallySorted()
	{
		// Group goals by section in one scan.
		Map<String, List<Goal>> goalsBySection = new LinkedHashMap<>();
		for (Goal g : api.goalStore.getGoals())
		{
			if (g.getSectionId() != null)
			{
				goalsBySection.computeIfAbsent(g.getSectionId(), k -> new ArrayList<>())
					.add(g);
			}
		}
		Map<String, List<GoalView>> result = new LinkedHashMap<>();
		for (Map.Entry<String, List<Goal>> entry : goalsBySection.entrySet())
		{
			result.put(entry.getKey(), topoSortSection(entry.getValue(), entry.getKey()));
		}
		return result;
	}

	/** Core topo-sort for a single section's goals. */
	private List<GoalView> topoSortSection(List<Goal> sectionGoals, String sectionId)
	{
		List<GoalView> out = new ArrayList<>();
		if (sectionGoals.isEmpty()) return out;

		// Completed section: most-recently-completed at the top. Skip the topo
		// machinery - every goal's prereqs are by definition already done, so
		// DAG ordering carries no information; chronological order is what users
		// actually want here. Tie-break by priority for stable rendering when
		// two goals were completed in the same millisecond (e.g. cascading
		// auto-completion in one VarbitChanged handler).
		Section section = api.goalStore.findSection(sectionId);
		if (section != null && section.getBuiltInKind() == Section.BuiltInKind.COMPLETED)
		{
			List<Goal> byDate = new ArrayList<>(sectionGoals);
			byDate.sort(Comparator
				.comparingLong(Goal::getCompletedAt).reversed()
				.thenComparingInt(Goal::getPriority));
			for (Goal g : byDate) out.add(toGoalView(g));
			return out;
		}

		sectionGoals.sort(Comparator.comparingInt(Goal::getPriority));

		Set<String> goalIds = new HashSet<>();
		for (Goal g : sectionGoals) goalIds.add(g.getId());

		// Stable local-repair sort.
		List<Goal> ordered = new ArrayList<>(sectionGoals);
		int maxIter = sectionGoals.size() * sectionGoals.size() + 1;
		int iter = 0;
		boolean converged = false;
		while (!converged && iter++ < maxIter)
		{
			converged = true;
			Map<String, Integer> pos = new HashMap<>();
			for (int i = 0; i < ordered.size(); i++) pos.put(ordered.get(i).getId(), i);

			for (int i = 0; i < ordered.size(); i++)
			{
				Goal g = ordered.get(i);
				// Collect both AND and OR edges for topo ordering
				List<String> allReqs = new ArrayList<>();
				if (g.getRequiredGoalIds() != null) allReqs.addAll(g.getRequiredGoalIds());
				if (g.getOrRequiredGoalIds() != null) allReqs.addAll(g.getOrRequiredGoalIds());
				if (allReqs.isEmpty()) continue;
				int maxReqPos = -1;
				for (String reqId : allReqs)
				{
					if (!goalIds.contains(reqId)) continue;
					Integer p = pos.get(reqId);
					if (p != null && p > maxReqPos) maxReqPos = p;
				}
				if (maxReqPos > i)
				{
					ordered.remove(i);
					ordered.add(maxReqPos, g);
					converged = false;
					break;
				}
			}
		}
		if (!converged)
		{
			log.warn("topoSortSection: local-repair hit iteration bound "
				+ "in section {} - graph may contain a cycle", sectionId);
		}

		// Post-sort: group OR-prereqs immediately before their parent.
		// For each goal with orRequiredGoalIds, extract those prereqs
		// from wherever they are in the list and re-insert them as a
		// contiguous block right before the parent.
		List<Goal> grouped = new ArrayList<>(ordered);
		for (int i = 0; i < grouped.size(); i++)
		{
			Goal parent = grouped.get(i);
			if (parent.getOrRequiredGoalIds() == null || parent.getOrRequiredGoalIds().isEmpty())
			{
				continue;
			}
			Set<String> orIds = new HashSet<>(parent.getOrRequiredGoalIds());
			// Collect OR-prereqs that are in this section
			List<Goal> orGroup = new ArrayList<>();
			for (int j = grouped.size() - 1; j >= 0; j--)
			{
				if (j == i) continue;
				if (orIds.contains(grouped.get(j).getId()))
				{
					orGroup.add(0, grouped.remove(j));
					if (j < i) i--; // adjust parent index
				}
			}
			if (!orGroup.isEmpty())
			{
				// Insert OR-prereqs right before the parent
				grouped.addAll(i, orGroup);
				i += orGroup.size(); // skip past the inserted group
			}
		}

		// User sections keep their completed goals inline (only the built-in
		// Incomplete/Completed default relocates on completion), so sink the
		// completed ones to the bottom - incomplete requirements first,
		// ticked-off below, like a checklist. Stable partition preserves the
		// topo/OR order within each group. (Built-in Completed is handled above.)
		if (section != null && !section.isBuiltIn())
		{
			List<Goal> incomplete = new ArrayList<>();
			List<Goal> done = new ArrayList<>();
			for (Goal g : grouped)
			{
				(g.isComplete() ? done : incomplete).add(g);
			}
			incomplete.addAll(done);
			grouped = incomplete;
		}

		for (Goal g : grouped)
		{
			out.add(toGoalView(g));
		}
		return out;
	}
}

package com.goalplanner.api;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Collections;

/**
 * Public DTO for a goal - the canonical "render-friendly snapshot" returned by
 * {@link GoalPlannerApi#queryAllGoals()}.
 *
 * <p>Core fields are type-agnostic. Type-specific extras live in {@link #attributes}
 * with documented per-type schemas:
 *
 * <ul>
 *   <li><b>SKILL</b>: {@code skillName} (String, net.runelite.api.Skill enum name)</li>
 *   <li><b>QUEST</b>: {@code questName} (String, net.runelite.api.Quest enum name),
 *       {@code tooltip} (String, optional)</li>
 *   <li><b>DIARY</b>: {@code area} (String), {@code tier} (String - "EASY"/"MEDIUM"/"HARD"/"ELITE"),
 *       {@code varbitId} (Integer), {@code tooltip} (String, optional)</li>
 *   <li><b>ITEM_GRIND</b>: {@code itemId} (Integer)</li>
 *   <li><b>COMBAT_ACHIEVEMENT</b>: {@code caTaskId} (Integer), {@code tier} (String - "EASY".."GRANDMASTER"),
 *       {@code monster} (String), {@code tooltip} (String, optional)</li>
 *   <li><b>CUSTOM</b>: no extras</li>
 * </ul>
 *
 * <p>Optional keys are <em>absent</em> from the map, not null. Consumers can use
 * {@link Map#containsKey(Object)} or {@link Map#getOrDefault(Object, Object)}.
 */
public class GoalView
{
	public String id;
	/** Goal type as a string: SKILL, QUEST, DIARY, ITEM_GRIND, COMBAT_ACHIEVEMENT, CUSTOM. */
	public String type;
	public String name;
	public String description;
	public int currentValue;
	public int targetValue;

	/** Non-zero for a repeatable goal: the gain expected each period. Renderers
	 *  must not do absolute-value math (level lookups, thresholds) on
	 *  currentValue/targetValue when this is set - those are period-relative. */
	public int repeatChunk;

	/** Wall-clock form of the same boundary ("00:00", "Wed 00:00", "1 Sep").
	 *  Completed repeatables show this instead of the countdown: you are not
	 *  working on it, so "when does it come back" beats "how long is left". */
	public String resetsAtClock;

	/** RepeatPeriod name, or "NONE". Non-NONE means this goal rolls over. */
	public String repeatEvery = "NONE";

	/** Epoch millis when the current period ends, or 0 if it never does. */
	public long resetsAt;

	/** Compact "by ..." stamp for the card, e.g. "00:00", "Wed 00:00", "1 Sep". */
	public String resetsAtLabel = "";
	/** 0 if not complete; nonzero millis-since-epoch when the goal was marked complete. */
	public long completedAt;
	public String sectionId;

	// ----- display hints -----

	/** RuneLite sprite id for the icon, or 0 if no sprite. */
	public int spriteId;
	/** Packed RGB color (0xRRGGBB) for the card background tint - override or default. */
	public int backgroundColorRgb;
	/** The type-default background color, even when an override is set. Lets
	 *  the UI preview what "reset to default" would revert to. */
	public int defaultBackgroundColorRgb;
	/** True when {@link #backgroundColorRgb} is a user override (not the type default). */
	public boolean backgroundColorOverridden;
	/** Ephemeral UI selection state - true when this card is currently selected
	 *  in the panel. Lost on plugin restart. */
	public boolean selected;
	/** True when the user has marked this goal as optional. */
	public boolean optional;
	/** True when this goal's nested prerequisite subtree is collapsed in the
	 *  nested view (persisted per profile). */
	public boolean nestCollapsed;
	/** Labels of DIRECT prerequisites the player hasn't met and that aren't in
	 *  the plan - drives the "blocked" badge. Empty = no badge. */
	public List<String> blockedRequirements = Collections.emptyList();
	/** Auto-generated tags from goal creation (boss/raid/tier/etc).
	 *  Cannot be removed by the user; restored by Restore Defaults. */
	public List<TagView> defaultTags;
	/** User-added tags layered on top of {@link #defaultTags}.
	 *  These are the only tags removable via the Remove Tag UI. */
	public List<TagView> customTags;

	// ----- relations -----

	/** Goals this one requires (outgoing edges), resolved at queryAllGoals
	 *  time. Empty list if none. Used by the card hover tooltip to show
	 *  the "Requires:" line. Implicit skill-chain edges (same skill,
	 *  different level) are excluded - those are internal bookkeeping. */
	public List<RelationView> requiresNames;
	/** OR-prerequisite edges (any one completing satisfies the link).
	 *  Empty if no OR-prereqs. Used by the card tooltip. */
	public List<RelationView> orRequiresNames;
	/** Goals that require this one via AND-edges (incoming), resolved at
	 *  queryAllGoals time. Used by the card hover tooltip. */
	public List<RelationView> requiredByNames;
	/** Goals that or-require this one (incoming OR-edges). Shows as
	 *  "Or-required by:" in the tooltip. */
	public List<RelationView> orRequiredByNames;

	/**
	 * Lightweight DTO for a single relation edge, carrying enough metadata
	 * to render skill icons in tooltips (quest→skill links) or fall back
	 * to the goal name for non-skill relations.
	 */
	public static class RelationView
	{
		/** Display name of the related goal (fallback text). */
		public String name;
		/** Non-null for SKILL goals - the Skill enum name. Enables compact
		 *  icon+level rendering in tooltips. */
		public String skillName;
		/** Target level for SKILL goals (used for compact display). */
		public int targetLevel;
		/** True when this relation target is an optional/recommended goal. */
		public boolean optional;

		public RelationView(String name, String skillName, int targetLevel, boolean optional)
		{
			this.name = name;
			this.skillName = skillName;
			this.targetLevel = targetLevel;
			this.optional = optional;
		}
	}
	// ----- type-specific extras -----

	public Map<String, Object> attributes = new HashMap<>();
}

package com.goalplanner.api;

import com.goalplanner.model.Goal;

import java.util.ArrayList;
import java.util.List;
import lombok.extern.slf4j.Slf4j;

/**
 * Encapsulates relation (requirement/dependency) methods extracted from {@link GoalPlannerApiImpl}.
 * Package-private - only {@link GoalPlannerApiImpl} instantiates and delegates to this.
 */
@Slf4j
class RelationService
{
	private final GoalPlannerApiImpl api;

	RelationService(GoalPlannerApiImpl api)
	{
		this.api = api;
	}

	boolean addRequirement(String fromGoalId, String toGoalId)
	{
		log.debug("API.internal addRequirement(from={}, to={})", fromGoalId, toGoalId);
		if (fromGoalId == null || toGoalId == null) return false;
		if (fromGoalId.equals(toGoalId)) return false;
		Goal from = api.findGoal(fromGoalId);
		Goal to = api.findGoal(toGoalId);
		if (from == null || to == null) return false;
		// Idempotent precheck so we don't push a no-op command on the stack.
		if (from.getRequiredGoalIds() != null && from.getRequiredGoalIds().contains(toGoalId))
		{
			return false;
		}
		if (api.goalStore.wouldCreateCycle(fromGoalId, toGoalId)) return false;

		final String fromName = from.getName();
		final String toName = to.getName();
		return api.executeCommand(new com.goalplanner.command.Command()
		{
			@Override public boolean apply()
			{
				return api.goalStore.addRequirement(fromGoalId, toGoalId);
			}
			@Override public boolean revert()
			{
				return api.goalStore.removeRequirement(fromGoalId, toGoalId);
			}
			@Override public String getDescription()
			{
				return "Link: " + fromName + " requires " + toName;
			}
		});
	}

	boolean removeRequirement(String fromGoalId, String toGoalId)
	{
		log.debug("API.internal removeRequirement(from={}, to={})", fromGoalId, toGoalId);
		if (fromGoalId == null || toGoalId == null) return false;
		Goal from = api.findGoal(fromGoalId);
		Goal to = api.findGoal(toGoalId);
		if (from == null || to == null) return false;
		// Idempotent precheck.
		if (from.getRequiredGoalIds() == null
			|| !from.getRequiredGoalIds().contains(toGoalId))
		{
			return false;
		}

		final String fromName = from.getName();
		final String toName = to.getName();
		return api.executeCommand(new com.goalplanner.command.Command()
		{
			@Override public boolean apply()
			{
				return api.goalStore.removeRequirement(fromGoalId, toGoalId);
			}
			@Override public boolean revert()
			{
				return api.goalStore.addRequirement(fromGoalId, toGoalId);
			}
			@Override public String getDescription()
			{
				return "Unlink: " + fromName + " requires " + toName;
			}
		});
	}

	boolean addOrRequirement(String fromGoalId, String toGoalId)
	{
		log.debug("API.internal addOrRequirement(from={}, to={})", fromGoalId, toGoalId);
		if (fromGoalId == null || toGoalId == null) return false;
		if (fromGoalId.equals(toGoalId)) return false;
		Goal from = api.findGoal(fromGoalId);
		Goal to = api.findGoal(toGoalId);
		if (from == null || to == null) return false;
		if (from.getOrRequiredGoalIds() != null && from.getOrRequiredGoalIds().contains(toGoalId))
		{
			return false;
		}
		if (api.goalStore.wouldCreateCycle(fromGoalId, toGoalId)) return false;

		final String fromName = from.getName();
		final String toName = to.getName();
		return api.executeCommand(new com.goalplanner.command.Command()
		{
			@Override public boolean apply()
			{
				return api.goalStore.addOrRequirement(fromGoalId, toGoalId);
			}
			@Override public boolean revert()
			{
				return api.goalStore.removeOrRequirement(fromGoalId, toGoalId);
			}
			@Override public String getDescription()
			{
				return "Link (OR): " + fromName + " or-requires " + toName;
			}
		});
	}

	List<String> getRequirements(String goalId)
	{
		Goal g = api.findGoal(goalId);
		if (g == null || g.getRequiredGoalIds() == null) return new ArrayList<>();
		return new ArrayList<>(g.getRequiredGoalIds());
	}

	List<String> getDependents(String goalId)
	{
		return api.goalStore.getDependents(goalId);
	}

	GoalPlannerInternalApi.FindOrCreateResult findOrCreateRequirement(Goal template, String preferredSectionId)
	{
		log.debug("API.internal findOrCreateRequirement(type={})",
			template == null ? null : template.getType());
		if (template == null || template.getType() == null) return null;

		// Structural match first - reuse an existing goal if one satisfies.
		Goal existing = api.goalStore.findMatchingGoal(template);
		if (existing != null)
		{
			return new GoalPlannerInternalApi.FindOrCreateResult(existing.getId(), false);
		}

		// No match - create a seed goal from the template, marked autoSeeded.
		Goal seed = Goal.builder()
			.type(template.getType())
			.name(template.getName())
			.description(template.getDescription())
			.targetValue(template.getTargetValue())
			.currentValue(template.getCurrentValue())
			.skillName(template.getSkillName())
			.questName(template.getQuestName())
			.varbitId(template.getVarbitId())
			.itemId(template.getItemId())
			.spriteId(template.getSpriteId())
			.caTaskId(template.getCaTaskId())
			.sectionId(preferredSectionId)
			.autoSeeded(true)
			.build();

		final String seedId = seed.getId();
		final Goal capturedSeed = seed;
		final String displayName = seed.getName() != null ? seed.getName() : "goal";
		boolean ok = api.executeCommand(new com.goalplanner.command.Command()
		{
			@Override public boolean apply()
			{
				if (api.findGoal(seedId) != null) return false;
				api.goalStore.addGoal(capturedSeed);
				return true;
			}
			@Override public boolean revert()
			{
				api.goalStore.removeGoal(seedId);
				return true;
			}
			@Override public String getDescription()
			{
				return "Seed requirement: " + displayName;
			}
		});
		return ok ? new GoalPlannerInternalApi.FindOrCreateResult(seedId, true) : null;
	}

	com.goalplanner.data.QuestRequirementResolver.Resolved resolveQuestRequirements(
		net.runelite.api.Quest quest)
	{
		log.debug("API.internal resolveQuestRequirements(quest={})", quest);
		if (quest == null || api.client == null)
		{
			return new com.goalplanner.data.QuestRequirementResolver.Resolved(
				List.of(), 0, 0, 0, 0);
		}
		return com.goalplanner.data.QuestRequirementResolver.resolve(quest, api.client);
	}
}

package com.goalplanner.api;

import com.goalplanner.model.Goal;
import com.goalplanner.model.Section;

import java.util.ArrayList;
import java.util.List;
import lombok.extern.slf4j.Slf4j;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Objects;
import java.util.Set;

/**
 * Encapsulates section-management methods extracted from {@link GoalPlannerApiImpl}.
 * Package-private - only {@link GoalPlannerApiImpl} instantiates and delegates to this.
 */
@Slf4j
class SectionService
{
	private final GoalPlannerApiImpl api;

	SectionService(GoalPlannerApiImpl api)
	{
		this.api = api;
	}

	String createSection(String name)
	{
		log.debug("API.internal createSection(name={})", name);
		Section created = api.goalStore.createUserSection(name);
		if (created == null) return null;
		final String sectionId = created.getId();
		final String sectionName = created.getName();
		// Already created. Wrap in a Command for the undo path.
		api.executeCommand(new com.goalplanner.command.Command()
		{
			private boolean firstApply = true;
			@Override public boolean apply()
			{
				if (firstApply) { firstApply = false; return true; }
				if (api.goalStore.findSection(sectionId) != null) return false;
				api.goalStore.recreateUserSection(sectionId, sectionName);
				return true;
			}
			@Override public boolean revert()
			{
				// Undoing "create" must not destroy goals the user has since
				// put in the section - relocate them, then drop the (empty)
				// section. deleteUserSection itself deletes a section's goals.
				api.goalStore.evacuateSectionToIncomplete(sectionId);
				return api.goalStore.deleteUserSection(sectionId);
			}
			@Override public String getDescription() { return "Add section: " + sectionName; }
		});
		return sectionId;
	}

	boolean renameSection(String sectionId, String newName)
	{
		log.debug("API.internal renameSection(sectionId={}, newName={})", sectionId, newName);
		Section sec = api.goalStore.findSection(sectionId);
		if (sec == null) return false;
		final String prevName = sec.getName();
		final String resolved = newName != null ? newName.trim() : "";
		if (resolved.isEmpty() || resolved.equals(prevName)) return false;
		return api.executeCommand(new com.goalplanner.command.Command()
		{
			@Override public boolean apply() { return api.goalStore.renameUserSection(sectionId, resolved); }
			@Override public boolean revert() { return api.goalStore.renameUserSection(sectionId, prevName); }
			@Override public String getDescription() { return "Rename section: " + prevName + " -> " + resolved; }
		});
	}

	boolean deleteSection(String sectionId, boolean moveGoalsToDefault)
	{
		log.debug("API.internal deleteSection(sectionId={}, moveGoalsToDefault={})",
			sectionId, moveGoalsToDefault);
		Section sec = api.goalStore.findSection(sectionId);
		if (sec == null || sec.isBuiltIn()) return false;
		final String name = sec.getName();
		final int order = sec.getOrder();
		final int colorRgb = sec.getColorRgb();
		final Boolean nestedOverride = sec.getNestedOverride();
		final Boolean autoArchiveOverride = sec.getAutoArchiveOverride();
		// Completed goals archived OUT of this section live in Completed and
		// survive either path, but the delete clears their home memory -
		// snapshot the ids so undo can restore the link.
		final List<String> archivedOutIds = new ArrayList<>();
		for (Goal g : api.goalStore.getGoals())
		{
			if (sectionId.equals(g.getArchivedFromSectionId())) archivedOutIds.add(g.getId());
		}

		if (moveGoalsToDefault)
		{
			// Opt-in sparing path: relocate the goals to the default buckets,
			// then drop the (now empty) section.
			final List<String> displacedGoalIds = new ArrayList<>();
			for (Goal g : api.goalStore.getGoals())
			{
				if (sectionId.equals(g.getSectionId())) displacedGoalIds.add(g.getId());
			}
			return api.executeCommand(new com.goalplanner.command.Command()
			{
				@Override public boolean apply()
				{
					api.goalStore.evacuateSectionToIncomplete(sectionId);
					return api.goalStore.deleteUserSection(sectionId);
				}
				@Override public boolean revert()
				{
					recreateSection(sectionId, name, order, colorRgb, nestedOverride, autoArchiveOverride);
					// moveGoalToSection pins completed goals inline in the
					// destination - matching their pre-delete placement.
					for (String gid : displacedGoalIds)
					{
						api.goalStore.moveGoalToSection(gid, sectionId);
					}
					restoreArchivedHomes(archivedOutIds, sectionId);
					api.goalStore.normalizeOrder();
					return true;
				}
				@Override public String getDescription() { return "Delete section (keep goals): " + name; }
			});
		}

		// Deleting a section deletes its goals, so revert must RESTORE them:
		// the goal objects (ascending flat index, so positions come back), a
		// copy of each one's outgoing edge lists (deletion scrubs doomed ids
		// out of doomed peers' lists, mutating the very objects we keep), and
		// the incoming edges from surviving goals (scrubbed by removeGoal).
		final List<Goal> doomedGoals = new ArrayList<>();
		final Map<String, Integer> originalIndex = new HashMap<>();
		final Map<String, List<String>> savedRequires = new HashMap<>();
		final Map<String, List<String>> savedOrRequires = new HashMap<>();
		List<Goal> all = api.goalStore.getGoals();
		for (int i = 0; i < all.size(); i++)
		{
			Goal g = all.get(i);
			if (sectionId.equals(g.getSectionId()))
			{
				doomedGoals.add(g);
				originalIndex.put(g.getId(), i);
				savedRequires.put(g.getId(), new ArrayList<>(g.getRequiredGoalIds()));
				savedOrRequires.put(g.getId(), new ArrayList<>(g.getOrRequiredGoalIds()));
			}
		}
		final Set<String> doomedIds = originalIndex.keySet();
		final List<String[]> survivorAndEdges = new ArrayList<>();
		final List<String[]> survivorOrEdges = new ArrayList<>();
		for (Goal g : all)
		{
			if (doomedIds.contains(g.getId())) continue;
			for (String rid : g.getRequiredGoalIds())
			{
				if (doomedIds.contains(rid)) survivorAndEdges.add(new String[]{g.getId(), rid});
			}
			for (String rid : g.getOrRequiredGoalIds())
			{
				if (doomedIds.contains(rid)) survivorOrEdges.add(new String[]{g.getId(), rid});
			}
		}
		return api.executeCommand(new com.goalplanner.command.Command()
		{
			@Override public boolean apply()
			{
				if (!api.goalStore.deleteUserSection(sectionId)) return false;
				api.selectedGoalIds.removeAll(doomedIds);
				return true;
			}
			@Override public boolean revert()
			{
				recreateSection(sectionId, name, order, colorRgb, nestedOverride, autoArchiveOverride);
				// Ascending original index so each goal lands back in place.
				for (Goal g : doomedGoals)
				{
					g.setSectionId(sectionId);
					api.goalStore.insertGoalAt(g, originalIndex.get(g.getId()));
				}
				// Re-add edges the delete scrubbed: doomed→doomed outgoing
				// (from the pre-delete copies) and survivor→doomed incoming.
				for (Goal g : doomedGoals)
				{
					for (String rid : savedRequires.get(g.getId()))
					{
						if (!g.getRequiredGoalIds().contains(rid)) api.goalStore.addRequirement(g.getId(), rid);
					}
					for (String rid : savedOrRequires.get(g.getId()))
					{
						if (!g.getOrRequiredGoalIds().contains(rid)) api.goalStore.addOrRequirement(g.getId(), rid);
					}
				}
				for (String[] e : survivorAndEdges) api.goalStore.addRequirement(e[0], e[1]);
				for (String[] e : survivorOrEdges) api.goalStore.addOrRequirement(e[0], e[1]);
				restoreArchivedHomes(archivedOutIds, sectionId);
				api.goalStore.normalizeOrder();
				return true;
			}
			@Override public String getDescription() { return "Delete section: " + name; }
		});
	}

	/** Recreate a deleted user section with its remembered display properties. */
	private void recreateSection(String sectionId, String name, int order, int colorRgb,
		Boolean nestedOverride, Boolean autoArchiveOverride)
	{
		api.goalStore.recreateUserSection(sectionId, name);
		Section restored = api.goalStore.findSection(sectionId);
		if (restored != null)
		{
			restored.setOrder(order);
			restored.setColorRgb(colorRgb);
			restored.setNestedOverride(nestedOverride);
			restored.setAutoArchiveOverride(autoArchiveOverride);
		}
	}

	/** Re-link completed goals in Completed back to their deleted-then-restored home section. */
	private void restoreArchivedHomes(List<String> goalIds, String sectionId)
	{
		for (String gid : goalIds)
		{
			Goal g = api.findGoal(gid);
			if (g != null && g.getArchivedFromSectionId() == null)
			{
				g.setArchivedFromSectionId(sectionId);
				api.goalStore.updateGoal(g);
			}
		}
	}

	boolean reorderSection(String sectionId, int newUserIndex)
	{
		log.debug("API.internal reorderSection(sectionId={}, newUserIndex={})", sectionId, newUserIndex);
		Section sec = api.goalStore.findSection(sectionId);
		if (sec == null) return false;
		// Compute current user index
		int prevUserIndex = -1;
		int idx = 0;
		for (Section s : api.goalStore.getSections())
		{
			// Test the flag, not the order: built-ins are no longer all
			// high-ordered (Repeatable is pinned to the top with MIN_VALUE), so
			// an order comparison would count it as a user section here.
			if (!s.isBuiltIn())
			{
				if (s.getId().equals(sectionId)) { prevUserIndex = idx; break; }
				idx++;
			}
		}
		final int snapshotPrev = prevUserIndex;
		final String name = sec.getName();
		return api.executeCommand(new com.goalplanner.command.Command()
		{
			@Override public boolean apply() { return api.goalStore.reorderUserSection(sectionId, newUserIndex); }
			@Override public boolean revert()
			{
				if (snapshotPrev < 0) return false;
				return api.goalStore.reorderUserSection(sectionId, snapshotPrev);
			}
			@Override public String getDescription() { return "Reorder section: " + name; }
		});
	}

	boolean moveGoalToSection(String goalId, String sectionId)
	{
		log.debug("API.internal moveGoalToSection(goalId={}, sectionId={})", goalId, sectionId);
		Goal current = api.findGoal(goalId);
		if (current == null) return false;
		if (sectionId == null) return false;
		if (sectionId.equals(current.getSectionId())) return false;
		final String prevSectionId = current.getSectionId();
		final int prevPriority = current.getPriority();
		final String name = current.getName();
		return api.executeCommand(new com.goalplanner.command.Command()
		{
			@Override public boolean apply() { return moveGoalToSectionInternal(goalId, sectionId); }
			@Override public boolean revert()
			{
				Goal g = api.findGoal(goalId);
				if (g == null) return false;
				api.goalStore.moveGoalToSection(goalId, prevSectionId);
				g.setPriority(prevPriority);
				api.goalStore.normalizeOrder();
				return true;
			}
			@Override public String getDescription() { return "Move: " + name; }
		});
	}

	boolean moveGoalToSectionInternal(String goalId, String sectionId)
	{
		boolean moved = api.goalStore.moveGoalToSection(goalId, sectionId);
		if (moved)
		{
			Goal g = api.findGoal(goalId);
			if (g != null && g.getType() == com.goalplanner.model.GoalType.SKILL)
			{
				api.reorderingService.enforceSkillOrderingInSection(sectionId);
			}
		}
		return moved;
	}

	/**
	 * Delete every user section that currently holds no goals. Built-in sections
	 * are never touched. Empty sections have nothing to re-home, so each is a
	 * plain {@link #deleteSection} - wrapped in one compound so the whole sweep
	 * is a single undo. Returns the number deleted.
	 */
	int removeEmptyUserSections()
	{
		log.debug("API.internal removeEmptyUserSections()");
		final Set<String> nonEmpty = new HashSet<>();
		for (Goal g : api.goalStore.getGoals())
		{
			if (g.getSectionId() != null) nonEmpty.add(g.getSectionId());
		}
		final List<String> empties = new ArrayList<>();
		for (Section s : api.goalStore.getSections())
		{
			if (s.getBuiltInKind() == null && !nonEmpty.contains(s.getId()))
			{
				empties.add(s.getId());
			}
		}
		if (empties.isEmpty()) return 0;
		api.beginCompound("Delete empty sections");
		try
		{
			for (String id : empties) deleteSection(id, false);
		}
		finally
		{
			api.endCompound();
		}
		return empties.size();
	}

	int removeAllUserSections()
	{
		log.debug("API.internal removeAllUserSections()");
		final List<Section> sectionSnapshots = new ArrayList<>();
		final Set<String> userSectionIds = new HashSet<>();
		for (Section s : api.goalStore.getSections())
		{
			if (s.getBuiltInKind() == null)
			{
				sectionSnapshots.add(s);
				userSectionIds.add(s.getId());
			}
		}
		// Single pass over goals to group by section.
		final Map<String, List<String>> goalsBySection = new HashMap<>();
		for (Goal g : api.goalStore.getGoals())
		{
			if (userSectionIds.contains(g.getSectionId()))
			{
				goalsBySection.computeIfAbsent(g.getSectionId(), k -> new ArrayList<>())
					.add(g.getId());
			}
		}
		if (sectionSnapshots.isEmpty()) return 0;
		boolean ok = api.executeCommand(new com.goalplanner.command.Command()
		{
			@Override public boolean apply() { return api.goalStore.removeAllUserSections() > 0; }
			@Override public boolean revert()
			{
				for (Section s : sectionSnapshots)
				{
					api.goalStore.recreateUserSection(s.getId(), s.getName());
					Section restored = api.goalStore.findSection(s.getId());
					if (restored != null)
					{
						restored.setOrder(s.getOrder());
						restored.setColorRgb(s.getColorRgb());
					}
					for (String gid : goalsBySection.get(s.getId()))
					{
						api.goalStore.moveGoalToSection(gid, s.getId());
					}
				}
				api.goalStore.normalizeOrder();
				return true;
			}
			@Override public String getDescription() { return "Remove all sections (" + sectionSnapshots.size() + ")"; }
		});
		return ok ? sectionSnapshots.size() : 0;
	}

	boolean setSectionCollapsed(String sectionId, boolean collapsed)
	{
		log.debug("API.internal setSectionCollapsed(sectionId={}, collapsed={})", sectionId, collapsed);
		if (sectionId == null) return false;
		for (Section s : api.goalStore.getSections())
		{
			if (sectionId.equals(s.getId()))
			{
				if (s.isCollapsed() == collapsed) return false;
				s.setCollapsed(collapsed);
				api.goalStore.save();
				api.fireIfNotInCompound();
				return true;
			}
		}
		return false;
	}

	boolean toggleSectionCollapsed(String sectionId)
	{
		log.debug("API.internal toggleSectionCollapsed(sectionId={})", sectionId);
		if (sectionId == null) return false;
		for (Section s : api.goalStore.getSections())
		{
			if (sectionId.equals(s.getId()))
			{
				boolean next = !s.isCollapsed();
				s.setCollapsed(next);
				api.goalStore.save();
				api.fireIfNotInCompound();
				return next;
			}
		}
		return false;
	}

	boolean setSectionNestedOverride(String sectionId, Boolean value)
	{
		log.debug("API.internal setSectionNestedOverride(sectionId={}, value={})", sectionId, value);
		if (sectionId == null) return false;
		Section s = api.goalStore.findSection(sectionId);
		if (s == null || Objects.equals(s.getNestedOverride(), value)) return false;
		s.setNestedOverride(value);
		api.goalStore.save();
		api.fireIfNotInCompound();
		return true;
	}

	boolean setSectionColor(String sectionId, int colorRgb)
	{
		log.debug("API.internal setSectionColor(sectionId={}, colorRgb={})", sectionId, colorRgb);
		Section section = api.goalStore.findSection(sectionId);
		if (section == null) return false;
		int normalized = colorRgb < 0 ? -1 : (colorRgb & 0xFFFFFF);
		if (section.getColorRgb() == normalized) return false;
		final int prevColor = section.getColorRgb();
		final String name = section.getName();
		return api.executeCommand(new com.goalplanner.command.Command()
		{
			@Override public boolean apply()
			{
				Section s = api.goalStore.findSection(sectionId);
				if (s == null) return false;
				s.setColorRgb(normalized);
				api.goalStore.save();
				return true;
			}
			@Override public boolean revert()
			{
				Section s = api.goalStore.findSection(sectionId);
				if (s == null) return false;
				s.setColorRgb(prevColor);
				api.goalStore.save();
				return true;
			}
			@Override public String getDescription() { return "Recolor section: " + name; }
		});
	}

	boolean setSectionAutoArchiveOverride(String sectionId, Boolean value)
	{
		log.debug("API.internal setSectionAutoArchiveOverride(sectionId={}, value={})", sectionId, value);
		Section section = api.goalStore.findSection(sectionId);
		if (section == null || section.isBuiltIn()) return false;
		if (Objects.equals(section.getAutoArchiveOverride(), value)) return false;
		final Boolean prev = section.getAutoArchiveOverride();
		final String name = section.getName();
		return api.executeCommand(new com.goalplanner.command.Command()
		{
			@Override public boolean apply()
			{
				Section s = api.goalStore.findSection(sectionId);
				if (s == null) return false;
				s.setAutoArchiveOverride(value);
				// Reconcile both directions: archive existing completed goals out
				// if this is now auto-archive, OR pull previously-archived goals
				// back inline if it's now keep-inline. (Like auto-completion, the
				// relocation itself isn't separately undoable - revert restores
				// just the flag.)
				api.goalStore.reconcileDerivedSections();
				api.goalStore.save();
				return true;
			}
			@Override public boolean revert()
			{
				Section s = api.goalStore.findSection(sectionId);
				if (s == null) return false;
				s.setAutoArchiveOverride(prev);
				api.goalStore.save();
				return true;
			}
			@Override public String getDescription()
			{
				String state = value == null ? "default" : (value ? "auto-archive" : "keep inline");
				return "Completed goals (" + state + "): " + name;
			}
		});
	}

	boolean setGoalColor(String goalId, int colorRgb)
	{
		log.debug("API.internal setGoalColor(goalId={}, colorRgb={})", goalId, colorRgb);
		Goal g = api.findGoal(goalId);
		if (g == null) return false;
		int normalized = colorRgb < 0 ? -1 : (colorRgb & 0xFFFFFF);
		if (g.getCustomColorRgb() == normalized) return false;
		final int previousColor = g.getCustomColorRgb();
		final String name = g.getName();
		return api.executeCommand(new com.goalplanner.command.Command()
		{
			@Override public boolean apply() { return setGoalColorInternal(goalId, normalized); }
			@Override public boolean revert() { return setGoalColorInternal(goalId, previousColor); }
			@Override public String getDescription() { return "Recolor: " + name; }
		});
	}

	boolean setGoalColorInternal(String goalId, int normalized)
	{
		Goal g = api.findGoal(goalId);
		if (g == null) return false;
		g.setCustomColorRgb(normalized);
		api.goalStore.save();
		return true;
	}
}

package com.goalplanner.api;

/**
 * Public DTO for a section. No internal model classes referenced.
 */
public class SectionView
{
	public String id;
	public String name;
	public int order;
	public boolean collapsed;
	public boolean builtIn;
	/**
	 * Built-in section role: "INCOMPLETE", "COMPLETED", or {@code null} for user-defined sections.
	 */
	public String kind;
	/**
	 * Current section color - user override if set, else the neutral default.
	 * Packed as 0xRRGGBB.
	 */
	public int colorRgb;
	/**
	 * The neutral default color, even when an override is set. Lets the UI
	 * preview what "reset to default" would revert to.
	 */
	public int defaultColorRgb;
	/** True when {@link #colorRgb} is a user override. */
	public boolean colorOverridden;
	/**
	 * Per-section completed-archiving override: {@code null} = inherit the global
	 * default; {@code TRUE} = always archive to Completed; {@code FALSE} = always
	 * keep inline. Always null for built-ins.
	 */
	public Boolean autoArchiveOverride;
	/**
	 * Per-section override for the nested ("Indent dependencies") view:
	 * {@code null} = follow the global default, {@code TRUE} = always nested,
	 * {@code FALSE} = never nested. View preference only - no effect on goal data.
	 */
	public Boolean nestedOverride;
}

package com.goalplanner.api;

import com.goalplanner.model.Goal;
import com.goalplanner.model.Section;
import com.goalplanner.share.SectionShareDto;
import com.goalplanner.share.ShareBundle;
import com.goalplanner.share.ShareMapper;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Builds a {@link ShareBundle} from goals currently in the store (export side).
 * Thin wrapper over {@code ShareMapper} that gathers the goals for a section (or
 * an explicit id set) and supplies the tag lookup. The encode-to-string,
 * clipboard steps live in the UI/plugin layer.
 */
class ShareExportService
{
	private final GoalPlannerApiImpl api;

	ShareExportService(GoalPlannerApiImpl api)
	{
		this.api = api;
	}

	/** Bundle of every goal in the given section, or null if no such section. */
	ShareBundle exportSection(String sectionId, String sharedBy)
	{
		Section section = api.goalStore.findSection(sectionId);
		if (section == null)
		{
			return null;
		}
		List<Goal> goals = new ArrayList<>();
		for (Goal g : api.goalStore.getGoals())
		{
			if (g != null && sectionId.equals(g.getSectionId()))
			{
				goals.add(g);
			}
		}
		return ShareMapper.toBundle(
			ShareBundle.Kind.SECTION, section.getName(), section.getColorRgb(),
			goals, api.goalStore::findTag, sharedBy);
	}

	/**
	 * Multi-section (v2) bundle of EVERY user section that has goals, in
	 * display order. Built-ins (the default plan) are not included. Returns
	 * null when there is no user section with goals.
	 */
	ShareBundle exportAllUserSections(String sharedBy)
	{
		List<SectionShareDto> sections = new ArrayList<>();
		List<List<Goal>> sectionGoals = new ArrayList<>();
		for (Section section : api.goalStore.getSections())
		{
			if (section == null || section.isBuiltIn())
			{
				continue;
			}
			List<Goal> goals = new ArrayList<>();
			for (Goal g : api.goalStore.getGoals())
			{
				if (g != null && section.getId().equals(g.getSectionId()))
				{
					goals.add(g);
				}
			}
			if (goals.isEmpty())
			{
				continue;
			}
			sections.add(ShareMapper.toSectionDto(
				section.getName(), section.getColorRgb(), false, section.getNestedOverride(),
				goals, api.goalStore::findTag));
			sectionGoals.add(goals);
		}
		if (sections.isEmpty())
		{
			return null;
		}
		ShareBundle bundle = ShareMapper.toMultiBundle(sections, sharedBy);
		bundle.setCrossEdges(ShareMapper.crossEdges(sectionGoals));
		return bundle;
	}

	/**
	 * Bundle of the given goals (in store order), or null if none resolve.
	 * The selection's SOURCE SECTIONS are preserved: goals from each user
	 * section export as that section (name + colour), goals from the default
	 * plan as a {@code targetDefault} entry. A selection entirely within the
	 * default plan stays a legacy loose-goals bundle, and one entirely within
	 * a single user section stays a legacy section bundle - both on the v1
	 * wire so older plugin builds keep importing them; anything spanning
	 * sections needs the v2 wire.
	 */
	ShareBundle exportGoals(List<String> goalIds, String sharedBy)
	{
		if (goalIds == null || goalIds.isEmpty())
		{
			return null;
		}
		Set<String> wanted = new HashSet<>(goalIds);
		// Group the selection by source section, in store (display) order;
		// the two built-ins collapse into one "default plan" group.
		List<Goal> defaultGroup = new ArrayList<>();
		Map<String, List<Goal>> bySection = new LinkedHashMap<>();
		for (Goal g : api.goalStore.getGoals())
		{
			if (g == null || !wanted.contains(g.getId()))
			{
				continue;
			}
			Section sec = api.goalStore.findSection(g.getSectionId());
			if (sec == null || sec.isBuiltIn())
			{
				defaultGroup.add(g);
			}
			else
			{
				bySection.computeIfAbsent(sec.getId(), k -> new ArrayList<>()).add(g);
			}
		}
		if (defaultGroup.isEmpty() && bySection.isEmpty())
		{
			return null;
		}
		if (bySection.isEmpty())
		{
			// Entirely from the default plan → legacy loose goals (v1 wire).
			return ShareMapper.toBundle(
				ShareBundle.Kind.GOALS, null, -1, defaultGroup, api.goalStore::findTag, sharedBy);
		}
		if (defaultGroup.isEmpty() && bySection.size() == 1)
		{
			// Entirely from one user section → legacy section bundle (v1 wire).
			String sid = bySection.keySet().iterator().next();
			Section sec = api.goalStore.findSection(sid);
			return ShareMapper.toBundle(
				ShareBundle.Kind.SECTION, sec.getName(), sec.getColorRgb(),
				bySection.get(sid), api.goalStore::findTag, sharedBy);
		}
		// Spans sections → multi-section (v2) bundle preserving each source.
		List<SectionShareDto> sections = new ArrayList<>();
		List<List<Goal>> groups = new ArrayList<>();
		for (Map.Entry<String, List<Goal>> e : bySection.entrySet())
		{
			Section sec = api.goalStore.findSection(e.getKey());
			sections.add(ShareMapper.toSectionDto(
				sec.getName(), sec.getColorRgb(), false, sec.getNestedOverride(),
				e.getValue(), api.goalStore::findTag));
			groups.add(e.getValue());
		}
		if (!defaultGroup.isEmpty())
		{
			sections.add(ShareMapper.toSectionDto(
				null, -1, true, null, defaultGroup, api.goalStore::findTag));
			groups.add(defaultGroup);
		}
		ShareBundle bundle = ShareMapper.toMultiBundle(sections, sharedBy);
		bundle.setCrossEdges(ShareMapper.crossEdges(groups));
		return bundle;
	}
}

package com.goalplanner.api;

import com.goalplanner.model.Goal;
import com.goalplanner.model.GoalType;
import com.goalplanner.model.Section;
import com.goalplanner.model.Tag;
import com.goalplanner.model.TagCategory;
import com.goalplanner.persistence.GoalStore;
import com.goalplanner.share.GoalShareDto;
import com.goalplanner.share.SectionShareDto;
import com.goalplanner.share.ShareBundle;
import com.goalplanner.share.TagShareDto;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;

/**
 * Applies a decoded {@link ShareBundle} (from a pasted share code, or
 * pasted as a share code) into the store: a new user section, fresh goals with
 * find-or-created tags and remapped relations, all in one undo-compound so a
 * single {@code undo()} reverses the whole import.
 *
 * <p>Imports land in their own user section: because user sections keep their
 * completed goals inline, the recipient sees the whole shared set as a checklist
 * against their own account - requirements they already meet show ticked off,
 * the rest show progress.
 *
 * <p>Inverse of {@code com.goalplanner.share.ShareMapper}. Because the payload
 * originates on another player's client it is treated as <b>untrusted</b>:
 * unknown {@link GoalType}/{@link TagCategory} values are skipped and string
 * fields are length-clamped, so a malformed or hostile bundle can't corrupt the
 * store.
 */
@Slf4j
class ShareImportService
{
	/** Defensive caps on attacker-controllable strings. */
	private static final int MAX_NAME = 120;
	private static final int MAX_TEXT = 600;

	private final GoalPlannerApiImpl api;

	ShareImportService(GoalPlannerApiImpl api)
	{
		this.api = api;
	}

	/**
	 * Import a bundle into a new user section.
	 *
	 * @return the id of the section the goals were imported into, or
	 *         {@code null} if there was nothing importable.
	 */
	String importBundle(ShareBundle bundle)
	{
		if (bundle == null)
		{
			return null;
		}
		// One canonical section list for the whole import - effectiveSections()
		// builds fresh wrapper instances per call for legacy bundles, and the
		// cross-edge pass needs stable bundle-position indices.
		final List<SectionShareDto> bundleSections = bundle.effectiveSections();
		final List<SectionShareDto> sections = new ArrayList<>();
		for (SectionShareDto s : bundleSections)
		{
			if (s != null && s.getGoals() != null && !s.getGoals().isEmpty())
			{
				sections.add(s);
			}
		}
		if (sections.isEmpty())
		{
			return null;
		}
		final String description = sections.size() == 1
			? "Import shared goals: " + displayName(sections.get(0))
			: "Import shared goals: " + sections.size() + " sections";

		// Wrap the whole import as ONE undoable command across every section.
		// Imported goals always start INCOMPLETE - buildGoal copies only
		// definition fields, never the sharer's progress/completion.
		final List<String> createdGoalIds = new ArrayList<>();
		final List<String> createdSectionIds = new ArrayList<>();
		// Relations added during import, tracked explicitly: default-target
		// sections REUSE existing goals, and a relation added between two reused
		// goals would otherwise survive an undo.
		final List<String[]> addedRequires = new ArrayList<>();
		final List<String[]> addedOrRequires = new ArrayList<>();
		final String[] landedSectionId = {null};

		// Batch persistence across the whole import: apply/revert/redo each flush
		// once instead of writing per goal+section. A large import's undo/redo
		// was issuing one config write per entity, the source of the lag.
		api.executeCommand(new com.goalplanner.command.SaveBatchingCommand(
			api.goalStore::suspendSave, api.goalStore::resumeSave,
			new com.goalplanner.command.Command()
		{
			@Override
			public boolean apply()
			{
				createdGoalIds.clear();
				createdSectionIds.clear();
				addedRequires.clear();
				addedOrRequires.clear();
				landedSectionId[0] = null;
				boolean importedAnything = false;
				// Per-section ref → created/reused goal id, keyed by the
				// section's position in the BUNDLE's section list - cross-edge
				// entries reference sections by that index.
				final Map<Integer, Map<Integer, String>> refMaps = new HashMap<>();

				for (SectionShareDto shared : sections)
				{
					final boolean reuseEquivalents = shared.isTargetDefault();
					final String targetSectionId;
					if (reuseEquivalents)
					{
						// Default plan: goals land in the Incomplete built-in and
						// existing equivalents are reused - the same dedup the
						// in-game Add Goal flow applies.
						targetSectionId = api.goalStore.getIncompleteSection().getId();
					}
					else
					{
						// A named import lands in its own NEW user section, forced
						// to KEEP COMPLETED INLINE so the recipient sees the shared
						// set as a checklist against their account.
						Section section = api.goalStore.createUserSection(
							importSectionName(shared));
						if (section == null)
						{
							log.warn("importBundle: createUserSection failed for '{}' - skipping section",
								shared.getName());
							continue;
						}
						if (shared.getColorRgb() >= 0)
						{
							section.setColorRgb(shared.getColorRgb());
						}
						// Carry the sharer's nested-view preference (TRUE/FALSE);
						// null leaves the recipient on their global default. Set
						// directly on the section (like colorRgb above) - the import
						// flow persists the section afterward.
						if (shared.getNestedOverride() != null)
						{
							section.setNestedOverride(shared.getNestedOverride());
						}
						api.goalStore.setSectionAutoArchiveOverride(section.getId(), false);
						createdSectionIds.add(section.getId());
						targetSectionId = section.getId();
					}
					if (landedSectionId[0] == null)
					{
						landedSectionId[0] = targetSectionId;
					}

					// First pass: create (or, in default mode, reuse) goals.
					// Relation refs are SECTION-scoped in v2.
					Map<Integer, String> refToId = new HashMap<>();
					for (GoalShareDto dto : shared.getGoals())
					{
						GoalType type = parseType(dto.getType());
						if (type == null)
						{
							log.warn("importBundle: skipping goal with unknown type '{}'", dto.getType());
							continue;
						}
						Goal goal = buildGoal(dto, type, reuseEquivalents ? null : targetSectionId);
						if (reuseEquivalents)
						{
							Goal existing = api.goalStore.findEquivalentInNamespace(targetSectionId, goal);
							if (existing != null)
							{
								refToId.put(dto.getRef(), existing.getId());
								importedAnything = true;
								continue;
							}
						}
						api.goalStore.addGoal(goal);   // null sectionId → Incomplete built-in
						createdGoalIds.add(goal.getId());
						refToId.put(dto.getRef(), goal.getId());
						importedAnything = true;
					}

					// Second pass: rewire relations now that every ref has an id.
					for (GoalShareDto dto : shared.getGoals())
					{
						String fromId = refToId.get(dto.getRef());
						if (fromId == null)
						{
							continue;
						}
						for (Integer ref : dto.getRequires())
						{
							String toId = refToId.get(ref);
							if (toId != null && api.goalStore.addRequirement(fromId, toId))
							{
								addedRequires.add(new String[]{fromId, toId});
							}
						}
						for (Integer ref : dto.getOrRequires())
						{
							String toId = refToId.get(ref);
							if (toId != null && api.goalStore.addOrRequirement(fromId, toId))
							{
								addedOrRequires.add(new String[]{fromId, toId});
							}
						}
					}
					refMaps.put(bundleSections.indexOf(shared), refToId);
				}

				// Third pass: cross-section edges - (section index, ref) pairs
				// resolved through the per-section maps. Unresolvable entries
				// (skipped goal/section, malformed indices) are dropped.
				if (bundle.getCrossEdges() != null)
				{
					for (com.goalplanner.share.CrossEdgeDto edge : bundle.getCrossEdges())
					{
						if (edge == null)
						{
							continue;
						}
						Map<Integer, String> fromMap = refMaps.get(edge.getFromSection());
						Map<Integer, String> toMap = refMaps.get(edge.getToSection());
						String fromId = fromMap != null ? fromMap.get(edge.getFromRef()) : null;
						String toId = toMap != null ? toMap.get(edge.getToRef()) : null;
						if (fromId == null || toId == null)
						{
							continue;
						}
						if (edge.isOr())
						{
							if (api.goalStore.addOrRequirement(fromId, toId))
							{
								addedOrRequires.add(new String[]{fromId, toId});
							}
						}
						else if (api.goalStore.addRequirement(fromId, toId))
						{
							addedRequires.add(new String[]{fromId, toId});
						}
					}
				}
				return importedAnything;
			}

			@Override
			public boolean revert()
			{
				// Relations first - created goals take theirs with them, but a
				// relation between two REUSED goals must be removed explicitly.
				for (String[] rel : addedRequires)
				{
					api.goalStore.removeRequirement(rel[0], rel[1]);
				}
				for (String[] rel : addedOrRequires)
				{
					api.goalStore.removeOrRequirement(rel[0], rel[1]);
				}
				for (String goalId : createdGoalIds)
				{
					api.goalStore.removeGoal(goalId);
				}
				for (String sectionId : createdSectionIds)
				{
					api.goalStore.deleteUserSection(sectionId);
				}
				return true;
			}

			@Override
			public String getDescription()
			{
				return description;
			}
		}));

		return landedSectionId[0];
	}

	private static String displayName(SectionShareDto shared)
	{
		if (shared.isTargetDefault())
		{
			return "Default";
		}
		return notBlank(shared.getName()) ? shared.getName().trim() : "Shared goals";
	}

	private Goal buildGoal(GoalShareDto dto, GoalType type, String sectionId)
	{
		// Enrich the icon fields the share wire doesn't carry, mirroring in-game
		// creation: QUEST/DIARY goals get the journal sprite, BOSS goals get their
		// pet item id - otherwise the card falls back to a plain colour dot.
		int spriteId = dto.getSpriteId();
		int itemId = dto.getItemId();
		if (spriteId <= 0)
		{
			if (type == GoalType.QUEST) spriteId = GoalPlannerApiImpl.QUEST_SPRITE_ID;
			else if (type == GoalType.DIARY) spriteId = com.goalplanner.data.AchievementDiaryData.DIARY_SPRITE_ID;
		}
		if (itemId <= 0 && type == GoalType.BOSS && notBlank(dto.getBossName()))
		{
			itemId = com.goalplanner.data.BossKillData.getPetItemId(dto.getBossName().trim());
		}
		Goal goal = Goal.builder()
			.type(type)
			.name(clamp(dto.getName(), MAX_NAME))
			.description(clamp(dto.getDescription(), MAX_TEXT))
			// A repeatable chunk goal's target is the SENDER's progress plus the
			// chunk - meaningless here. Import it as 0 ("not yet sized") and let
			// the first tracker read size it against the recipient's own progress
			// (see GoalMutationService.recordGoalProgress). Sending 9,810,000 to
			// someone with 2M Prayer XP would ask them for 7.8M in a day while the
			// card displayed a tidy "0 / 10K".
			.targetValue(dto.getRepeatChunk() > 0 ? 0 : dto.getTargetValue())
			.skillName(dto.getSkillName())
			.questName(dto.getQuestName())
			.accountMetric(dto.getAccountMetric())
			.bossName(clamp(dto.getBossName(), MAX_NAME))
			.varbitId(dto.getVarbitId())
			.itemId(itemId)
			.spriteId(spriteId)
			.tooltip(clamp(dto.getTooltip(), MAX_TEXT))
			.caTaskId(dto.getCaTaskId())
			.repeatEvery(parseRepeatPeriod(dto.getRepeatEvery()))
			.repeatChunk(Math.max(0, dto.getRepeatChunk()))
			.customColorRgb(dto.getCustomColorRgb())
			.optional(dto.isOptional())
			.autoSeeded(dto.isAutoSeeded())
			.wikiUrl(clamp(dto.getWikiUrl(), MAX_TEXT))
			.inventorySetup(clamp(dto.getInventorySetup(), MAX_NAME))
			.sectionId(sectionId)
			.build();
		goal.setTagIds(resolveTags(dto.getTags()));
		return goal;
	}

	private List<String> resolveTags(List<TagShareDto> tags)
	{
		List<String> ids = new ArrayList<>();
		if (tags == null)
		{
			return ids;
		}
		for (TagShareDto spec : tags)
		{
			String label = clamp(spec.getLabel(), MAX_NAME);
			TagCategory category = parseCategory(spec.getCategory());
			if (label == null || label.isEmpty() || category == null)
			{
				continue;   // unusable tag - skip
			}
			Tag tag = spec.isSystem()
				? api.goalStore.findOrCreateSystemTag(label, category)
				: findOrCreateUserTag(label, category);
			if (tag == null)
			{
				continue;
			}
			// Only recolour user tags - system-tag colours are shared across the
			// recipient's goals and shouldn't be mutated by an import.
			if (!spec.isSystem() && spec.getColorRgb() != -1)
			{
				api.goalStore.recolorTag(tag.getId(), spec.getColorRgb());
			}
			ids.add(tag.getId());
		}
		return ids;
	}

	private Tag findOrCreateUserTag(String label, TagCategory category)
	{
		Tag existing = api.goalStore.findTagByLabel(label, category);
		return existing != null ? existing : api.goalStore.createUserTag(label, category);
	}

	private String importSectionName(SectionShareDto shared)
	{
		// Use the shared section's own name verbatim - no "(from <sharer>)" suffix.
		// That suffix ate horizontal space in the panel; sharer attribution isn't
		// worth a section's limited width. Clamp as a backstop against the cap
		// (createUserSection THROWS on over-length names, which CommandHistory
		// swallows - silently failing the whole import).
		String base = notBlank(shared.getName()) ? shared.getName().trim() : "Shared goals";
		return clamp(base, GoalStore.MAX_SECTION_NAME_LENGTH);
	}

	private static GoalType parseType(String name)
	{
		if (name == null)
		{
			return null;
		}
		try
		{
			return GoalType.valueOf(name);
		}
		catch (IllegalArgumentException e)
		{
			return null;
		}
	}

	private static TagCategory parseCategory(String name)
	{
		if (name == null)
		{
			return null;
		}
		try
		{
			return TagCategory.valueOf(name);
		}
		catch (IllegalArgumentException e)
		{
			return null;
		}
	}

	private static boolean notBlank(String s)
	{
		return s != null && !s.trim().isEmpty();
	}

	private static String clamp(String s, int max)
	{
		if (s == null)
		{
			return null;
		}
		String t = s.trim();
		return t.length() <= max ? t : t.substring(0, max);
	}

	/**
	 * Read a shared repeat period. Anything unrecognised - absent (an older
	 * sender), misspelled, or a period a future version adds - imports as a
	 * plain one-shot rather than failing the whole bundle. A share code is
	 * untrusted input from another client.
	 */
	private static com.goalplanner.model.RepeatPeriod parseRepeatPeriod(String raw)
	{
		if (raw == null || raw.trim().isEmpty())
		{
			return com.goalplanner.model.RepeatPeriod.NONE;
		}
		try
		{
			return com.goalplanner.model.RepeatPeriod.valueOf(raw.trim());
		}
		catch (IllegalArgumentException e)
		{
			log.warn("share import: unknown repeat period {} - importing as one-shot", raw);
			return com.goalplanner.model.RepeatPeriod.NONE;
		}
	}
}

package com.goalplanner.api;

import com.goalplanner.model.Goal;
import com.goalplanner.model.GoalType;
import com.goalplanner.model.Tag;
import com.goalplanner.model.TagCategory;

import java.util.ArrayList;
import java.util.List;
import lombok.extern.slf4j.Slf4j;
import java.awt.Color;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;

/**
 * Encapsulates all tag-management methods extracted from {@link GoalPlannerApiImpl}.
 * Package-private - only {@link GoalPlannerApiImpl} instantiates and delegates to this.
 */
@Slf4j
class TagService
{
	private final GoalPlannerApiImpl api;

	TagService(GoalPlannerApiImpl api)
	{
		this.api = api;
	}

	boolean addTag(String goalId, String label)
	{
		log.debug("API.public addTag(goalId={}, label={})", goalId, label);
		if (goalId == null || label == null || label.trim().isEmpty()) return false;
		Goal g = api.findGoal(goalId);
		if (g == null) return false;
		Tag tag = api.goalStore.createUserTag(label.trim(), TagCategory.OTHER);
		if (tag == null) return false;
		if (g.getTagIds() != null && g.getTagIds().contains(tag.getId())) return false; // already has it
		final String tagId = tag.getId();
		final String label2 = label.trim();
		final String name = g.getName();
		return api.executeCommand(new com.goalplanner.command.Command()
		{
			@Override public boolean apply()
			{
				Goal cg = api.findGoal(goalId);
				if (cg == null) return false;
				if (cg.getTagIds() == null) cg.setTagIds(new ArrayList<>());
				if (cg.getTagIds().contains(tagId)) return false;
				cg.getTagIds().add(tagId);
				api.goalStore.updateGoal(cg);
				return true;
			}
			@Override public boolean revert()
			{
				Goal cg = api.findGoal(goalId);
				if (cg == null || cg.getTagIds() == null) return false;
				boolean removed = cg.getTagIds().remove(tagId);
				if (removed) api.goalStore.updateGoal(cg);
				return removed;
			}
			@Override public String getDescription() { return "Add tag '" + label2 + "' to " + name; }
		});
	}

	boolean removeTag(String goalId, String label)
	{
		log.debug("API.public removeTag(goalId={}, label={})", goalId, label);
		if (goalId == null || label == null) return false;
		Goal g = api.findGoal(goalId);
		if (g == null || g.getTagIds() == null) return false;
		List<String> defaults = g.getDefaultTagIds() != null ? g.getDefaultTagIds() : Collections.emptyList();
		String toRemove = null;
		int idx = -1;
		for (int i = 0; i < g.getTagIds().size(); i++)
		{
			String id = g.getTagIds().get(i);
			if (defaults.contains(id)) continue;
			Tag tag = api.goalStore.findTag(id);
			if (tag != null && label.equals(tag.getLabel()))
			{
				toRemove = id;
				idx = i;
				break;
			}
		}
		if (toRemove == null) return false;
		final String tagId = toRemove;
		final int restoreIdx = idx;
		final String name = g.getName();
		return api.executeCommand(new com.goalplanner.command.Command()
		{
			@Override public boolean apply()
			{
				Goal cg = api.findGoal(goalId);
				if (cg == null || cg.getTagIds() == null) return false;
				boolean removed = cg.getTagIds().remove(tagId);
				if (removed) api.goalStore.updateGoal(cg);
				return removed;
			}
			@Override public boolean revert()
			{
				Goal cg = api.findGoal(goalId);
				if (cg == null) return false;
				if (cg.getTagIds() == null) cg.setTagIds(new ArrayList<>());
				int safeIdx = Math.min(restoreIdx, cg.getTagIds().size());
				cg.getTagIds().add(safeIdx, tagId);
				api.goalStore.updateGoal(cg);
				return true;
			}
			@Override public String getDescription() { return "Remove tag '" + label + "' from " + name; }
		});
	}

	boolean addTagWithCategory(String goalId, String label, String categoryName)
	{
		log.debug("API.internal addTagWithCategory(goalId={}, label={}, category={})",
			goalId, label, categoryName);
		if (goalId == null || label == null || label.trim().isEmpty()) return false;
		Goal g = api.findGoal(goalId);
		if (g == null) return false;
		TagCategory category;
		try
		{
			category = TagCategory.valueOf(categoryName);
		}
		catch (IllegalArgumentException ex)
		{
			log.warn("addTagWithCategory: unknown category {}", categoryName);
			return false;
		}
		// SKILLING is system-only: only allow attaching an existing skill tag,
		// never creating a new one. Look up via findTag-by-label; null = reject.
		Tag tag;
		if (category == TagCategory.SKILLING)
		{
			tag = api.goalStore.findTagByLabel(label.trim(), category);
			if (tag == null)
			{
				log.warn("addTagWithCategory: SKILLING tag '{}' does not exist", label);
				return false;
			}
		}
		else
		{
			tag = api.goalStore.createUserTag(label.trim(), category);
		}
		if (tag == null) return false;
		if (g.getTagIds() != null && g.getTagIds().contains(tag.getId())) return false;
		final String tagId = tag.getId();
		final String tagLabel = tag.getLabel();
		final String name = g.getName();
		return api.executeCommand(new com.goalplanner.command.Command()
		{
			@Override public boolean apply()
			{
				Goal cg = api.findGoal(goalId);
				if (cg == null) return false;
				if (cg.getTagIds() == null) cg.setTagIds(new ArrayList<>());
				if (cg.getTagIds().contains(tagId)) return false;
				cg.getTagIds().add(tagId);
				api.goalStore.updateGoal(cg);
				return true;
			}
			@Override public boolean revert()
			{
				Goal cg = api.findGoal(goalId);
				if (cg == null || cg.getTagIds() == null) return false;
				boolean removed = cg.getTagIds().remove(tagId);
				if (removed) api.goalStore.updateGoal(cg);
				return removed;
			}
			@Override public String getDescription() { return "Add tag '" + tagLabel + "' to " + name; }
		});
	}

	boolean restoreDefaultTags(String goalId)
	{
		log.debug("API.public restoreDefaultTags(goalId={})", goalId);
		if (goalId == null) return false;
		Goal g = api.findGoal(goalId);
		if (g == null) return false;
		List<String> defaults = g.getDefaultTagIds();
		if (defaults == null || defaults.isEmpty()) return false;
		final List<String> snapshotTagIds = new ArrayList<>(g.getTagIds() != null ? g.getTagIds() : Collections.emptyList());
		final String name = g.getName();
		return api.executeCommand(new com.goalplanner.command.Command()
		{
			@Override public boolean apply()
			{
				Goal cg = api.findGoal(goalId);
				if (cg == null) return false;
				cg.setTagIds(new ArrayList<>(cg.getDefaultTagIds()));
				api.goalStore.updateGoal(cg);
				return true;
			}
			@Override public boolean revert()
			{
				Goal cg = api.findGoal(goalId);
				if (cg == null) return false;
				cg.setTagIds(new ArrayList<>(snapshotTagIds));
				api.goalStore.updateGoal(cg);
				return true;
			}
			@Override public String getDescription() { return "Restore defaults: " + name; }
		});
	}

	List<TagView> queryAllTags()
	{
		log.debug("API.internal queryAllTags()");
		List<TagView> out = new ArrayList<>();
		for (Tag t : api.goalStore.getTags())
		{
			out.add(toTagView(t));
		}
		return out;
	}

	String createUserTag(String label, String categoryName)
	{
		log.debug("API.internal createUserTag(label={}, category={})", label, categoryName);
		TagCategory category;
		try
		{
			category = TagCategory.valueOf(categoryName);
		}
		catch (IllegalArgumentException ex)
		{
			log.warn("createUserTag: unknown category {}", categoryName);
			return null;
		}
		if (category == TagCategory.SKILLING)
		{
			log.warn("createUserTag: SKILLING category is reserved for system tags");
			return null;
		}
		// Use the same find-or-create semantics. If it already existed, no
		// command - return existing id with no history entry.
		Tag existing = api.goalStore.findTagByLabel(label != null ? label.trim() : "", category);
		if (existing != null) return existing.getId();
		Tag tag = api.goalStore.createUserTag(label, category);
		if (tag == null) return null;
		final Tag captured = tag;
		final String tagLabel = tag.getLabel();
		api.executeCommand(new com.goalplanner.command.Command()
		{
			private boolean firstApply = true;
			@Override public boolean apply()
			{
				if (firstApply) { firstApply = false; return true; }
				api.goalStore.recreateTag(captured);
				return true;
			}
			@Override public boolean revert() { return api.goalStore.deleteTag(captured.getId()); }
			@Override public String getDescription() { return "Create tag: " + tagLabel; }
		});
		return tag.getId();
	}

	boolean renameTag(String tagId, String newLabel)
	{
		log.debug("API.internal renameTag(tagId={}, newLabel={})", tagId, newLabel);
		Tag t = api.goalStore.findTag(tagId);
		if (t == null) return false;
		final String prevLabel = t.getLabel();
		final String resolved = newLabel != null ? newLabel.trim() : "";
		if (resolved.isEmpty() || resolved.equals(prevLabel)) return false;
		return api.executeCommand(new com.goalplanner.command.Command()
		{
			@Override public boolean apply() { return api.goalStore.renameTag(tagId, resolved); }
			@Override public boolean revert() { return api.goalStore.renameTag(tagId, prevLabel); }
			@Override public String getDescription() { return "Rename tag: " + prevLabel + " -> " + resolved; }
		});
	}

	boolean recolorTag(String tagId, int colorRgb)
	{
		log.debug("API.internal recolorTag(tagId={}, colorRgb={})", tagId, colorRgb);
		Tag t = api.goalStore.findTag(tagId);
		if (t == null) return false;
		final int prevColor = t.getColorRgb();
		final TagCategory cat = t.getCategory();
		final int prevCategoryColor = api.goalStore.isCategoryColorOverridden(cat)
			? api.goalStore.getCategoryColor(cat) : -1;
		final String label = t.getLabel();
		return api.executeCommand(new com.goalplanner.command.Command()
		{
			@Override public boolean apply()
			{
				if (cat == TagCategory.OTHER) return api.goalStore.recolorTag(tagId, colorRgb);
				return api.goalStore.setCategoryColor(cat, colorRgb);
			}
			@Override public boolean revert()
			{
				if (cat == TagCategory.OTHER) return api.goalStore.recolorTag(tagId, prevColor);
				return api.goalStore.setCategoryColor(cat, prevCategoryColor);
			}
			@Override public String getDescription() { return "Recolor tag: " + label; }
		});
	}

	boolean deleteTag(String tagId)
	{
		log.debug("API.internal deleteTag(tagId={})", tagId);
		Tag t = api.goalStore.findTag(tagId);
		if (t == null || t.isSystem()) return false;
		// Snapshot the tag entity AND the per-goal references so revert can
		// restore both. We also snapshot defaultTagIds membership for goals
		// that had this tag in their defaults.
		final Tag captured = t;
		final List<String> tagOnGoals = new ArrayList<>();
		final List<String> tagOnDefaults = new ArrayList<>();
		for (Goal g : api.goalStore.getGoals())
		{
			if (g.getTagIds() != null && g.getTagIds().contains(tagId)) tagOnGoals.add(g.getId());
			if (g.getDefaultTagIds() != null && g.getDefaultTagIds().contains(tagId)) tagOnDefaults.add(g.getId());
		}
		final String label = t.getLabel();
		return api.executeCommand(new com.goalplanner.command.Command()
		{
			@Override public boolean apply() { return api.goalStore.deleteTag(tagId); }
			@Override public boolean revert()
			{
				api.goalStore.recreateTag(captured);
				for (String gid : tagOnGoals)
				{
					Goal g = api.findGoal(gid);
					if (g == null) continue;
					if (g.getTagIds() == null) g.setTagIds(new ArrayList<>());
					if (!g.getTagIds().contains(tagId)) g.getTagIds().add(tagId);
				}
				for (String gid : tagOnDefaults)
				{
					Goal g = api.findGoal(gid);
					if (g == null) continue;
					if (g.getDefaultTagIds() == null) g.setDefaultTagIds(new ArrayList<>());
					if (!g.getDefaultTagIds().contains(tagId)) g.getDefaultTagIds().add(tagId);
				}
				return true;
			}
			@Override public String getDescription() { return "Delete tag: " + label; }
		});
	}

	boolean setCategoryColor(String categoryName, int colorRgb)
	{
		log.debug("API.internal setCategoryColor(category={}, colorRgb={})", categoryName, colorRgb);
		TagCategory category;
		try { category = TagCategory.valueOf(categoryName); }
		catch (IllegalArgumentException ex) { return false; }
		final int prevColor = api.goalStore.isCategoryColorOverridden(category)
			? api.goalStore.getCategoryColor(category) : -1;
		return api.executeCommand(new com.goalplanner.command.Command()
		{
			@Override public boolean apply() { return api.goalStore.setCategoryColor(category, colorRgb); }
			@Override public boolean revert() { return api.goalStore.setCategoryColor(category, prevColor); }
			@Override public String getDescription() { return "Recolor category: " + category.name(); }
		});
	}

	boolean resetCategoryColor(String categoryName)
	{
		log.debug("API.internal resetCategoryColor(category={})", categoryName);
		return setCategoryColor(categoryName, -1);
	}

	int getCategoryColor(String categoryName)
	{
		try { return api.goalStore.getCategoryColor(TagCategory.valueOf(categoryName)); }
		catch (IllegalArgumentException ex) { return 0; }
	}

	int getCategoryDefaultColor(String categoryName)
	{
		try
		{
			Color c = TagCategory.valueOf(categoryName).getColor();
			return (c.getRed() << 16) | (c.getGreen() << 8) | c.getBlue();
		}
		catch (IllegalArgumentException ex) { return 0; }
	}

	boolean isCategoryColorOverridden(String categoryName)
	{
		try { return api.goalStore.isCategoryColorOverridden(TagCategory.valueOf(categoryName)); }
		catch (IllegalArgumentException ex) { return false; }
	}

	boolean setTagIcon(String tagId, String iconKey)
	{
		log.debug("API.internal setTagIcon(tagId={}, iconKey={})", tagId, iconKey);
		Tag t = api.goalStore.findTag(tagId);
		if (t == null) return false;
		final String prevIcon = t.getIconKey();
		final String label = t.getLabel();
		return api.executeCommand(new com.goalplanner.command.Command()
		{
			@Override public boolean apply() { return api.goalStore.setTagIcon(tagId, iconKey); }
			@Override public boolean revert() { api.goalStore.setTagIcon(tagId, prevIcon); return true; }
			@Override public String getDescription() { return "Set icon: " + label; }
		});
	}

	boolean clearTagIcon(String tagId)
	{
		log.debug("API.internal clearTagIcon(tagId={})", tagId);
		return setTagIcon(tagId, null);
	}

	boolean setTagColor(String goalId, String tagLabel, int colorRgb)
	{
		// Per-tag colors are OTHER-only. For OTHER tags this
		// stores the color on the tag entity; for other categories it
		// delegates to setCategoryColor which affects every tag in the
		// category. SKILLING is rejected.
		log.debug("API.internal setTagColor(goalId={}, tagLabel={}, colorRgb={})",
			goalId, tagLabel, colorRgb);
		Goal g = api.findGoal(goalId);
		if (g == null || tagLabel == null || g.getTagIds() == null) return false;
		for (String id : g.getTagIds())
		{
			Tag tag = api.goalStore.findTag(id);
			if (tag != null && tagLabel.equals(tag.getLabel()))
			{
				boolean changed;
				if (tag.getCategory() == TagCategory.OTHER)
				{
					changed = api.goalStore.recolorTag(id, colorRgb);
				}
				else
				{
					changed = api.goalStore.setCategoryColor(tag.getCategory(), colorRgb);
				}
				if (changed) api.fireIfNotInCompound();
				return changed;
			}
		}
		return false;
	}

	List<GoalPlannerInternalApi.TagRemovalOption> getRemovableTagsForSelection(Set<String> goalIds)
	{
		if (goalIds == null || goalIds.isEmpty()) return Collections.emptyList();
		// tagId → count of selected goals where it's both present and removable
		Map<String, Integer> counts = new HashMap<>();
		for (String goalId : goalIds)
		{
			Goal g = api.findGoal(goalId);
			if (g == null || g.getTagIds() == null) continue;
			boolean isCustom = g.getType() == GoalType.CUSTOM;
			List<String> defaults = g.getDefaultTagIds() != null ? g.getDefaultTagIds() : Collections.emptyList();
			for (String tid : g.getTagIds())
			{
				if (!isCustom && defaults.contains(tid)) continue;
				counts.merge(tid, 1, Integer::sum);
			}
		}
		List<GoalPlannerInternalApi.TagRemovalOption> out = new ArrayList<>(counts.size());
		for (Map.Entry<String, Integer> e : counts.entrySet())
		{
			Tag tag = api.goalStore.findTag(e.getKey());
			if (tag == null) continue;
			out.add(new GoalPlannerInternalApi.TagRemovalOption(tag.getId(), tag.getLabel(), e.getValue()));
		}
		// Sort: count desc, then label asc (case-insensitive)
		out.sort((a, b) -> {
			if (a.count != b.count) return Integer.compare(b.count, a.count);
			return a.label.compareToIgnoreCase(b.label);
		});
		return out;
	}

	int bulkRemoveTagFromGoals(Set<String> goalIds, String tagId)
	{
		log.debug("API.internal bulkRemoveTagFromGoals({} goals, tagId={})",
			goalIds == null ? 0 : goalIds.size(), tagId);
		if (goalIds == null || goalIds.isEmpty() || tagId == null) return 0;
		// Snapshot which goals will lose this tag and at what
		// index, so revert can re-insert at the same position.
		final String fTagId = tagId;
		final List<int[]> snapshots = new ArrayList<>(); // unused
		final List<String> goalIdsAffected = new ArrayList<>();
		final List<Integer> indices = new ArrayList<>();
		for (String goalId : goalIds)
		{
			Goal g = api.findGoal(goalId);
			if (g == null || g.getTagIds() == null) continue;
			if (!g.getTagIds().contains(tagId)) continue;
			boolean isCustom = g.getType() == GoalType.CUSTOM;
			List<String> defaults = g.getDefaultTagIds() != null ? g.getDefaultTagIds() : Collections.emptyList();
			if (!isCustom && defaults.contains(tagId)) continue;
			goalIdsAffected.add(goalId);
			indices.add(g.getTagIds().indexOf(tagId));
		}
		if (goalIdsAffected.isEmpty()) return 0;
		final Tag tagSnapshot = api.goalStore.findTag(tagId);
		final String tagLabel = tagSnapshot != null ? tagSnapshot.getLabel() : tagId;
		boolean ok = api.executeCommand(new com.goalplanner.command.Command()
		{
			@Override public boolean apply()
			{
				for (String goalId : goalIdsAffected)
				{
					Goal g = api.findGoal(goalId);
					if (g == null || g.getTagIds() == null) continue;
					g.getTagIds().remove(fTagId);
					api.goalStore.updateGoal(g);
				}
				return true;
			}
			@Override public boolean revert()
			{
				for (int i = 0; i < goalIdsAffected.size(); i++)
				{
					Goal g = api.findGoal(goalIdsAffected.get(i));
					if (g == null) continue;
					if (g.getTagIds() == null) g.setTagIds(new ArrayList<>());
					int idx = Math.min(indices.get(i), g.getTagIds().size());
					g.getTagIds().add(idx, fTagId);
					api.goalStore.updateGoal(g);
				}
				return true;
			}
			@Override public String getDescription()
			{
				return "Remove tag '" + tagLabel + "' (" + goalIdsAffected.size() + " goals)";
			}
		});
		return ok ? goalIdsAffected.size() : 0;
	}

	/**
	 * Converts a {@link Tag} entity to its API view representation. This helper
	 * is also used by {@link GoalPlannerApiImpl#toGoalView} for tag splitting.
	 */
	TagView toTagView(Tag t)
	{
		// Defensive: null category fallback to OTHER (handles enum removal migration).
		TagCategory cat = t.getCategory() != null ? t.getCategory() : TagCategory.OTHER;
		int defaultRgb = api.goalStore.getCategoryDefaultColor(cat);

		int currentRgb;
		boolean overridden;
		if (cat == TagCategory.OTHER)
		{
			// OTHER is special: per-tag colors. Each Other tag carries its own.
			if (t.getColorRgb() >= 0)
			{
				currentRgb = t.getColorRgb();
				overridden = true;
			}
			else
			{
				currentRgb = defaultRgb;
				overridden = false;
			}
		}
		else
		{
			// BOSS/RAID/CLUE/MINIGAME/SKILLING: shared category color. The
			// per-tag colorRgb field is ignored for these categories.
			currentRgb = api.goalStore.getCategoryColor(cat);
			overridden = api.goalStore.isCategoryColorOverridden(cat);
		}

		TagView v = new TagView(t.getLabel(), cat.name(),
			currentRgb, defaultRgb, overridden);
		v.id = t.getId();
		v.system = t.isSystem();
		v.iconKey = t.getIconKey();
		return v;
	}
}

