package com.goalplanner.command;

/**
 * A reversible user action on the goal tracker.
 *
 * <p>Commands carry the state needed to revert themselves at construction
 * time - typically a snapshot of "before" values plus the parameters of the
 * action - so applying the command does not depend on any external state
 * that may have changed by the time {@link #revert()} runs.
 *
 * <p>Both {@link #apply()} and {@link #revert()} return a boolean. False
 * means "the operation failed at the store level" (e.g. the entity it was
 * trying to mutate is gone). The {@code CommandHistory} treats a false
 * return on revert as a failed undo: it logs the failure and drops the
 * entry from history rather than crashing or rolling further back.
 *
 * <p>{@link #getDescription()} is a short user-facing string for the
 * undo/redo button tooltip ("Undo: Add goal 'Vorkath KC'").
 *
 * <p>Tracker-driven mutations (XP gain, quest tick, item count change) do
 * NOT go through Command - they call the underlying store mutation
 * primitives directly so they never appear in undo history.
 */
public interface Command
{
	/** Run the action. Returns true if it actually changed state. */
	boolean apply();

	/** Reverse the action. Returns true if the revert succeeded. */
	boolean revert();

	/** Short user-facing label, e.g. "Add goal 'Vorkath KC'". */
	String getDescription();
}

package com.goalplanner.command;

import lombok.extern.slf4j.Slf4j;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.ArrayList;
import java.util.List;

/**
 * In-memory undo / redo stack for {@link Command} entries.
 *
 * <p>Standard semantics:
 * <ul>
 *   <li>{@link #execute(Command)} runs the command and pushes onto the
 *       undo stack. Any pending redo entries are cleared (forking history).
 *   <li>{@link #undo()} pops the most recent undo entry, calls
 *       {@code revert()}, and pushes onto the redo stack. If revert returns
 *       false the entry is dropped without being pushed onto redo.
 *   <li>{@link #redo()} pops the most recent redo entry, calls
 *       {@code apply()}, and pushes back onto the undo stack. If apply
 *       returns false the entry is dropped.
 * </ul>
 *
 * <p>The undo stack is bounded - once it exceeds {@link #CAP} entries, the
 * oldest entries are dropped (the redo stack is implicitly bounded by what
 * the user has undone). Both stacks are session-only; they are never
 * persisted.
 *
 * <p>Not thread-safe - all calls must come from the EDT (or whichever
 * single thread owns the API impl).
 */
@Slf4j
public class CommandHistory
{
	public static final int CAP = 50;

	private final Deque<Command> undoStack = new ArrayDeque<>();
	private final Deque<Command> redoStack = new ArrayDeque<>();

	/** When non-null, execute() appends to this buffer instead of
	 *  pushing to undoStack. endCompound() collapses the buffer into a single
	 *  CompositeCommand and pushes it. */
	private List<Command> compoundBuffer = null;
	private String compoundDescription = null;
	/** Nesting depth counter for begin/endCompound. addSkillGoal and
	 *  addQuestGoalWithPrereqs both wrap in compounds, and the latter
	 *  calls the former inside its own compound. Without ref-counting,
	 *  the inner endCompound prematurely closes the outer compound. */
	private int compoundDepth = 0;

	/**
	 * Run a command and push it onto the undo stack on success.
	 * Forking behavior: any pending redo entries are cleared.
	 *
	 * @return whatever {@link Command#apply()} returned
	 */
	public boolean execute(Command cmd)
	{
		boolean ok;
		try
		{
			ok = cmd.apply();
		}
		catch (Exception ex)
		{
			log.warn("Command apply threw, dropping: {}", cmd.getDescription(), ex);
			return false;
		}
		if (!ok) return false;
		if (compoundBuffer != null)
		{
			compoundBuffer.add(cmd);
		}
		else
		{
			undoStack.push(cmd);
			redoStack.clear();
			trim();
		}
		return true;
	}

	/**
	 * Begin a compound command. Subsequent {@link #execute} calls collect
	 * into a buffer instead of pushing individually. {@link #endCompound}
	 * collapses the buffer into a single undo entry with the given
	 * description. Nested compounds are ref-counted: only the outermost
	 * end actually closes the buffer.
	 */
	public void beginCompound(String description)
	{
		compoundDepth++;
		if (compoundBuffer != null) return; // already in a compound - just bump the depth
		compoundBuffer = new ArrayList<>();
		compoundDescription = description;
	}

	/**
	 * Close the current compound, wrap its commands in a CompositeCommand,
	 * and push it onto the undo stack as a single entry. No-op if no
	 * compound is active or if the buffer is empty.
	 */
	/** True when a compound is active (between begin/endCompound). */
	public boolean isInCompound()
	{
		return compoundBuffer != null;
	}

	public void endCompound()
	{
		if (compoundDepth > 0) compoundDepth--;
		if (compoundDepth > 0) return; // still inside a nested compound
		if (compoundBuffer == null) return;
		List<Command> buf = compoundBuffer;
		String desc = compoundDescription;
		compoundBuffer = null;
		compoundDescription = null;
		if (buf.isEmpty()) return;
		undoStack.push(new CompositeCommand(buf, desc));
		redoStack.clear();
		trim();
	}

	/**
	 * Pop the most recent undo entry and revert it. On success the entry
	 * moves to the redo stack. On failure the entry is dropped - fail-open.
	 *
	 * @return true if an entry was reverted, false if the stack was empty
	 *         or the revert failed
	 */
	public boolean undo()
	{
		if (undoStack.isEmpty()) return false;
		Command cmd = undoStack.pop();
		boolean ok;
		try
		{
			ok = cmd.revert();
		}
		catch (Exception ex)
		{
			log.warn("Command revert threw, dropping: {}", cmd.getDescription(), ex);
			return false;
		}
		if (!ok)
		{
			log.warn("Command revert returned false, dropping: {}", cmd.getDescription());
			return false;
		}
		redoStack.push(cmd);
		return true;
	}

	/**
	 * Pop the most recent redo entry and re-apply it. On success the entry
	 * moves back to the undo stack. On failure the entry is dropped.
	 */
	public boolean redo()
	{
		if (redoStack.isEmpty()) return false;
		Command cmd = redoStack.pop();
		boolean ok;
		try
		{
			ok = cmd.apply();
		}
		catch (Exception ex)
		{
			log.warn("Command re-apply threw, dropping: {}", cmd.getDescription(), ex);
			return false;
		}
		if (!ok)
		{
			log.warn("Command re-apply returned false, dropping: {}", cmd.getDescription());
			return false;
		}
		undoStack.push(cmd);
		return true;
	}

	public boolean canUndo() { return !undoStack.isEmpty(); }
	public boolean canRedo() { return !redoStack.isEmpty(); }

	/** Description of the next undo target, or null if the stack is empty. */
	public String peekUndoDescription()
	{
		return undoStack.isEmpty() ? null : undoStack.peek().getDescription();
	}

	/** Description of the next redo target, or null if the stack is empty. */
	public String peekRedoDescription()
	{
		return redoStack.isEmpty() ? null : redoStack.peek().getDescription();
	}

	/** Wipe both stacks. */
	public void clear()
	{
		undoStack.clear();
		redoStack.clear();
	}

	private void trim()
	{
		while (undoStack.size() > CAP)
		{
			undoStack.pollLast();
		}
	}

	int undoSize() { return undoStack.size(); }
	int redoSize() { return redoStack.size(); }
}

package com.goalplanner.command;

import java.util.List;

/**
 * A single Command that wraps an ordered list of sub-commands so they
 * appear as one entry in undo/redo history.
 *
 * <p>Used by the create-and-position flow in GoalPanel where adding a goal
 * is followed by an immediate move/reposition: without compounding, the
 * user would see two stack entries and have to undo twice to actually
 * remove the goal (the first undo would silently revert the position).
 *
 * <p>Apply runs sub-commands in order; revert runs them in reverse order.
 * If any sub-command fails, the composite returns false but does NOT roll
 * back the partially-applied prefix - the {@link CommandHistory}
 * fail-open contract handles this by dropping the entry from history,
 * leaving the partial state in place.
 */
public final class CompositeCommand implements Command
{
	private final List<Command> children;
	private final String description;

	public CompositeCommand(List<Command> children, String description)
	{
		this.children = children;
		this.description = description != null ? description : "Compound action";
	}

	@Override
	public boolean apply()
	{
		boolean any = false;
		for (Command c : children)
		{
			if (c.apply()) any = true;
		}
		return any;
	}

	@Override
	public boolean revert()
	{
		boolean any = false;
		for (int i = children.size() - 1; i >= 0; i--)
		{
			if (children.get(i).revert()) any = true;
		}
		return any;
	}

	@Override
	public String getDescription()
	{
		return description;
	}
}

package com.goalplanner.command;

/**
 * Wraps another {@link Command} so its apply()/revert() run with persistence
 * suspended, flushing once at the end instead of writing per mutation. Use for
 * bulk commands (e.g. importing many goals/sections) whose undo/redo would
 * otherwise issue one config write per entity - the dominant cost on a large
 * import's undo/redo.
 *
 * <p>The begin/end hooks are passed as Runnables (typically {@code
 * GoalStore::suspendSave} / {@code GoalStore::resumeSave}) so this stays in the
 * command layer without depending on persistence. {@code end} runs in a finally
 * so a throwing inner command can't leave saves permanently suspended.
 */
public final class SaveBatchingCommand implements Command
{
	private final Runnable begin;
	private final Runnable end;
	private final Command inner;

	public SaveBatchingCommand(Runnable begin, Runnable end, Command inner)
	{
		this.begin = begin;
		this.end = end;
		this.inner = inner;
	}

	@Override
	public boolean apply()
	{
		begin.run();
		try
		{
			return inner.apply();
		}
		finally
		{
			end.run();
		}
	}

	@Override
	public boolean revert()
	{
		begin.run();
		try
		{
			return inner.revert();
		}
		finally
		{
			end.run();
		}
	}

	@Override
	public String getDescription()
	{
		return inner.getDescription();
	}
}

package com.goalplanner.data;

import net.runelite.api.gameval.VarbitID;

import java.util.HashMap;
import java.util.Map;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.util.function.IntUnaryOperator;

/**
 * Metadata for achievement diaries: widget IDs, sprite icon, and the
 * (area, tier) → completion-tracking lookup used by DiaryTracker.
 *
 * Widget IDs come from {@code InterfaceID.AreaTask} (group 259).
 *
 * <p>Two tracking modes:
 * <ul>
 *   <li><b>Boolean COMPLETE varbit</b> (most diaries): named
 *       {@code <AREA>_DIARY_<TIER>_COMPLETE} in {@link VarbitID}; flips
 *       0→1 when the tier is finished. Goal stores {@code targetValue=1}.</li>
 *   <li><b>Count varbit + task total</b> (Karamja Easy/Medium/Hard only):
 *       runelite-api doesn't expose boolean completes for these three tiers,
 *       only {@code KARAMJA_*_COUNT} task counters. Completion is detected
 *       by comparing the count against the tier's total task count, stored
 *       on the goal as {@code targetValue=<taskCount>}.</li>
 * </ul>
 */
public final class AchievementDiaryData
{
	private AchievementDiaryData() {}

	// InterfaceID.AreaTask constants - group 259
	public static final int GROUP_ID = 259;
	public static final int TASKBOX = 16973826; // clicked row layer (param1 on right-click)

	// Sprite icon: SpriteID.AchievementDiaryIcons.GREEN_ACHIEVEMENT_DIARIES
	public static final int DIARY_SPRITE_ID = 836;

	public enum Tier
	{
		EASY("Easy"),
		MEDIUM("Medium"),
		HARD("Hard"),
		ELITE("Elite");

		private final String displayName;

		Tier(String displayName) { this.displayName = displayName; }

		public String getDisplayName() { return displayName; }
	}

	/**
	 * Tracking spec for one (area, tier): which varbit to read and what
	 * value indicates completion. {@code requiredValue == 1} for boolean
	 * COMPLETE varbits; for Karamja Easy/Medium/Hard it's the tier's total
	 * task count compared against the {@code KARAMJA_*_COUNT} varbit.
	 */
	public static final class Tracking
	{
		public final int varbitId;
		public final int requiredValue;

		public Tracking(int varbitId, int requiredValue)
		{
			this.varbitId = varbitId;
			this.requiredValue = requiredValue;
		}
	}

	/**
	 * Map of "<AREA>|<TIER>" (uppercase, pipe-separated) to the boolean
	 * completion varbit ID. Karamja Easy/Medium/Hard are absent - those
	 * use {@link #KARAMJA_COUNT_VARBITS} instead.
	 */
	private static final Map<String, Integer> COMPLETION_VARBITS = new HashMap<>();

	/**
	 * Karamja Easy/Medium/Hard: count varbit ID and total task count. The
	 * tier is complete when {@code varbit value >= taskCount}.
	 */
	private static final Map<Tier, Tracking> KARAMJA_COUNT_VARBITS = new HashMap<>();
	static
	{
		KARAMJA_COUNT_VARBITS.put(Tier.EASY,   new Tracking(VarbitID.KARAMJA_EASY_COUNT, 10));
		KARAMJA_COUNT_VARBITS.put(Tier.MEDIUM, new Tracking(VarbitID.KARAMJA_MED_COUNT,  19));
		KARAMJA_COUNT_VARBITS.put(Tier.HARD,   new Tracking(VarbitID.KARAMJA_HARD_COUNT, 10));
	}

	static
	{
		try (InputStream in = AchievementDiaryData.class.getResourceAsStream("diary-completion-varbits.tsv"))
		{
			if (in == null)
			{
				throw new IllegalStateException("missing resource: diary-completion-varbits.tsv");
			}
			try (BufferedReader reader = new BufferedReader(
				new InputStreamReader(in, StandardCharsets.UTF_8)))
			{
				String line;
				while ((line = reader.readLine()) != null)
				{
					if (line.isEmpty()) continue;
					int t = line.indexOf('\t');
					COMPLETION_VARBITS.put(line.substring(0, t), Integer.parseInt(line.substring(t + 1)));
				}
			}
		}
		catch (IOException e)
		{
			throw new UncheckedIOException("failed to load diary-completion-varbits.tsv", e);
		}
	}


	/**
	 * All 12 diary area keys, normalized as used in the varbit map. Every
	 * (area key, tier) pair has a tracking spec, so this enumerates all
	 * {@link #TOTAL_TIER_COUNT} tiers.
	 */
	public static final String[] AREA_KEYS = {
		"ARDOUGNE", "DESERT", "FALADOR", "FREMENNIK", "KANDARIN", "KARAMJA",
		"KOUREND", "LUMBRIDGE", "MORYTANIA", "VARROCK", "WESTERN", "WILDERNESS"
	};

	/** Total diary tiers across all areas (12 areas x 4 tiers = 48). */
	public static final int TOTAL_TIER_COUNT = AREA_KEYS.length * Tier.values().length;

	/**
	 * Count completed diary tiers (0..{@link #TOTAL_TIER_COUNT}) by reading
	 * each tier's tracking varbit through the supplied reader (typically
	 * {@code client::getVarbitValue}). A tier counts as complete when the
	 * varbit has reached the tracking spec's required value - 1 for boolean
	 * COMPLETE varbits, the tier task total for Karamja Easy/Medium/Hard
	 * count varbits.
	 */
	public static int countCompletedTiers(IntUnaryOperator varbitReader)
	{
		int completed = 0;
		for (String area : AREA_KEYS)
		{
			for (Tier tier : Tier.values())
			{
				Tracking t = tracking(area, tier);
				if (t != null && varbitReader.applyAsInt(t.varbitId) >= t.requiredValue)
				{
					completed++;
				}
			}
		}
		return completed;
	}

	/**
	 * Look up the tracking spec (varbit + required value) for a given area
	 * and tier. Returns null when neither a boolean COMPLETE varbit nor a
	 * Karamja count varbit is available (in which case the goal is manual).
	 */
	public static Tracking tracking(String areaDisplayName, Tier tier)
	{
		if (areaDisplayName == null || tier == null) return null;
		String areaKey = normalizeAreaKey(areaDisplayName);
		Integer boolVarbit = COMPLETION_VARBITS.get(areaKey + "|" + tier.name());
		if (boolVarbit != null) return new Tracking(boolVarbit, 1);
		if ("KARAMJA".equals(areaKey)) return KARAMJA_COUNT_VARBITS.get(tier);
		return null;
	}

	/**
	 * Parse the tier out of a diary goal's description (e.g.
	 * "Medium Achievement Diary" → MEDIUM). Returns null if the description
	 * doesn't start with a recognized tier word. Used by the load-time
	 * backfill to recover tier info from existing stored goals.
	 */
	public static Tier parseTierFromDescription(String description)
	{
		if (description == null) return null;
		String trimmed = description.trim();
		int space = trimmed.indexOf(' ');
		String firstWord = (space < 0 ? trimmed : trimmed.substring(0, space)).toUpperCase();
		try { return Tier.valueOf(firstWord); }
		catch (IllegalArgumentException e) { return null; }
	}

	/**
	 * Normalize a display area name into the constant key used in the varbit map.
	 * Handles single-word names ("Desert" → "DESERT") and the few multi-word
	 * aliases used by the diary interface vs. the VarbitID naming.
	 */
	public static String normalizeAreaKey(String displayName)
	{
		if (displayName == null) return "";
		String trimmed = displayName.trim();
		// "Western Provinces" → "WESTERN"
		if (trimmed.equalsIgnoreCase("Western Provinces")) return "WESTERN";
		// "Kourend & Kebos" → "KOUREND"
		if (trimmed.toLowerCase().startsWith("kourend")) return "KOUREND";
		return trimmed.toUpperCase().replace(' ', '_');
	}

	/**
	 * Parse the area display name out of an AreaTask menu entry's option string.
	 * The option looks like "Open &lt;col=ff9040&gt;Desert Journal&lt;/col&gt;" or
	 * "Wiki &lt;col=ff9040&gt;Desert Journal&lt;/col&gt;".
	 *
	 * Returns the trimmed area name (e.g. "Desert") or null if the option doesn't match.
	 */
	public static String parseAreaFromOption(String rawOption)
	{
		if (rawOption == null) return null;
		String stripped = rawOption.replaceAll("<col=[^>]*>", "")
			.replaceAll("</col>", "")
			.trim();
		// Drop leading verb (Open / Wiki / any single word + space)
		int firstSpace = stripped.indexOf(' ');
		if (firstSpace < 0) return null;
		String afterVerb = stripped.substring(firstSpace + 1).trim();
		// Drop trailing " Journal"
		if (afterVerb.toLowerCase().endsWith(" journal"))
		{
			afterVerb = afterVerb.substring(0, afterVerb.length() - " journal".length()).trim();
		}
		return afterVerb.isEmpty() ? null : afterVerb;
	}
}

