import net.runelite.api.Skill;

/**
 * Resolves diary tier requirements against live player state, producing
 * goal templates for unmet requirements. Parallel to
 * {@link QuestRequirementResolver} but for achievement diaries.
 */
public final class DiaryRequirementResolver
{
	private static final int QUEST_SPRITE_ID = 899;

	/** A resolved goal (boss or account) with its own prereq templates
	 *  (e.g. quest prereqs for an account metric like MISC_APPROVAL). */
	public static class ResolvedBossReq
	{
		public final Goal bossTemplate;
		/** Prereq templates (quests, skills) to link to this goal. */
		public final List<Goal> skillTemplates;

		public ResolvedBossReq(Goal bossTemplate, List<Goal> skillTemplates,
			List<ResolvedUnlock> unlockTemplates)
		{
			this.bossTemplate = bossTemplate;
			this.skillTemplates = skillTemplates;
		}
	}

	/** A single alternative path within an unlock (OR-group member). */
	public static class ResolvedAlternative
	{
		public final String label;
		public final List<Goal> skillTemplates;
		public final List<Goal> accountTemplates;
		public final List<Goal> bossTemplates;

		public ResolvedAlternative(String label, List<Goal> skillTemplates,
			List<Goal> accountTemplates)
		{
			this(label, skillTemplates, accountTemplates, List.of());
		}

		public ResolvedAlternative(String label, List<Goal> skillTemplates,
			List<Goal> accountTemplates, List<Goal> bossTemplates)
		{
			this.label = label;
			this.skillTemplates = skillTemplates;
			this.accountTemplates = accountTemplates;
			this.bossTemplates = bossTemplates;
		}
	}

	/** A resolved unlock with its unmet quest, skill, account prereqs, and alternatives. */
	public static class ResolvedUnlock
	{
		public final String name;
		public final List<Goal> questTemplates;
		public final List<Goal> skillTemplates;
		public final List<Goal> accountTemplates;
		/** OR-alternatives. Empty = standard AND-prereqs only. */
		public final List<ResolvedAlternative> alternatives;
		public final int itemId;

		public ResolvedUnlock(String name, List<Goal> questTemplates, int itemId)
		{
			this(name, questTemplates, List.of(), List.of(), List.of(), itemId);
		}

		public ResolvedUnlock(String name, List<Goal> questTemplates,
			List<Goal> skillTemplates, int itemId)
		{
			this(name, questTemplates, skillTemplates, List.of(), List.of(), itemId);
		}

		public ResolvedUnlock(String name, List<Goal> questTemplates,
			List<Goal> skillTemplates, List<Goal> accountTemplates, int itemId)
		{
			this(name, questTemplates, skillTemplates, accountTemplates, List.of(), itemId);
		}

		public ResolvedUnlock(String name, List<Goal> questTemplates,
			List<Goal> skillTemplates, List<Goal> accountTemplates,
			List<ResolvedAlternative> alternatives, int itemId)
		{
			this.name = name;
			this.questTemplates = questTemplates;
			this.skillTemplates = skillTemplates;
			this.accountTemplates = accountTemplates;
			this.alternatives = alternatives;
			this.itemId = itemId;
		}
	}

	/** Resolution result. */
	public static class Resolved
	{
		public final List<Goal> templates;
		public final List<ResolvedUnlock> unlocks;
		public final List<ResolvedBossReq> bossReqs;
		public final int skippedSkills;
		public final int skippedQuests;

		public Resolved(List<Goal> templates, List<ResolvedUnlock> unlocks,
			int skippedSkills, int skippedQuests)
		{
			this(templates, unlocks, List.of(), skippedSkills, skippedQuests);
		}

		public Resolved(List<Goal> templates, List<ResolvedUnlock> unlocks,
			List<ResolvedBossReq> bossReqs, int skippedSkills, int skippedQuests)
		{
			this.templates = templates;
			this.unlocks = unlocks;
			this.bossReqs = bossReqs;
			this.skippedSkills = skippedSkills;
			this.skippedQuests = skippedQuests;
		}

		public boolean isEmpty()
		{
			return templates.isEmpty() && unlocks.isEmpty() && bossReqs.isEmpty();
		}
	}

	/** Production overload: resolve against a live Client. */
	public static Resolved resolve(String area, AchievementDiaryData.Tier tier, Client client)
	{
		return resolve(
			area, tier,
			client::getRealSkillLevel,
			q ->
			{
				try
				{
					return q.getState(client);
				}
				catch (Exception e)
				{
					return null;
				}
			},
			// Live account-metric values, so "Incomplete only" doesn't seed an
			// already-met account requirement (e.g. Warriors' Guild entry =
			// ATT_STR_COMBINED 130) that would auto-complete on the next tick.
			metric -> metric.currentValue(client));
	}

	/**
	 * Core overload with injected lookups (testable without a Client). Defaults
	 * the account lookup to "nothing met" (0), so the floor/"All" path and tests
	 * emit every account requirement.
	 */
	public static Resolved resolve(
		String area,
		AchievementDiaryData.Tier tier,
		ToIntFunction<Skill> skillLevelLookup,
		Function<Quest, QuestState> questStateLookup)
	{
		return resolve(area, tier, skillLevelLookup, questStateLookup, metric -> 0);
	}

	/**
	 * Core overload with an account-metric current-value lookup, used to
	 * pre-filter account requirements the player already meets (mirrors the
	 * skill/quest pre-filtering).
	 */
	public static Resolved resolve(
		String area,
		AchievementDiaryData.Tier tier,
		ToIntFunction<Skill> skillLevelLookup,
		Function<Quest, QuestState> questStateLookup,
		ToIntFunction<com.goalplanner.model.AccountMetric> accountValueLookup)
	{
		DiaryRequirements.Reqs reqs = DiaryRequirements.lookup(area, tier);
		if (reqs == null)
		{
			return new Resolved(List.of(), List.of(), 0, 0);
		}

		List<Goal> templates = new ArrayList<>();
		int skippedSkills = 0;
		int skippedQuests = 0;

		// Sort skills lowest-level-first so the card list reads bottom-to-top
		// (lowest at top = do first, highest at bottom = do last).
		List<DiaryRequirements.SkillReq> sortedSkills = new ArrayList<>(reqs.skills);
		sortedSkills.sort((a, b) -> Integer.compare(a.level, b.level));

		for (DiaryRequirements.SkillReq req : sortedSkills)
		{
			int currentLevel = skillLevelLookup.applyAsInt(req.skill);
			if (currentLevel >= req.level)
			{
				skippedSkills++;
				continue;
			}
			int targetXp = Experience.getXpForLevel(req.level);
			templates.add(Goal.builder()
				.type(GoalType.SKILL)
				.name(req.skill.getName() + " - Level " + req.level)
				.skillName(req.skill.name())
				.targetValue(targetXp)
				.build());
		}

		for (Quest prereq : reqs.prereqQuests)
		{
			QuestState state;
			try
			{
				state = questStateLookup.apply(prereq);
			}
			catch (Exception e)
			{
				state = null;
			}
			if (state == QuestState.FINISHED)
			{
				skippedQuests++;
				continue;
			}
			templates.add(Goal.builder()
				.type(GoalType.QUEST)
				.name(prereq.getName())
				.description("Quest")
				.questName(prereq.name())
				.targetValue(1)
				.spriteId(QUEST_SPRITE_ID)
				.build());
		}

		// Prepare boss req list early so account reqs can add to it too.
		List<ResolvedBossReq> resolvedBossReqs = new ArrayList<>();

		// Account metric requirements (e.g. combined Att+Str 130 for the
		// Warriors' Guild). Pre-filter against the player's live value so
		// "Incomplete only" skips an already-met one (the floor/"All" path
		// passes a 0-lookup, so it still emits everything). Skipping a met
		// metric also drops its quest prereqs - correct, since meeting the
		// metric implies those prereqs are done.
		for (DiaryRequirements.AccountReq accountReq : reqs.accountReqs)
		{
			com.goalplanner.model.AccountMetric metric =
				com.goalplanner.model.AccountMetric.parse(accountReq.metricName);
			if (metric != null && accountValueLookup.applyAsInt(metric) >= accountReq.target)
			{
				continue;
			}

			Goal accountTemplate = Goal.builder()
				.type(GoalType.ACCOUNT)
				.name(accountReq.metricName)
				.accountMetric(accountReq.metricName)
				.targetValue(accountReq.target)
				.build();

			if (accountReq.prereqQuests.isEmpty())
			{
				templates.add(accountTemplate);
			}
			else
			{
				// Account req with quest prereqs - treat like a boss req
				List<Goal> questTemplates = new ArrayList<>();
				for (Quest prereq : accountReq.prereqQuests)
				{
					QuestState state;
					try { state = questStateLookup.apply(prereq); }
					catch (Exception e) { state = null; }
					if (state == QuestState.FINISHED) continue;
					questTemplates.add(Goal.builder()
						.type(GoalType.QUEST)
						.name(prereq.getName())
						.description("Quest")
						.questName(prereq.name())
						.targetValue(1)
						.spriteId(QUEST_SPRITE_ID)
						.build());
				}
				// Use ResolvedBossReq to carry the account goal + quest prereqs
				resolvedBossReqs.add(new ResolvedBossReq(
					accountTemplate, questTemplates, List.of()));
			}
		}

		// Boss kills: all go as plain templates. Boss-specific prereqs
		// (skills, unlocks) are auto-seeded by addBossGoal via BossKillData.
		for (DiaryRequirements.BossReq bossReq : reqs.bossKills)
		{
			templates.add(Goal.builder()
				.type(GoalType.BOSS)
				.name(bossReq.bossName)
				.description(bossReq.killCount + " kills")
				.bossName(bossReq.bossName)
				.targetValue(bossReq.killCount)
				.itemId(BossKillData.getPetItemId(bossReq.bossName))
				.build());
		}

		// Item requirements: create ITEM_GRIND goal templates.
		for (DiaryRequirements.ItemReq itemReq : reqs.itemReqs)
		{
			templates.add(Goal.builder()
				.type(GoalType.ITEM_GRIND)
				.name(itemReq.displayName)
				.itemId(itemReq.itemId)
				.targetValue(itemReq.quantity)
				.build());
		}

		// Unlocks: virtual milestones with their own quest and skill prereq trees.
		// An unlock is considered "met" if ALL its prereq quests are FINISHED
		// and ALL its prereq skills are met.
		List<ResolvedUnlock> resolvedUnlocks = new ArrayList<>();
		for (DiaryRequirements.Unlock unlock : reqs.unlocks)
		{
			boolean allMet = true;
			List<Goal> unlockQuestTemplates = new ArrayList<>();
			for (Quest prereq : unlock.prereqQuests)
			{
				QuestState state;
				try
				{
					state = questStateLookup.apply(prereq);
				}
				catch (Exception e)
				{
					state = null;
				}
				if (state == QuestState.FINISHED)
				{
					continue;
				}
				allMet = false;
				unlockQuestTemplates.add(Goal.builder()
					.type(GoalType.QUEST)
					.name(prereq.getName())
					.description("Quest")
					.questName(prereq.name())
					.targetValue(1)
					.spriteId(QUEST_SPRITE_ID)
					.build());
			}
			List<Goal> unlockSkillTemplates = new ArrayList<>();
			for (DiaryRequirements.SkillReq skillReq : unlock.prereqSkills)
			{
				int currentLevel = skillLevelLookup.applyAsInt(skillReq.skill);
				if (currentLevel >= skillReq.level)
				{
					continue;
				}
				allMet = false;
				int targetXp = Experience.getXpForLevel(skillReq.level);
				unlockSkillTemplates.add(Goal.builder()
					.type(GoalType.SKILL)
					.name(skillReq.skill.getName() + " - Level " + skillReq.level)
					.skillName(skillReq.skill.name())
					.targetValue(targetXp)
					.build());
			}
			List<Goal> unlockAccountTemplates = new ArrayList<>();
			for (DiaryRequirements.AccountReq accountReq : unlock.prereqAccounts)
			{
				// Pre-filter against the live value (floor/"All" path passes a
				// 0-lookup, so it still seeds). A met direct account req no
				// longer forces the unlock to seed.
				com.goalplanner.model.AccountMetric m =
					com.goalplanner.model.AccountMetric.parse(accountReq.metricName);
				if (m != null && accountValueLookup.applyAsInt(m) >= accountReq.target)
				{
					continue;
				}
				allMet = false;
				unlockAccountTemplates.add(Goal.builder()
					.type(GoalType.ACCOUNT)
					.name(accountReq.metricName)
					.accountMetric(accountReq.metricName)
					.targetValue(accountReq.target)
					.build());
			}
			// Alternatives: each is an OR-option. The unlock's alternative gate
			// is satisfied once ANY single alternative is fully met by live
			// state - so a player who already has e.g. 99 Attack for the
			// Warriors' Guild doesn't get the whole OR-block seeded. Boss-KC
			// alternatives can't be checked live, so they never auto-satisfy
			// (seeded conservatively). The floor/"All" path satisfies none, so
			// it seeds every alternative as before.
			List<ResolvedAlternative> resolvedAlternatives = new ArrayList<>();
			boolean anyAltSatisfied = false;
			for (DiaryRequirements.Alternative alt : unlock.alternatives)
			{
				boolean altMet = alt.bosses.isEmpty();
				for (DiaryRequirements.SkillReq sr : alt.skills)
				{
					if (skillLevelLookup.applyAsInt(sr.skill) < sr.level) altMet = false;
				}
				for (DiaryRequirements.AccountReq ar : alt.accounts)
				{
					com.goalplanner.model.AccountMetric m =
						com.goalplanner.model.AccountMetric.parse(ar.metricName);
					if (m == null || accountValueLookup.applyAsInt(m) < ar.target) altMet = false;
				}
				if (altMet)
				{
					anyAltSatisfied = true;
				}
			}
			if (!unlock.alternatives.isEmpty() && !anyAltSatisfied)
			{
				// No alternative met yet - seed them all as OR-options.
				allMet = false;
				for (DiaryRequirements.Alternative alt : unlock.alternatives)
				{
					List<Goal> altSkills = new ArrayList<>();
					for (DiaryRequirements.SkillReq sr : alt.skills)
					{
						int targetXp = Experience.getXpForLevel(sr.level);
						altSkills.add(Goal.builder()
							.type(GoalType.SKILL)
							.name(sr.skill.getName() + " - Level " + sr.level)
							.skillName(sr.skill.name())
							.targetValue(targetXp)
							.build());
					}
					List<Goal> altAccounts = new ArrayList<>();
					for (DiaryRequirements.AccountReq ar : alt.accounts)
					{
						altAccounts.add(Goal.builder()
							.type(GoalType.ACCOUNT)
							.name(ar.metricName)
							.accountMetric(ar.metricName)
							.targetValue(ar.target)
							.build());
					}
					List<Goal> altBosses = new ArrayList<>();
					for (DiaryRequirements.BossReq br : alt.bosses)
					{
						altBosses.add(Goal.builder()
							.type(GoalType.BOSS)
							.name(br.bossName)
							.description(br.killCount + " kills")
							.bossName(br.bossName)
							.targetValue(br.killCount)
							.itemId(BossKillData.getPetItemId(br.bossName))
							.build());
					}
					resolvedAlternatives.add(new ResolvedAlternative(alt.label, altSkills, altAccounts, altBosses));
				}
			}
			if (!allMet)
			{
				resolvedUnlocks.add(new ResolvedUnlock(
					unlock.name, unlockQuestTemplates, unlockSkillTemplates,
					unlockAccountTemplates, resolvedAlternatives, unlock.itemId));
			}
		}

		return new Resolved(templates, resolvedUnlocks, resolvedBossReqs, skippedSkills, skippedQuests);
	}

	private DiaryRequirementResolver() {}
}

package com.goalplanner.data;

import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.ItemID;
import net.runelite.api.Quest;
import net.runelite.api.Skill;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;

/**
 * Pre-defined achievement diary tier requirements (skill levels,
 * quest prerequisites, and unlock milestones). Keyed on
 * "{Area}|{TIER}" strings matching {@link AchievementDiaryData.Tier}.
 *
 * <p><b>Unlocks</b> are virtual milestones like "Fairy Rings" that
 * represent in-game capabilities with their own prerequisite trees.
 * They're seeded as CUSTOM goals with quest requirements attached,
 * replacing misleading quest entries (e.g. Fairytale II when only
 * fairy ring access is needed).
 */
public final class DiaryRequirements
{
	/** A single skill requirement. */
	public static final class SkillReq
	{
		public final Skill skill;
		public final int level;

		public SkillReq(Skill skill, int level)
		{
			this.skill = skill;
			this.level = level;
		}
	}

	/**
	 * A virtual unlock milestone (e.g. "Fairy Rings Unlocked").
	 * Seeded as a CUSTOM goal with quest prerequisites.
	 */
	public static final class Unlock
	{
		public final String name;
		public final List<Quest> prereqQuests;
		public final List<SkillReq> prereqSkills;
		public final List<AccountReq> prereqAccounts;
		/** Alternative paths (OR-group). Empty = no alternatives. */
		public final List<Alternative> alternatives;
		/** Item ID for the icon (e.g. fairy ring POH item). 0 = no icon. */
		public final int itemId;

		public Unlock(String name, List<Quest> prereqQuests, int itemId)
		{
			this(name, prereqQuests, Collections.emptyList(), Collections.emptyList(),
				Collections.emptyList(), itemId);
		}

		public Unlock(String name, List<Quest> prereqQuests, List<SkillReq> prereqSkills, int itemId)
		{
			this(name, prereqQuests, prereqSkills, Collections.emptyList(),
				Collections.emptyList(), itemId);
		}

		public Unlock(String name, List<Quest> prereqQuests, List<SkillReq> prereqSkills,
			List<AccountReq> prereqAccounts, int itemId)
		{
			this(name, prereqQuests, prereqSkills, prereqAccounts,
				Collections.emptyList(), itemId);
		}

		public Unlock(String name, List<Quest> prereqQuests, List<SkillReq> prereqSkills,
			List<AccountReq> prereqAccounts, List<Alternative> alternatives, int itemId)
		{
			this.name = name;
			this.prereqQuests = Collections.unmodifiableList(prereqQuests);
			this.prereqSkills = Collections.unmodifiableList(prereqSkills);
			this.prereqAccounts = Collections.unmodifiableList(prereqAccounts);
			this.alternatives = Collections.unmodifiableList(alternatives);
			this.itemId = itemId;
		}
	}

	/** A boss kill requirement (e.g. 1 Kalphite Queen kill for Desert Hard).
	 *  Boss-specific prereqs (skills, unlocks) are defined in
	 *  {@link BossKillData#getPrereqs} and auto-seeded by addBossGoal. */
	public static final class BossReq
	{
		public final String bossName;
		public final int killCount;

		public BossReq(String bossName, int killCount)
		{
			this.bossName = bossName;
			this.killCount = killCount;
		}
	}

	/** An account metric requirement (e.g. combined Att+Str 130). */
	public static final class AccountReq
	{
		public final String metricName; // AccountMetric enum name
		public final int target;
		public final List<Quest> prereqQuests;

		public AccountReq(String metricName, int target)
		{
			this(metricName, target, Collections.emptyList());
		}

		public AccountReq(String metricName, int target, List<Quest> prereqQuests)
		{
			this.metricName = metricName;
			this.target = target;
			this.prereqQuests = Collections.unmodifiableList(prereqQuests);
		}
	}

	/** An item requirement (e.g. KQ head for Desert Elite). */
	public static final class ItemReq
	{
		public final int itemId;
		public final String displayName;
		public final int quantity;

		public ItemReq(int itemId, String displayName, int quantity)
		{
			this.itemId = itemId;
			this.displayName = displayName;
			this.quantity = quantity;
		}
	}

	/** Full requirement set for a diary tier. */
	public static final class Reqs
	{
		public final List<SkillReq> skills;
		public final List<Quest> prereqQuests;
		public final List<Unlock> unlocks;
		public final List<BossReq> bossKills;
		public final List<ItemReq> itemReqs;
		public final List<AccountReq> accountReqs;

		public Reqs(List<SkillReq> skills, List<Quest> prereqQuests)
		{
			this(skills, prereqQuests, Collections.emptyList(), Collections.emptyList(),
				Collections.emptyList(), Collections.emptyList());
		}

		public Reqs(List<SkillReq> skills, List<Quest> prereqQuests, List<Unlock> unlocks)
		{
			this(skills, prereqQuests, unlocks, Collections.emptyList(),
				Collections.emptyList(), Collections.emptyList());
		}

		public Reqs(List<SkillReq> skills, List<Quest> prereqQuests,
			List<Unlock> unlocks, List<BossReq> bossKills)
		{
			this(skills, prereqQuests, unlocks, bossKills,
				Collections.emptyList(), Collections.emptyList());
		}

		public Reqs(List<SkillReq> skills, List<Quest> prereqQuests,
			List<Unlock> unlocks, List<BossReq> bossKills, List<ItemReq> itemReqs)
		{
			this(skills, prereqQuests, unlocks, bossKills, itemReqs, Collections.emptyList());
		}

		public Reqs(List<SkillReq> skills, List<Quest> prereqQuests,
			List<Unlock> unlocks, List<BossReq> bossKills,
			List<ItemReq> itemReqs, List<AccountReq> accountReqs)
		{
			this.skills = Collections.unmodifiableList(skills);
			this.prereqQuests = Collections.unmodifiableList(prereqQuests);
			this.unlocks = Collections.unmodifiableList(unlocks);
			this.bossKills = Collections.unmodifiableList(bossKills);
			this.itemReqs = Collections.unmodifiableList(itemReqs);
			this.accountReqs = Collections.unmodifiableList(accountReqs);
		}
	}

	// ============================================================
	// Predefined unlocks - reusable across multiple diary areas
	// ============================================================

	/** Fairy rings: requires Fairytale I + Lost City (NOT full Fairytale II). */
	public static final Unlock FAIRY_RINGS = new Unlock(
		"Fairy Rings Unlocked",
		List.of(Quest.FAIRYTALE_I__GROWING_PAINS, Quest.LOST_CITY),
		772); // ItemID.DRAMEN_STAFF

	/**
	 * An alternative path for an unlock. Multiple alternatives form an
	 * OR-group: ANY one being satisfied unlocks the goal.
	 */
	public static final class Alternative
	{
		public final String label;
		public final List<SkillReq> skills;
		public final List<AccountReq> accounts;
		public final List<BossReq> bosses;

		public Alternative(String label, List<SkillReq> skills, List<AccountReq> accounts)
		{
			this(label, skills, accounts, Collections.emptyList());
		}

		public Alternative(String label, List<SkillReq> skills, List<AccountReq> accounts,
			List<BossReq> bosses)
		{
			this.label = label;
			this.skills = Collections.unmodifiableList(skills);
			this.accounts = Collections.unmodifiableList(accounts);
			this.bosses = Collections.unmodifiableList(bosses);
		}
	}

	/** Warriors Guild entry: 130 combined Att+Str OR 99 Attack OR 99 Strength. */
	public static final Unlock WARRIORS_GUILD = new Unlock(
		"Warriors Guild Entry",
		List.of(), // no shared quest prereqs
		List.of(), // no shared skill prereqs
		List.of(), // no shared account prereqs
		List.of(
			new Alternative("Att+Str Combined >= 130",
				List.of(), List.of(new AccountReq("ATT_STR_COMBINED", 130))),
			new Alternative("99 Attack",
				List.of(new SkillReq(Skill.ATTACK, 99)), List.of()),
			new Alternative("99 Strength",
				List.of(new SkillReq(Skill.STRENGTH, 99)), List.of())
		),
		ItemID.STEEL_DEFENDER);

	/** Mith grapple: requires 59 Fletching + 59 Smithing to craft. */
	public static final Unlock MITH_GRAPPLE = new Unlock(
		"Mith Grapple",
		List.of(), // no quest prereqs
		List.of(new SkillReq(Skill.FLETCHING, 59), new SkillReq(Skill.SMITHING, 59)),
		ItemID.MITH_GRAPPLE);


	private static final Map<String, Reqs> TABLE = new HashMap<>();

	private static String key(String area, AchievementDiaryData.Tier tier)
	{
		return area + "|" + tier.name();
	}

	/**
	 * Look up the requirements for a diary tier.
	 *
	 * @return the requirements, or {@code null} if not in the table
	 */
	public static Reqs lookup(String area, AchievementDiaryData.Tier tier)
	{
		if (area == null || tier == null) return null;
		return TABLE.get(key(area, tier));
	}

	/** True iff the diary tier has non-empty requirements. */
	public static boolean hasRequirements(String area, AchievementDiaryData.Tier tier)
	{
		Reqs r = lookup(area, tier);
		if (r == null) return false;
		return !r.skills.isEmpty() || !r.prereqQuests.isEmpty() || !r.unlocks.isEmpty();
	}

	// ============================================================
	// Wiki-sourced diary requirements (2026-04-11), loaded from
	// diary-requirements.json at plugin start-up via the injected
	// client Gson - see GoalPlannerPlugin.startUp().
	// ============================================================

	private static volatile boolean loaded;

	/**
	 * Loads the diary requirement table from its bundled JSON resource.
	 * Idempotent and thread-safe; the first caller wins and subsequent
	 * calls are no-ops. Pass the client's injected {@link com.google.gson.Gson}
	 * (the plugin must never create its own - the hub forbids it).
	 */
	public static void init(com.google.gson.Gson gson)
	{
		if (loaded)
		{
			return;
		}
		synchronized (DiaryRequirements.class)
		{
			if (loaded)
			{
				return;
			}
			try (InputStream in = DiaryRequirements.class.getResourceAsStream("diary-requirements.json"))
			{
				if (in == null)
				{
					throw new IllegalStateException("missing resource: diary-requirements.json");
				}
				try (Reader reader = new InputStreamReader(in, StandardCharsets.UTF_8))
				{
					TABLE.putAll(gson.fromJson(reader,
						new com.google.gson.reflect.TypeToken<Map<String, Reqs>>(){}.getType()));
				}
			}
			catch (IOException e)
			{
				throw new UncheckedIOException("failed to load diary-requirements.json", e);
			}
			loaded = true;
		}
	}

	private DiaryRequirements() {}
}

package com.goalplanner.data;

import com.goalplanner.model.ItemTag;
import com.goalplanner.model.TagCategory;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import net.runelite.client.game.ItemVariationMapping;
import java.util.Locale;
import java.util.Map;

/**
 * Answers "what repeatable activity drops this item?" by joining the two
 * reference tables the plugin already ships: {@link ItemSourceData}
 * ({@code itemId -> source label -> category}) and {@link BossKillData}
 * ({@code boss name -> kill-count varp}).
 *
 * <p>This is what lets an item goal spawn a repeatable activity goal - "you
 * want a Bandos chestplate, so kill General Graardor 20 times today".
 *
 * <p>Two joins are deliberately lossy and it matters which:
 * <ul>
 *   <li>Only grindable categories resolve. Roughly half of all item rows are
 *       {@link TagCategory#OTHER} - shop items, skilling drops, one-offs - and
 *       a bronze bar has no boss to farm. Callers must treat an empty result
 *       as "no menu entry", not as an error.</li>
 *   <li>Source labels and boss names are two vocabularies that mostly, but not
 *       always, agree. {@link #matchActivities} reconciles the mechanical
 *       differences (case, a leading "The", the collection-log alias table's
 *       one-to-many splits like Perilous Moons); anything left over is a real
 *       data gap rather than a naming one.</li>
 * </ul>
 */
public final class ItemActivityResolver
{
	private ItemActivityResolver() {}

	/** A trackable activity: a boss name plus the varp holding its kill count. */
	public static final class Activity
	{
		private final String name;
		private final int varpId;

		Activity(String name, int varpId)
		{
			this.name = name;
			this.varpId = varpId;
		}

		public String getName() { return name; }

		public int getVarpId() { return varpId; }

		@Override
		public String toString() { return name + " (varp " + varpId + ")"; }
	}

	/**
	 * Categories worth offering a repeatable goal for.
	 *
	 * <p>SKILLING and QUEST are excluded by design: a skilling drop is better
	 * served by an XP chunk off the skill goal, and a quest happens once.
	 *
	 * <p>MINIGAME is excluded by CIRCUMSTANCE, not design, and should be added
	 * back. Measured: all 22 minigame source labels (Pest Control, Mahogany
	 * Homes, Tithe Farm, Barbarian Assault, ...) resolve to nothing, because
	 * minigames have no row in boss-killcount.tsv - their completion counters
	 * are the 19 {@code collection_minigames_*_completed} varbits, which the
	 * plugin does not read yet. Including the category before those are wired
	 * would offer menu entries that produce untrackable goals.
	 */
	private static boolean isGrindable(TagCategory category)
	{
		return category == TagCategory.BOSS
			|| category == TagCategory.RAID;
	}

	/**
	 * Source labels naming a GROUP of bosses that share one collection-log
	 * entry. The generic " and " split below handles the wilderness pairs;
	 * these are the ones whose group name shares no words with its members.
	 * Every target verified present in boss-killcount.tsv by test.
	 */
	private static final Map<String, String[]> GROUP_LABELS =
		Map.of(
			"Dagannoth Kings",
			new String[]{"Dagannoth Prime", "Dagannoth Rex", "Dagannoth Supreme"},
			"Moons of Peril",
			new String[]{"Blue Moon", "Blood Moon", "Eclipse Moon"});

	/**
	 * Every trackable activity that drops {@code itemId}, in source order and
	 * de-duplicated. Empty when the item has no grindable source or its source
	 * has no kill-count varp - both are ordinary outcomes, not failures.
	 */
	public static List<Activity> resolve(int itemId)
	{
		// Variant mapping FIRST. Chargeable and degradable items are stored
		// under one variant in item-sources (Scythe of vitur is 22324, not the
		// charged 22325), so skipping this silently returns nothing for exactly
		// the high-value items a player is most likely to be grinding for.
		int base = ItemVariationMapping.map(itemId);
		List<ItemTag> tags = ItemSourceData.getTags(base);
		if (tags.isEmpty() && base != itemId)
		{
			tags = ItemSourceData.getTags(itemId);
		}

		List<Activity> out = new ArrayList<>();
		Set<String> seen = new LinkedHashSet<>();
		for (ItemTag tag : tags)
		{
			if (!isGrindable(tag.getCategory()))
			{
				continue;
			}
			for (String bossName : matchActivities(tag.getLabel()))
			{
				if (seen.add(bossName))
				{
					out.add(new Activity(bossName, BossKillData.getVarpId(bossName)));
				}
			}
		}
		return out;
	}

	/** True when {@code itemId} has at least one trackable activity. */
	public static boolean hasActivity(int itemId)
	{
		return !resolve(itemId).isEmpty();
	}

	/**
	 * Reconcile one source label against the boss-name vocabulary, returning
	 * every boss it corresponds to. One label can legitimately mean several
	 * bosses - "Dagannoth Kings" is three, "Perilous Moons" is four - so the
	 * return is a list, and a caller offering a menu shows one entry per boss.
	 */
	static List<String> matchActivities(String label)
	{
		List<String> out = new ArrayList<>();
		if (label == null || label.isEmpty())
		{
			return out;
		}

		// 1. Exact name. The common case: ~three quarters of source labels are
		//    already spelled the way boss-killcount spells them.
		if (BossKillData.isKnownBoss(label))
		{
			out.add(label);
			return out;
		}

		// 2. The collection-log alias table, which already encodes the
		//    one-to-many splits (raid tiers, Perilous Moons, Nightmare variants).
		List<String> aliased = BossKillData.resolveCollectionLogName(label);
		if (aliased != null)
		{
			for (String name : aliased)
			{
				if (BossKillData.isKnownBoss(name))
				{
					out.add(name);
				}
			}
			if (!out.isEmpty())
			{
				return out;
			}
		}

		// 3. Named groups whose label shares no words with its members.
		String[] group = GROUP_LABELS.get(label);
		if (group != null)
		{
			for (String name : group)
			{
				if (BossKillData.isKnownBoss(name))
				{
					out.add(name);
				}
			}
			if (!out.isEmpty())
			{
				return out;
			}
		}

		// 4. Mechanical spelling differences: case, and a leading article that
		//    one table carries and the other does not ("The Hueycoatl").
		for (String candidate : BossKillData.getBossNames())
		{
			if (normalize(candidate).equals(normalize(label)))
			{
				out.add(candidate);
				return out;
			}
		}

		// 5. Wilderness bosses share one collection-log entry with their
		//    singles-plus counterpart ("Callisto and Artio"). Split and match
		//    each half rather than enumerating every pair by hand.
		if (label.contains(" and "))
		{
			for (String half : label.split(" and "))
			{
				String trimmed = half.trim();
				if (BossKillData.isKnownBoss(trimmed))
				{
					out.add(trimmed);
				}
			}
		}
		return out;
	}

	/** Lowercase, strip a leading "the ", collapse to alphanumerics. */
	private static String normalize(String s)
	{
		String t = s.toLowerCase(Locale.ROOT).trim();
		if (t.startsWith("the "))
		{
			t = t.substring(4);
		}
		return t.replaceAll("[^a-z0-9]", "");
	}
}

package com.goalplanner.data;

import com.goalplanner.model.ItemTag;
import com.goalplanner.model.TagCategory;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Maps item IDs to their drop sources (boss / raid / clue / minigame), used to
 * auto-seed source tags on collection-log item goals.
 *
 * <p>The data - 3,785 (itemId, source, category) rows covering inventory,
 * noted, collection-log, and follower item variants, generated from the OSRS
 * Wiki Collection Log - lives in the {@code item-sources.tsv} resource beside
 * this class rather than inline, and is loaded once into {@link #SOURCES} on
 * class init. Format: {@code itemId<TAB>label<TAB>TagCategory} per line.
 */
public final class ItemSourceData
{
	private ItemSourceData() {}

	private static final String RESOURCE = "item-sources.tsv";
	private static final Map<Integer, List<ItemTag>> SOURCES = new HashMap<>();

	public static List<ItemTag> getTags(int itemId)
	{
		return SOURCES.getOrDefault(itemId, Collections.emptyList());
	}

	private static void source(int itemId, String label, TagCategory category)
	{
		SOURCES.computeIfAbsent(itemId, k -> new ArrayList<>()).add(new ItemTag(label, category));
	}

	static
	{
		try (InputStream in = ItemSourceData.class.getResourceAsStream(RESOURCE))
		{
			if (in == null)
			{
				throw new IllegalStateException("missing resource: " + RESOURCE);
			}
			try (BufferedReader r = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
			{
				String line;
				while ((line = r.readLine()) != null)
				{
					if (line.isEmpty())
					{
						continue;
					}
					// itemId \t label \t category - labels never contain tabs.
					int t1 = line.indexOf('\t');
					int t2 = line.indexOf('\t', t1 + 1);
					int itemId = Integer.parseInt(line.substring(0, t1));
					String label = line.substring(t1 + 1, t2);
					TagCategory category = TagCategory.valueOf(line.substring(t2 + 1));
					source(itemId, label, category);
				}
			}
		}
		catch (IOException e)
		{
			throw new UncheckedIOException("failed to load " + RESOURCE, e);
		}
	}
}

package com.goalplanner.data;

import com.goalplanner.model.Goal;
import com.goalplanner.model.GoalType;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Function;
import java.util.function.IntSupplier;
import java.util.function.ToIntFunction;
import net.runelite.api.Client;
import net.runelite.api.Experience;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import java.util.HashSet;
import java.util.Set;

/**
 * Resolves a {@link QuestRequirements.Reqs} entry into concrete goal
 * templates, filtering out any requirement the player already meets.
 *
 * <p>Split from {@code GoalPlannerApiImpl} so the API layer stays free
 * of {@link Client} dependencies - the API receives pre-filtered
 * templates and doesn't know or care about live player state. The
 * resolver lives next to {@link QuestRequirements} because its output
 * shape is dictated by that data.
 *
 * <p><b>Lookup injection.</b> The core {@link #resolve(Quest, ToIntFunction,
 * Function)} overload takes functional lookups so tests can fake
 * player state without mocking {@link Quest#getState(Client)} (which
 * is a final method reading a varp - painful to stub without
 * mockito-inline). Production code uses the {@link #resolve(Quest,
 * Client)} convenience overload which builds the lambdas from a live
 * {@link Client}.
 *
 * <p><b>Skipping rules.</b>
 * <ul>
 *   <li><b>Skill req</b>: skipped if {@code skillLevelLookup} returns
 *       a value &gt;= the required level. The "real" (unboosted) level
 *       is used because skill goals target base XP, not boosted XP.</li>
 *   <li><b>Quest prereq</b>: skipped if {@code questStateLookup}
 *       returns {@link QuestState#FINISHED}. Any {@link Exception}
 *       thrown during lookup is treated as "not finished" (defensive).</li>
 *   <li><b>Quest points / combat level / kudos</b>: resolved to
 *       {@code GoalType.ACCOUNT} goal templates.</li>
 * </ul>
 */
public final class QuestRequirementResolver
{
	/** Sprite id for the blue quest book icon. Mirrors
	 *  {@code GoalPlannerApiImpl.QUEST_SPRITE_ID} - kept as a local
	 *  constant to avoid a dependency on the api package. */
	private static final int QUEST_SPRITE_ID = 899;


	/** Output of {@link #resolve}. */
	public static final class Resolved
	{
		/** Goal templates to feed into {@code findOrCreateRequirement}. */
		public final List<Goal> templates;
		/** Count of skill reqs skipped because the player already meets the level. */
		public final int skippedSkills;
		/** Count of quest prereqs skipped because the player already finished them. */
		public final int skippedQuests;
		/** Quest-point requirement from the data table (0 = none). Not turned
		 *  into a template - stubbed until QP goals ship. */
		public final int stubbedQuestPoints;
		/** Combat-level requirement from the data table (0 = none). Not turned
		 *  into a template - stubbed until combat-level goals ship. */
		public final int stubbedCombatLevel;

		public Resolved(List<Goal> templates, int skippedSkills, int skippedQuests,
			int stubbedQuestPoints, int stubbedCombatLevel)
		{
			this.templates = templates;
			this.skippedSkills = skippedSkills;
			this.skippedQuests = skippedQuests;
			this.stubbedQuestPoints = stubbedQuestPoints;
			this.stubbedCombatLevel = stubbedCombatLevel;
		}

		/** True iff there's nothing for the caller to do - no templates AND
		 *  no QP / combat-level stub. The secondary menu entry uses this
		 *  to decide whether to render. */
		public boolean isEmpty()
		{
			return templates.isEmpty() && stubbedQuestPoints == 0 && stubbedCombatLevel == 0;
		}
	}

	/**
	 * Production overload: resolve against a live RuneLite {@link Client}.
	 */
	public static Resolved resolve(Quest quest, Client client)
	{
		return resolve(
			quest,
			client::getRealSkillLevel,
			q ->
			{
				try
				{
					return q.getState(client);
				}
				catch (Exception e)
				{
					return null;
				}
			},
			() ->
			{
				net.runelite.api.Player p = client.getLocalPlayer();
				return p != null ? p.getCombatLevel() : 0;
			},
			// Live current values for the hard account-metric requirements, so
			// "Incomplete only" doesn't seed a QP/combat/Kudos goal the player
			// already meets (it would auto-complete on the next tick - the bug
			// this closes). currentValue covers every metric generically.
			metric -> metric.currentValue(client));
	}

	/**
	 * Backwards-compatible 3-arg overload for tests that don't care
	 * about the recommended-combat-level filter. Defaults the combat
	 * level to 3 (fresh account) - matches the semantic "no boosts,
	 * lowest plausible value". New tests that want to exercise the
	 * recommended-combat pre-filter should use the 4-arg overload.
	 */
	public static Resolved resolve(
		Quest quest,
		ToIntFunction<Skill> skillLevelLookup,
		Function<Quest, QuestState> questStateLookup)
	{
		return resolve(quest, skillLevelLookup, questStateLookup, () -> 3);
	}

	/**
	 * Core overload: resolve using injected lookups. Tests use this
	 * directly with fake lookups.
	 *
	 * @param quest             quest to look up in {@link QuestRequirements}
	 * @param skillLevelLookup  maps a {@link Skill} to the player's current
	 *                          unboosted level
	 * @param questStateLookup  maps a prereq {@link Quest} to the player's
	 *                          current {@link QuestState}; may return null
	 * @param combatLevelLookup supplies the player's current combat level;
	 *                          used to pre-filter recommended-combat-level
	 *                          templates so already-met recommendations
	 *                          don't seed as pre-completed cards
	 */
	public static Resolved resolve(
		Quest quest,
		ToIntFunction<Skill> skillLevelLookup,
		Function<Quest, QuestState> questStateLookup,
		IntSupplier combatLevelLookup)
	{
		// Default account lookup = "nothing met" (0), so the floor-based "All"
		// path and existing tests emit every account requirement. The live
		// (client) path supplies real current values to pre-filter met ones.
		return resolve(quest, skillLevelLookup, questStateLookup, combatLevelLookup,
			metric -> 0);
	}

	/**
	 * Core overload with an account-metric current-value lookup, used to
	 * pre-filter hard QP / combat / Kudos requirements the player already
	 * meets (mirrors the skill/quest pre-filtering). {@code accountValueLookup}
	 * returns the player's current value for a metric, or 0 to treat it as
	 * unmet (emit the requirement).
	 */
	public static Resolved resolve(
		Quest quest,
		ToIntFunction<Skill> skillLevelLookup,
		Function<Quest, QuestState> questStateLookup,
		IntSupplier combatLevelLookup,
		ToIntFunction<com.goalplanner.model.AccountMetric> accountValueLookup)
	{
		QuestRequirements.Reqs reqs = QuestRequirements.lookup(quest);
		if (reqs == null)
		{
			return new Resolved(List.of(), 0, 0, 0, 0);
		}

		List<Goal> templates = new ArrayList<>();
		int skippedSkills = 0;
		int skippedQuests = 0;

		for (QuestRequirements.SkillReq req : reqs.skills)
		{
			int currentLevel = skillLevelLookup.applyAsInt(req.skill);
			if (currentLevel >= req.level)
			{
				skippedSkills++;
				continue;
			}
			int targetXp = Experience.getXpForLevel(req.level);
			templates.add(Goal.builder()
				.type(GoalType.SKILL)
				.name(req.skill.getName() + " - Level " + req.level)
				.skillName(req.skill.name())
				.targetValue(targetXp)
				.build());
		}

		for (Quest prereq : reqs.prereqQuests)
		{
			QuestState state;
			try
			{
				state = questStateLookup.apply(prereq);
			}
			catch (Exception e)
			{
				state = null;
			}
			if (state == QuestState.FINISHED)
			{
				skippedQuests++;
				continue;
			}
			// Mirrors GoalPlannerApiImpl.addQuestGoal: set the blue quest
			// book sprite so the card shows the proper icon instead of
			// the GoalType default color dot.
			templates.add(Goal.builder()
				.type(GoalType.QUEST)
				.name(prereq.getName())
				.description("Quest")
				.questName(prereq.name())
				.targetValue(1)
				.spriteId(QUEST_SPRITE_ID)
				.build());
		}

		// Account-wide requirements: QP, combat level, and Kudos as real ACCOUNT
		// goal templates. Pre-filtered against the player's current value (like
		// skills/quests above) so "Incomplete only" never seeds an already-met
		// account requirement that would auto-complete on the next tracker tick.
		// The "All" / test paths pass a 0-lookup, so nothing is filtered there.
		if (reqs.questPoints > 0
			&& accountValueLookup.applyAsInt(com.goalplanner.model.AccountMetric.QUEST_POINTS) < reqs.questPoints)
		{
			templates.add(Goal.builder()
				.type(GoalType.ACCOUNT)
				.name(reqs.questPoints + " Quest Points")
				.accountMetric(com.goalplanner.model.AccountMetric.QUEST_POINTS.name())
				.targetValue(reqs.questPoints)
				.build());
		}
		// Hard combat gate. Filtered via the ACCOUNT lookup (not combatLevelLookup),
		// so the floor/"All" path - which passes a 0-lookup - always emits it
		// (a hard gate stays visible), while the live "Incomplete only" path,
		// which supplies the real combat level, skips it once met.
		if (reqs.combatLevel > 0
			&& accountValueLookup.applyAsInt(com.goalplanner.model.AccountMetric.COMBAT_LEVEL) < reqs.combatLevel)
		{
			templates.add(Goal.builder()
				.type(GoalType.ACCOUNT)
				.name(reqs.combatLevel + " Combat Level")
				.accountMetric(com.goalplanner.model.AccountMetric.COMBAT_LEVEL.name())
				.targetValue(reqs.combatLevel)
				.build());
		}
		if (reqs.kudos > 0
			&& accountValueLookup.applyAsInt(com.goalplanner.model.AccountMetric.KUDOS) < reqs.kudos)
		{
			templates.add(Goal.builder()
				.type(GoalType.ACCOUNT)
				.name(reqs.kudos + " Museum Kudos")
				.accountMetric(com.goalplanner.model.AccountMetric.KUDOS.name())
				.targetValue(reqs.kudos)
				.build());
		}

		// Recommended combat level (wiki suggestion) - seeded as optional.
		// Only added when there's no hard combat level requirement (which
		// takes precedence and is already added above as non-optional),
		// AND the player's current combat level is below the recommendation.
		// Pre-filtering here (rather than relying on isComplete after
		// creation) prevents the "already-met recommendation ships as a
		// pre-completed card" bug - a freshly-created ACCOUNT goal has
		// currentValue=0 so the post-creation isComplete check misses.
		if (reqs.combatLevel == 0)
		{
			int recommended = QuestRequirements.recommendedCombatLevel(quest);
			if (recommended > 0 && combatLevelLookup.getAsInt() < recommended)
			{
				templates.add(Goal.builder()
					.type(GoalType.ACCOUNT)
					.name(recommended + " Combat Level (recommended)")
					.accountMetric(com.goalplanner.model.AccountMetric.COMBAT_LEVEL.name())
					.targetValue(recommended)
					.optional(true)
					.build());
			}
		}

		// Recommended skills (wiki suggestions) - seeded as optional.
		// Only added for skills not already in the hard requirements.
		Set<String> hardSkillNames = new HashSet<>();
		for (QuestRequirements.SkillReq req : reqs.skills)
		{
			hardSkillNames.add(req.skill.name());
		}
		for (QuestRequirements.SkillReq rec : QuestRequirements.recommendedSkills(quest))
		{
			if (hardSkillNames.contains(rec.skill.name())) continue;
			int currentLevel = skillLevelLookup.applyAsInt(rec.skill);
			if (currentLevel >= rec.level) continue;
			int targetXp = Experience.getXpForLevel(rec.level);
			templates.add(Goal.builder()
				.type(GoalType.SKILL)
				.name(rec.skill.getName() + " - Level " + rec.level + " (recommended)")
				.skillName(rec.skill.name())
				.targetValue(targetXp)
				.optional(true)
				.build());
		}

		return new Resolved(templates, skippedSkills, skippedQuests, reqs.questPoints, reqs.combatLevel);
	}

	private QuestRequirementResolver() {}
}

package com.goalplanner.data;

import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Quest;
import net.runelite.api.Skill;
import java.io.IOException;
import java.io.UncheckedIOException;
import java.util.EnumSet;
import java.util.Set;

/**
 * Pre-defined quest → requirement associations.
 *
 * <p>Keyed on the RuneLite {@link Quest} enum - the same identity the
 * plugin uses in {@code Goal.questName} - so no string plumbing is
 * needed at the consumer. Consumed by the "Add Goal with Requirements"
 * flow in {@code GoalPlannerApiImpl.addQuestGoalWithPrereqs}, which
 * feeds each entry through {@code findOrCreateRequirement} inside a
 * compound command.
 *
 * <p><b>Coverage.</b> This table covers all 211 quests in the
 * RuneLite {@link Quest} enum. Requirements are wiki-sourced.
 *
 * <p><b>Account-wide requirements.</b> Quest points, combat level,
 * and museum kudos are recorded as numeric fields on {@link Reqs} and
 * resolved into {@code GoalType.ACCOUNT} goal templates by the
 * {@link QuestRequirementResolver}.
 */
@Slf4j
public final class QuestRequirements
{
	/** {@link Quest#valueOf} but null instead of throwing on a constant this
	 *  RuneLite API version doesn't have (a forward-declared new quest). */
	private static Quest questOrNull(String name)
	{
		try
		{
			return Quest.valueOf(name);
		}
		catch (IllegalArgumentException e)
		{
			return null;
		}
	}

	/** A single skill requirement (skill + minimum level). */
	public static final class SkillReq
	{
		public final Skill skill;
		public final int level;

		public SkillReq(Skill skill, int level)
		{
			this.skill = skill;
			this.level = level;
		}
	}

	/** The full requirement set for a quest. Any field may be empty. */
	public static final class Reqs
	{
		public final List<SkillReq> skills;
		public final List<Quest> prereqQuests;
		/** Minimum total quest points required. 0 = none. */
		public final int questPoints;
		/** Minimum combat level required. 0 = none. */
		public final int combatLevel;
		/** Minimum museum kudos required. 0 = none. */
		public final int kudos;
		public Reqs(List<SkillReq> skills, List<Quest> prereqQuests, int questPoints, int combatLevel)
		{
			this(skills, prereqQuests, questPoints, combatLevel, 0);
		}

		public Reqs(List<SkillReq> skills, List<Quest> prereqQuests, int questPoints, int combatLevel, int kudos)
		{
			this.skills = Collections.unmodifiableList(skills);
			this.prereqQuests = Collections.unmodifiableList(prereqQuests);
			this.questPoints = questPoints;
			this.combatLevel = combatLevel;
			this.kudos = kudos;
		}
	}

	private static final Map<Quest, Reqs> TABLE = new EnumMap<>(Quest.class);

	/** Miniquests - 0 QP, shorter, different description in the goal card. */
	private static final Set<Quest> MINIQUESTS = EnumSet.noneOf(Quest.class);

	/** The complete set of F2P quests, used to auto-tag quest goals. */
	private static final Set<Quest> F2P_QUESTS = EnumSet.noneOf(Quest.class);

	// ============================================================
	// XP reward tags: skills that a quest rewards XP in (fixed
	// rewards only - choice lamps are excluded).
	// ============================================================
	private static final Map<Quest, List<Skill>> XP_REWARDS = new EnumMap<>(Quest.class);

	// ============================================================
	// Quest point rewards
	// ============================================================
	private static final Map<Quest, Integer> QP_REWARDS = new EnumMap<>(Quest.class);

	/** Quests that reward an XP lamp (choice-based, not fixed skill). */
	private static final Set<Quest> LAMP_REWARD_QUESTS = EnumSet.noneOf(Quest.class);

	// ============================================================
	// Recommended skills (wiki-sourced suggestions, not hard
	// requirements). Seeded as optional goals.
	// ============================================================
	private static final Map<Quest, List<SkillReq>> RECOMMENDED_SKILLS = new EnumMap<>(Quest.class);

	// ============================================================
	// Recommended combat levels (wiki-sourced suggestions, not hard
	// requirements). Seeded as optional goals.
	// ============================================================
	private static final Map<Quest, Integer> RECOMMENDED_COMBAT = new EnumMap<>(Quest.class);

	// ============================================================
	// Display names - short labels for quests whose RuneLite enum
	// name is too long for tags or UI labels. Falls back to
	// Quest.getName() when not overridden.
	// ============================================================
	private static final Map<Quest, String> DISPLAY_NAMES = new EnumMap<>(Quest.class);

	/**
	 * Short display name for a quest, suitable for tags and UI labels.
	 * Falls back to {@code quest.getName()} if no override is defined.
	 */
	public static String displayName(Quest quest)
	{
		if (quest == null) return null;
		return DISPLAY_NAMES.getOrDefault(quest, quest.getName());
	}

	private static void put(Quest quest, List<SkillReq> skills, List<Quest> prereqQuests,
		int questPoints, int combatLevel)
	{
		TABLE.put(quest, new Reqs(skills, prereqQuests, questPoints, combatLevel));
	}

	/**
	 * Look up the requirements for a quest.
	 *
	 * @return the requirements, or {@code null} if this quest is not in
	 *         the data table. A null return means "no data", not "no
	 *         requirements" - an empty {@link Reqs} is used to express
	 *         the latter (see {@link Quest#COOKS_ASSISTANT}).
	 */
	public static Reqs lookup(Quest quest)
	{
		if (quest == null) return null;
		return TABLE.get(quest);
	}

	/**
	 * Skills that a quest rewards fixed XP in. Returns an empty list
	 * for quests with no fixed XP rewards or quests not in the table.
	 * Choice lamps are excluded.
	 */
	public static List<Skill> xpRewards(Quest quest)
	{
		if (quest == null) return Collections.emptyList();
		return XP_REWARDS.getOrDefault(quest, Collections.emptyList());
	}

	/**
	 * Recommended skills for a quest (wiki suggestions, not hard requirements).
	 * Seeded as optional goals. Returns an empty list if none.
	 */
	public static List<SkillReq> recommendedSkills(Quest quest)
	{
		if (quest == null) return Collections.emptyList();
		return RECOMMENDED_SKILLS.getOrDefault(quest, Collections.emptyList());
	}

	/**
	 * Recommended combat level for a quest (wiki suggestion), or 0 if none.
	 * Not a hard requirement - seeded as an optional goal.
	 */
	public static int recommendedCombatLevel(Quest quest)
	{
		if (quest == null) return 0;
		return RECOMMENDED_COMBAT.getOrDefault(quest, 0);
	}

	/**
	 * Quest point reward for a quest, or 0 if not in the table.
	 */
	public static int questPointReward(Quest quest)
	{
		if (quest == null) return 0;
		return QP_REWARDS.getOrDefault(quest, 0);
	}

	/** True iff the quest rewards an XP lamp (choice-based). */
	public static boolean rewardsLamp(Quest quest)
	{
		return quest != null && LAMP_REWARD_QUESTS.contains(quest);
	}

	/** True iff the quest is free-to-play. */
	/** True iff the quest is a miniquest (not a full quest). */
	public static boolean isMiniquest(Quest quest)
	{
		return quest != null && MINIQUESTS.contains(quest);
	}

	public static boolean isF2P(Quest quest)
	{
		return quest != null && F2P_QUESTS.contains(quest);
	}

	/** True iff the quest has a non-empty requirements entry. */
	public static boolean hasRequirements(Quest quest)
	{
		Reqs r = lookup(quest);
		if (r == null) return false;
		return !r.skills.isEmpty() || !r.prereqQuests.isEmpty()
			|| r.questPoints > 0 || r.combatLevel > 0 || r.kudos > 0
			|| recommendedCombatLevel(quest) > 0
			|| !recommendedSkills(quest).isEmpty();
	}

	static
	{
		try (InputStream in = QuestRequirements.class.getResourceAsStream("quest-requirements.tsv"))
		{
			if (in == null)
			{
				throw new IllegalStateException("missing resource: quest-requirements.tsv");
			}
			try (BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
			{
				String line;
				while ((line = reader.readLine()) != null)
				{
					if (line.isEmpty())
					{
						continue;
					}
					// quest \t skills \t prereqs \t questPoints \t combatLevel
					//   \t xpRewards \t qpReward \t recSkills \t recCombat \t displayOverride \t flags(M=mini,F=f2p,L=lamp)
					String[] f = line.split("\t", -1);
					// A row may name a quest the current RuneLite API doesn't ship
					// yet (a just-released quest forward-declared here before the
					// dependency bump). Skip it rather than throwing and taking the
					// whole table down; it activates automatically once the enum lands.
					Quest quest = questOrNull(f[0]);
					if (quest == null)
					{
						log.debug("quest-requirements.tsv: skipping unknown Quest '{}' (not in this RuneLite API version)", f[0]);
						continue;
					}

					List<Quest> prereqs = new ArrayList<>();
					if (!f[2].isEmpty())
					{
						for (String pq : f[2].split(";"))
						{
							Quest p = questOrNull(pq);
							if (p != null)
							{
								prereqs.add(p);
							}
							else
							{
								log.debug("quest-requirements.tsv: {} lists unknown prerequisite '{}' - skipped", f[0], pq);
							}
						}
					}
					put(quest, parseSkillReqs(f[1]), prereqs,
						Integer.parseInt(f[3]), Integer.parseInt(f[4]));

					if (f.length > 5 && !f[5].isEmpty())
					{
						List<Skill> xp = new ArrayList<>();
						for (String s : f[5].split(";"))
						{
							xp.add(Skill.valueOf(s));
						}
						XP_REWARDS.put(quest, xp);
					}
					if (f.length > 6 && !f[6].isEmpty() && Integer.parseInt(f[6]) > 0)
					{
						QP_REWARDS.put(quest, Integer.parseInt(f[6]));
					}
					if (f.length > 7 && !f[7].isEmpty())
					{
						RECOMMENDED_SKILLS.put(quest, parseSkillReqs(f[7]));
					}
					if (f.length > 8 && !f[8].isEmpty() && Integer.parseInt(f[8]) > 0)
					{
						RECOMMENDED_COMBAT.put(quest, Integer.parseInt(f[8]));
					}
					if (f.length > 9 && !f[9].isEmpty())
					{
						DISPLAY_NAMES.put(quest, f[9]);
					}
					if (f.length > 10 && !f[10].isEmpty())
					{
						if (f[10].indexOf('M') >= 0) MINIQUESTS.add(quest);
						if (f[10].indexOf('F') >= 0) F2P_QUESTS.add(quest);
						if (f[10].indexOf('L') >= 0) LAMP_REWARD_QUESTS.add(quest);
					}
				}
			}
		}
		catch (IOException e)
		{
			throw new UncheckedIOException("failed to load quest-requirements.tsv", e);
		}
	}

	private static List<SkillReq> parseSkillReqs(String field)
	{
		List<SkillReq> skills = new ArrayList<>();
		if (!field.isEmpty())
		{
			for (String sk : field.split(";"))
			{
				int c = sk.indexOf(':');
				skills.add(new SkillReq(Skill.valueOf(sk.substring(0, c)),
					Integer.parseInt(sk.substring(c + 1))));
			}
		}
		return skills;
	}


	private QuestRequirements() {}
}

