	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.goalplanner.model;

import java.util.UUID;
import lombok.Builder;
import lombok.Data;

/**
 * A user-facing section in the goal panel. Sections group goals into visual
 * buckets with their own header row.
 *
 * All sections - built-in and user-defined - use UUID identifiers. The
 * {@link #builtInKind} field identifies built-in sections (Incomplete / Completed)
 * without requiring magic string IDs in code; user sections have builtInKind = null.
 *
 * Ordering is explicit via {@link #order}. Built-ins have fixed relative positions:
 * Incomplete at {@link #ORDER_INCOMPLETE}, Completed at {@link #ORDER_COMPLETED}.
 * User sections can be placed between them.
 */
@Data
@Builder
public class Section
{
	/**
	 * Built-in section roles. User-defined sections use {@code null} for this field.
	 */
	public enum BuiltInKind
	{
		REPEATABLE,
		INCOMPLETE,
		COMPLETED
	}

	/**
	 * Order value for the Repeatable built-in section (always first). It is the
	 * "what am I doing right now" list, so it sits above the backlog rather
	 * than below it.
	 */
	public static final int ORDER_REPEATABLE = Integer.MIN_VALUE;

	/**
	 * Order value for the Incomplete built-in section. Pinned just above
	 * Completed, so user-defined sections (1..N) render first, then
	 * Incomplete, then Completed.
	 */
	public static final int ORDER_INCOMPLETE = Integer.MAX_VALUE - 1;

	/** Order value for the Completed built-in section (always last). */
	public static final int ORDER_COMPLETED = Integer.MAX_VALUE;

	@Builder.Default
	private String id = UUID.randomUUID().toString();

	private String name;

	/** Lower values render first. */
	private int order;

	@Builder.Default
	private boolean collapsed = false;

	/**
	 * User-set color override for the section header, packed as 0xRRGGBB.
	 * -1 means "use the default neutral border color". Built-in sections ignore
	 * this (their header is fixed).
	 */
	@Builder.Default
	private int colorRgb = -1;

	/** Non-null for built-in sections (Incomplete / Completed). Null for user sections. */
	private BuiltInKind builtInKind;

	/**
	 * Per-section override for completed-goal archiving:
	 * {@code null} = inherit the global default; {@code TRUE} = always archive
	 * completed goals out to Completed; {@code FALSE} = always keep them inline.
	 * Built-ins ignore it.
	 */
	private Boolean autoArchiveOverride;

	/**
	 * Per-section override for the "Indent dependencies" nested view:
	 * {@code null} = follow the global default, {@code TRUE} = always nested,
	 * {@code FALSE} = never nested. Purely a view preference - does not change
	 * goal data or ordering. Mirrors {@link #autoArchiveOverride}.
	 */
	private Boolean nestedOverride;

	public boolean isBuiltIn()
	{
		return builtInKind != null;
	}
}

package com.goalplanner.model;

import java.util.UUID;
import lombok.Builder;
import lombok.Data;

/**
 * A first-class tag entity. Replaces the per-goal embedded {@code ItemTag}
 * model.
 *
 * <p>Tags have stable IDs and live in their own collection on
 * {@link com.goalplanner.persistence.GoalStore}. Goals reference tags by id
 * via {@code Goal.tagIds}, so renaming or recoloring a tag at the entity
 * level propagates instantly to every goal using it.
 *
 * <p>The {@link #system} flag distinguishes tags created by the plugin
 * (auto-generated on goal creation, e.g. Boss/Raid/Tier/Slayer on combat
 * achievements) from tags created by the user. The flag drives the edit
 * permissions:
 * <ul>
 *   <li><b>User tags</b> (any category): rename ✓ recolor ✓ delete ✓</li>
 *   <li><b>System tags</b>, SKILLING category: rename ✗ recolor ✗ delete ✗ (skill icons)</li>
 *   <li><b>System tags</b>, other categories: rename ✗ recolor ✓ delete ✗</li>
 * </ul>
 *
 * <p>The {@code colorRgb} field is a packed 0xRRGGBB user override; -1
 * means "use the category default color from {@link TagCategory#getColor()}".
 * Per-goal color overrides do not exist - recoloring a tag affects every
 * goal that references it.
 */
@Data
@Builder
public class Tag
{
	@Builder.Default
	private String id = UUID.randomUUID().toString();

	private String label;
	private TagCategory category;

	/**
	 * Per-tag color override, packed as 0xRRGGBB. -1 means "use the category color".
	 *
	 * <p>Tag color responsibility is split by category:
	 * <ul>
	 *   <li>OTHER tags: this field is the source of truth. Each Other tag can
	 *       carry its own color independent of every other Other tag.</li>
	 *   <li>BOSS / RAID / CLUE / MINIGAME tags: this field is IGNORED. Color
	 *       comes from the category-level override on GoalStore.categoryColors,
	 *       so all tags in the category share one color.</li>
	 *   <li>SKILLING tags: rendered as skill icons, color is irrelevant.</li>
	 * </ul>
	 */
	@Builder.Default
	private int colorRgb = -1;

	/**
	 * True if this tag was auto-generated by the plugin (e.g. attached to a
	 * combat achievement goal at creation time). False for user-created tags.
	 * System tags cannot be renamed or deleted.
	 */
	@Builder.Default
	private boolean system = false;

	/**
	 * Icon resource key. null means "no icon, render as a colored pill".
	 *
	 * <p>Resolver: if the key matches a {@link net.runelite.api.Skill} enum
	 * name (case-insensitive), the renderer pulls the icon from
	 * {@code SkillIconManager.getSkillImage(skill)}. Otherwise it tries to
	 * load {@code /icons/<iconKey>.png} as a bundled classpath resource.
	 * If both lookups fail, the tag falls back to color rendering.
	 *
	 * <p>When an icon resolves successfully, it entirely replaces the colored
	 * pill - color and icon are mutually exclusive at render time.
	 */
	private String iconKey;
}

