import lombok.Data;

/**
 * One dependency edge between goals in two DIFFERENT sections of a
 * multi-section (v2) bundle. Within a section, relations ride on each
 * {@link GoalShareDto}'s section-scoped {@code requires}/{@code orRequires}
 * refs; edges that cross sections can't be expressed there, so the bundle
 * carries them in {@link ShareBundle#getCrossEdges()} as
 * (section index, ref) → (section index, ref) pairs. Section indices are
 * positions in the bundle's {@code sections} list; refs are the per-section
 * goal refs.
 */
@Data
public class CrossEdgeDto
{
	/** Index of the dependent goal's section in the bundle's section list. */
	private int fromSection;
	/** The dependent goal's ref within its section. */
	private int fromRef;
	/** Index of the prerequisite goal's section in the bundle's section list. */
	private int toSection;
	/** The prerequisite goal's ref within its section. */
	private int toRef;
	/** True for an OR (any-of) edge; false for a hard requirement. */
	private boolean or;
}

package com.goalplanner.share;

import java.util.ArrayList;
import java.util.List;
import lombok.Data;

/**
 * A single goal's shareable definition inside a {@link ShareBundle}.
 *
 * <p>Mirrors the definition-bearing fields of {@code com.goalplanner.model.Goal}
 * and deliberately omits recipient-specific state: {@code id}, {@code status},
 * {@code currentValue}, {@code completedAt}, {@code createdAt}, {@code priority}
 * and {@code sectionId} are all regenerated on import.
 *
 * <p>Relations are encoded structurally: each goal carries a bundle-local
 * {@link #ref} index, and {@link #requires}/{@link #orRequires} reference those
 * indices rather than store ids - so they re-wire to fresh ids on import and
 * any edge pointing outside the bundle is simply dropped.
 */
@Data
public class GoalShareDto
{
	/** Bundle-local index used to wire {@link #requires}/{@link #orRequires}. */
	private int ref;

	private String type;          // GoalType name
	private String name;
	private String description;
	private int targetValue;

	// Type-specific references (nullable / sentinel) - mirror Goal.
	private String skillName;
	private String questName;
	private String accountMetric;
	private String bossName;
	private int varbitId;
	private int itemId;
	private int spriteId;
	private String tooltip;
	private int caTaskId = -1;

	/** How often the goal repeats ({@code RepeatPeriod} name), or null/"NONE"
	 *  for an ordinary one-shot. Additive to GPSHARE2: an older decoder simply
	 *  ignores it and imports the goal as non-repeating. */
	private String repeatEvery;

	/** For a derived repeatable goal, the gain expected each period. Zero for a
	 *  plain repeat. The recipient re-bases their own target off their OWN
	 *  progress on import - the sender's absolute target is meaningless to
	 *  them, which is exactly why the chunk travels and the target does not. */
	private int repeatChunk;
	private int customColorRgb = -1;
	private boolean optional;
	private boolean autoSeeded;
	private String wikiUrl;
	private String inventorySetup;

	/** Tags resolved to {label, category, colour} - store ids are meaningless
	 *  cross-client, so they re-resolve (findOrCreate) on import. */
	private List<TagShareDto> tags = new ArrayList<>();

	/** AND-prerequisite edges, as bundle-local {@link #ref} indices. */
	private List<Integer> requires = new ArrayList<>();

	/** OR-prerequisite edges, as bundle-local {@link #ref} indices. */
	private List<Integer> orRequires = new ArrayList<>();
}

package com.goalplanner.share;

import java.util.ArrayList;
import java.util.List;

/**
 * Helpers for the "Saved Plans" feature: read and override the section display
 * names a {@link ShareBundle} will create when imported. A saved plan stores a
 * list of desired names parallel to {@link ShareBundle#effectiveSections()};
 * these helpers read the current names (to populate the editor) and apply the
 * overrides (just before the plan is imported).
 */
public final class SavedPlanSections
{
	private SavedPlanSections()
	{
	}

	/**
	 * The section names this bundle would import as, parallel to
	 * {@link ShareBundle#effectiveSections()}. An entry may be {@code null} - a
	 * loose-goals bundle has no section name until one is assigned.
	 */
	public static List<String> sectionNamesOf(ShareBundle bundle)
	{
		List<String> names = new ArrayList<>();
		if (bundle == null)
		{
			return names;
		}
		for (SectionShareDto s : bundle.effectiveSections())
		{
			names.add(s.getName());
		}
		return names;
	}

	/**
	 * Override the bundle's section display names with {@code names} (parallel to
	 * {@link ShareBundle#effectiveSections()}). A null/blank entry leaves that
	 * section's original name unchanged. Mutates {@code bundle} in place.
	 *
	 * <p>For a loose-goals bundle, assigning a name promotes it to a named
	 * section so the chosen name actually shows on import.
	 */
	public static void applySectionNames(ShareBundle bundle, List<String> names)
	{
		if (bundle == null || names == null || names.isEmpty())
		{
			return;
		}
		List<SectionShareDto> secs = bundle.getSections();
		if (secs != null && !secs.isEmpty())
		{
			for (int i = 0; i < secs.size() && i < names.size(); i++)
			{
				String nm = clean(names.get(i));
				if (nm != null)
				{
					secs.get(i).setName(nm);
				}
			}
			return;
		}
		// v1 single-section path: the lone effective section maps to sectionName.
		String nm = clean(names.get(0));
		if (nm != null)
		{
			bundle.setSectionName(nm);
			// effectiveSections() only surfaces sectionName for SECTION-kind
			// bundles, so promote loose goals to a named section.
			if (bundle.getKind() != ShareBundle.Kind.SECTION)
			{
				bundle.setKind(ShareBundle.Kind.SECTION);
			}
		}
	}

	private static String clean(String s)
	{
		if (s == null)
		{
			return null;
		}
		String t = s.trim();
		return t.isEmpty() ? null : t;
	}
}

