package com.goalplanner.share;

import java.util.ArrayList;
import java.util.List;
import lombok.Data;
import java.util.Collections;

/**
 * Transport-neutral payload for sharing a section or a set of goals with
 * another player who runs the plugin. Carries goal <em>definitions</em> only -
 * recipient-specific state (ids, progress, completion, section membership) is
 * stripped on export and regenerated on import, so imported goals track
 * against the recipient's own account.
 *
 * <p>Serialized via {@link ShareCodec}. The {@link #v} schema version lets the
 * decoder reject payloads from an incompatible plugin version up front - the
 * persistence/share format may still change before a stable 1.0.
 */
@Data
public class ShareBundle
{
	/** Current share-format schema version. Bump on any breaking change. */
	public static final int SCHEMA_VERSION = 2;

	/** Legacy single-section schema version (still decoded and, for plain
	 *  single-section bundles, still emitted - older plugin builds import it). */
	public static final int SCHEMA_VERSION_V1 = 1;

	/** What the bundle represents. */
	public enum Kind
	{
		/** A whole section and its goals. */
		SECTION,
		/** A loose set of goals with no section identity. */
		GOALS
	}

	/** Wire schema version. {@link ShareCodec#encode} sets this from the bundle
	 *  shape (see {@code normalizeForWire}); the default matches a legacy-built
	 *  single-section bundle so hand-constructed bundles stay v1-comparable. */
	private int v = SCHEMA_VERSION_V1;
	private Kind kind;

	/** Display name (RSN) of the sharer, shown in the import prompt. */
	private String sharedBy;

	/** Name of the shared section; null for {@link Kind#GOALS}. */
	private String sectionName;

	/** Section colour override (0xRRGGBB; -1 = default). Ignored for GOALS. */
	private int sectionColorRgb = -1;

	/** The shared goal definitions. Relations between them are encoded as
	 *  bundle-local {@code ref} indices on each {@link GoalShareDto}.
	 *  v1 payloads only; {@code null} on the v2 wire (see {@link #sections}). */
	private List<GoalShareDto> goals = new ArrayList<>();

	/**
	 * v2 payloads: one entry per shared section ({@code null} on the v1 wire).
	 * Consumers should read {@link #effectiveSections()} instead of branching
	 * on the schema version.
	 */
	private List<SectionShareDto> sections;

	/**
	 * Version-neutral view: the v2 section list, or the legacy single-section
	 * fields wrapped as one {@link SectionShareDto}. Never null/empty (a legacy
	 * bundle with no goals yields one section with an empty goal list).
	 */
	public List<SectionShareDto> effectiveSections()
	{
		if (sections != null && !sections.isEmpty())
		{
			return sections;
		}
		SectionShareDto legacy = new SectionShareDto();
		legacy.setName(kind == Kind.SECTION ? sectionName : null);
		legacy.setColorRgb(sectionColorRgb);
		legacy.setGoals(goals != null ? goals : new ArrayList<>());
		return Collections.singletonList(legacy);
	}

	/**
	 * v2 payloads: dependency edges between goals in DIFFERENT sections,
	 * which the per-section {@code requires}/{@code orRequires} refs cannot
	 * express. {@code null} on the v1 wire and when no edges cross sections.
	 */
	private List<CrossEdgeDto> crossEdges;

	/** Total goals across all sections, version-neutral (v1 or v2 shape). */
	public int totalGoalCount()
	{
		int n = 0;
		for (SectionShareDto s : effectiveSections())
		{
			n += s.getGoals() != null ? s.getGoals().size() : 0;
		}
		return n;
	}

	/**
	 * True when this bundle needs the v2 wire format: more than one section, or
	 * any section targeting the recipient's default plan. Plain single-section
	 * bundles stay on the v1 wire so older plugin builds keep importing them.
	 */
	public boolean needsV2()
	{
		List<SectionShareDto> secs = effectiveSections();
		if (secs.size() > 1)
		{
			return true;
		}
		return secs.get(0).isTargetDefault();
	}
}

package com.goalplanner.share;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.Base64;
import java.util.zip.GZIPInputStream;
import java.util.zip.GZIPOutputStream;
import java.util.List;

/**
 * Encodes a {@link ShareBundle} to (and from) a compact, copy-safe string:
 *
 * <pre>  ShareBundle → Gson JSON → gzip → URL-safe Base64, prefixed "GPSHARE1:"</pre>
 *
 * <p>The {@code GPSHARE&lt;n&gt;:} prefix is a magic marker + schema version: it
 * lets {@link #decode(String)} reject arbitrary pasted text and incompatible
 * versions before doing any work. The same encoded string is the payload for
 * a copy/paste export.
 *
 * <p>Gzip matters because goal data is highly repetitive (enum names, level
 * targets) and chat clients cap message size - compression keeps a
 * typical section inside a single message.
 *
 * <p>Takes an injected {@link Gson}; the plugin hub rejects {@code new Gson()},
 * so production wires the shared client instance. Pure and side-effect free.
 */
public final class ShareCodec
{
	/** Magic marker + schema version (current, multi-section). */
	static final String PREFIX_V2 = "GPSHARE" + ShareBundle.SCHEMA_VERSION + ":";

	/** Legacy single-section marker - still decoded, and still emitted for
	 *  plain single-section bundles so older plugin builds can import them. */
	static final String PREFIX = "GPSHARE" + ShareBundle.SCHEMA_VERSION_V1 + ":";

	private final Gson gson;

	public ShareCodec(Gson gson)
	{
		this.gson = gson;
	}

	/**
	 * Encode a bundle to a prefixed, gzipped, URL-safe-Base64 string. The wire
	 * version is chosen from the content: multi-section or default-target
	 * bundles emit {@code GPSHARE2:}; plain single-section bundles down-convert
	 * to the legacy {@code GPSHARE1:} shape so older plugin builds import them.
	 */
	public String encode(ShareBundle bundle)
	{
		if (bundle == null)
		{
			throw new ShareFormatException("nothing to share");
		}
		ShareBundle wire = normalizeForWire(bundle);
		String prefix = wire.getV() == ShareBundle.SCHEMA_VERSION ? PREFIX_V2 : PREFIX;
		byte[] json = gson.toJson(wire).getBytes(StandardCharsets.UTF_8);
		byte[] gz = gzip(json);
		return prefix + Base64.getUrlEncoder().withoutPadding().encodeToString(gz);
	}

	/**
	 * Build the version-correct wire copy of {@code bundle}: v2 keeps only
	 * {@code sections}; v1 keeps only the legacy single-section fields. The
	 * input bundle is never mutated.
	 */
	static ShareBundle normalizeForWire(ShareBundle bundle)
	{
		List<SectionShareDto> secs = bundle.effectiveSections();
		ShareBundle wire = new ShareBundle();
		wire.setSharedBy(bundle.getSharedBy());
		if (bundle.needsV2())
		{
			wire.setV(ShareBundle.SCHEMA_VERSION);
			wire.setKind(null);
			wire.setSectionName(null);
			wire.setGoals(null);
			wire.setSections(secs);
			wire.setCrossEdges(bundle.getCrossEdges() != null && !bundle.getCrossEdges().isEmpty()
				? bundle.getCrossEdges() : null);
			return wire;
		}
		SectionShareDto only = secs.get(0);
		wire.setV(ShareBundle.SCHEMA_VERSION_V1);
		wire.setKind(only.getName() != null ? ShareBundle.Kind.SECTION : ShareBundle.Kind.GOALS);
		wire.setSectionName(only.getName());
		wire.setSectionColorRgb(only.getColorRgb());
		wire.setGoals(only.getGoals());
		wire.setSections(null);
		wire.setCrossEdges(null); // single section - nothing to cross
		return wire;
	}

	/**
	 * Decode a string produced by {@link #encode(ShareBundle)}.
	 *
	 * @throws ShareFormatException if the input is null/blank, lacks the
	 *         {@link #PREFIX} (wrong tool or version), or is corrupt.
	 */
	public ShareBundle decode(String text)
	{
		if (text == null || text.trim().isEmpty())
		{
			throw new ShareFormatException("empty share code");
		}
		// The code may be embedded in surrounding instruction text - e.g. a
		// "get the plugin to import this: <code>" chat/Discord line - so locate
		// the marker and read the base64url token that follows it, rather than
		// requiring the code to sit alone. v2 is checked first; both decode.
		String prefix = PREFIX_V2;
		int marker = text.indexOf(PREFIX_V2);
		if (marker < 0)
		{
			prefix = PREFIX;
			marker = text.indexOf(PREFIX);
		}
		if (marker < 0)
		{
			throw new ShareFormatException("unrecognised or wrong-version share code");
		}
		// Collect the Base64url body, SKIPPING embedded whitespace. A long code
		// pasted from chat often wraps across lines; without skipping, the scan
		// would stop at the first newline/space and decode a truncated payload
		// ("That doesn't look like a valid share code"). Stop at the first real
		// non-Base64url, non-whitespace char (trailing prose after the code).
		int start = marker + prefix.length();
		StringBuilder body = new StringBuilder(text.length() - start);
		for (int i = start; i < text.length(); i++)
		{
			char c = text.charAt(i);
			if (isBase64Url(c))
			{
				body.append(c);
			}
			else if (!Character.isWhitespace(c))
			{
				break;
			}
		}
		String b64 = body.toString();

		byte[] gz;
		try
		{
			gz = Base64.getUrlDecoder().decode(b64);
		}
		catch (IllegalArgumentException e)
		{
			throw new ShareFormatException("corrupt share code", e);
		}

		String json = new String(gunzip(gz), StandardCharsets.UTF_8);

		ShareBundle bundle;
		try
		{
			bundle = gson.fromJson(json, ShareBundle.class);
		}
		catch (JsonSyntaxException e)
		{
			throw new ShareFormatException("invalid share payload", e);
		}
		if (bundle == null)
		{
			throw new ShareFormatException("empty share payload");
		}
		int expected = prefix.equals(PREFIX_V2)
			? ShareBundle.SCHEMA_VERSION : ShareBundle.SCHEMA_VERSION_V1;
		if (bundle.getV() != expected)
		{
			throw new ShareFormatException(
				"share code is from an incompatible plugin version (v" + bundle.getV() + ")");
		}
		if (expected == ShareBundle.SCHEMA_VERSION)
		{
			if (bundle.getSections() == null || bundle.getSections().isEmpty())
			{
				throw new ShareFormatException("empty share payload");
			}
			for (SectionShareDto s : bundle.getSections())
			{
				if (s == null || s.getGoals() == null)
				{
					throw new ShareFormatException("invalid share payload");
				}
			}
		}
		else if (bundle.getGoals() == null)
		{
			throw new ShareFormatException("empty share payload");
		}
		return bundle;
	}

	/** URL-safe Base64 alphabet (no padding): {@code [A-Za-z0-9_-]}. */
	private static boolean isBase64Url(char c)
	{
		return (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z')
			|| (c >= '0' && c <= '9') || c == '-' || c == '_';
	}

	private static byte[] gzip(byte[] data)
	{
		ByteArrayOutputStream out = new ByteArrayOutputStream();
		try (GZIPOutputStream gz = new GZIPOutputStream(out))
		{
			gz.write(data);
		}
		catch (IOException e)
		{
			// In-memory streams don't do real IO; treat as unexpected.
			throw new ShareFormatException("failed to compress share payload", e);
		}
		return out.toByteArray();
	}

	private static byte[] gunzip(byte[] data)
	{
		try (GZIPInputStream gz = new GZIPInputStream(new ByteArrayInputStream(data)))
		{
			ByteArrayOutputStream out = new ByteArrayOutputStream();
			byte[] buf = new byte[4096];
			int n;
			while ((n = gz.read(buf)) != -1)
			{
				out.write(buf, 0, n);
			}
			return out.toByteArray();
		}
		catch (IOException e)
		{
			throw new ShareFormatException("corrupt share code", e);
		}
	}
}

package com.goalplanner.share;

/**
 * Thrown by {@link ShareCodec#decode(String)} when the input is not a
 * recognisable, current-version, well-formed share code. Callers (paste
 * dialog, cross-plugin receive handler) catch this to show a friendly "couldn't read
 * that share code" message instead of failing hard.
 */
public class ShareFormatException extends RuntimeException
{
	public ShareFormatException(String message)
	{
		super(message);
	}

	public ShareFormatException(String message, Throwable cause)
	{
		super(message, cause);
	}
}

package com.goalplanner.share;

import com.goalplanner.model.Goal;
import com.goalplanner.model.Tag;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;

/**
 * Export-side mapping: live {@link Goal}/{@link Tag} model objects →
 * {@link ShareBundle}. Pure - takes a tag-lookup {@link Function} rather than a
 * store, so it's unit-testable without the client.
 *
 * <p>Three responsibilities:
 * <ul>
 *   <li><b>Strip recipient-specific state.</b> Only definition fields are
 *       copied; {@code id}, {@code status}, {@code currentValue},
 *       {@code completedAt}, {@code createdAt}, {@code priority} and
 *       {@code sectionId} are left behind (the {@link GoalShareDto} has no
 *       slots for them) - imported goals track against the recipient's own
 *       account.</li>
 *   <li><b>Resolve tags.</b> A goal's {@code tagIds} are looked up and emitted
 *       as {label, category, colour} so the importer can find-or-create them;
 *       dangling tag refs are dropped.</li>
 *   <li><b>Rewrite relations.</b> {@code requiredGoalIds} /
 *       {@code orRequiredGoalIds} become bundle-local {@code ref} indices;
 *       edges pointing outside the shared set are dropped.</li>
 * </ul>
 */
public final class ShareMapper
{
	private ShareMapper()
	{
	}

	/**
	 * Build a shareable bundle from the goals being shared.
	 *
	 * @param kind            SECTION (carries a section name) or GOALS
	 * @param sectionName     section name for SECTION shares; null otherwise
	 * @param sectionColorRgb section colour override (0xRRGGBB; -1 = default)
	 * @param goals           the goals to share, in display order
	 * @param tagLookup       resolves a tag id to its {@link Tag} (or null)
	 * @param sharedBy        sharer's display name, for the import prompt
	 */
	public static ShareBundle toBundle(
		ShareBundle.Kind kind,
		String sectionName,
		int sectionColorRgb,
		List<Goal> goals,
		Function<String, Tag> tagLookup,
		String sharedBy)
	{
		ShareBundle bundle = new ShareBundle();
		bundle.setKind(kind);
		bundle.setSharedBy(sharedBy);
		bundle.setSectionName(sectionName);
		bundle.setSectionColorRgb(sectionColorRgb);
		bundle.setGoals(toDtos(goals, tagLookup));
		return bundle;
	}

	/**
	 * Build one v2 section entry. Relation refs are scoped to this section's
	 * goal list ({@code remap} skips out-of-section edges - the bundle-level
	 * {@link #crossEdges} pass carries those).
	 */
	public static SectionShareDto toSectionDto(
		String name,
		int colorRgb,
		boolean targetDefault,
		Boolean nestedOverride,
		List<Goal> goals,
		Function<String, Tag> tagLookup)
	{
		SectionShareDto dto = new SectionShareDto();
		dto.setName(name);
		dto.setColorRgb(colorRgb);
		dto.setTargetDefault(targetDefault);
		dto.setNestedOverride(nestedOverride);
		dto.setGoals(toDtos(goals, tagLookup));
		return dto;
	}

	/** Build a multi-section (v2) bundle from prepared section entries. */
	public static ShareBundle toMultiBundle(List<SectionShareDto> sections, String sharedBy)
	{
		ShareBundle bundle = new ShareBundle();
		bundle.setSharedBy(sharedBy);
		bundle.setSections(sections != null ? sections : new ArrayList<>());
		return bundle;
	}

	/**
	 * Build the cross-section dependency edges for a multi-section bundle:
	 * every requires/orRequires edge whose endpoints live in two DIFFERENT
	 * groups. {@code groups} must be the same goal lists, in the same order,
	 * that produced the bundle's section entries - refs are the per-section
	 * list indices {@link #toDtos} assigned. Edges to goals outside the
	 * bundle entirely are not representable and remain dropped.
	 */
	public static List<CrossEdgeDto> crossEdges(List<List<Goal>> groups)
	{
		// goal id → (section index, ref) across the whole bundle.
		Map<String, int[]> at = new HashMap<>();
		for (int s = 0; s < groups.size(); s++)
		{
			List<Goal> goals = groups.get(s);
			for (int r = 0; r < goals.size(); r++)
			{
				Goal g = goals.get(r);
				if (g != null && g.getId() != null)
				{
					at.put(g.getId(), new int[]{s, r});
				}
			}
		}
		List<CrossEdgeDto> out = new ArrayList<>();
		for (int s = 0; s < groups.size(); s++)
		{
			List<Goal> goals = groups.get(s);
			for (int r = 0; r < goals.size(); r++)
			{
				Goal g = goals.get(r);
				if (g == null)
				{
					continue;
				}
				addCrossEdges(out, at, s, r, g.getRequiredGoalIds(), false);
				addCrossEdges(out, at, s, r, g.getOrRequiredGoalIds(), true);
			}
		}
		return out;
	}

	private static void addCrossEdges(List<CrossEdgeDto> out, Map<String, int[]> at,
		int fromSection, int fromRef, List<String> targetIds, boolean or)
	{
		if (targetIds == null)
		{
			return;
		}
		for (String id : targetIds)
		{
			int[] target = at.get(id);
			if (target == null || target[0] == fromSection)
			{
				continue;   // outside the bundle, or section-local (carried on the dto)
			}
			CrossEdgeDto edge = new CrossEdgeDto();
			edge.setFromSection(fromSection);
			edge.setFromRef(fromRef);
			edge.setToSection(target[0]);
			edge.setToRef(target[1]);
			edge.setOr(or);
			out.add(edge);
		}
	}

	private static List<GoalShareDto> toDtos(List<Goal> goals, Function<String, Tag> tagLookup)
	{
		List<Goal> source = goals != null ? goals : List.of();

		// goal id → bundle-local ref index, for rewiring relations.
		Map<String, Integer> idToRef = new HashMap<>();
		for (int i = 0; i < source.size(); i++)
		{
			Goal g = source.get(i);
			if (g != null && g.getId() != null)
			{
				idToRef.put(g.getId(), i);
			}
		}

		List<GoalShareDto> dtos = new ArrayList<>();
		for (int i = 0; i < source.size(); i++)
		{
			Goal g = source.get(i);
			if (g == null)
			{
				continue;
			}
			GoalShareDto dto = new GoalShareDto();
			dto.setRef(i);
			dto.setType(g.getType() != null ? g.getType().name() : null);
			dto.setName(g.getName());
			dto.setDescription(g.getDescription());
			dto.setTargetValue(g.getTargetValue());
			dto.setSkillName(g.getSkillName());
			dto.setQuestName(g.getQuestName());
			dto.setAccountMetric(g.getAccountMetric());
			dto.setBossName(g.getBossName());
			dto.setVarbitId(g.getVarbitId());
			dto.setItemId(g.getItemId());
			dto.setSpriteId(g.getSpriteId());
			dto.setTooltip(g.getTooltip());
			dto.setCaTaskId(g.getCaTaskId());
			dto.setRepeatEvery(g.getRepeatEvery().name());
			dto.setRepeatChunk(g.getRepeatChunk());
			dto.setCustomColorRgb(g.getCustomColorRgb());
			dto.setOptional(g.isOptional());
			dto.setAutoSeeded(g.isAutoSeeded());
			dto.setWikiUrl(g.getWikiUrl());
			dto.setInventorySetup(g.getInventorySetup());
			dto.setTags(resolveTags(g.getTagIds(), tagLookup));
			dto.setRequires(remap(g.getRequiredGoalIds(), idToRef));
			dto.setOrRequires(remap(g.getOrRequiredGoalIds(), idToRef));
			dtos.add(dto);
		}

		return dtos;
	}

	private static List<TagShareDto> resolveTags(List<String> tagIds, Function<String, Tag> lookup)
	{
		List<TagShareDto> out = new ArrayList<>();
		if (tagIds == null || lookup == null)
		{
			return out;
		}
		for (String id : tagIds)
		{
			Tag tag = lookup.apply(id);
			if (tag == null)
			{
				continue;   // dangling tag ref - drop
			}
			TagShareDto t = new TagShareDto();
			t.setLabel(tag.getLabel());
			t.setCategory(tag.getCategory() != null ? tag.getCategory().name() : null);
			t.setColorRgb(tag.getColorRgb());
			t.setSystem(tag.isSystem());
			out.add(t);
		}
		return out;
	}

	private static List<Integer> remap(List<String> goalIds, Map<String, Integer> idToRef)
	{
		List<Integer> out = new ArrayList<>();
		if (goalIds == null)
		{
			return out;
		}
		for (String id : goalIds)
		{
			Integer ref = idToRef.get(id);
			if (ref != null)   // drop edges pointing outside the bundle
			{
				out.add(ref);
			}
		}
		return out;
	}
}

package com.goalplanner.share;
import java.util.List;

/**
 * Wraps a {@link ShareCodec} share code in a human-readable, copy-paste-ready
 * invite line. The point is graceful degradation: a player <em>without</em> the
 * plugin who sees the pasted line (Discord, PM, in-game chat) reads a plain
 * "get the plugin to import this" instruction, while a player <em>with</em> the
 * plugin can import it - {@link ShareCodec#decode(String)} extracts the code
 * from the surrounding text.
 *
 * <p>{@link #MARKER} doubles as the detection token for in-game chat
 * auto-detection (a later transport).
 */
public final class ShareText
{
	/** Leading marker - human label + detection token for chat scanning. */
	public static final String MARKER = "[Goal Planner]";

	private ShareText()
	{
	}

	/**
	 * Build an invite line: {@code [Goal Planner] <who> shared <what> - get the
	 * Goal Planner RuneLite plugin to import it: <code>}.
	 *
	 * @param bundle the bundle being shared (for the sharer name + summary)
	 * @param code   the encoded share code from {@link ShareCodec#encode}
	 */
	public static String invite(ShareBundle bundle, String code)
	{
		String who = bundle != null && notBlank(bundle.getSharedBy())
			? bundle.getSharedBy().trim()
			: "Someone";
		return MARKER + " " + who + " shared " + describe(bundle)
			+ " - get the Goal Planner RuneLite plugin to import it: "
			+ (code != null ? code : "");
	}

	private static String describe(ShareBundle bundle)
	{
		if (bundle == null)
		{
			return "0 goals";
		}
		List<SectionShareDto> sections = bundle.effectiveSections();
		int n = bundle.totalGoalCount();
		String goals = n == 1 ? "1 goal" : n + " goals";
		if (sections.size() > 1)
		{
			return sections.size() + " sections (" + goals + ")";
		}
		SectionShareDto only = sections.get(0);
		if (!only.isTargetDefault() && notBlank(only.getName()))
		{
			return "\"" + only.getName().trim() + "\" (" + goals + ")";
		}
		return goals;
	}

	private static boolean notBlank(String s)
	{
		return s != null && !s.trim().isEmpty();
	}
}

