package com.goalplanner.ui;

import com.goalplanner.model.AccountMetric;
import java.util.LinkedHashSet;

/**
 * Pure quick-fill target presets for account-metric goals (Task 3). Data-driven
 * off each metric's static {@link AccountMetric#getMaxTarget()} - no per-metric
 * hardcoded tables and no live Client read. The dock's account create form offers
 * these as one-tap buttons alongside the free-text target field, so common
 * milestones (a quarter/half/three-quarters of the ceiling, and the ceiling
 * itself) don't have to be typed. Typing a custom value still works.
 */
public final class AccountTargetPresets
{
	private AccountTargetPresets() {}

	/** The fractions of max offered below the Max button. */
	private static final double[] FRACTIONS = { 0.25, 0.50, 0.75 };

	/**
	 * Ordered, de-duplicated quick-fill targets for {@code metric}: roughly
	 * 25% / 50% / 75% of the ceiling (nice-rounded and clamped to the metric's
	 * [min, max] range), followed by the max itself. The max is always the last
	 * element, so the array is never empty. Fractions that round to a duplicate
	 * (common on small-ceiling metrics) are dropped.
	 */
	public static int[] presetsFor(AccountMetric metric)
	{
		if (metric == null)
		{
			return new int[0];
		}
		int min = metric.getMinTarget();
		int max = metric.getMaxTarget();
		// Preserve insertion order, drop duplicates.
		LinkedHashSet<Integer> out = new LinkedHashSet<>();

		int[] milestones = milestonesFor(metric);
		if (milestones != null)
		{
			// Curated significant milestones read better than fractions-of-max for
			// metrics like Total Level (594/1188/1782 was meaningless). Clamp into
			// range, keep those below max, then append max as the last element.
			for (int m : milestones)
			{
				if (m > min && m < max)
				{
					out.add(m);
				}
			}
		}
		else
		{
			for (double f : FRACTIONS)
			{
				int v = niceRound((int) Math.round(max * f));
				v = Math.max(min, Math.min(max, v));
				if (v > 0 && v < max)
				{
					out.add(v);
				}
			}
		}
		// Collection Log: the Gilded staff unlocks at 90% of the total, rounded
		// down to the nearest 25 - a headline tier between Dragon (1200) and full
		// completion. Computed off the live max so it tracks as the log grows.
		if (metric == AccountMetric.COLLECTION_LOG_SLOTS)
		{
			int gilded = (int) (Math.floor(0.9 * max / 25.0) * 25);
			if (gilded > min && gilded < max)
			{
				out.add(gilded);
			}
		}
		out.add(max);
		int[] arr = new int[out.size()];
		int i = 0;
		for (int v : out)
		{
			arr[i++] = v;
		}
		return arr;
	}

	/**
	 * Curated significant milestones (sub-max; the caller appends the metric's
	 * max) for metrics where a quarter/half/three-quarter of the ceiling reads as
	 * an arbitrary number. {@code null} = use the fraction fallback.
	 */
	private static int[] milestonesFor(AccountMetric metric)
	{
		switch (metric)
		{
			// 2277 = all 99s before Sailing (the classic max cape); max (2376) appended.
			case TOTAL_LEVEL:  return new int[]{ 1500, 2000, 2277 };
			case QUEST_POINTS: return new int[]{ 100, 200, 300 };
			// Collection-log reward-staff tiers: Bronze..Dragon are fixed slot
			// counts; Gilded (90% of the dynamic max) is added in presetsFor; the
			// full-completion max is appended by the caller.
			case COLLECTION_LOG_SLOTS: return new int[]{ 100, 300, 500, 700, 900, 1000, 1100, 1200 };
			default:           return null;
		}
	}

	/**
	 * Round {@code v} to a human-friendly step scaled to its magnitude (small
	 * values are left exact so tiny ceilings like Diary Tiers (48) or DoM depth
	 * (8) still produce distinct quarter/half/three-quarter presets).
	 */
	static int niceRound(int v)
	{
		if (v <= 0)
		{
			return 0;
		}
		if (v < 50)
		{
			return v;
		}
		int step;
		if (v < 200)
		{
			step = 5;
		}
		else if (v < 2000)
		{
			step = 10;
		}
		else if (v < 20000)
		{
			step = 100;
		}
		else
		{
			step = 1000;
		}
		return Math.round((float) v / step) * step;
	}
}

package com.goalplanner.ui;

import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JColorChooser;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.LineBorder;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.GridLayout;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.Graphics;
import java.awt.Insets;

/**
 * Reusable color picker widget for section / goal / tag color overrides.
 *
 * <p>Layout:
 * <ul>
 *   <li>A small preview swatch + "Current" label at the top</li>
 *   <li>A grid of curated preset swatches - click to select</li>
 *   <li>A "More..." button opening a full {@link JColorChooser}</li>
 *   <li>A "Reset to default" button that clears the override</li>
 * </ul>
 *
 * <p>State: either a concrete RGB int, or -1 meaning "no override".
 * {@link #getSelectedRgb()} returns the current value.
 */
public class ColorPickerField extends JPanel
{
	/** Curated palette tuned for the RuneLite dark sidebar. 12 swatches, 4×3 grid. */
	public static final Color[] PRESETS = new Color[]{
		new Color(0xE74C3C), // red
		new Color(0xE67E22), // orange
		new Color(0xF1C40F), // yellow
		new Color(0x2ECC71), // green
		new Color(0x1ABC9C), // teal
		new Color(0x3498DB), // blue
		new Color(0x9B59B6), // purple
		new Color(0xE91E63), // pink
		new Color(0x8B4513), // brown
		new Color(0x607D8B), // slate
		new Color(0x455A64), // dark slate
		new Color(0x2C3E50), // midnight
	};

	private static final int SWATCH = 22;
	private static final Color DEFAULT_BORDER = new Color(80, 80, 80);
	private static final Color SELECTED_BORDER = Color.WHITE;

	/** Current selection: -1 means "no override / use default". */
	private int selectedRgb;
	/** The underlying default color for this item - shown as the preview when
	 *  selectedRgb == -1, and used as the reset target. */
	private final int defaultRgb;

	private final JPanel previewSwatch;
	private final JLabel previewLabel;

	/** Backward-compatible constructor; uses a neutral fallback for default. */
	public ColorPickerField(int initialRgb)
	{
		this(initialRgb, 0x3C3C3C);
	}

	public ColorPickerField(int initialRgb, int defaultRgb)
	{
		this.selectedRgb = initialRgb;
		this.defaultRgb = defaultRgb;

		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setOpaque(false);

		// --- Preview row -------------------------------------------------
		JPanel previewRow = new JPanel(new FlowLayout(FlowLayout.LEFT, 6, 2));
		previewRow.setOpaque(false);
		previewSwatch = new JPanel()
		{
			@Override
			protected void paintComponent(Graphics g)
			{
				// Paint the fill ourselves so FlatLaf/UI delegates don't override it.
				int rgb = selectedRgb >= 0 ? selectedRgb : defaultRgb;
				g.setColor(new Color(rgb));
				g.fillRect(0, 0, getWidth(), getHeight());
			}
		};
		previewSwatch.setOpaque(false);
		previewSwatch.setPreferredSize(new Dimension(SWATCH, SWATCH));
		previewSwatch.setBorder(new LineBorder(DEFAULT_BORDER, 1));
		previewLabel = new JLabel();
		previewRow.add(previewSwatch);
		previewRow.add(previewLabel);
		add(previewRow);

		add(Box.createVerticalStrut(4));

		// --- Swatch grid -------------------------------------------------
		JPanel grid = new JPanel(new GridLayout(3, 4, 4, 4));
		grid.setOpaque(false);
		for (Color preset : PRESETS)
		{
			grid.add(makeSwatchButton(preset));
		}
		add(grid);

		add(Box.createVerticalStrut(6));

		// --- Action buttons ---------------------------------------------
		JPanel actions = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0));
		actions.setOpaque(false);

		JButton more = new JButton("More...");
		more.setMargin(new Insets(2, 6, 2, 6));
		more.addActionListener(e -> {
			Color initial = selectedRgb >= 0 ? new Color(selectedRgb) : Color.GRAY;
			Color picked = JColorChooser.showDialog(this, "Pick a color", initial);
			if (picked != null) setSelectedRgb(rgbFromColor(picked));
		});
		actions.add(more);

		JButton reset = new JButton("Reset to default");
		reset.setMargin(new Insets(2, 6, 2, 6));
		reset.addActionListener(e -> setSelectedRgb(-1));
		actions.add(reset);

		add(actions);

		refreshPreview();
	}

	/** @return selected RGB packed as 0xRRGGBB, or -1 for "no override". */
	public int getSelectedRgb()
	{
		return selectedRgb;
	}

	public void setSelectedRgb(int rgb)
	{
		this.selectedRgb = rgb < 0 ? -1 : (rgb & 0xFFFFFF);
		refreshPreview();
	}

	private void refreshPreview()
	{
		previewLabel.setText(selectedRgb >= 0
			? String.format("Color: #%06X", selectedRgb)
			: String.format("Color: default (#%06X)", defaultRgb));
		previewSwatch.repaint();
	}

	private JPanel makeSwatchButton(final Color color)
	{
		JPanel swatch = new JPanel()
		{
			@Override
			protected void paintComponent(Graphics g)
			{
				// Paint the fill ourselves so FlatLaf/UI delegates don't override it.
				g.setColor(color);
				g.fillRect(0, 0, getWidth(), getHeight());
			}
		};
		swatch.setOpaque(false);
		swatch.setPreferredSize(new Dimension(SWATCH, SWATCH));
		swatch.setBorder(new LineBorder(DEFAULT_BORDER, 1));
		swatch.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		swatch.setToolTipText(String.format("#%06X", rgbFromColor(color)));
		swatch.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				setSelectedRgb(rgbFromColor(color));
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				swatch.setBorder(new LineBorder(SELECTED_BORDER, 1));
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				swatch.setBorder(new LineBorder(DEFAULT_BORDER, 1));
			}
		});
		return swatch;
	}

	private static int rgbFromColor(Color c)
	{
		return (c.getRed() << 16) | (c.getGreen() << 8) | c.getBlue();
	}
}

