	 *  the dock surface that replaced the MultiSelectDialog flows). */
	private void openReqRemoveSurface(String goalId, boolean dependents)
	{
		dockReqRemoveTarget = goalId;
		dockReqDependents = dependents;
		dockReqMounted = false;
		refreshDock();
