	/** One chip per requirement; a click removes that requirement and remounts,
	 *  so several can be dropped without leaving the overlay. Mirrors
	 *  {@link #buildTagRemoveSurface}. */
	private JComponent buildReqRemoveSurface()
	{
		JPanel inner = new JPanel(new BorderLayout(0, 6));
		innerPad(inner);

		JPanel head = new JPanel(new WrapLayout(FlowLayout.LEFT, 4, 0));
		head.setOpaque(false);
		head.add(chip("< Back", "Back without removing more requirements", this::closeReqSurface));
		inner.add(head, BorderLayout.NORTH);

		JPanel chips = new JPanel(new WrapLayout(FlowLayout.LEFT, 4, 4));
		chips.setOpaque(false);
		final String gid = dockReqRemoveTarget;
		final boolean deps = dockReqDependents;
		List<String> edges = deps
			? new ArrayList<>(api.getDependents(gid))
			: new ArrayList<>(api.getRequirements(gid));
		for (String reqId : edges)
		{
			final String name = reorderController.goalNameById(reqId);
			final String rid = reqId;
			chips.add(chip(name,
				deps ? name + " no longer requires this goal"
					: "Remove the requirement on " + name, () -> {
				api.beginCompound((deps ? "Remove dependent '" : "Remove requirement '")
					+ name + "'");
				try
				{
					// A dependent is the reversed edge: THAT goal requires this one.
					if (deps)
					{
						api.removeRequirement(rid, gid);
					}
					else
					{
						api.removeRequirement(gid, rid);
					}
				}
				finally
				{
					api.endCompound();
				}
				dockReqMounted = false;
				refreshDock();
			}));
		}
		inner.add(chips, BorderLayout.CENTER);
		return inner;
	}

	/**
	 * Open an explicit pick for a boolean/enum setting. Replaces tap-to-cycle
	 * chips: a cycle hides the option set, needs up to three taps to reach a
	 * known state, and reports only through its own changing label.
	 */
	// Package-private, not private: the headless render harness drives this
	// directly so the surface can be SEEN. Section selection has no API-level
	// entry point, and shipping an unverifiable surface is how the dock got
	// six defects nobody spotted in review.
	void openChoiceSurface(String title, String[] labels, int current,
		java.util.function.IntConsumer onPick)
	{
		dockChoiceTitle = title;
		dockChoiceLabels = labels;
		dockChoiceCurrent = current;
		dockChoicePick = onPick;
		dockChoiceMounted = false;
		refreshDock();
	}

	private void closeChoiceSurface()
	{
		dockChoiceTitle = null;
		dockChoiceLabels = null;
		dockChoicePick = null;
		dockChoiceMounted = false;
		dockSectionMounted = false;
		refreshDock();
	}

	/** Title, one chip per option with the current one marked, and Back. */
	private JComponent buildChoiceSurface()
	{
		JPanel inner = new JPanel(new BorderLayout(0, 6));
		innerPad(inner);

		JLabel head = new JLabel(dockChoiceTitle);
		formLabel(head);
		inner.add(head, BorderLayout.NORTH);

		JPanel body = new JPanel(new WrapLayout(FlowLayout.LEFT, 4, 2));
		body.setOpaque(false);
		for (int i = 0; i < dockChoiceLabels.length; i++)
		{
			final int idx = i;
			boolean isCurrent = i == dockChoiceCurrent;
			// The option in force wears the dock's PRIMARY treatment - the same
			// green fill the create-mode chips use - rather than a text marker.
			// Colour is the panel's existing language for "this one is active";
			// a glyph prefix would also break the ASCII-only rule.
			JButton b = flatButton(dockChoiceLabels[i], isCurrent);
			b.setToolTipText(isCurrent ? "Currently in force" : "Use " + dockChoiceLabels[i]);
			b.addActionListener(e -> {
				java.util.function.IntConsumer pick = dockChoicePick;
				closeChoiceSurface();
				if (pick != null)
				{
					pick.accept(idx);
				}
			});
			body.add(b);
		}
		body.add(chip("< Back", "Leave the setting unchanged", this::closeChoiceSurface));
		inner.add(body, BorderLayout.CENTER);
		return inner;
	}

