	/** A prefilled text field with Save / Back chips; a failed commit shows the
	 *  surface's inline hint and stays open. One surface for every text ask -
	 *  replaces the JOptionPane input windows (1.0.0 no-popups rule). */
	private JComponent buildInputSurface()
	{
		JPanel inner = new JPanel(new BorderLayout(0, 6));
		innerPad(inner);

		JPanel head = new JPanel(new WrapLayout(FlowLayout.LEFT, 4, 0));
		head.setOpaque(false);
		head.add(chip("< Back", "Back without saving", this::closeInputSurface));
		JLabel title = new JLabel(dockInputTitle);
		formLabel(title);
		head.add(title);
		inner.add(head, BorderLayout.NORTH);

		JPanel body = new JPanel();
		stack(body);

		final JTextField field = new JTextField(dockInputInitial, 16);
		styleField(field);
		field.setMaximumSize(new Dimension(Integer.MAX_VALUE, field.getPreferredSize().height));
		field.setAlignmentX(Component.LEFT_ALIGNMENT);
		body.add(field);

		if (dockInputFailed)
		{
			JLabel hint = new JLabel(dockInputHint);
			hint.setForeground(new Color(220, 140, 120));
			hint.setFont(hint.getFont().deriveFont(11f));
			hint.setAlignmentX(Component.LEFT_ALIGNMENT);
			body.add(Box.createVerticalStrut(4));
			body.add(hint);
		}

		Runnable commit = () -> {
			java.util.function.Predicate<String> test = dockInputCommit;
			if (test != null && test.test(field.getText()))
			{
				closeInputSurface();
			}
			else
			{
				dockInputFailed = true;
				dockInputMounted = false;
				refreshDock();
			}
		};
		field.addActionListener(e -> commit.run());

		JPanel actions = new JPanel(new WrapLayout(FlowLayout.LEFT, 4, 0));
		loose(actions);
		actions.add(chip("Save", "Apply", commit));
		body.add(Box.createVerticalStrut(6));
		body.add(actions);

		inner.add(body, BorderLayout.CENTER);
		return inner;
	}

	/** Dispatch to the active inline tag surface (ADD or REMOVE). */
	private JComponent buildTagSurface()
	{
		return dockTagMode == TagMode.ADD ? buildTagAddSurface() : buildTagRemoveSurface();
	}

	/** Display name for a {@link com.goalplanner.model.TagCategory} enum name, or
	 *  the raw name if it does not resolve. */
	private static String tagCategoryDisplay(String categoryName)
	{
		if (categoryName == null)
		{
			return null;
		}
		try
		{
			return com.goalplanner.model.TagCategory.valueOf(categoryName).getDisplayName();
		}
		catch (IllegalArgumentException e)
		{
			return categoryName;
		}
	}

	/** Build the inline Add Tag surface (GOAL or MULTI): every existing tag from
	 *  {@code api.queryAllTags()} rendered as a rounded tappable chip that adds it and
	 *  returns, plus a "New tag" text field + Add button that creates-and-adds a
	 *  brand-new label. Tapping an existing chip preserves its category
	 *  ({@code addTagWithCategory}); a brand-new label goes to the OTHER (user/custom)
	 *  category via {@code api.addTag}, since this compact surface has no category
	 *  picker (the dialog's category dropdown is intentionally not mirrored). For
	 *  MULTI every add applies to the whole selection as one compound (one undo). */
	private JComponent buildTagAddSurface()
	{
		// (label, categoryName) -> add an existing tag preserving its category.
		final BiConsumer<String, String> addExisting;
		// label -> create-and-add a brand-new tag (OTHER / user-custom category).
		final Consumer<String> addNew;
		if (dockTagReturn == TagReturn.MULTI)
		{
			final Set<String> ids =
				new LinkedHashSet<>(api.getSelectedGoalIds());
			final int n = ids.size();
			addExisting = (label, cat) -> {
				api.beginCompound("Add tag '" + label + "' to " + n + " goals");
				try
				{
					for (String id : ids)
					{
						api.addTagWithCategory(id, label, cat);
					}
				}
				finally
				{
					api.endCompound();
				}
				closeTagSurface();
			};
			addNew = label -> {
				api.beginCompound("Add tag '" + label + "' to " + n + " goals");
				try
				{
					for (String id : ids)
					{
						api.addTag(id, label);
					}
				}
				finally
				{
					api.endCompound();
				}
				closeTagSurface();
			};
		}
		else
		{
			final String gid = dockTagTarget;
			addExisting = (label, cat) -> { api.addTagWithCategory(gid, label, cat); closeTagSurface(); };
			addNew = label -> { api.addTag(gid, label); closeTagSurface(); };
		}

		JPanel inner = new JPanel(new BorderLayout(0, 6));
		innerPad(inner);

		// Back returns to the prior surface WITHOUT adding anything.
		JPanel head = new JPanel(new WrapLayout(FlowLayout.LEFT, 4, 0));
		head.setOpaque(false);
		head.add(chip("< Back", "Back without adding a tag", this::closeTagSurface));
		inner.add(head, BorderLayout.NORTH);

		JPanel body = new JPanel();
		stack(body);

		final List<com.goalplanner.api.TagView> all = api.queryAllTags();

		// ONE field drives everything (user): typing narrows the existing tags to
		// live suggestions so you attach the tag that already exists instead of
		// creating a near-duplicate; a brand-new label is only created when nothing
		// matches it exactly.
		final JTextField field = new JTextField();
		styleField(field);
		field.setToolTipText("Type to find an existing tag, or create a new one");
		field.setAlignmentX(Component.LEFT_ALIGNMENT);
		field.setMaximumSize(new Dimension(Integer.MAX_VALUE, field.getPreferredSize().height));
		body.add(field);
		body.add(Box.createVerticalStrut(6));

		final JPanel suggest = new JPanel(new WrapLayout(FlowLayout.LEFT, 4, 4));
		loose(suggest);
		body.add(suggest);

		// Enter / the Create chip: an exact (case-insensitive) hit attaches THAT tag
		// with its real category; otherwise the typed label becomes a new tag.
		final Runnable commit = () -> {
			String q = field.getText() == null ? "" : field.getText().trim();
			if (q.isEmpty())
			{
				return;
			}
			for (com.goalplanner.api.TagView t : all)
			{
				if (t.label != null && t.label.equalsIgnoreCase(q))
				{
					addExisting.accept(t.label, t.category);
					return;
				}
			}
			addNew.accept(q);
		};

		final Runnable renderSuggestions = () -> {
			String q = field.getText() == null ? "" : field.getText().trim();
			String needle = q.toLowerCase(Locale.ROOT);
			suggest.removeAll();
			boolean exact = false;
			int shown = 0;
			for (com.goalplanner.api.TagView t : all)
			{
				final String label = t.label;
				if (label == null)
				{
					continue;
				}
				String hay = label.toLowerCase(Locale.ROOT);
				if (hay.equals(needle))
				{
					exact = true;
				}
				if (!needle.isEmpty() && !hay.contains(needle))
				{
					continue;
				}
				if (shown >= TAG_SUGGEST_MAX)
				{
					continue;
				}
				shown++;
				final String cat = t.category;
				String catName = tagCategoryDisplay(cat);
				String tip = catName != null ? "Add " + label + " (" + catName + ")" : "Add " + label;
				suggest.add(chip(label, tip, () -> addExisting.accept(label, cat)));
			}
			if (all.isEmpty())
			{
				suggest.add(mutedTip("No tags yet - type a name to create the first one."));
			}
			else if (shown == 0 && !needle.isEmpty())
			{
				suggest.add(mutedTip("No tag matches that."));
			}
			// Creating is offered only when the text isn't already a tag, so the
			// suggestion above is always the way to reuse an existing one.
			if (!q.isEmpty() && !exact)
			{
				JButton create = flatButton("Create \"" + q + "\"", true);
				create.setToolTipText("Create a new tag named " + q);
				create.addActionListener(e -> commit.run());
				suggest.add(create);
			}
			suggest.setMaximumSize(
				new Dimension(Integer.MAX_VALUE, suggest.getPreferredSize().height));
			refresh(suggest);
			remeasureDock();
		};

		field.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override public void insertUpdate(DocumentEvent e) { renderSuggestions.run(); }
			@Override public void removeUpdate(DocumentEvent e) { renderSuggestions.run(); }
			@Override public void changedUpdate(DocumentEvent e) { renderSuggestions.run(); }
		});
		field.addActionListener(e -> commit.run());
		renderSuggestions.run();

		inner.add(body, BorderLayout.CENTER);
		return surfaceShell("Add Tag", false, inner);
	}

	/** Build the inline Remove Tag surface (GOAL or MULTI): the removable tags as
	 *  rounded tappable chips. Tapping one removes it immediately and re-renders the
	 *  surface (so several can be dropped without leaving); Back returns. For a goal
	 *  the chips are {@link #removableTagsFor}; for MULTI they are the merged
	 *  removable set from {@code api.getRemovableTagsForSelection} (label + count),
	 *  each removed across the selection as one compound. */
	private JComponent buildTagRemoveSurface()
	{
		JPanel inner = new JPanel(new BorderLayout(0, 6));
		innerPad(inner);

		// Back returns to the prior surface WITHOUT changing anything further.
		JPanel head = new JPanel(new WrapLayout(FlowLayout.LEFT, 4, 0));
		head.setOpaque(false);
		head.add(chip("< Back", "Back without removing more tags", this::closeTagSurface));
		inner.add(head, BorderLayout.NORTH);

		JPanel chips = new JPanel(new WrapLayout(FlowLayout.LEFT, 4, 4));
		chips.setOpaque(false);

		boolean any = false;
		if (dockTagReturn == TagReturn.MULTI)
		{
			final Set<String> ids =
				new LinkedHashSet<>(api.getSelectedGoalIds());
			List<com.goalplanner.api.GoalPlannerInternalApi.TagRemovalOption> opts =
				api.getRemovableTagsForSelection(ids);
			for (com.goalplanner.api.GoalPlannerInternalApi.TagRemovalOption o : opts)
			{
				any = true;
				final String tagId = o.tagId;
				final String label = o.label;
				final int count = o.count;
				chips.add(chip(label, "Remove " + label + " (" + count + ") from the selection", () -> {
					api.beginCompound("Remove tag '" + label + "' from selection");
					try
					{
						api.bulkRemoveTagFromGoals(ids, tagId);
					}
					finally
					{
						api.endCompound();
					}
					remountTagSurface();
				}));
			}
		}
		else
		{
			final String gid = dockTagTarget;
			Goal g = goalStore.findGoalById(gid);
			List<Tag> removable = g != null
				? removableTagsFor(g) : Collections.emptyList();
			for (Tag t : removable)
			{
				any = true;
				final String label = t.getLabel();
				chips.add(chip(label,
					"Remove " + label + " (" + t.getCategory().getDisplayName() + ")",
					() -> { api.removeTag(gid, label); remountTagSurface(); }));
			}
		}
		if (!any)
		{
			JLabel none = new JLabel("No tags to remove");
			formFont(none);
			chips.add(none);
		}
		inner.add(chips, BorderLayout.CENTER);
		return surfaceShell("Remove Tag", false, inner);
	}

