	/** Daily / Weekly / Monthly pills for edit mode: the tapped one is highlighted
	 *  AND committed to the goal via {@code setGoalRepeat}. */
	private JComponent buildEditPeriodPills(String gid, com.goalplanner.model.RepeatPeriod[] out)
	{
		com.goalplanner.model.RepeatPeriod[] periods = {
			com.goalplanner.model.RepeatPeriod.DAILY,
			com.goalplanner.model.RepeatPeriod.WEEKLY,
			com.goalplanner.model.RepeatPeriod.MONTHLY };
		JPanel row = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0));
		loose(row);
		List<JButton> pills = new ArrayList<>();
		Map<JButton, com.goalplanner.model.RepeatPeriod> owner = new HashMap<>();
		Runnable refresh = () ->
		{
			for (JButton b : pills)
			{
				boolean sel = owner.get(b) == out[0];
				b.setBackground(sel ? CREATE_SEL_BG : CREATE_TILE_BG);
				b.setForeground(sel ? CREATE_PRIMARY_FG : CREATE_FG);
			}
		};
		for (com.goalplanner.model.RepeatPeriod p : periods)
		{
			JButton b = new RoundedPaint.RoundedButton(p.getLabel());
			b.setFont(b.getFont().deriveFont(11f));
			b.setBorder(new EmptyBorder(3, 10, 3, 10));
			b.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
			pills.add(b);
			owner.put(b, p);
			b.addActionListener(e ->
			{
				out[0] = p;
				refresh.run();
				api.setGoalRepeat(gid, p);
			});
			row.add(b);
		}
		refresh.run();
		return row;
	}

	// ----- edit-mode lifecycle action chips -----


	/** The drill-in groups the SECTION dock chips tree into. EDIT = rename/color/
	 *  delete; LAYOUT = nesting + archive override; SHARE = copy/save codes. */
	private enum SectionGroup { EDIT, LAYOUT, SHARE }

	/** The edit form's action chips, rendered flat. Nothing drills in any more:
	 *  Data is a direct chip row, Relations an itemized inline list, and the
	 *  former [Actions] group now shows its six chips directly. */
	private JComponent buildEditChips(Goal g)
	{
		JPanel wrap = new JPanel(new WrapLayout(FlowLayout.LEFT, 4, 4));
		wrap.setOpaque(false);

		// Flattened: the actions show directly. "Actions" described nothing and
		// hid six chips behind a tap - the same discoverability problem the
		// scrolling strips had. Now that chip rows WRAP there is room to just
		// show them, which completes the "only go deeper when necessary" pass
		// that already flattened Data and Relations.
		buildActionsChips(g, wrap);
		return wrap;
	}

	/** Data group: optional/required, color, tags, restore defaults. */
	private void buildDataChips(Goal g, JPanel wrap)
	{
		final String gid = g.getId();
		final boolean complete = g.isComplete();

		if (!complete)
		{
			wrap.add(chip(g.isOptional() ? "Required" : "Optional",
				g.isOptional() ? "Mark this goal required" : "Mark this goal optional",
				() -> { api.setGoalOptional(gid, !g.isOptional()); refreshEditForm(); }));
		}
		wrap.add(chip("Color", "Change this goal's color",
			() -> openColorSurfaceForGoal(gid)));
		wrap.add(chip("Add tag", "Add a tag to this goal",
			() -> openTagAddSurfaceForGoal(gid)));
		List<Tag> removable = removableTagsFor(g);
		if (!removable.isEmpty())
		{
			wrap.add(chip("Drop tags", "Remove tags from this goal",
				() -> openTagRemoveSurfaceForGoal(gid)));
		}
		if (api.isGoalOverridden(gid))
		{
			wrap.add(chip("Restore defaults", "Reset tags and color to their defaults",
				() -> { api.bulkRestoreDefaults(Collections.singleton(gid)); refreshEditForm(); }));
		}
	}

	/** Actions group: move/copy to section, seed reqs, Loadout Lab, share, remove.
	 *  The Requires / Required-by / Drop-reqs / Drop-dependents chips moved out of a
	 *  drill-in group: relations are now edited inline on the itemized list (per-row
	 *  X + "+ Add relation"). "Add reqs to section" (the seed action) landed here as
	 *  the one relation-adjacent action with no inline-list home. */
	private void buildActionsChips(Goal g, JPanel wrap)
	{
		final String gid = g.getId();
		final GoalType type = g.getType();

		wrap.add(chip("Move", "Move this goal to another section",
			() -> openMoveSurface(MoveMode.MOVE, Collections.singletonList(gid))));
		wrap.add(chip("Copy", "Duplicate this goal into another section",
			() -> openMoveSurface(MoveMode.COPY, Collections.singletonList(gid))));

		if (goalHasSeedableReqs(g))
		{
			wrap.add(chip("Add reqs",
				"Add this goal's requirements into its section", () -> dockSeedReqs(g)));
		}

		if (type == GoalType.BOSS && g.getBossName() != null && !g.getBossName().isEmpty())
		{
			LoadoutLabState labState = loadoutLabState();
			if (labState == LoadoutLabState.ENABLED)
			{
				final String monster = g.getBossName();
				wrap.add(chip("Loadout Lab", "Search this boss in Loadout Lab",
					() -> searchLoadoutLab(monster)));
			}
			else if (labState == LoadoutLabState.INSTALLED_DISABLED)
			{
				JButton off = flatButton("Lab is off", false);
				off.setToolTipText("Loadout Lab is installed but disabled");
				off.setEnabled(false);
				wrap.add(off);
			}
		}

		if (isShareAvailable())
		{
			final List<String> shareIds = Collections.singletonList(gid);
			wrap.add(chip("Share", "Copy or save a share code for this goal",
				() -> openShareForGoals(shareIds)));
		}

		wrap.add(chip("Remove", "Remove this goal (undoable)", () -> api.removeGoal(gid)));
	}

	// ============================================================
	// Section-surface (ADR-0007): the SECTION action dock.
	//
	// A selected section renders its actions as a surface above the permanent
	// create footer, exactly like the goal EDIT view. Assembly lives ONLY here,
	// reached from refreshDock()'s SECTION case (the single-place rule). Every
	// chip REUSES an existing dialog / API / GoalPanel handler - the still-intact
	// GoalContextMenuBuilder section menu is the parity reference; nothing is
	// rebuilt. Built-in sections (Incomplete/Completed/Repeatable) mirror the
	// menu's gating: no rename/delete/archive-override, and Add Goal is hidden on
	// the auto-managed Completed section.
	// ============================================================

	/** Build the section action surface for {@code sv}: a name header, a short
	 *  meta line, and the action chips (drill-in grouped when it gets crowded),
	 *  under a full-width indicator bar naming the section. */
	private JComponent buildSectionDock(com.goalplanner.api.SectionView sv)
	{
		JPanel inner = new JPanel(new BorderLayout(0, 6));
		innerPad(inner);

		int goalCount = countGoalsInSection(sv.id);
		String kind = sv.builtIn
			? (sv.kind != null ? sv.kind.substring(0, 1)
				+ sv.kind.substring(1).toLowerCase(Locale.ROOT) + " (built-in)"
				: "Built-in")
			: "Section";
		JLabel meta = new JLabel(kind + " - " + goalCount
			+ (goalCount == 1 ? " goal" : " goals"));
		dimFont(meta);
		inner.add(meta, BorderLayout.NORTH);

		inner.add(buildSectionChips(sv), BorderLayout.CENTER);
		// The indicator bar names the section (uppercased small-caps), heading the
		// surface so it is unmistakably about this section.
		return surfaceShell(sv.name, false, inner);
	}

	private JComponent buildSectionChips(com.goalplanner.api.SectionView sv)
	{
		JPanel wrap = new JPanel(new WrapLayout(FlowLayout.LEFT, 4, 4));
		wrap.setOpaque(false);

		if (dockSectionGroup == null)
		{
			buildSectionChipsTop(sv, wrap);
			return wrap;
		}

		wrap.add(chip("< Back", "Back to section actions",
			() -> { dockSectionGroup = null; refreshSectionDock(); }));
		switch (dockSectionGroup)
		{
			case EDIT:   buildSectionEditChips(sv, wrap); break;
			case LAYOUT: buildSectionLayoutChips(sv, wrap); break;
			case SHARE:  buildSectionShareChips(sv, wrap); break;
			default:     break;
		}
		return wrap;
	}

	/** Top level: select-all, add-goal, the Edit/Layout/Share groups, deselect. */
	private void buildSectionChipsTop(com.goalplanner.api.SectionView sv, JPanel wrap)
	{
		final String sid = sv.id;
		final boolean builtIn = sv.builtIn;
		final boolean completed = "COMPLETED".equals(sv.kind);
		final int goalCount = countGoalsInSection(sid);

		// Select all / Deselect all - label flips like the menu; hidden when empty.
		if (goalCount > 0)
		{
			final boolean allSel = isAllSelectedInSection(sid);
			wrap.add(chip(allSel ? "Deselect all" : "Select all",
				allSel ? "Deselect every goal in this section"
					: "Select every goal in this section",
				() -> {
					if (allSel) api.deselectAllInSection(sid);
					else api.selectAllInSection(sid);
					// (De)selecting goals moves the dock to the goal/multi state.
				}));
		}

		// Add a goal into this section. Hidden on Completed (auto-managed), mirroring
		// the menu. Task 1: opens the in-dock create flow (type grid + stepper) with
		// this section as the fixed landing target, so the created goal lands here
		// with no section-pick step - not the Swing add-goal dialog.
		if (!completed)
		{
			wrap.add(chip("Add goal", "Add a goal into this section",
				() -> openCreateFlowForSection(sid)));
		}

		// Rename/color/delete only make sense on user sections; a built-in gets a
		// direct Change color chip (the one edit the menu allows on built-ins).
		if (!builtIn)
		{
			wrap.add(chip("Edit", "Rename, change color, or delete",
				() -> { dockSectionGroup = SectionGroup.EDIT; refreshSectionDock(); }));
		}
		else
		{
			wrap.add(chip("Change color", "Change this section's color",
				() -> openColorSurfaceForSection(sv.id)));
		}

		// Layout: dependency nesting (all sections) + completed handling (user only).
		wrap.add(chip("Layout", "Dependency nesting and completed-goal handling",
			() -> { dockSectionGroup = SectionGroup.LAYOUT; refreshSectionDock(); }));

		// Share: only when sharing is available and there are goals to encode.
		if (isShareAvailable() && goalCount > 0)
		{
			wrap.add(chip("Share", "Copy or save a share code",
				() -> { dockSectionGroup = SectionGroup.SHARE; refreshSectionDock(); }));
		}

		wrap.add(chip("Deselect", "Clear the section selection",
			this::clearSectionSelection));
	}

	/** Edit group (user sections only): rename, color, delete. */
	private void buildSectionEditChips(com.goalplanner.api.SectionView sv, JPanel wrap)
	{
		wrap.add(chip("Rename", "Rename this section",
			() -> openRenameSectionSurface(sv.id)));
		wrap.add(chip("Change color", "Change this section's color",
			() -> openColorSurfaceForSection(sv.id)));
		wrap.add(chip("Delete", "Delete this section (undoable)",
			() -> confirmDeleteSection(sv)));
	}

	/** Layout group: the dependency-nesting cycle, plus the completed-goal archive
	 *  cycle on user sections. Each chip's label shows the current state and a tap
	 *  advances it (Default -> On -> Off -> Default), mirroring the menu's radios. */
	private void buildSectionLayoutChips(com.goalplanner.api.SectionView sv, JPanel wrap)
	{
		final String sid = sv.id;

		final boolean indentDefault = config.showDependenciesIndented();
		final Boolean nested = sv.nestedOverride;
		wrap.add(chip("Nesting", "Choose how this section shows dependencies",
			() -> openChoiceSurface("Nesting",
				new String[]{"Default (" + (indentDefault ? "nested" : "flat") + ")",
					"Nested", "Flat"},
				nested == null ? 0 : (Boolean.TRUE.equals(nested) ? 1 : 2),
				i -> {
					api.setSectionNestedOverride(sid,
						i == 0 ? null : Boolean.valueOf(i == 1));
					refreshSectionDock();
				})));

		if (!sv.builtIn)
		{
			final boolean archiveDefault = api.isAutoArchiveDefault();
			final Boolean archive = sv.autoArchiveOverride;
			wrap.add(chip("Completed", "Choose how completed goals are handled here",
				() -> openChoiceSurface("Completed goals",
					new String[]{"Default (" + (archiveDefault ? "archive" : "inline") + ")",
						"Archive", "Keep inline"},
					archive == null ? 0 : (Boolean.TRUE.equals(archive) ? 1 : 2),
					i -> {
						api.setSectionAutoArchiveOverride(sid,
							i == 0 ? null : Boolean.valueOf(i == 1));
						refreshSectionDock();
					})));
		}
	}

	/** Share group: open the inline Share surface for this section or for all
	 *  sections (the surface carries both Copy and, when wired, Save). */
	private void buildSectionShareChips(com.goalplanner.api.SectionView sv, JPanel wrap)
	{
		final String sid = sv.id;
		wrap.add(chip("Share section", "Copy or save a share code for this section",
			() -> openShareForSection(sid)));
		wrap.add(chip("Share all", "Copy or save a share code for all sections",
			this::openShareForAllSections));
	}

	/** The section delete confirm as a choice surface (was a JOptionPane with
	 *  a checkbox): the move-instead option becomes its own explicit choice,
	 *  Back cancels. Clears the selection on either pick since the section is
	 *  about to vanish. Undoable either way. */
	private void confirmDeleteSection(com.goalplanner.api.SectionView sv)
	{
		final String sid = sv.id;
		int goalCount = countGoalsInSection(sid);
		Runnable clear = () -> {
			selectedSectionId = null;
			dockSectionGroup = null;
		};
		if (goalCount == 0)
		{
			openChoiceSurface("Delete section \"" + sv.name + "\"? Undoable.",
				new String[]{"Delete section"}, -1, pick -> {
					clear.run();
					api.deleteSection(sid, false);
				});
			return;
		}
		String plural = goalCount == 1 ? "goal" : "goals";
		openChoiceSurface(
			"Delete section \"" + sv.name + "\" and its " + goalCount + " "
				+ plural + "? Undoable.",
			new String[]{
				"Delete section and " + plural,
				"Move " + plural + " to Default, delete section"}, -1, pick -> {
				clear.run();
				api.deleteSection(sid, pick == 1);
			});
	}

	/** Dock form-text styling, factored from ~66 repeated call sites. The
	 *  panel builds its surfaces by hand (no layout framework), so these three
	 *  property triples were the real duplication - not the surfaces themselves. */
	private static void dimLabel(JComponent c)
	{
		dimFont(c);
		c.setAlignmentX(Component.LEFT_ALIGNMENT);
	}

	private static void formLabel(JComponent c)
	{
		formFont(c);
		c.setAlignmentX(Component.LEFT_ALIGNMENT);
	}

	private static void dimFont(JComponent c)
	{
		c.setForeground(CREATE_FG_DIM);
		c.setFont(c.getFont().deriveFont(10f));
	}

	private static void formFont(JComponent c)
	{
		c.setForeground(CREATE_FG);
		c.setFont(c.getFont().deriveFont(11f));
	}

	/** Transparent and vertically stacked (the reverse-order twin of column). */
	private static void stack(JComponent c)
	{
		c.setOpaque(false);
		c.setLayout(new BoxLayout(c, BoxLayout.Y_AXIS));
	}

	/** Re-lay-out and repaint a live component after its contents change. */
	private static void refresh(JComponent c)
	{
		c.revalidate();
		c.repaint();
	}

	/** Transparent, left-aligned, vertically stacked. */
	private static void column(JComponent c)
	{
		c.setLayout(new BoxLayout(c, BoxLayout.Y_AXIS));
		loose(c);
	}

	/** Transparent and left-aligned - the default for anything inside a surface. */
	private static void loose(JComponent c)
	{
		c.setOpaque(false);
		c.setAlignmentX(Component.LEFT_ALIGNMENT);
	}

	/** A surface's outer panel: transparent with the standard inset. */
	private static void innerPad(JComponent c)
	{
		c.setOpaque(false);
		c.setBorder(new EmptyBorder(6, 8, 8, 8));
	}

	private JButton chip(String label, String tooltip, Runnable action)
	{
		JButton b = flatButton(label, false);
		b.setToolTipText(tooltip);
		b.addActionListener(e -> action.run());
		return b;
	}

	/** A panel that fills the dock's width when hosted in the expanded scroll
	 *  area, so the BoxLayout rows and the {@link WrapLayout} chip flow lay out
	 *  against the real dock width. A plain JPanel would take only its preferred
	 *  width and clip (the dock suppresses horizontal scrolling), and the
	 *  full-width indicator bar would not span the dock. */
	private static final class ScrollablePanel extends JPanel implements Scrollable
	{
		/** When set, the panel paints a rounded card fill of this color (glam
		 *  surfaces); null keeps it fully transparent (result columns). */
		private Color cardBg = null;

		ScrollablePanel(LayoutManager lm) { super(lm); }

		/** Paint a rounded {@link RoundedPaint#SURFACE_RADIUS} card behind this
		 *  panel so a surface reads as a card. Returns this for chaining. */
		ScrollablePanel asCard(Color bg) { this.cardBg = bg; return this; }

		@Override
		protected void paintComponent(Graphics g)
		{
			if (cardBg != null)
			{
				Graphics2D g2 = (Graphics2D) g.create();
				try
				{
					RoundedPaint.fill(g2, 0, 0, getWidth(), getHeight(),
						RoundedPaint.SURFACE_RADIUS, cardBg);
				}
				finally
				{
					g2.dispose();
				}
			}
			super.paintComponent(g);
		}

		@Override public Dimension getPreferredScrollableViewportSize() { return getPreferredSize(); }
		@Override public int getScrollableUnitIncrement(Rectangle r, int o, int d) { return 16; }
		@Override public int getScrollableBlockIncrement(Rectangle r, int o, int d) { return 48; }
		@Override public boolean getScrollableTracksViewportWidth() { return true; }
		@Override public boolean getScrollableTracksViewportHeight() { return false; }
	}

}

package com.goalplanner.ui;

import com.goalplanner.api.GoalPlannerApiImpl;
import com.goalplanner.api.GoalView;
import com.goalplanner.model.Goal;
import com.goalplanner.persistence.GoalStore;

import java.util.List;

/**
 * Handles goal reordering within sections, including topo-aware chain
 * moves that respect requirement edges. Extracted from GoalPanel.
 */
class GoalReorderController
{
	private final GoalPlannerApiImpl api;
	private final GoalStore goalStore;

	GoalReorderController(GoalPlannerApiImpl api, GoalStore goalStore)
	{
		this.api = api;
		this.goalStore = goalStore;
	}


	/** Move a goal directly to a target index within its section. */
	void moveGoalTo(String goalId, int toIndex)
	{
		api.moveGoal(goalId, toIndex);
	}

	/**
	 * Topo-aware chain move via recursive descent. Wrapped in a compound
	 * so one Ctrl+Z reverses the whole gesture.
	 */
	void moveChainInTopo(String goalId, String sectionId, boolean up)
	{
		api.beginCompound(up ? "Move up" : "Move down");
		try
		{
			moveRecursive(goalId, sectionId, up, 0);
		}
		finally
		{
			api.endCompound();
		}
	}

	/**
	 * One step of the recursive descent. Returns true if the goal
	 * successfully moved by one position in the requested direction.
	 */
	private boolean moveRecursive(String goalId, String sectionId, boolean up, int depth)
	{
		if (depth > 256) return false;

		List<GoalView> topo = api.queryGoalsTopologicallySorted(sectionId);
		int pos = -1;
		for (int i = 0; i < topo.size(); i++)
		{
			if (goalId.equals(topo.get(i).id)) { pos = i; break; }
		}
		if (pos < 0) return false;
		int targetPos = up ? pos - 1 : pos + 1;
		if (targetPos < 0 || targetPos >= topo.size()) return false;

		GoalView adjacent = topo.get(targetPos);

		boolean blocked;
		if (up)
		{
			blocked = goalDirectlyRequires(goalId, adjacent.id);
		}
		else
		{
			blocked = goalDirectlyRequires(adjacent.id, goalId);
		}

		if (blocked)
		{
			boolean blockerMoved = moveRecursive(adjacent.id, sectionId, up, depth + 1);
			if (!blockerMoved) return false;
			return moveRecursive(goalId, sectionId, up, depth + 1);
		}

		int adjacentFlatIdx = globalIndexOf(adjacent.id);
		if (adjacentFlatIdx < 0) return false;
		return api.moveGoal(goalId, adjacentFlatIdx);
	}

	/**
	 * Does fromId's goal have a direct requirement edge pointing at toId?
	 */
	boolean goalDirectlyRequires(String fromId, String toId)
	{
		if (fromId == null || toId == null) return false;
		Goal g = goalStore.findGoalById(fromId);
		if (g == null) return false;
		return g.getRequiredGoalIds() != null
			&& g.getRequiredGoalIds().contains(toId);
	}

	/** Global (flat-priority) index of the given goal, or -1 if missing. */
	int globalIndexOf(String goalId)
	{
		List<Goal> goals = goalStore.getGoals();
		for (int i = 0; i < goals.size(); i++)
		{
			if (goals.get(i).getId().equals(goalId)) return i;
		}
		return -1;
	}

	/**
	 * Resolve a goal id to a display-friendly name. Returns the id itself
	 * if no match (defensive fallback).
	 */
	String goalNameById(String goalId)
	{
		if (goalId == null) return "(unknown)";
		Goal g = goalStore.findGoalById(goalId);
		if (g == null) return goalId;
		return g.getName() != null ? g.getName() : goalId;
	}
}

package com.goalplanner.ui;

import net.runelite.client.game.ItemManager;
import net.runelite.client.util.AsyncBufferedImage;

import javax.swing.ImageIcon;
import javax.swing.JLabel;
import javax.swing.SwingUtilities;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Cache for scaled item images. Uses AsyncBufferedImage.onLoaded()
 * to properly handle RuneLite's async image loading.
 */
public final class ItemImageCache
{
	private ItemImageCache() {}

	private static final ConcurrentHashMap<Integer, ImageIcon> CACHE = new ConcurrentHashMap<>();

	/**
	 * Get a cached icon, or null if not yet loaded.
	 */
	public static ImageIcon get(int itemId)
	{
		return CACHE.get(itemId);
	}

	/**
	 * Set a JLabel's icon to the item image. Handles async loading properly.
	 * If cached, sets immediately. If not, sets when loaded via callback.
	 */
	public static void applyTo(JLabel label, int itemId, ItemManager itemManager)
	{
		ImageIcon cached = CACHE.get(itemId);
		if (cached != null)
		{
			label.setIcon(cached);
			return;
		}

		// Request async image and register callback
		AsyncBufferedImage abi = itemManager.getImage(itemId);
		abi.onLoaded(() ->
		{
			BufferedImage scaled = new BufferedImage(18, 18, BufferedImage.TYPE_INT_ARGB);
			Graphics2D g2d = scaled.createGraphics();
			g2d.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
			g2d.drawImage(abi, 0, 0, 18, 18, null);
			g2d.dispose();

			ImageIcon icon = new ImageIcon(scaled);
			CACHE.put(itemId, icon);

			SwingUtilities.invokeLater(() ->
			{
				label.setIcon(icon);
				label.revalidate();
				label.repaint();
			});
		});
	}
}

package com.goalplanner.ui;

import com.goalplanner.PanelFontFamily;
import com.goalplanner.PanelFontScale;
import java.awt.Font;
import javax.swing.UIManager;

/**
 * Central resolver for Goal Planner panel fonts so the family + size scale chosen
 * in config apply everywhere through one path. Call sites use
 * {@link #derive(int, float)} in place of {@code component.getFont().deriveFont(...)},
 * which previously pinned both family and size.
 *
 * <p>Configured once at start-up and again whenever the relevant config changes
 * (see {@code GoalPlannerPlugin}); the panel is rebuilt afterwards so the new
 * fonts take effect. All reads/writes happen on the Swing EDT; the fields are
 * {@code volatile} as a cheap guard regardless.
 */
public final class PanelFonts
{
	private PanelFonts()
	{
	}

	// Store the CHOICE, not a frozen Font. The base font is resolved live on every
	// derive() call so DEFAULT always tracks the look-and-feel's current Label.font -
	// exactly like the old per-call {@code component.getFont().deriveFont(...)}. A
	// font frozen at configure()-time could capture a not-yet-themed L&F and leave
	// every panel label stuck on the wrong face.
	private static volatile PanelFontFamily family = PanelFontFamily.DEFAULT;
	private static volatile float scale = 1.0f;
	// Bumped on every configure() so callers that cache rendered components (e.g.
	// the GoalPanel card-reuse signature) can detect a font change and rebuild -
	// a reused card keeps the font it was constructed with otherwise.
	private static volatile int generation = 0;

	/** Apply the configured family + size scale. Safe to call repeatedly. */
	public static void configure(PanelFontFamily fontFamily, PanelFontScale fontScale)
	{
		family = fontFamily != null ? fontFamily : PanelFontFamily.DEFAULT;
		scale = fontScale.getMultiplier();
		generation++;
	}

	/** Monotonic token that changes whenever the configured font changes. */
	public static int generation()
	{
		return generation;
	}

	/** The configured size multiplier - so fixed-pixel layouts (card heights,
	 *  icon sizes) can grow with the font instead of clipping larger text. */
	public static float scale()
	{
		return scale;
	}

	/** Font at {@code size} (scaled) in the given {@link Font} style. */
	public static Font derive(int style, float size)
	{
		return resolveBase(family).deriveFont(style, size * scale);
	}

	/** Plain font at {@code size} (scaled). */
	public static Font derive(float size)
	{
		return derive(Font.PLAIN, size);
	}

	/** Restyle at the base size (scaled) - for call sites that only changed style. */
	public static Font derive(int style)
	{
		Font base = resolveBase(family);
		return base.deriveFont(style, base.getSize2D() * scale);
	}

	private static Font resolveBase(PanelFontFamily family)
	{
		switch (family)
		{
			case SANS_SERIF:
				return new Font(Font.SANS_SERIF, Font.PLAIN, 12);
			case SERIF:
				return new Font(Font.SERIF, Font.PLAIN, 12);
			case DEFAULT:
			default:
				// The look-and-feel's base label font (FlatLaf), with a sane fallback.
				Font label = UIManager.getFont("Label.font");
				return label != null ? label : new Font(Font.DIALOG, Font.PLAIN, 12);
		}
	}
}

package com.goalplanner.ui;

/**
 * Pure helpers for resolving "gain X more" relative goal inputs into the
 * absolute target values stored on Goal entities.
 *
 * <p>Relative goals are an input convenience only - once resolved, the goal
 * is indistinguishable from one created with the same absolute target. The
 * math lives here so it can be unit-tested without spinning up Swing or the
 * RuneLite client.
 */
public final class RelativeTargetResolver
{
	private RelativeTargetResolver() {}

	/** OSRS XP cap. Skill XP saturates here regardless of what the user enters. */
	public static final int MAX_SKILL_XP = 200_000_000;

	/**
	 * Resolve a "gain N XP" delta against the player's current XP for a skill.
	 * Negative or zero deltas are returned as -1 to signal "invalid input" so
	 * the caller can show an error message.
	 *
	 * @param currentXp the player's current XP for the skill (>= 0)
	 * @param deltaXp the XP the user wants to gain (must be > 0)
	 * @return resolved absolute XP target, clamped at {@link #MAX_SKILL_XP},
	 *         or -1 if delta is non-positive
	 */
	public static int resolveSkillXp(int currentXp, int deltaXp)
	{
		if (deltaXp <= 0) return -1;
		long sum = (long) Math.max(0, currentXp) + (long) deltaXp;
		return (int) Math.min((long) MAX_SKILL_XP, sum);
	}

	/**
	 * Resolve a "get N more kills" delta against the player's current kill count for
	 * a boss/activity. An unknown or unreadable current count is treated as 0, so the
	 * target falls back to the raw delta rather than failing - the user still gets a
	 * goal (used by the dock's boss Relative mode, Task 2).
	 *
	 * @param currentKc the player's current kill count (an unknown/negative read is floored to 0)
	 * @param delta the extra kills the user wants (must be > 0)
	 * @return resolved absolute kill target, or -1 if delta is non-positive
	 */
	public static int resolveKillCount(int currentKc, int delta)
	{
		if (delta <= 0) return -1;
		long sum = (long) Math.max(0, currentKc) + (long) delta;
		return (int) Math.min((long) Integer.MAX_VALUE, sum);
	}

}

package com.goalplanner.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Component;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Insets;
import java.awt.LayoutManager;
import java.awt.RenderingHints;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JButton;
import javax.swing.JPanel;
import javax.swing.border.Border;

/**
 * The single source of rounded, antialiased corners across the action dock
 * (glam pass). Swing paints hard 90-degree rectangles for buttons, panels, and
 * borders; this utility replaces that with tasteful rounded corners rendered
 * with {@link RenderingHints#KEY_ANTIALIASING} on, so corners stay smooth at
 * every font scale.
 *
 * <p>One radius vocabulary keeps everything visually consistent: {@link #RADIUS}
 * for the small interactive elements (buttons, tiles, chips, pills, fields) and
 * {@link #SURFACE_RADIUS} for the larger surface cards. Callers should reuse
 * {@link RoundedButton}, {@link RoundedPanel}, and {@link #border} rather than
 * scattering their own {@code fillRoundRect} calls.
 */
public final class RoundedPaint
{
	/** Corner radius for the small interactive elements - buttons, tiles, chips,
	 *  pills, fields. Nicely rounded, not bubble-round. */
	public static final int RADIUS = 8;
	/** Corner radius for the larger surface cards (create / edit / section
	 *  surfaces and their indicator bars). */
	public static final int SURFACE_RADIUS = 11;

	private RoundedPaint()
	{
	}

	/** Fill an antialiased rounded rectangle of corner {@code radius} in
	 *  {@code color}. The graphics is not disposed (caller owns it). */
	public static void fill(Graphics2D g2, int x, int y, int w, int h, int radius, Color color)
	{
		if (color == null || w <= 0 || h <= 0)
		{
			return;
		}
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g2.setColor(color);
		g2.fillRoundRect(x, y, w, h, radius * 2, radius * 2);
	}

	/** Fill a rectangle whose TOP corners are rounded and bottom corners square -
	 *  for a full-bleed header bar that caps a card. Achieved by rounding a taller
	 *  rect whose rounded bottom falls below the visible bounds. */
	public static void fillTop(Graphics2D g2, int w, int h, int radius, Color color)
	{
		if (color == null || w <= 0 || h <= 0)
		{
			return;
		}
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g2.setColor(color);
		g2.fillRoundRect(0, 0, w, h + radius, radius * 2, radius * 2);
	}

	/** A reusable antialiased rounded-rectangle border: a hairline stroke in
	 *  {@code color} plus {@code padding} inner insets. Radius is the corner
	 *  radius; thickness is the stroke width. */
	public static Border border(Color color, int thickness, int radius, Insets padding)
	{
		return new RoundedBorder(color, thickness, radius, padding);
	}

	/**
	 * An antialiased rounded-rectangle {@link Border}. Reports {@code padding} as
	 * its insets (so it doubles as the component's inner padding), and strokes a
	 * rounded outline in {@code color}. A transparent color paints only padding
	 * (useful when a component wants rounded padding but no visible outline).
	 */
	public static final class RoundedBorder implements Border
	{
		private final Color color;
		private final int thickness;
		private final int radius;
		private final Insets padding;

		public RoundedBorder(Color color, int thickness, int radius, Insets padding)
		{
			this.color = color;
			this.thickness = Math.max(1, thickness);
			this.radius = radius;
			this.padding = padding != null ? padding : new Insets(0, 0, 0, 0);
		}

		@Override
		public Insets getBorderInsets(Component c)
		{
			return new Insets(padding.top, padding.left, padding.bottom, padding.right);
		}

		@Override
		public boolean isBorderOpaque()
		{
			return false;
		}

		@Override
		public void paintBorder(Component c, Graphics g, int x, int y, int width, int height)
		{
			if (color == null || color.getAlpha() == 0 || width <= 0 || height <= 0)
			{
				return;
			}
			Graphics2D g2 = (Graphics2D) g.create();
			try
			{
				g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
					RenderingHints.VALUE_ANTIALIAS_ON);
				g2.setColor(color);
				g2.setStroke(new BasicStroke(thickness));
				float off = thickness / 2f;
				g2.draw(new RoundRectangle2D.Float(
					x + off, y + off,
					width - thickness, height - thickness,
					radius * 2, radius * 2));
			}
			finally
			{
				g2.dispose();
			}
		}
	}

	/**
	 * A {@link JButton} that paints an antialiased rounded background from its
	 * current {@code getBackground()} (so hover / disabled background swaps still
	 * work) instead of the L&amp;F's square fill. Content-area fill and opacity
	 * are turned off in the constructor so no square corners bleed through; keep
	 * them off in callers. An optional top accent stripe (for the create tiles)
	 * inherits the rounded top corners.
	 */
	public static class RoundedButton extends JButton
	{
		private final int radius;
		private Color topAccent = null;
		private int topAccentHeight = 0;

		public RoundedButton(String text)
		{
			this(text, RADIUS);
		}

		public RoundedButton(String text, int radius)
		{
			super(text);
			this.radius = radius;
			setContentAreaFilled(false);
			setBorderPainted(false);
			setFocusPainted(false);
			setOpaque(false);
		}

		/** Paint a full-width accent stripe of {@code height} px across the top,
		 *  clipped to the rounded shape so it keeps the rounded top corners. */
		public RoundedButton withTopAccent(Color accent, int height)
		{
			this.topAccent = accent;
			this.topAccentHeight = height;
			return this;
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			try
			{
				int w = getWidth();
				int h = getHeight();
				fill(g2, 0, 0, w, h, radius, getBackground());
				if (topAccent != null && topAccentHeight > 0)
				{
					g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
						RenderingHints.VALUE_ANTIALIAS_ON);
					g2.clip(new RoundRectangle2D.Float(0, 0, w, h, radius * 2, radius * 2));
					g2.setColor(topAccent);
					g2.fillRect(0, 0, w, topAccentHeight);
				}
			}
			finally
			{
				g2.dispose();
			}
			super.paintComponent(g);
		}
	}

	/**
	 * A {@link JPanel} that paints an antialiased rounded background from its
	 * {@code getBackground()}. Kept non-opaque so the rounded corners reveal
	 * whatever is behind; set a background to draw a rounded card / row.
	 */
	public static class RoundedPanel extends JPanel
	{
		private final int radius;

		public RoundedPanel(LayoutManager layout, int radius)
		{
			super(layout);
			this.radius = radius;
			setOpaque(false);
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Color bg = getBackground();
			if (bg != null)
			{
				Graphics2D g2 = (Graphics2D) g.create();
				try
				{
					fill(g2, 0, 0, getWidth(), getHeight(), radius, bg);
				}
				finally
				{
					g2.dispose();
				}
			}
			super.paintComponent(g);
		}
	}
}

package com.goalplanner.ui;

import com.goalplanner.api.SectionView;

import javax.swing.BorderFactory;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.border.EmptyBorder;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.BasicStroke;
import java.awt.Graphics2D;
import java.awt.Graphics;
import java.awt.Image;
import java.util.function.BooleanSupplier;
import javax.swing.ImageIcon;

/**
 * A row rendered as a section header in the goal panel.
 * The chevron on the left edge is the collapse target (click it to
 * collapse/expand); its shape indicates the current state (down = expanded,
 * right = collapsed). Clicking anywhere else on the row SELECTS the section, so
 * the action dock shows that section's actions (mirrors clicking a goal card).
 * A selected header paints a highlight border. When the section has goals, a
 * checkbox glyph on the right edge selects/unselects all of them in one click
 * (mirrors the context menu's "Select All in Section"); it neither selects nor
 * collapses the section.
 */
public class SectionHeaderRow extends JPanel
{
	private static final Color BORDER_COLOR = new Color(60, 60, 60);
	private static final Color TEXT_COLOR = new Color(200, 200, 200);
	private static final Color CHEVRON_COLOR = new Color(160, 160, 160);
	/** Selection highlight stroke - matches GoalCard's white selection outline. */
	private static final Color SELECT_COLOR = Color.WHITE;
	private static final int ROW_HEIGHT = 22;
	private static final int CHEVRON_WIDTH = 14;
	private static final int CHECKBOX_SIZE = 10;

	/**
	 * Multiplier applied to each RGB channel of a user-picked section color so
	 * the header always has enough darkness to contrast against the existing
	 * light-grey label text. Lower = darker; 0.55 keeps the hue obvious while
	 * guaranteeing WCAG-ish contrast with 200-grey text.
	 */
	private static final double DARKEN_FACTOR = 0.55;

	/** Whether this header has a user color override; if so, paint a darkened fill. */
	private final boolean hasColor;
	private final Color darkenedFill;

	/** Select-all toggle state - null when the section has no goals (no glyph shown). */
	private final BooleanSupplier allSelectedState;
	private final JLabel selectToggle;

	/** This header's section id, so the panel can match it against the current
	 *  section selection when refreshing the highlight without a full rebuild. */
	private final String sectionId;
	/** Whether this section is the currently selected one (paints a highlight). */
	private boolean selected;

	public SectionHeaderRow(SectionView section, int goalCount, Runnable onToggle)
	{
		this(section, goalCount, onToggle, null, null, null, false);
	}

	/**
	 * @param onSelect runs when the row body (anywhere but the chevron and the
	 *                 select-all toggle) is left-clicked - selects the section so
	 *                 the dock shows its actions. Null leaves the row unselectable.
	 * @param allSelectedState true when every goal in the section is currently
	 *                         selected (drives the glyph + tooltip); null hides
	 *                         the select-all toggle entirely.
	 * @param onToggleSelectAll runs on glyph click - select all when not all
	 *                          selected, unselect all otherwise.
	 */
	public SectionHeaderRow(SectionView section, int goalCount, Runnable onToggle,
		Runnable onSelect,
		BooleanSupplier allSelectedState, Runnable onToggleSelectAll,
		boolean allCompleted)
	{
		this.sectionId = section.id;
		setLayout(new BorderLayout());

		// User-set color fills the header face with a darkened version of the
		// picked color so the existing light-grey label text always contrasts.
		// Default sections stay transparent with a 1px neutral underline.
		this.hasColor = section.colorOverridden;
		if (hasColor)
		{
			Color picked = new Color(section.colorRgb);
			this.darkenedFill = new Color(
				(int) (picked.getRed() * DARKEN_FACTOR),
				(int) (picked.getGreen() * DARKEN_FACTOR),
				(int) (picked.getBlue() * DARKEN_FACTOR));
			setOpaque(false); // paintComponent draws the fill manually
		}
		else
		{
			this.darkenedFill = null;
			setOpaque(false);
		}
		setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 0, 1, 0, BORDER_COLOR),
			new EmptyBorder(4, 8, 4, 8)
		));
		// Match GoalCard's sizing idiom so BoxLayout treats the row identically:
		// preferred width 0 + max width MAX_VALUE + default CENTER alignment lets the
		// row stretch to the full panel width.
		setPreferredSize(new Dimension(0, ROW_HEIGHT));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, ROW_HEIGHT));
		setAlignmentX(Component.CENTER_ALIGNMENT);
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

		// Programmatic shape icon avoids font-fallback failure on macOS Tahoe
		// where ▶/▼ Unicode glyphs render as missing-glyph placeholders.
		JLabel chevron = new JLabel(section.collapsed
			? ShapeIcons.rightTriangle(8, CHEVRON_COLOR)
			: ShapeIcons.downTriangle(8, CHEVRON_COLOR));
		chevron.setPreferredSize(new Dimension(CHEVRON_WIDTH, ROW_HEIGHT));
		chevron.setToolTipText(section.collapsed ? "Expand section" : "Collapse section");
		// The chevron is the collapse target. It has its own listener, so Swing
		// routes clicks on it here and NOT to the row's select listener below - the
		// two are cleanly separated (chevron = collapse, row body = select).
		chevron.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				if (e.getButton() == MouseEvent.BUTTON1 && onToggle != null)
				{
					onToggle.run();
				}
			}
		});

		JLabel nameLabel = new JLabel(section.name.toUpperCase(), SwingConstants.CENTER);
		nameLabel.setForeground(TEXT_COLOR);
		nameLabel.setFont(PanelFonts.derive(Font.BOLD, 10f));

		// Right edge: the select-all/unselect-all checkbox when the section has
		// goals, otherwise an empty spacer of equal width so the centered name
		// stays visually centered despite the chevron on the left edge.
		this.allSelectedState = allSelectedState;
		// Right edge: an optional all-complete badge to the LEFT of the select-all
		// toggle. BorderLayout (not FlowLayout) so children stretch to the row's
		// bordered content height instead of being clipped at their preferred size.
		JPanel eastPanel = new JPanel(new BorderLayout(2, 0));
		eastPanel.setOpaque(false);

		// Every goal in a non-empty section is complete -> show the plugin's
		// completion icon as a section badge, scaled to fit the short header row.
		if (allCompleted && goalCount > 0)
		{
			ImageIcon src = GoalCard.completionIcon();
			if (src != null)
			{
				int px = ROW_HEIGHT - 10; // fit within the 4px-bordered content height
				Image scaled = src.getImage().getScaledInstance(px, px, Image.SCALE_SMOOTH);
				JLabel doneBadge = new JLabel(new ImageIcon(scaled));
				doneBadge.setToolTipText("All goals in this section are complete");
				eastPanel.add(doneBadge, BorderLayout.WEST);
			}
		}

		if (allSelectedState != null && onToggleSelectAll != null && goalCount > 0)
		{
			this.selectToggle = new JLabel();
			// A few px wider than the chevron column: the glyph is a small
			// target, so give the hit area some slack.
			selectToggle.setPreferredSize(new Dimension(CHEVRON_WIDTH + 6, ROW_HEIGHT));
			selectToggle.setHorizontalAlignment(SwingConstants.CENTER);
			refreshSelectToggle();
			selectToggle.addMouseListener(new MouseAdapter()
			{
				@Override
				public void mousePressed(MouseEvent e)
				{
					// mousePressed, not mouseClicked: clicked only fires when
					// press and release land on the same pixel, so rapid
					// repeat clicks (which drift slightly) get swallowed.
					// Swing doesn't bubble child events to the row, so this
					// never also triggers the collapse toggle.
					if (e.getButton() == MouseEvent.BUTTON1)
					{
						onToggleSelectAll.run();
					}
				}
			});
			eastPanel.add(selectToggle, BorderLayout.EAST);
		}
		else
		{
			this.selectToggle = null;
			JLabel spacer = new JLabel();
			spacer.setPreferredSize(new Dimension(CHEVRON_WIDTH, ROW_HEIGHT));
			eastPanel.add(spacer, BorderLayout.EAST);
		}
		add(eastPanel, BorderLayout.EAST);

		add(chevron, BorderLayout.WEST);
		add(nameLabel, BorderLayout.CENTER);

		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				// Clicking the row body SELECTS the section - left OR right click
				// (right-click is retired as a context-menu trigger in 1.0.0; it now
				// just selects, like on goal cards). The chevron and select-all glyph
				// have their own listeners, so their clicks never reach here.
				if ((e.getButton() == MouseEvent.BUTTON1 || e.getButton() == MouseEvent.BUTTON3)
					&& onSelect != null)
				{
					onSelect.run();
				}
			}
		});
	}

	/** This header's section id. */
	public String getSectionId()
	{
		return sectionId;
	}

	/** Paint (or clear) the selected-section highlight. Called by the panel when
	 *  the section selection changes without a full list rebuild. */
	public void setSelected(boolean sel)
	{
		if (this.selected != sel)
		{
			this.selected = sel;
			repaint();
		}
	}

	/**
	 * Re-read the selection state and update the checkbox glyph + tooltip.
	 * Called by the panel whenever the goal selection changes (the header rows
	 * themselves aren't rebuilt on selection-only updates).
	 */
	public void refreshSelectToggle()
	{
		if (selectToggle == null || allSelectedState == null)
		{
			return;
		}
		boolean allSelected = allSelectedState.getAsBoolean();
		selectToggle.setIcon(allSelected
			? ShapeIcons.checkboxChecked(CHECKBOX_SIZE, CHEVRON_COLOR)
			: ShapeIcons.checkboxEmpty(CHECKBOX_SIZE, CHEVRON_COLOR));
		selectToggle.setToolTipText(allSelected
			? "Unselect all in section"
			: "Select all in section");
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		// Paint the darkened user-color fill ourselves so FlatLaf/UI delegates
		// don't override it. Matches the pattern in ColorPickerField swatches
		// and GoalCard's background paint.
		if (hasColor && darkenedFill != null)
		{
			g.setColor(darkenedFill);
			g.fillRect(0, 0, getWidth(), getHeight());
		}
		super.paintComponent(g);

		// Selection outline, painted last so it sits above the fill and the
		// bottom hairline. Mirrors GoalCard's 2px inset white outline.
		if (selected)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setColor(SELECT_COLOR);
			g2.setStroke(new BasicStroke(2f));
			g2.drawRect(1, 1, getWidth() - 3, getHeight() - 3);
			g2.dispose();
		}
	}
}

package com.goalplanner.ui;

import javax.swing.Icon;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Component;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Path2D;
import java.awt.geom.AffineTransform;

/**
 * Programmatic Swing icons for the small UI glyphs we used to render with
 * Unicode characters (▲ ▼ ▶ ✕). Drawing the shapes via Graphics2D avoids the
 * font-fallback failure on macOS Tahoe (and any other OS/JDK combo where the
 * BMP-Symbols glyphs aren't in the default sans-serif fallback chain), and
 * scales cleanly at any DPI.
 *
 * Visual treatment is OSRS sprite-inspired: a four-tone bevel with a dark
 * outline, a base fill, a brighter top/left highlight, and a subtle drop
 * shadow underneath. It's chunky on purpose - feels at home next to RuneLite.
 */
public final class ShapeIcons
{
	private ShapeIcons() {}

	/** Solid upward-pointing triangle (OSRS-bevel styling). */
	public static Icon upTriangle(int size, Color color)
	{
		return new TriangleIcon(size, color, Direction.UP);
	}

	/** Solid downward-pointing triangle (OSRS-bevel styling). */
	public static Icon downTriangle(int size, Color color)
	{
		return new TriangleIcon(size, color, Direction.DOWN);
	}

	/** Solid right-pointing triangle (collapsed chevron). */
	public static Icon rightTriangle(int size, Color color)
	{
		return new TriangleIcon(size, color, Direction.RIGHT);
	}

	/** "Close" / X icon - beveled diagonals like an OSRS UI button. */
	public static Icon closeX(int size, Color color)
	{
		return new CloseIcon(size, color);
	}




	/** Curved undo arrow - left-facing hook. */
	public static Icon undoArrow(int size, Color color)
	{
		return new UndoArrow(size, color, true);
	}

	/** Curved redo arrow - right-facing hook (mirror of undo). */
	public static Icon redoArrow(int size, Color color)
	{
		return new UndoArrow(size, color, false);
	}

	/** Horizontal three-dot glyph for "more options" / overflow menus. */
	public static Icon moreDots(int size, Color color)
	{
		return new MoreDotsIcon(size, color);
	}

	/** Empty checkbox outline - "select all" affordance. */
	public static Icon checkboxEmpty(int size, Color color)
	{
		return new CheckboxIcon(size, color, false);
	}

	/** Ticked checkbox - "unselect all" affordance (everything already selected). */
	public static Icon checkboxChecked(int size, Color color)
	{
		return new CheckboxIcon(size, color, true);
	}

	/** Warning triangle with an exclamation - the "blocked by prereqs" badge. */
	public static Icon warning(int size, Color color)
	{
		return new WarningIcon(size, color);
	}

	private enum Direction { UP, DOWN, RIGHT }

	// ----- color helpers -----

	/** Darken a color by a fixed amount, clamped at 0. Used for outlines/shadows. */
	private static Color darken(Color c, int amount)
	{
		return new Color(
			Math.max(0, c.getRed() - amount),
			Math.max(0, c.getGreen() - amount),
			Math.max(0, c.getBlue() - amount),
			c.getAlpha()
		);
	}

	/** Brighten a color by a fixed amount, clamped at 255. Used for highlights. */
	private static Color lighten(Color c, int amount)
	{
		return new Color(
			Math.min(255, c.getRed() + amount),
			Math.min(255, c.getGreen() + amount),
			Math.min(255, c.getBlue() + amount),
			c.getAlpha()
		);
	}

	private static final class TriangleIcon implements Icon
	{
		private final int size;
		private final Color color;
		private final Direction dir;

		TriangleIcon(int size, Color color, Direction dir)
		{
			this.size = size;
			this.color = color;
			this.dir = dir;
		}

		@Override
		public void paintIcon(Component c, Graphics g, int x, int y)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			try
			{
				g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

				Path2D body = trianglePath(x, y, size, dir);

				// Drop shadow - same shape, offset 1px down/right, semi-transparent
				Path2D shadow = trianglePath(x + 1, y + 1, size, dir);
				g2.setColor(new Color(0, 0, 0, 110));
				g2.fill(shadow);

				// Base fill
				g2.setColor(color);
				g2.fill(body);

				// Top/leading-edge highlight - partial stroke along the brightest edge
				g2.setColor(lighten(color, 60));
				g2.setStroke(new BasicStroke(1.0f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				drawHighlightEdge(g2, x, y, size, dir);

				// Outline - dark border for chunky OSRS feel
				g2.setColor(darken(color, 90));
				g2.setStroke(new BasicStroke(1.0f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				g2.draw(body);
			}
			finally
			{
				g2.dispose();
			}
		}

		private static Path2D trianglePath(int x, int y, int size, Direction dir)
		{
			Path2D p = new Path2D.Float();
			switch (dir)
			{
				case UP:
					p.moveTo(x + size / 2.0, y);
					p.lineTo(x + size, y + size);
					p.lineTo(x, y + size);
					break;
				case DOWN:
					p.moveTo(x, y);
					p.lineTo(x + size, y);
					p.lineTo(x + size / 2.0, y + size);
					break;
				case RIGHT:
					p.moveTo(x, y);
					p.lineTo(x + size, y + size / 2.0);
					p.lineTo(x, y + size);
					break;
			}
			p.closePath();
			return p;
		}

		private static void drawHighlightEdge(Graphics2D g2, int x, int y, int size, Direction dir)
		{
			switch (dir)
			{
				case UP:
					// Left slope
					g2.drawLine(x + size / 2, y, x, y + size);
					break;
				case DOWN:
					// Top edge
					g2.drawLine(x, y, x + size, y);
					break;
				case RIGHT:
					// Top slope
					g2.drawLine(x, y, x + size, y + size / 2);
					break;
			}
		}

		@Override public int getIconWidth() { return size + 1; }
		@Override public int getIconHeight() { return size + 1; }
	}

	private static final class MinusIcon implements Icon
	{
		private final int size;
		private final Color color;

		MinusIcon(int size, Color color)
		{
			this.size = size;
			this.color = color;
		}

		@Override
		public void paintIcon(Component c, Graphics g, int x, int y)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			try
			{
				g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				int pad = 1;
				int x1 = x + pad, x2 = x + size - pad;
				int cy = y + size / 2;

				// Drop shadow
				g2.setStroke(new BasicStroke(2.4f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				g2.setColor(new Color(0, 0, 0, 130));
				g2.drawLine(x1 + 1, cy + 1, x2 + 1, cy + 1);

				// Outline (thicker dark stroke)
				g2.setStroke(new BasicStroke(2.4f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				g2.setColor(darken(color, 100));
				g2.drawLine(x1, cy, x2, cy);

				// Base color (slightly thinner so the dark outline shows)
				g2.setStroke(new BasicStroke(1.4f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				g2.setColor(color);
				g2.drawLine(x1, cy, x2, cy);

				// Highlight along the upper edge of the bar
				g2.setStroke(new BasicStroke(0.6f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				g2.setColor(lighten(color, 80));
				g2.drawLine(x1, cy - 1, x1 + 2, cy - 1);
			}
			finally
			{
				g2.dispose();
			}
		}

		@Override public int getIconWidth() { return size + 1; }
		@Override public int getIconHeight() { return size + 1; }
	}

	private static final class PlusIcon implements Icon
