	private static final class CloseIcon implements Icon
	{
		private final int size;
		private final Color color;

		CloseIcon(int size, Color color)
		{
			this.size = size;
			this.color = color;
		}

		@Override
		public void paintIcon(Component c, Graphics g, int x, int y)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			try
			{
				g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				int pad = 1;
				int x1 = x + pad, y1 = y + pad;
				int x2 = x + size - pad, y2 = y + size - pad;

				// Drop shadow - diagonals offset 1px
				g2.setStroke(new BasicStroke(2.4f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				g2.setColor(new Color(0, 0, 0, 130));
				g2.drawLine(x1 + 1, y1 + 1, x2 + 1, y2 + 1);
				g2.drawLine(x2 + 1, y1 + 1, x1 + 1, y2 + 1);

				// Outline - slightly thicker dark stroke
				g2.setStroke(new BasicStroke(2.4f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				g2.setColor(darken(color, 100));
				g2.drawLine(x1, y1, x2, y2);
				g2.drawLine(x2, y1, x1, y2);

				// Base color stroke on top - slightly thinner so the dark outline shows
				g2.setStroke(new BasicStroke(1.4f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				g2.setColor(color);
				g2.drawLine(x1, y1, x2, y2);
				g2.drawLine(x2, y1, x1, y2);

				// Highlight - thin bright stroke along the upper edges of the diagonals
				g2.setStroke(new BasicStroke(0.6f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				g2.setColor(lighten(color, 80));
				g2.drawLine(x1, y1, x1 + 2, y1 + 2);
				g2.drawLine(x2, y1, x2 - 2, y1 + 2);
			}
			finally
			{
				g2.dispose();
			}
		}

		@Override public int getIconWidth() { return size + 1; }
		@Override public int getIconHeight() { return size + 1; }
	}

	private static final class UndoArrow implements Icon
	{
		private final int size;
		private final Color color;
		private final boolean mirrored;

		UndoArrow(int size, Color color, boolean mirrored)
		{
			this.size = size;
			this.color = color;
			this.mirrored = mirrored;
		}

		@Override
		public void paintIcon(Component c, Graphics g, int x, int y)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			try
			{
				g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

				// Draw a 3/4 arc with an arrowhead at one end. The arc opens
				// downward and the head sits on the upper-left (undo) or
				// upper-right (redo, mirrored).
				int pad = 2;
				int s = size - pad;
				int cx = x + size / 2;
				int cy = y + size / 2 + 1;
				int r = s / 2;

				if (mirrored)
				{
					// Flip horizontally around the center
					AffineTransform at = g2.getTransform();
					g2.translate(2 * cx, 0);
					g2.scale(-1, 1);
				}

				// Drop shadow arc
				g2.setStroke(new BasicStroke(2.4f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				g2.setColor(new Color(0, 0, 0, 110));
				g2.drawArc(cx - r + 1, cy - r + 1, r * 2, r * 2, 60, 240);

				// Outline arc
				g2.setStroke(new BasicStroke(2.4f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				g2.setColor(darken(color, 100));
				g2.drawArc(cx - r, cy - r, r * 2, r * 2, 60, 240);

				// Base color arc
				g2.setStroke(new BasicStroke(1.4f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				g2.setColor(color);
				g2.drawArc(cx - r, cy - r, r * 2, r * 2, 60, 240);

				// Arrowhead at the end of the arc (60° = upper-right of arc circle).
				// The arc starts at angle 60 (upper right) and sweeps 240° CCW,
				// ending at angle 300. We place the head at the START (60°).
				double startAngleRad = Math.toRadians(60);
				int hx = (int) Math.round(cx + r * Math.cos(startAngleRad));
				int hy = (int) Math.round(cy - r * Math.sin(startAngleRad));
				int headSize = Math.max(2, s / 4);
				Path2D head = new Path2D.Float();
				head.moveTo(hx, hy);
				head.lineTo(hx - headSize, hy);
				head.lineTo(hx, hy - headSize);
				head.closePath();
				g2.setColor(darken(color, 100));
				g2.fill(head);
				g2.setColor(color);
				g2.draw(head);
			}
			finally
			{
				g2.dispose();
			}
		}

		@Override public int getIconWidth() { return size + 2; }
		@Override public int getIconHeight() { return size + 2; }
	}

	private static final class TagIcon implements Icon
	{
		private final int size;
		private final Color color;

		TagIcon(int size, Color color)
		{
			this.size = size;
			this.color = color;
		}

		@Override
		public void paintIcon(Component c, Graphics g, int x, int y)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			try
			{
				g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

				// Tag silhouette: a quad with a triangular point on the left.
				// The eyelet hole is a small circle near the point.
				int pad = 1;
				int x0 = x + pad, y0 = y + pad;
				int s = size - pad * 2;
				int pointX = x0;
				int bodyLeft = x0 + s / 4;
				int right = x0 + s;
				int top = y0;
				int bottom = y0 + s;
				int midY = y0 + s / 2;

				Path2D body = new Path2D.Float();
				body.moveTo(pointX, midY);
				body.lineTo(bodyLeft, top);
				body.lineTo(right, top);
				body.lineTo(right, bottom);
				body.lineTo(bodyLeft, bottom);
				body.closePath();

				// Drop shadow
				Path2D shadow = new Path2D.Float();
				shadow.append(body.getPathIterator(AffineTransform.getTranslateInstance(1, 1)), false);
				g2.setColor(new Color(0, 0, 0, 110));
				g2.fill(shadow);

				// Base fill
				g2.setColor(color);
				g2.fill(body);

				// Outline
				g2.setColor(darken(color, 90));
				g2.setStroke(new BasicStroke(1.0f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				g2.draw(body);

				// Eyelet hole - small circle just inside the body near the point
				int holeR = Math.max(1, s / 6);
				int holeCx = bodyLeft + holeR + 1;
				int holeCy = midY;
				g2.setColor(darken(color, 90));
				g2.fillOval(holeCx - holeR, holeCy - holeR, holeR * 2, holeR * 2);
				g2.setColor(new Color(40, 40, 40));
				g2.fillOval(holeCx - holeR + 1, holeCy - holeR + 1, holeR * 2 - 2, holeR * 2 - 2);

				// Top-edge highlight
				g2.setColor(lighten(color, 60));
				g2.setStroke(new BasicStroke(1.0f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				g2.drawLine(bodyLeft + 1, top + 1, right - 1, top + 1);
			}
			finally
			{
				g2.dispose();
			}
		}

		@Override public int getIconWidth() { return size + 2; }
		@Override public int getIconHeight() { return size + 2; }
	}

	/** Three horizontal dots - universal "more options" glyph. */
	private static final class MoreDotsIcon implements Icon
	{
		private final int size;
		private final Color color;

		MoreDotsIcon(int size, Color color)
		{
			this.size = size;
			this.color = color;
		}

		@Override
		public void paintIcon(Component c, Graphics g, int x, int y)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			try
			{
				g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				int dot = Math.max(2, size / 4);
				int cy = y + size / 2 - dot / 2;
				int span = size - dot;
				int cx1 = x;
				int cx2 = x + span / 2;
				int cx3 = x + span;

				// Drop shadow
				g2.setColor(new Color(0, 0, 0, 120));
				g2.fillOval(cx1 + 1, cy + 1, dot, dot);
				g2.fillOval(cx2 + 1, cy + 1, dot, dot);
				g2.fillOval(cx3 + 1, cy + 1, dot, dot);

				// Dots
				g2.setColor(color);
				g2.fillOval(cx1, cy, dot, dot);
				g2.fillOval(cx2, cy, dot, dot);
				g2.fillOval(cx3, cy, dot, dot);
			}
			finally
			{
				g2.dispose();
			}
		}

		@Override public int getIconWidth() { return size + 1; }
		@Override public int getIconHeight() { return size + 1; }
	}
	/**
	 * Square checkbox, empty or ticked - same four-tone bevel treatment as the
	 * other glyphs. Used as the section-header select-all/unselect-all toggle.
	 */
	private static final class CheckboxIcon implements Icon
	{
		private final int size;
		private final Color color;
		private final boolean checked;

		CheckboxIcon(int size, Color color, boolean checked)
		{
			this.size = size;
			this.color = color;
			this.checked = checked;
		}

		@Override
		public void paintIcon(Component c, Graphics g, int x, int y)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			try
			{
				g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				int pad = 1;
				int x1 = x + pad, y1 = y + pad;
				int box = size - 2 * pad;

				// Drop shadow
				g2.setStroke(new BasicStroke(1.6f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				g2.setColor(new Color(0, 0, 0, 110));
				g2.drawRect(x1 + 1, y1 + 1, box, box);

				// Outline
				g2.setColor(darken(color, 100));
				g2.drawRect(x1, y1, box, box);

				// Base color box
				g2.setStroke(new BasicStroke(1.0f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				g2.setColor(color);
				g2.drawRect(x1, y1, box, box);

				// Highlight along the top edge
				g2.setStroke(new BasicStroke(0.6f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				g2.setColor(lighten(color, 80));
				g2.drawLine(x1 + 1, y1 + 1, x1 + box - 1, y1 + 1);

				if (checked)
				{
					// Tick: short down-stroke then long up-stroke, inset in the box.
					int tx1 = x1 + box / 5;
					int ty1 = y1 + box / 2;
					int tx2 = x1 + (int) (box * 0.42);
					int ty2 = y1 + box - box / 4;
					int tx3 = x1 + box - box / 6;
					int ty3 = y1 + box / 5;
					g2.setStroke(new BasicStroke(1.8f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
					g2.setColor(darken(color, 100));
					g2.drawLine(tx1 + 1, ty1 + 1, tx2 + 1, ty2 + 1);
					g2.drawLine(tx2 + 1, ty2 + 1, tx3 + 1, ty3 + 1);
					g2.setStroke(new BasicStroke(1.4f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
					g2.setColor(lighten(color, 60));
					g2.drawLine(tx1, ty1, tx2, ty2);
					g2.drawLine(tx2, ty2, tx3, ty3);
				}
			}
			finally
			{
				g2.dispose();
			}
		}

		@Override public int getIconWidth() { return size + 1; }
		@Override public int getIconHeight() { return size + 1; }
	}

	/** Rounded warning triangle with a beveled exclamation mark. */
	private static final class WarningIcon implements Icon
	{
		private final int size;
		private final Color color;

		WarningIcon(int size, Color color)
		{
			this.size = size;
			this.color = color;
		}

		@Override
		public void paintIcon(Component c, Graphics g, int x, int y)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			try
			{
				g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				Path2D tri = new Path2D.Float();
				tri.moveTo(x + size / 2.0, y);
				tri.lineTo(x + size, y + size);
				tri.lineTo(x, y + size);
				tri.closePath();

				// Drop shadow
				g2.setColor(new Color(0, 0, 0, 90));
				g2.translate(1, 1);
				g2.fill(tri);
				g2.translate(-1, -1);

				// Body + dark outline
				g2.setColor(color);
				g2.fill(tri);
				g2.setStroke(new BasicStroke(1.0f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				g2.setColor(darken(color, 110));
				g2.draw(tri);

				// Exclamation: short bar + dot, dark for contrast on the amber body.
				int cx = x + size / 2;
				g2.setColor(darken(color, 150));
				g2.setStroke(new BasicStroke(Math.max(1.2f, size / 7f), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				g2.drawLine(cx, y + (int) (size * 0.40), cx, y + (int) (size * 0.66));
				g2.fillOval(cx - 1, y + (int) (size * 0.74), 2, 2);
			}
			finally
			{
				g2.dispose();
			}
		}

		@Override public int getIconWidth() { return size + 2; }
		@Override public int getIconHeight() { return size + 2; }
	}
}

package com.goalplanner.ui;

import net.runelite.api.Experience;

import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextField;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import java.awt.Dimension;
import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.awt.Insets;

/**
 * A two-row form with synchronized Level and XP fields. Editing either field
 * updates the other on the fly so the user can target a level or a raw XP value
 * with whichever feels more natural. Both rows always reflect the same goal.
 *
 * <p>Used by both the panel Add Goal dialog (skill type) and the Skills-tab
 * right-click "Add Goal" handler so the UX is identical in both places.
 */
public class SkillTargetForm extends JPanel
{
	private final JTextField levelField = new JTextField(8);
	private final JTextField xpField = new JTextField(8);
	private final JLabel levelLabel = new JLabel("Level:");

	/** Suppress the cross-update listener while we programmatically set a field. */
	private boolean syncing = false;

	/** When >= 0, the form interprets both fields as DELTAS over
	 *  this current XP baseline (relative goal mode). When -1, fields are
	 *  absolute targets (existing behavior). */
	private int relativeBaselineXp = -1;

	public SkillTargetForm(int initialLevel)
	{
		super(new GridBagLayout());
		setOpaque(false);

		GridBagConstraints gbc = new GridBagConstraints();
		gbc.insets = new Insets(3, 4, 3, 4);
		gbc.anchor = GridBagConstraints.WEST;

		gbc.gridx = 0; gbc.gridy = 0; gbc.fill = GridBagConstraints.NONE; gbc.weightx = 0;
		levelLabel.setPreferredSize(new Dimension(60, 24));
		add(levelLabel, gbc);

		gbc.gridx = 1; gbc.fill = GridBagConstraints.HORIZONTAL; gbc.weightx = 1;
		add(levelField, gbc);

		gbc.gridx = 0; gbc.gridy = 1; gbc.fill = GridBagConstraints.NONE; gbc.weightx = 0;
		JLabel xpLabel = new JLabel("XP:");
		xpLabel.setPreferredSize(new Dimension(60, 24));
		add(xpLabel, gbc);

		gbc.gridx = 1; gbc.fill = GridBagConstraints.HORIZONTAL; gbc.weightx = 1;
		add(xpField, gbc);

		// Wire bidirectional sync via DocumentListeners. The `syncing` guard prevents
		// the level→xp update from re-triggering xp→level (and vice versa).
		// When relativeBaselineXp >= 0, both fields are interpreted
		// as DELTAS - level field input = "+N levels", XP field input = "+N XP".
		levelField.getDocument().addDocumentListener(new SimpleDocumentListener(() -> {
			if (syncing) return;
			Integer level = parseInt(levelField.getText());
			if (level == null) return;
			int xp;
			if (relativeBaselineXp >= 0)
			{
				// level is a delta over current; resulting absolute level is current+delta
				int currentLevel = Experience.getLevelForXp(relativeBaselineXp);
				int targetLevel = Math.min(126, currentLevel + level);
				if (targetLevel < 1) return;
				int targetXp = targetLevel <= 99
					? Experience.getXpForLevel(targetLevel)
					: Experience.getXpForLevel(99);
				xp = Math.max(0, targetXp - relativeBaselineXp);
			}
			else
			{
				if (level < 1 || level > 126) return;
				xp = level <= 99
					? Experience.getXpForLevel(level)
					: Experience.getXpForLevel(99);
			}
			syncing = true;
			try { xpField.setText(Integer.toString(xp)); }
			finally { syncing = false; }
		}));

		xpField.getDocument().addDocumentListener(new SimpleDocumentListener(() -> {
			if (syncing) return;
			Integer xp = parseInt(xpField.getText());
			if (xp == null || xp < 0 || xp > 200_000_000) return;
			int level;
			if (relativeBaselineXp >= 0)
			{
				// xp is a delta; resulting level is levelForXp(baseline + delta),
				// shown as the delta over the current level so the field stays consistent.
				int currentLevel = Experience.getLevelForXp(relativeBaselineXp);
				long resultingXp = Math.min(200_000_000L, (long) relativeBaselineXp + xp);
				int resultingLevel = Experience.getLevelForXp((int) resultingXp);
				level = resultingLevel - currentLevel;
			}
			else
			{
				level = Experience.getLevelForXp(xp);
			}
			syncing = true;
			try { levelField.setText(Integer.toString(level)); }
			finally { syncing = false; }
		}));

		// Seed both fields from the initial level. The level setter triggers the
		// listener which fills in the XP field.
		levelField.setText(Integer.toString(initialLevel));
	}


	/** @return target XP currently represented by the form, or -1 if invalid. */
	public int getTargetXp()
	{
		Integer xp = parseInt(xpField.getText());
		if (xp == null || xp < 0 || xp > 200_000_000) return -1;
		return xp;
	}

	/**
	 * Seed the form to an absolute target XP (edit mode). Writing the XP field
	 * lets the sync listener fill in the matching level, so both rows agree.
	 */
	public void setTargetXp(int xp)
	{
		xpField.setText(Integer.toString(xp));
	}


	private static Integer parseInt(String s)
	{
		if (s == null) return null;
		String trimmed = s.trim().replace(",", "");
		if (trimmed.isEmpty()) return null;
		try { return Integer.parseInt(trimmed); }
		catch (NumberFormatException e) { return null; }
	}

	/** Adapter so we can supply a single Runnable instead of three method overrides. */
	private static class SimpleDocumentListener implements DocumentListener
	{
		private final Runnable onChange;
		SimpleDocumentListener(Runnable onChange) { this.onChange = onChange; }
		@Override public void insertUpdate(DocumentEvent e) { onChange.run(); }
		@Override public void removeUpdate(DocumentEvent e) { onChange.run(); }
		@Override public void changedUpdate(DocumentEvent e) { onChange.run(); }
	}
}

package com.goalplanner.ui;

import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Insets;
import javax.swing.JScrollPane;
import javax.swing.SwingUtilities;

/**
 * A {@link FlowLayout} that reports a real preferred HEIGHT once its rows wrap,
 * so a container can grow to fit instead of clipping.
 *
 * <p>Extracted from GoalPanel so the action dock can wrap its chip strips too:
 * a horizontally scrolling strip on a 225px panel hides actions behind a pan
 * gesture with no scrollbar and no affordance.
 */
/** A {@link FlowLayout} that reports a wrapped preferred size, so chips flow
 *  onto multiple lines and grow the dock vertically instead of overflowing a
 *  fixed-width, horizontal-scroll-suppressed surface. */
public final class WrapLayout extends FlowLayout
{
	public WrapLayout(int align, int hgap, int vgap) { super(align, hgap, vgap); }

	@Override public Dimension preferredLayoutSize(Container target) { return layoutSize(target, true); }

	@Override public Dimension minimumLayoutSize(Container target)
	{
		Dimension d = layoutSize(target, false);
		d.width -= (getHgap() + 1);
		return d;
	}

	private Dimension layoutSize(Container target, boolean preferred)
	{
		synchronized (target.getTreeLock())
		{
			int targetWidth = target.getSize().width;
			if (targetWidth == 0)
			{
				targetWidth = Integer.MAX_VALUE;
			}
			int hgap = getHgap();
			int vgap = getVgap();
			Insets insets = target.getInsets();
			int maxWidth = targetWidth - (insets.left + insets.right + hgap * 2);
			Dimension dim = new Dimension(0, 0);
			int rowWidth = 0;
			int rowHeight = 0;
			int n = target.getComponentCount();
			for (int i = 0; i < n; i++)
			{
				Component m = target.getComponent(i);
				if (!m.isVisible())
				{
					continue;
				}
				Dimension d = preferred ? m.getPreferredSize() : m.getMinimumSize();
				if (rowWidth + d.width > maxWidth && rowWidth > 0)
				{
					dim.width = Math.max(dim.width, rowWidth);
					dim.height += rowHeight + vgap;
					rowWidth = 0;
					rowHeight = 0;
				}
				if (rowWidth != 0)
				{
					rowWidth += hgap;
				}
				rowWidth += d.width;
				rowHeight = Math.max(rowHeight, d.height);
			}
			dim.width = Math.max(dim.width, rowWidth);
			dim.height += rowHeight;
			dim.width += insets.left + insets.right + hgap * 2;
			dim.height += insets.top + insets.bottom + vgap * 2;
			return dim;
		}
	}
}

package com.goalplanner.ui.dock;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.GridLayout;
import java.awt.Insets;
import java.awt.RenderingHints;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.border.Border;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import com.goalplanner.ui.RoundedPaint;
import net.runelite.client.ui.ColorScheme;
import java.awt.Cursor;
import java.awt.Font;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.Locale;
import javax.swing.BoxLayout;
import javax.swing.JScrollBar;

/**
 * The permanent control panel docked under the goal list (ADR-0007).
 *
 * <p>Two fixed-height rows of compact action buttons. Selection changes swap
 * the CONTENT, never the height - a dock that resizes on click shifts the
 * list under the cursor. Each row is a horizontally scrollable strip, so
 * overflow is reached by scrolling, never via a popup menu (removing popups
 * is the whole point). A chevron collapses the dock to a slim handle;
 * collapse is session-only for now.
 *
 * <p>The dock is deliberately dumb: it renders whatever {@link Row} lists the
 * panel hands it. All state decisions live in {@link DockContext}; all action
 * assembly lives in GoalPanel, so the coming parity pass edits one method.
 */
public class ActionDock extends JPanel
{
	/** One dock button: short ASCII label, one-clause tooltip, action. */
	public static final class Item
	{
		final String label;
		final String tooltip;
		final Runnable action;
		final boolean enabled;

		public Item(String label, String tooltip, Runnable action)
		{
			this(label, tooltip, action, true);
		}

		public Item(String label, String tooltip, Runnable action, boolean enabled)
		{
			this.label = label;
			this.tooltip = tooltip;
			this.action = action;
			this.enabled = enabled;
		}
	}

	/** The two strips. Either may be empty (the row still reserves height). */
	public static final class Rows
	{
		final List<Item> top;
		final List<Item> bottom;
		final String hint;
		/** Optional full-width button pinned ABOVE the two strips (e.g. the MULTI
		 *  "Deselect (N)"); null for none. */
		final Item lead;

		/** @param hint short status text shown at the left of the top row
		 *              (e.g. "3 selected"); null for none. */
		public Rows(String hint, List<Item> top, List<Item> bottom)
		{
			this(hint, top, bottom, null);
		}

		public Rows(String hint, List<Item> top, List<Item> bottom, Item lead)
		{
			this.hint = hint;
			this.top = top != null ? top : List.of();
			this.bottom = bottom != null ? bottom : List.of();
			this.lead = lead;
		}
	}

	private static final int ROW_H = 26;
	private static final int PEEK_H = 28;
	/** Ceiling for the create surface's expanded height; taller forms scroll
	 *  inside the dock rather than shoving the list off-screen (ADR-0008 says
	 *  the form grows to fit, but the list must keep a usable minimum). */
	private static final int CREATE_MAX_H = 300;

	private final JPanel content = new JPanel();
	private final JPanel centerHost = new JPanel(new BorderLayout());
	/** Holds the mounted surface (content strips or a custom view) BELOW the grab
	 *  handle, so swapping the surface never removes the handle (Task 8). */
	private final JPanel surfaceHost = new JPanel(new BorderLayout());
	/** Holds the optional full-width lead button above the strips (MULTI
	 *  "Deselect (N)"); hidden when no lead is set. */
	private final JPanel leadHost = new JPanel(new BorderLayout());
	private final JPanel topRow = strip();
	private final JPanel bottomRow = strip();
	/** Drag-down / click-to-dismiss handle pinned at the top of the expanded
	 *  surface (Task 8). Only visible while expanded (it lives inside centerHost,
	 *  which hides on collapse). */
	private final GrabHandle grabHandle = new GrabHandle();
	/** Panel-supplied dismiss action: clear whatever drives the surface (goal /
	 *  section selection, create nav) and collapse, so the dock rests at the footer
	 *  from ANY state. Falls back to a plain collapse when unset. */
	private Runnable onDismiss = null;
	// The PERMANENT footer: Create Goal | Create Section, always visible in every
	// state (ADR-0008 refinement). The contextual surface (create grid/form, a
	// selected goal's edit view, or the multi-select action strips) renders ABOVE
	// it in centerHost; the footer never swaps out and stays put when collapsed.
	private final JButton createGoalBtn = new RoundedPaint.RoundedButton("Create Goal");
	private final JButton createSectionBtn = new RoundedPaint.RoundedButton("Create Section");
	private final JPanel footerRow = new JPanel(new GridLayout(1, 2, 1, 0));
	private Runnable onCreateGoal = null;
	private Runnable onCreateSection = null;
	private boolean collapsed = true; // rest = just the permanent footer, surface hidden
	private Rows current = new Rows(null, List.of(), List.of());
	/** The surface component currently mounted above the footer (create grid/form
	 *  or an edit view), or null when the dock is in button-strip (multi) mode. */
	private JComponent customView = null;

	public ActionDock()
	{
		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		// An engraved, center-glowing rule marks the seam between the goal list and
		// the dock - a deliberate separator rather than a flat hairline (Task C).
		setBorder(new DockDivider());

		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setOpaque(false);
		leadHost.setOpaque(false);
		leadHost.setVisible(false);
		leadHost.setAlignmentX(Component.LEFT_ALIGNMENT);
		content.add(leadHost);
		content.add(wrapStrip(topRow));
		content.add(wrapStrip(bottomRow));

		// Opaque dark backing so nothing behind the dock (e.g. an optional goal's
		// diagonal hatch in the list) bleeds through the rounded, non-opaque surface
		// card or the non-opaque DockDivider seam.
		centerHost.setOpaque(true);
		centerHost.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		// The grab handle stays pinned at the top of the expanded surface; the
		// swappable surface (strips or a custom view) lives in surfaceHost below it.
		surfaceHost.setOpaque(true);
		surfaceHost.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		surfaceHost.add(content, BorderLayout.CENTER);
		centerHost.add(grabHandle, BorderLayout.NORTH);
		centerHost.add(surfaceHost, BorderLayout.CENTER);

		buildFooterRow();
		// Surface above, permanent create footer below.
		add(centerHost, BorderLayout.CENTER);
		add(footerRow, BorderLayout.SOUTH);
		applyCollapsed();
	}

	/**
	 * Wire the two permanent footer buttons. The footer is always visible, so
	 * this only (re)binds the callbacks the panel wants to run when Create Goal /
	 * Create Section are tapped. The caller owns the toggle/switch semantics
	 * (open the create surface, switch modes, or collapse) - the dock just
	 * forwards the click.
	 */
	public void setFooterActions(Runnable onCreateGoal, Runnable onCreateSection)
	{
		this.onCreateGoal = onCreateGoal;
		this.onCreateSection = onCreateSection;
	}

	/** Wire the drag-down / click dismiss action (Task 8). The panel clears the
	 *  surface drivers (selection, section, create nav) and collapses; without it
	 *  the handle just collapses the surface. */
	public void setOnDismiss(Runnable onDismiss)
	{
		this.onDismiss = onDismiss;
	}

	/** Fired by the grab handle: hand off to the panel-supplied dismiss, or fall
	 *  back to a plain collapse. */
	private void triggerDismiss()
	{
		if (onDismiss != null)
		{
			onDismiss.run();
		}
		else
		{
			setExpanded(false);
		}
	}

	/**
	 * Show or hide the contextual surface above the footer. The footer stays put
	 * either way. Collapsed = rest (just the two-button footer, list keeps its
	 * height); expanded = the mounted surface renders above the footer. The panel
	 * drives this: a selection auto-expands, a deselect collapses, the footer
	 * buttons toggle it.
	 */
	public void setExpanded(boolean expanded)
	{
		boolean wantCollapsed = !expanded;
		if (collapsed == wantCollapsed)
		{
			return; // already in the requested state
		}
		collapsed = wantCollapsed;
		applyCollapsed();
	}

	/** Whether the contextual surface is currently showing above the footer. */
	public boolean isExpanded()
	{
		return !collapsed;
	}

	/** Replace the expanded content with the two button strips (selection
	 *  mode). Does not force the dock open. */
	public void setRows(Rows rows)
	{
		if (customView != null)
		{
			// Leave create mode: swap the strips back into the surface host.
			surfaceHost.removeAll();
			surfaceHost.add(content, BorderLayout.CENTER);
			customView = null;
		}
		this.current = rows;
		renderLead(rows.lead);
		rebuildStrip(topRow, rows.hint, rows.top);
		rebuildStrip(bottomRow, null, rows.bottom);
		revalidate();
		repaint();
	}

	/** Render (or clear) the full-width lead button pinned above the strips. A
	 *  null lead hides the host so it reserves no height. */
	private void renderLead(Item lead)
	{
		leadHost.removeAll();
		if (lead == null || lead.action == null)
		{
			leadHost.setVisible(false);
			return;
		}
		JButton b = leadButton(lead.label, lead.tooltip, lead.action);
		leadHost.add(b, BorderLayout.CENTER);
		leadHost.setMaximumSize(new Dimension(Integer.MAX_VALUE,
			b.getPreferredSize().height + 4));
		leadHost.setVisible(true);
	}

	/** Build a full-width "lead" button styled like the MULTI "Deselect (N)" bar
	 *  pinned above the strips. Shared so the single-goal edit surface can pin an
	 *  identical Deselect at its top (single + multi match). */
	public static JButton leadButton(String label, String tooltip, Runnable action)
	{
		final JButton b = new RoundedPaint.RoundedButton(label);
		b.setToolTipText(tooltip);
		b.setBackground(BTN_BG);
		b.setForeground(BTN_FG);
		b.setFont(b.getFont().deriveFont(Font.BOLD, 11f));
		b.setBorder(BorderFactory.createEmptyBorder(5, 9, 5, 9));
		b.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		b.addMouseListener(new MouseAdapter()
		{
			@Override public void mouseEntered(MouseEvent e) { b.setBackground(BTN_HOVER); }
			@Override public void mouseExited(MouseEvent e) { b.setBackground(BTN_BG); }
		});
		if (action != null)
		{
			b.addActionListener(e -> action.run());
		}
		return b;
	}

	/**
	 * Replace the expanded content with an arbitrary component - the create
	 * surface (type grid or a type-specific form) from ADR-0008. The dock
	 * grows to fit it, capped at {@link #CREATE_MAX_H}; beyond that the form
	 * scrolls inside the dock. Does not force the dock open.
	 */
	public void setExpandedComponent(JComponent view)
	{
		this.customView = view;
		surfaceHost.removeAll();
		// The view must TRACK the viewport width: a plain panel reports the
		// preferred width of its widest row, and with the horizontal bar
		// forbidden the overflow was simply clipped - the Options surface
		// lost every chip past the dock edge (field report 2026-08-27).
		// Width-tracked, WrapLayout learns the real width and wraps.
		JScrollPane sp = new JScrollPane(new TracksWidth(view),
			JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED,
			JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
		sp.setBorder(null);
		// Opaque (dock background) rather than transparent: the surface must fully
		// cover whatever is behind the dock, or an optional goal's diagonal hatch
		// shows through the rounded card's margins.
		sp.setOpaque(true);
		sp.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		sp.getViewport().setOpaque(true);
		sp.getViewport().setBackground(ColorScheme.DARKER_GRAY_COLOR);
		sp.getVerticalScrollBar().setUnitIncrement(16);
		surfaceHost.add(sp, BorderLayout.CENTER);
		revalidate();
		repaint();
	}

	/** A viewport view pinned to the viewport's width, never wider - the
	 * vertical-only scroll contract, made true for layout as well. */
	private static final class TracksWidth extends JPanel implements javax.swing.Scrollable
	{
		TracksWidth(JComponent view)
		{
			super(new BorderLayout());
			setOpaque(false);
			add(view, BorderLayout.CENTER);
		}

		@Override
		public Dimension getPreferredScrollableViewportSize()
		{
			return getPreferredSize();
		}

		@Override
		public int getScrollableUnitIncrement(java.awt.Rectangle r, int o, int d)
		{
			return 16;
		}

		@Override
		public int getScrollableBlockIncrement(java.awt.Rectangle r, int o, int d)
		{
			return 64;
		}

		@Override
		public boolean getScrollableTracksViewportWidth()
		{
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight()
		{
			return false;
		}
	}

	private static JPanel strip()
	{
		JPanel p = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 2));
		p.setOpaque(false);
		// LEFT, not the JPanel default of CENTER: BoxLayout lines its children
		// up by their alignment points, so a centred strip beside the
		// left-aligned "Deselect (N)" lead pushed that button to the right half
		// of the dock. The old scroll strips hid this by declaring a preferred
		// width of 0.
		p.setAlignmentX(Component.LEFT_ALIGNMENT);
		return p;
	}

	/** A row that scroll-overflows horizontally: wheel over the strip pans it. */
	/**
	 * Chip strips WRAP rather than scroll. A 225px panel fits about two chips
	 * per row, so a single scrolling row hid most actions behind a mouse-wheel
	 * pan with no scrollbar and no affordance - reachable in theory, invisible
	 * in practice. Vertical space is the cheaper currency here: the dock
	 * already grows for mounted forms.
	 */
	private JPanel wrapStrip(JPanel row)
	{
		row.setLayout(new com.goalplanner.ui.WrapLayout(FlowLayout.LEFT, 4, 2));
		row.setOpaque(false);
		return row;
	}

	private static final Color BTN_BG = new Color(0x3B, 0x3B, 0x3B);
	private static final Color BTN_HOVER = new Color(0x4C, 0x4C, 0x52);
	private static final Color BTN_FG = new Color(0xDC, 0xDC, 0xDC);
	private static final Color BTN_FG_OFF = new Color(0x77, 0x77, 0x77);
	private static final Color HINT_FG = new Color(0x9A, 0x9A, 0x9A);

	private void rebuildStrip(JPanel row, String hint, List<Item> items)
	{
		row.removeAll();
		if (hint != null && !hint.isEmpty())
		{
			JLabel l = new JLabel(hint.toUpperCase(Locale.ROOT));
			l.setForeground(HINT_FG);
			l.setFont(l.getFont().deriveFont(Font.BOLD, 10f));
			l.setBorder(BorderFactory.createEmptyBorder(0, 2, 0, 6));
			row.add(l);
		}
		for (Item item : items)
		{
			// An item with no action is a group separator: a faint small-caps
			// label, so a scrolled strip still reads as clusters.
			if (item.action == null)
			{
				JLabel sep = new JLabel(item.label.toUpperCase(Locale.ROOT));
				sep.setForeground(HINT_FG);
				sep.setFont(sep.getFont().deriveFont(Font.BOLD, 9f));
				sep.setBorder(BorderFactory.createEmptyBorder(0, 6, 0, 2));
				row.add(sep);
				continue;
			}
			row.add(makeButton(item));
		}
	}

	private JButton makeButton(Item item)
	{
		JButton b = new RoundedPaint.RoundedButton(item.label);
		b.setToolTipText(item.tooltip);
		b.setEnabled(item.enabled);
		b.setBackground(BTN_BG);
		b.setForeground(item.enabled ? BTN_FG : BTN_FG_OFF);
		b.setFont(b.getFont().deriveFont(11f));
		b.setBorder(BorderFactory.createEmptyBorder(3, 9, 3, 9));
		b.setCursor(Cursor.getPredefinedCursor(
			item.enabled ? Cursor.HAND_CURSOR : Cursor.DEFAULT_CURSOR));
		b.setPreferredSize(new Dimension(
			b.getPreferredSize().width + 2, ROW_H - 2));
		if (item.enabled)
		{
			b.addMouseListener(new MouseAdapter()
			{
				@Override public void mouseEntered(MouseEvent e) { b.setBackground(BTN_HOVER); }
				@Override public void mouseExited(MouseEvent e) { b.setBackground(BTN_BG); }
			});
			b.addActionListener(e -> item.action.run());
		}
		return b;
	}

	private static final Color PEEK_CREATE_BG = new Color(0x1D, 0x2A, 0x1F);
	private static final Color PEEK_CREATE_FG = new Color(0xBF, 0xE0, 0xBF);
	/** A hairline splitting the surface above from the permanent footer below. */
	private static final Color FOOTER_TOP_RULE = new Color(0x2A, 0x2A, 0x2C);

	private static final Color PEEK_SECTION_BG = new Color(0x1E, 0x26, 0x30);
	private static final Color PEEK_SECTION_FG = new Color(0xAF, 0xC8, 0xE6);

	/** The permanent footer: Create Goal | Create Section. Both forward their tap
	 *  to the panel-supplied callback; the panel decides whether that opens the
	 *  create surface, switches modes, or collapses (it owns the nav state). */
	private void buildFooterRow()
	{
		footerRow.setOpaque(false);
		styleCreateButton(createGoalBtn, PEEK_CREATE_BG, PEEK_CREATE_FG);
		styleCreateButton(createSectionBtn, PEEK_SECTION_BG, PEEK_SECTION_FG);
		createGoalBtn.setToolTipText("Create a goal");
		createSectionBtn.setToolTipText("Create a section");
		createGoalBtn.addActionListener(e -> {
			if (onCreateGoal != null)
			{
				onCreateGoal.run();
			}
		});
		createSectionBtn.addActionListener(e -> {
			if (onCreateSection != null)
			{
				onCreateSection.run();
			}
		});
		footerRow.add(createGoalBtn);
		footerRow.add(createSectionBtn);
	}

	private void styleCreateButton(JButton b, Color bg, Color fg)
	{
		b.setFocusPainted(false);
		b.setBorderPainted(false);
		b.setBackground(bg);
		b.setForeground(fg);
		b.setFont(b.getFont().deriveFont(Font.BOLD, 12f));
		b.setBorder(BorderFactory.createEmptyBorder(6, 8, 6, 8));
		b.setPreferredSize(new Dimension(0, PEEK_H));
		b.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		Color hover = bg.brighter();
		b.addMouseListener(new MouseAdapter()
		{
			@Override public void mouseEntered(MouseEvent e) { b.setBackground(hover); }
			@Override public void mouseExited(MouseEvent e) { b.setBackground(bg); }
		});
	}

	private void applyCollapsed()
	{
		// Only the surface hides on collapse; the footer stays visible always.
		centerHost.setVisible(!collapsed);
		// The footer's top hairline divides it from the surface above - shown only
		// when expanded, so at rest it does not read as a double rule under the
		// dock's own DockDivider. A 1px empty border keeps the footer height steady.
		footerRow.setBorder(collapsed
			? BorderFactory.createEmptyBorder(1, 0, 0, 0)
			: BorderFactory.createMatteBorder(1, 0, 0, 0, FOOTER_TOP_RULE));
		revalidate();
		repaint();
	}

	@Override
	public Dimension getPreferredSize()
	{
		int surface;
		if (customView != null)
		{
			// A mounted surface (create grid/form or edit view): grow to its
			// preferred height, capped so the goal list keeps a usable minimum.
			surface = Math.min(CREATE_MAX_H, customView.getPreferredSize().height + 4);
		}
		else
		{
			// Wrapped strips have a real preferred height, but WrapLayout can
			// only compute it if the row already HAS a width - an unsized row
			// falls back to Integer.MAX_VALUE and reports a single row, which
			// is exactly how the extra chips got clipped. Seed the width from
			// the dock before asking.
			int stripW = getWidth() - 8;
			if (stripW > 0)
			{
				topRow.setSize(stripW, 1);
				bottomRow.setSize(stripW, 1);
			}
			surface = topRow.getPreferredSize().height
				+ bottomRow.getPreferredSize().height + 6;
			// The optional full-width lead button (MULTI "Deselect (N)") sits above
			// the two strips; count its height only while it is showing.
			if (leadHost.isVisible())
			{
				surface += leadHost.getPreferredSize().height;
			}
		}
		// The grab handle sits above the surface while expanded (Task 8).
		if (!collapsed)
		{
			surface += grabHandle.getPreferredSize().height;
		}
		// The permanent footer is always counted; the surface only adds height
		// while expanded.
		int footerH = footerRow.getPreferredSize().height;
		int h = footerH + (collapsed ? 0 : surface);
		return new Dimension(super.getPreferredSize().width, h);
	}

	private static final int HANDLE_H = 12;
	private static final int DISMISS_DRAG_THRESHOLD = 24;
	private static final Color HANDLE_COLOR = new Color(0x6A, 0x6A, 0x70);
	private static final Color HANDLE_HOVER = new Color(0x9A, 0x9A, 0xA2);

	/**
	 * A short centered horizontal bar at the top of the expanded surface (Task 8)
	 * signalling the dock is dismissable. Dragging it DOWN past a small threshold
	 * collapses the surface; a plain CLICK is the no-drag fallback. Both route
	 * through {@link #triggerDismiss()} so the panel can also clear the surface
	 * drivers (selection / section / create nav), resting the dock at the footer
	 * from any state.
	 */
	private final class GrabHandle extends JPanel
	{
		private int pressY = -1;
		private boolean fired = false;
		private boolean hover = false;

		GrabHandle()
		{
			// Opaque: every pixel inside the dock must be painted by an opaque
			// component this pass, so nothing behind (an optional goal's diagonal
			// hatch) can survive in the handle band.
			setOpaque(true);
			setBackground(ColorScheme.DARKER_GRAY_COLOR);
			Dimension d = new Dimension(0, HANDLE_H);
			setPreferredSize(d);
			setMinimumSize(d);
			setMaximumSize(new Dimension(Integer.MAX_VALUE, HANDLE_H));
			setCursor(Cursor.getPredefinedCursor(Cursor.N_RESIZE_CURSOR));
			setToolTipText("Drag down or click to dismiss");
			MouseAdapter ma = new MouseAdapter()
			{
				@Override public void mousePressed(MouseEvent e)
				{
					pressY = e.getYOnScreen();
					fired = false;
				}

				@Override public void mouseDragged(MouseEvent e)
				{
					if (!fired && pressY >= 0
						&& e.getYOnScreen() - pressY > DISMISS_DRAG_THRESHOLD)
					{
						fired = true;
						triggerDismiss();
					}
				}

				@Override public void mouseReleased(MouseEvent e)
				{
					pressY = -1;
				}

				@Override public void mouseClicked(MouseEvent e)
				{
					// No-drag fallback: a click also collapses.
					if (!fired)
					{
						triggerDismiss();
					}
				}

				@Override public void mouseEntered(MouseEvent e)
				{
					hover = true;
					repaint();
				}

				@Override public void mouseExited(MouseEvent e)
				{
					hover = false;
					repaint();
				}
			};
			addMouseListener(ma);
			addMouseMotionListener(ma);
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			super.paintComponent(g);
			Graphics2D g2 = (Graphics2D) g.create();
			try
			{
				g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
					RenderingHints.VALUE_ANTIALIAS_ON);
				int w = 36;
				int barH = 4;
				int x = (getWidth() - w) / 2;
				int y = (getHeight() - barH) / 2;
				g2.setColor(hover ? HANDLE_HOVER : HANDLE_COLOR);
				g2.fillRoundRect(x, y, w, barH, barH, barH);
			}
			finally
			{
				g2.dispose();
			}
		}
	}

	/**
	 * The seam between the goal list and the dock: an engraved two-tone rule -
	 * a dark groove line with a lighter highlight beneath it - both tapering to
	 * transparent at the panel edges, plus a soft central glow so the divider
	 * reads as a deliberate flourish rather than a flat border. Painted entirely
	 * in code from {@link ColorScheme} tones, so it stays in step with the theme
	 * and ships no assets. A few pixels tall.
	 */
	private static final class DockDivider implements Border
	{
		private static final int HEIGHT = 6;

		@Override
		public Insets getBorderInsets(Component c)
		{
			return new Insets(HEIGHT, 0, 0, 0);
		}

		@Override
		public boolean isBorderOpaque()
		{
			return false;
		}

		@Override
		public void paintBorder(Component c, Graphics g, int x, int y, int width, int height)
		{
			if (width <= 0)
			{
				return;
			}
			Graphics2D g2 = (Graphics2D) g.create();
			try
			{
				g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

				int cx = x + width / 2;
				int grooveY = y + 2;
				Color groove = shade(ColorScheme.DARKER_GRAY_COLOR, -14);
				Color highlight = shade(ColorScheme.DARK_GRAY_HOVER_COLOR, 18);

				// Two stacked hairlines, each fading to nothing at the edges.
				paintFadedLine(g2, x, width, grooveY, groove, 255);
				paintFadedLine(g2, x, width, grooveY + 1, highlight, 255);

				// Central glow: a short, brighter, edge-faded segment centered on cx.
				int glowW = Math.max(28, width / 3);
				paintFadedLine(g2, cx - glowW / 2, glowW, grooveY + 1,
					shade(ColorScheme.LIGHT_GRAY_COLOR, 0), 110);
			}
			finally
			{
				g2.dispose();
			}
		}

		/** A 1px horizontal line centered in {@code [lx, lx+w)} that ramps from
		 *  transparent at both ends to {@code peakAlpha} of {@code base} in the middle. */
		private static void paintFadedLine(Graphics2D g2, int lx, int w, int lineY,
			Color base, int peakAlpha)
		{
			Color solid = new Color(base.getRed(), base.getGreen(), base.getBlue(), peakAlpha);
			Color edge = new Color(base.getRed(), base.getGreen(), base.getBlue(), 0);
			int mid = lx + w / 2;
			g2.setPaint(new GradientPaint(lx, 0, edge, mid, 0, solid));
			g2.fillRect(lx, lineY, w / 2, 1);
			g2.setPaint(new GradientPaint(mid, 0, solid, lx + w, 0, edge));
			g2.fillRect(mid, lineY, w - w / 2, 1);
		}

		private static Color shade(Color base, int d)
		{
			return new Color(clamp(base.getRed() + d), clamp(base.getGreen() + d),
				clamp(base.getBlue() + d));
		}

		private static int clamp(int v)
		{
			return Math.max(0, Math.min(255, v));
		}
	}
}

package com.goalplanner.ui.dock;

import java.util.Set;

/**
 * What the action dock should show, derived purely from the current
 * selection. See ADR-0007: the dock is selection-driven - it answers "what
 * does an action operate on?" with whatever the user has selected, replacing
 * the positional answer the right-click menus gave.
 *
 * <p>Pure by design (no Swing, no store): the state decision is the part a
 * test can hold still, mirroring {@code AccountBindingGate} and
 * {@code RepeatSchedule}.
 */
public final class DockContext
{
	/** The dock's contextual states. */
	public enum State
	{
		/** Nothing selected: panel-level actions (add, import, share-all). */
		EMPTY,
		/** Exactly one goal selected: that goal's actions. */
		GOAL,
		/** Several goals selected: bulk actions. */
		MULTI,
		/** One section selected: that section's actions. */
		SECTION
	}

	private final State state;
	private final String soleGoalId;
	private final String sectionId;
	private final int count;

	private DockContext(State state, String soleGoalId, String sectionId, int count)
	{
		this.state = state;
		this.soleGoalId = soleGoalId;
		this.sectionId = sectionId;
		this.count = count;
	}

	public static DockContext of(Set<String> selectedGoalIds)
	{
		return of(selectedGoalIds, null);
	}

	/**
	 * Resolve the dock state from the selection. Goals and a section are
	 * mutually exclusive, and a goal selection always wins: any selected goals
	 * yield GOAL/MULTI (the section id is ignored); otherwise a non-null section
	 * id yields SECTION; otherwise EMPTY. Pure - the caller enforces the mutual
	 * exclusion in its own selection model; this just answers "what wins".
	 */
	public static DockContext of(Set<String> selectedGoalIds, String selectedSectionId)
	{
		if (selectedGoalIds != null && !selectedGoalIds.isEmpty())
		{
			if (selectedGoalIds.size() == 1)
			{
				return new DockContext(State.GOAL,
					selectedGoalIds.iterator().next(), null, 1);
			}
			return new DockContext(State.MULTI, null, null, selectedGoalIds.size());
		}
		if (selectedSectionId != null)
		{
			return new DockContext(State.SECTION, null, selectedSectionId, 0);
		}
		return new DockContext(State.EMPTY, null, null, 0);
	}

	public State getState() { return state; }

	/** The selected goal's id in {@link State#GOAL}; null otherwise. */
	public String getSoleGoalId() { return soleGoalId; }

	/** The selected section's id in {@link State#SECTION}; null otherwise. */
	public String getSectionId() { return sectionId; }

	public int getCount() { return count; }
}

package com.goalplanner.ui.nest;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Function;
import java.util.function.Predicate;

/**
 * Arranges one section's goals into a subtly-nested <em>outline tree</em> so that
 * indentation encodes dependency: each goal is placed directly beneath the goal
 * it depends on, indented one level deeper, and the section is emitted in
 * pre-order (a parent immediately followed by its children).
 *
 * <p>Goals form a DAG, not a tree - a "diamond" goal can depend on several others
 * (Quest Cape needs three quests; Grandmaster CA needs Quest Cape AND a cape).
 * Indentation can only nest a goal under <em>one</em> parent, so each goal is
 * placed under its <b>primary parent</b>: the in-section prerequisite with the
 * greatest dependency depth (ties broken by input order), so the longest chain
 * forms the spine. Any remaining prerequisites are reported via
 * {@link Result#extraPrereqs} (count) and {@link Result#primaryParent} so the UI
 * can hint at them (e.g. a tooltip) without drawing connector lines.
 *
 * <p>Both AND ({@code requires}) and OR ({@code orRequires}) prerequisites count.
 * Prerequisites not present in the same section are ignored. Input MUST be in
 * topological order (prereqs before dependents).
 */
public final class NestIndentAssigner
{
	private NestIndentAssigner() {}

	/** One goal: its id and its in-section prerequisites (AND + OR combined), in display order. */
	public static final class Node
	{
		public final String id;
		public final List<String> prereqs;

		public Node(String id, List<String> prereqs)
		{
			this.id = id;
			this.prereqs = prereqs != null ? prereqs : new ArrayList<>();
		}
	}

	/** The computed outline: render order, indent level per goal, and multi-parent info. */
	public static final class Result
	{
		/** Goal ids in pre-order (parent immediately before its children). */
		public final List<String> ordered;
		/** id → indent level (0 = root / no in-section prereqs). */
		public final Map<String, Integer> level;
		/** id → primary-parent id (the prereq it's nested under), or {@code null} for roots. */
		public final Map<String, String> primaryParent;
		/** id → number of in-section prerequisites beyond the primary parent (0 if ≤1). */
		public final Map<String, Integer> extraPrereqs;

		Result(List<String> ordered, Map<String, Integer> level,
			   Map<String, String> primaryParent, Map<String, Integer> extraPrereqs)
		{
			this.ordered = ordered;
			this.level = level;
			this.primaryParent = primaryParent;
			this.extraPrereqs = extraPrereqs;
		}
	}

	/**
	 * Resolve a goal's visible prerequisites by following edges THROUGH hidden
	 * nodes: a hidden prerequisite (e.g. a completed goal the caller filters
	 * out of the outline) is replaced by its own visible prerequisites,
	 * transitively - so A → B(hidden) → C still nests A under C instead of
	 * flattening A to a root. Cycle-safe via the visited set; result order
	 * follows edge order (depth-first through hidden nodes).
	 *
	 * @param direct    the goal's direct prerequisite ids (already scoped, e.g.
	 *                  in-section only)
	 * @param prereqsOf direct prerequisite ids for any id (same scoping)
	 * @param hidden    true for ids excluded from the outline (pass-through)
	 */
	public static List<String> resolveVisiblePrereqs(
		List<String> direct,
		Function<String, List<String>> prereqsOf,
		Predicate<String> hidden)
	{
		List<String> out = new ArrayList<>();
		expandThroughHidden(direct, prereqsOf, hidden, new HashSet<>(), out);
		return out;
	}

	private static void expandThroughHidden(
		List<String> edges,
		Function<String, List<String>> prereqsOf,
		Predicate<String> hidden,
		Set<String> visited,
		List<String> out)
	{
		if (edges == null) return;
		for (String id : edges)
		{
			if (!visited.add(id)) continue;
			if (hidden.test(id))
			{
				expandThroughHidden(prereqsOf.apply(id), prereqsOf, hidden, visited, out);
			}
			else
			{
				out.add(id);
			}
		}
	}

	/**
	 * @param nodes goals in topological order (prereqs before dependents)
	 * @return the outline tree (order, levels, primary parents, extra-prereq counts)
	 */
	public static Result assign(List<Node> nodes)
	{
		Set<String> present = new HashSet<>();
		for (Node n : nodes) present.add(n.id);

		// 1) dependency depth (max over prereqs + 1) - used to choose the primary parent.
		Map<String, Integer> depth = new HashMap<>();
		for (Node n : nodes)
		{
			int d = 0;
			for (String p : n.prereqs)
			{
				if (!present.contains(p)) continue;
				Integer pd = depth.get(p);
				if (pd != null) d = Math.max(d, pd + 1);
			}
			depth.put(n.id, d);
		}

		// 2) primary parent = deepest in-section prereq (ties → first in input order);
		//    build child lists (preserving input order) and the root list.
		Map<String, String> primaryParent = new HashMap<>();
		Map<String, Integer> extraPrereqs = new HashMap<>();
		Map<String, List<String>> children = new HashMap<>();
		for (Node n : nodes) children.put(n.id, new ArrayList<>());
		List<String> roots = new ArrayList<>();

		for (Node n : nodes)
		{
			String best = null;
			int bestDepth = -1;
			int inSection = 0;
			for (String p : n.prereqs)
			{
				if (!present.contains(p)) continue;
				inSection++;
				int pd = depth.getOrDefault(p, 0);
				if (pd > bestDepth)
				{
					bestDepth = pd;
					best = p;
				}
			}
			primaryParent.put(n.id, best);
			extraPrereqs.put(n.id, Math.max(0, inSection - 1));
			if (best == null) roots.add(n.id);
			else children.get(best).add(n.id);
		}

		// 3) pre-order walk: each parent immediately followed by its children.
		List<String> ordered = new ArrayList<>(nodes.size());
		Map<String, Integer> level = new HashMap<>();
		for (String root : roots) walk(root, 0, children, ordered, level);

		// Safety net: if the input wasn't strictly topo-ordered and something
		// wasn't reached, append it at level 0 so nothing is silently dropped.
		for (Node n : nodes)
		{
			if (!level.containsKey(n.id))
			{
				ordered.add(n.id);
				level.put(n.id, 0);
			}
		}

		return new Result(ordered, level, primaryParent, extraPrereqs);
	}

	private static void walk(String id, int lvl, Map<String, List<String>> children,
							 List<String> ordered, Map<String, Integer> level)
	{
		if (level.containsKey(id)) return; // defensive against accidental re-entry
		ordered.add(id);
		level.put(id, lvl);
		for (String c : children.getOrDefault(id, new ArrayList<>()))
		{
			walk(c, lvl + 1, children, ordered, level);
		}
	}
}

package com.goalplanner.ui.nest;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.util.ArrayList;
import java.util.List;
import javax.swing.JComponent;
import javax.swing.JPanel;
import java.awt.Cursor;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.HashMap;
import java.util.Map;
import java.util.function.Consumer;
import javax.swing.JLabel;

/**
 * Renders one section's goals as a <em>subtly nested</em> list: each real
 * {@link com.goalplanner.ui.GoalCard} is stacked full-width (so every card
 * behaviour - menus, arrows, selection, progress - is preserved untouched) but
 * left-indented by its dependency depth ({@link NestIndentAssigner}), with a
 * thin, low-contrast vertical guide drawn at each ancestor level (file-tree
 * style). This is the quiet alternative to the connector-rail view: no dots, no
 * S-curves - just indentation + a faint guide so the hierarchy is scannable.
 */
public final class SectionNestContainer extends JPanel
{
	/** One goal row: its indent level (0 = root), its card, and whether it is a
	 *  collapsible nest parent (and if so, whether currently collapsed). */
	public static final class Row
	{
		public final String id;
		public final int level;
		public final JComponent card;
		public final boolean parent;
		public final boolean collapsed;

		public Row(String id, int level, JComponent card)
		{
			this(id, level, card, false, false);
		}

		public Row(String id, int level, JComponent card, boolean parent, boolean collapsed)
		{
			this.id = id;
			this.level = Math.max(0, level);
			this.card = card;
			this.parent = parent;
			this.collapsed = collapsed;
		}
	}

	// Faint, theme-friendly guide on the dark panel - low contrast on purpose.
	private static final Color GUIDE = new Color(0x6a, 0x6a, 0x6a, 0x66);
	private static final Color CHEVRON_COLOR = new Color(0xB4, 0xB4, 0xDC);

	private static final int LEFT_PAD    = 14;  // margin before level-0 cards (room for the collapse chevron)
	private static final int INDENT_STEP = 13;  // px added per nesting level (max; shrinks to fit, see effectiveStep)
	private static final int MIN_STEP    = 7;   // floor for the per-level indent on a very narrow / deep panel
	private static final int MIN_CARD_W  = 150; // keep the deepest card at least this wide before squeezing the indent
	private static final int MAX_LEVEL   = 6;   // cap indent so deep chains don't run off a narrow panel
	private static final int ROW_GAP     = 4;   // vertical gap between cards
	private static final int TICK        = 5;   // short horizontal stub from the parent guide into the card

	private final List<Row> rows;
	private final int deepestLevel; // deepest capped level present, for indent bookkeeping
	private final int indentW; // widest indent at full step, for preferred-size bookkeeping
	/**
	 * Left gutter before level-0 cards. LEFT_PAD when anything actually nests
	 * (the gutter holds collapse chevrons and guide lines); 0 when the whole
	 * section is level-0 - a degenerate outline, common since repeatable goals
	 * auto-move out of their import section and can leave only flat cards
	 * behind. Without this, those cards render inset for no visible reason.
	 */
	private final int basePad;
	private int stepPx = INDENT_STEP; // effective per-level indent, width-adapted each doLayout()
	/** Collapse chevron per parent row id, positioned in the gutter in doLayout(). */
	private final Map<String, JLabel> chevrons = new HashMap<>();

	public SectionNestContainer(List<Row> rows, Consumer<String> onToggleCollapse)
	{
		this.rows = rows;
		setOpaque(false);
		setLayout(null); // manual layout in doLayout()

		int maxLevel = 0;
		for (Row r : rows) maxLevel = Math.max(maxLevel, capped(r.level));
		this.deepestLevel = maxLevel;
		this.basePad = maxLevel > 0 ? LEFT_PAD : 0;
		this.indentW = basePad + maxLevel * INDENT_STEP;

		for (Row r : rows)
		{
			add(r.card);
			// A clickable collapse chevron for goals that have a nested subtree.
			if (r.parent && onToggleCollapse != null)
			{
				JLabel chev = new JLabel(r.collapsed
					? com.goalplanner.ui.ShapeIcons.rightTriangle(8, CHEVRON_COLOR)
					: com.goalplanner.ui.ShapeIcons.downTriangle(8, CHEVRON_COLOR));
				chev.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
				chev.setToolTipText(r.collapsed
					? "Show nested prerequisites" : "Hide nested prerequisites");
				final String gid = r.id;
				chev.addMouseListener(new MouseAdapter()
				{
					@Override public void mousePressed(MouseEvent e)
					{
						if (e.getButton() == MouseEvent.BUTTON1) onToggleCollapse.accept(gid);
					}
				});
				chevrons.put(r.id, chev);
				add(chev);
			}
		}
	}

	private static int capped(int level) { return Math.min(level, MAX_LEVEL); }

	/** Left x of a card at the given (capped) level. */
	private int cardX(int level) { return basePad + capped(level) * stepPx; }

	/** X of the vertical guide for ancestor level k (1-based). */
	private int guideX(int k) { return basePad + (k - 1) * stepPx + stepPx / 2; }

	/** Per-level indent that fits the current panel width: full {@link #INDENT_STEP}
	 *  when there's room, shrinking toward {@link #MIN_STEP} so the deepest card keeps
	 *  at least {@link #MIN_CARD_W} px instead of clipping its progress column. */
	private int effectiveStep(int width)
	{
		if (deepestLevel <= 0 || width <= 0) return INDENT_STEP;
		// Reserve more card width at larger font scales (the card content grows with
		// the font); the MIN_STEP floor keeps the hierarchy legible regardless.
		int minCard = Math.round(MIN_CARD_W * com.goalplanner.ui.PanelFonts.scale());
		int budget = width - basePad - minCard;
		int fit = budget / deepestLevel;
		return Math.max(MIN_STEP, Math.min(INDENT_STEP, fit));
	}

	@Override
	public void doLayout()
	{
		int width = getWidth();
		stepPx = effectiveStep(width);
		int y = 0;
		for (Row r : rows)
		{
			int x = cardX(r.level);
			int h = r.card.getPreferredSize().height;
			r.card.setBounds(x, y, Math.max(40, width - x), h);
			JLabel chev = chevrons.get(r.id);
			if (chev != null)
			{
				int cw = chev.getPreferredSize().width;
				int ch = chev.getPreferredSize().height;
				chev.setBounds(Math.max(1, x - cw - 2), y + (h - ch) / 2, cw, ch);
			}
			y += h + ROW_GAP;
		}
	}

	@Override
	public Dimension getPreferredSize()
	{
		int h = 0;
		for (Row r : rows) h += r.card.getPreferredSize().height + ROW_GAP;
		// Width driven by the parent (BoxLayout); report indent + a modest card
		// minimum so a section never collapses below usability.
		return new Dimension(indentW + 120, Math.max(h, 1));
	}

	@Override
	public Dimension getMaximumSize()
	{
		return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		super.paintComponent(g);
		if (rows.isEmpty()) return;

		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g2.setColor(GUIDE);
		g2.setStroke(new BasicStroke(1f));

		for (Row r : rows)
		{
			int lvl = capped(r.level);
			if (lvl == 0) continue;

			int top = r.card.getY();
			int bottom = top + r.card.getHeight() + ROW_GAP; // span the gap so guides read continuous
			int midY = top + r.card.getHeight() / 2;

			// Vertical guide at every ancestor level (file-tree spine). Consecutive
			// rows sharing a level stack into one continuous-looking line.
			for (int k = 1; k <= lvl; k++)
			{
				int gx = guideX(k);
				g2.drawLine(gx, top, gx, bottom);
			}

			// Short horizontal stub from this card's immediate parent guide into it.
			int stubX = guideX(lvl);
			g2.drawLine(stubX, midY, stubX + TICK, midY);
		}
		g2.dispose();
	}

	/** Convenience for callers that don't track child components separately. */
	public List<Component> cards()
	{
		List<Component> out = new ArrayList<>(rows.size());
		for (Row r : rows) out.add(r.card);
		return out;
	}
}

package com.goalplanner.util;

/**
 * Decides whether the loaded goal set may be tracked against the logged-in
 * account.
 *
 * <p><b>The problem.</b> Goals are stored per config profile, but a profile is
 * only a file - nothing guarantees it matches whoever is at the keyboard.
 * Trackers score whatever goals are in memory against whatever account is live,
 * and completion is terminal for auto-tracked types, so one drain with the
 * wrong pairing permanently completes every goal the other account satisfies.
 * Config sync then carries that to the user's other machines.
 *
 * <p><b>The gate.</b> A goal set is bound to an account hash on first tracked
 * login. Tracking proceeds only while the live hash matches. An unbound set
 * adopts the current account, so existing users migrate with no action.
 *
 * <p><b>Pure by design.</b> No RuneLite dependencies - the caller passes the
 * live and bound hashes in. This mirrors {@link SkillSyncGate} and exists for
 * the same reason: the decision logic is the part that can silently disable
 * itself or spam the chat box, so it has to be testable without a client.
 */
public final class AccountBindingGate
{
	/** What the caller should do with the current (live, bound) pairing. */
	public enum Decision
	{
		/** Hashes match - track normally. */
		TRACK,
		/** No binding yet - claim this account and track. */
		ADOPT,
		/** Bound to a different account - do not track. */
		PAUSE,
		/** Logged out or no readable account - nothing to track against. */
		NO_ACCOUNT
	}

	private boolean mismatchAnnounced = false;

	/**
	 * Classify a pairing. Called on every tracker drain, so it must be cheap and
	 * side-effect-free beyond the announce latch.
	 *
	 * @param liveAccountHash  the logged-in account, or any non-positive value
	 *                         when logged out. Deliberately not just {@code -1}:
	 *                         the guard must not depend on which sentinel the
	 *                         client uses, because falling through would unbind
	 *                         the goal set and re-enable the very bug this
	 *                         prevents.
	 * @param boundAccountHash the account this goal set belongs to, or 0 if unbound
	 */
	public Decision evaluate(long liveAccountHash, long boundAccountHash)
	{
		if (liveAccountHash <= 0L)
		{
			// Logged out is not a mismatch - leave the latch alone so logging
			// out and back in on the wrong account does not re-announce.
			return Decision.NO_ACCOUNT;
		}
		if (boundAccountHash == 0L)
		{
			mismatchAnnounced = false;
			return Decision.ADOPT;
		}
		if (boundAccountHash == liveAccountHash)
		{
			mismatchAnnounced = false;
			return Decision.TRACK;
		}
		return Decision.PAUSE;
	}

	/**
	 * True exactly once per mismatch episode, so the warning does not repeat on
	 * every game tick. Resets once a matching account is seen, so a later
	 * mismatch is announced again rather than silently swallowed.
	 */
	public boolean shouldAnnounceMismatch()
	{
		if (mismatchAnnounced)
		{
			return false;
		}
		mismatchAnnounced = true;
		return true;
	}

	/** Whether tracking may proceed for this decision. */
	public static boolean allowsTracking(Decision decision)
	{
		return decision == Decision.TRACK || decision == Decision.ADOPT;
	}
}

package com.goalplanner.util;

/**
 * Shared formatting utilities used across UI components.
 */
public final class FormatUtil
{
	private FormatUtil() {}

	/**
	 * Format a number in shortened form: 1.2M, 50K, 999.
	 */
	public static String formatNumber(int n)
	{
		if (n >= 1_000_000)
		{
			return String.format("%.1fM", n / 1_000_000.0);
		}
		if (n >= 1_000)
		{
			return String.format("%.0fK", n / 1_000.0);
		}
		return String.valueOf(n);
	}

	/**
	 * Progress percent for a goal that has NOT met its target, e.g. "99%".
	 *
	 * <p>Floors instead of rounding, and caps at 99. Rounding made a goal at
	 * 126/127 Miscellania favour render "100%" while the card still showed it
	 * as unfinished - a percentage that claims completion on an incomplete goal
	 * reads as a bug even when the underlying tracking is right. Flooring also
	 * matches how a grind actually feels: you are at 99% until you are done.
	 *
	 * <p>Callers must only use this for incomplete goals; a finished goal shows
	 * its completion icon instead of a percentage.
	 */
	public static String formatProgressPercent(int currentValue, int targetValue)
	{
		if (targetValue <= 0)
		{
			return "0%";
		}
		double pct = (currentValue * 100.0) / targetValue;
		int floored = (int) Math.floor(pct);
		return Math.max(0, Math.min(99, floored)) + "%";
	}

	/**
	 * Format a number with commas: 1,234,567.
	 */
	public static String formatXp(int xp)
	{
		return String.format("%,d", xp);
	}

	/**
	 * Truncate text with ellipsis if too long.
	 */
	public static String truncate(String text, int maxLen)
	{
		if (text == null) return "";
		if (text.length() <= maxLen) return text;
		// Reserve 3 chars for the ASCII "..." so the result stays within maxLen
		// (a 1-char "…" would render as tofu on macOS Tahoe — see check_glyphs).
		if (maxLen <= 3) return text.substring(0, maxLen);
		return text.substring(0, maxLen - 3) + "...";
	}

	/**
	 * Escape HTML special characters.
	 */
	public static String escapeHtml(String text)
	{
		if (text == null) return "";
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}
}

package com.goalplanner.util;

import com.goalplanner.ResetBoundary;
import com.goalplanner.model.RepeatPeriod;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.time.ZonedDateTime;

/**
 * Pure clock math for repeatable goals: which period a moment falls in, and
 * when the current period ends.
 *
 * <p>The model is a <em>period key</em> - a plain integer bucket for the
 * current period. A goal stores the key it last reset in; when the computed
 * key differs, it resets. Nothing subtracts timestamps, which is what makes
 * the hard cases fall out for free: five days offline is one key change rather
 * than five, and DST is {@code java.time}'s problem rather than ours.
 *
 * <p>{@link #nextBoundary} and {@link #periodKey} are deliberately derived
 * from the same {@link #boundaryDate}. The countdown shown in the panel and
 * the reset check MUST come from this one class - a countdown that reaches
 * zero while nothing resets is the worst failure this feature has.
 *
 * <p>No Swing, no RuneLite client, no {@code System.currentTimeMillis()} -
 * callers pass the instant in, so every case here is testable.
 */
public final class RepeatSchedule
{
	private RepeatSchedule() {}

	/**
	 * Epoch day 0 (1970-01-01) was a Thursday, so the first Wednesday is epoch
	 * day 6. Weekly periods are anchored to Wednesday to match the OSRS weekly
	 * reset rather than to the epoch's arbitrary Thursday.
	 */
	private static final long WEDNESDAY_EPOCH_DAY = 6;

	/**
	 * The date a moment belongs to, once the boundary hour is taken into
	 * account. With a 5am boundary, 03:00 on the 10th still belongs to the 9th.
	 */
	public static LocalDate boundaryDate(Instant now, ZoneId zone, int boundaryHour)
	{
		return now.atZone(zone).minusHours(clampHour(boundaryHour)).toLocalDate();
	}

	/**
	 * The integer bucket for {@code date} under {@code period}. Equal keys mean
	 * "same period, no reset due"; any difference means one is due.
	 *
	 * <p>Each period has its own rule - there is no shared divisor, because
	 * months are not a fixed number of days.
	 */
	public static long periodKey(RepeatPeriod period, LocalDate date)
	{
		if (period == null || date == null)
		{
			return 0L;
		}
		switch (period)
		{
			case DAILY:
				return date.toEpochDay();
			case WEEKLY:
				return Math.floorDiv(date.toEpochDay() - WEDNESDAY_EPOCH_DAY, 7);
			case MONTHLY:
				// The year term is load-bearing: a bare month value collides
				// every January.
				return date.getYear() * 12L + date.getMonthValue();
			case NONE:
			default:
				return 0L;
		}
	}

	/** The first date of the period containing {@code date}. */
	public static LocalDate periodStart(RepeatPeriod period, LocalDate date)
	{
		if (period == null || date == null)
		{
			return date;
		}
		switch (period)
		{
			case WEEKLY:
				return date.minusDays(
					Math.floorMod(date.toEpochDay() - WEDNESDAY_EPOCH_DAY, 7));
			case MONTHLY:
				return date.withDayOfMonth(1);
			case DAILY:
			case NONE:
			default:
				return date;
		}
	}

	/**
	 * The instant at which the period containing {@code now} ends and the key
	 * changes. Returns null for {@link RepeatPeriod#NONE}, which never rolls.
	 */
	public static Instant nextBoundary(RepeatPeriod period, Instant now, ZoneId zone,
		int boundaryHour)
	{
		if (period == null || !period.isRepeating() || now == null)
		{
			return null;
		}
		int hour = clampHour(boundaryHour);
		LocalDate start = periodStart(period, boundaryDate(now, zone, hour));
		LocalDate next;
		switch (period)
		{
			case WEEKLY:
				next = start.plusWeeks(1);
				break;
			case MONTHLY:
				next = start.plusMonths(1);
				break;
			case DAILY:
			default:
				next = start.plusDays(1);
				break;
		}
		// atZone resolves a DST gap forward, which is the behaviour we want:
		// on a spring-forward day the boundary lands at the first instant that
		// actually exists.
		return next.atTime(hour, 0).atZone(zone).toInstant();
	}

	/** The zone a boundary mode measures days in. */
	public static ZoneId zoneFor(ResetBoundary boundary)
	{
		return boundary == ResetBoundary.GAME_RESET
			? ZoneOffset.UTC
			: ZoneId.systemDefault();
	}

	/** The hour-of-day a boundary mode rolls over at; only CUSTOM_HOUR is not 0. */
	public static int hourFor(ResetBoundary boundary, int configuredHour)
	{
		return boundary == ResetBoundary.CUSTOM_HOUR ? clampHour(configuredHour) : 0;
	}

	/**
	 * Human countdown for the section header, e.g. {@code "3h 42m"} or
	 * {@code "2d 03h"}. Deliberately not {@code HH:MM} - a monthly goal can be
	 * 30 days out, and "03:42" reads as minutes and seconds to half of people.
	 *
	 * <p>ASCII only: this string is rendered by Swing, where symbol glyphs tofu
	 * on macOS Tahoe.
	 */
	public static String formatCountdown(long millisRemaining)
	{
		long secs = Math.max(0, millisRemaining) / 1000L;
		long days = secs / 86_400L;
		long hours = (secs % 86_400L) / 3600L;
		long mins = (secs % 3600L) / 60L;
		if (days > 0)
		{
			return days + "d " + String.format("%02dh", hours);
		}
		if (hours > 0)
		{
			return hours + "h " + String.format("%02dm", mins);
		}
		return mins + "m";
	}

	/**
	 * Compact "complete it by" stamp for the card, sized to the period: a daily
	 * only needs a clock time, a weekly needs the weekday, a monthly needs the
	 * date. ASCII only - Swing tofus symbol glyphs on macOS Tahoe.
	 */
	public static String formatDeadline(Instant boundary, ZoneId zone, RepeatPeriod period)
	{
		if (boundary == null || period == null || !period.isRepeating())
		{
			return "";
		}
		ZonedDateTime z = boundary.atZone(zone);
		String time = String.format("%02d:%02d", z.getHour(), z.getMinute());
		switch (period)
		{
			case WEEKLY:
				return DAY_NAMES[z.getDayOfWeek().getValue() - 1] + " " + time;
			case MONTHLY:
				return z.getDayOfMonth() + " " + MONTH_NAMES[z.getMonthValue() - 1];
			case DAILY:
			default:
				return time;
		}
	}

	private static final String[] DAY_NAMES =
		{"Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"};
	private static final String[] MONTH_NAMES =
		{"Jan", "Feb", "Mar", "Apr", "May", "Jun",
			"Jul", "Aug", "Sep", "Oct", "Nov", "Dec"};

	private static int clampHour(int hour)
	{
		return Math.max(0, Math.min(23, hour));
	}
}

package com.goalplanner.util;

import java.util.ArrayList;
import java.util.List;
import java.util.function.BooleanSupplier;
import java.util.function.LongSupplier;

/**
 * Gates skill-level-reading actions (goal prerequisite seeding) until the
 * client's skill cache has actually synced for the current login.
 *
 * <p><b>The problem.</b> Adding a goal that seeds skill prerequisites
 * (e.g. Song of the Elves seeding Herblore/Farming) reads live skill
 * levels via {@code client.getRealSkillLevel} to skip requirements the
 * player already meets. Right after login the skill XP cache has not yet
 * received the server's stat block, so every skill reads as its default
 * (level 1). Already-met requirements then fail the skip check and seed
 * as spurious level-1 cards that only self-correct once {@code StatChanged}
 * fires - exactly the user-reported "Herblore/Farming added at level 1"
 * bug.
 *
 * <p><b>The gate.</b> Seeding actions are routed through
 * {@link #runWhenSynced(Runnable)}. While skills are unsynced the action
 * is queued; it runs once the post-login {@code StatChanged} burst has
 * arrived and settled. "Settled" means at least {@code settleTicks} game
 * ticks have elapsed with no further {@code StatChanged} - the stat block
 * lands as a single burst, so a quiet tick after it means every skill is
 * in. A wall-clock fallback ({@code fallbackMs}) drains the queue anyway
 * if no {@code StatChanged} is ever observed (e.g. a freshly-created
 * account whose skills equal the client default), so an action can never
 * be stranded.
 *
 * <p>Notably this does <em>not</em> wait for every {@link
 * net.runelite.api.Skill} value to report: {@code Skill.OVERALL} never
 * fires {@code StatChanged} and the unreleased {@code SAILING} skill may
 * never sync, so a "all skills reported" predicate could never become
 * true. Burst-settle sidesteps that entirely.
 *
 * <p><b>Pure by design.</b> No RuneLite dependencies - the plugin injects
 * a logged-in predicate and a clock and feeds lifecycle callbacks
 * ({@link #onLogin()}, {@link #onLogout()}, {@link #onStatChanged()},
 * {@link #onTick()}). This keeps the timing state machine unit-testable
 * without a live client, mirroring how {@code QuestRequirementResolver}
 * was split out from the client-bound API layer.
 */
public final class SkillSyncGate
{
	private final BooleanSupplier loggedIn;
	private final LongSupplier nowMs;
	private final int settleTicks;
	private final long fallbackMs;

	private final List<Runnable> pending = new ArrayList<>();
	/** True once at least one StatChanged has arrived since the last login. */
	private boolean sawStatSinceLogin = false;
	/** Game ticks observed with no StatChanged since the last one. */
	private int quietTicks = 0;
	/** Wall-clock deadline (epoch ms) after which we drain regardless; 0 = unset. */
	private long fallbackAt = 0L;

	/**
	 * @param loggedIn    supplies whether the client is currently logged in
	 * @param nowMs       supplies the current epoch-millis (injectable clock)
	 * @param settleTicks quiet game ticks required after the last StatChanged
	 *                    before skills are considered synced (>= 1)
	 * @param fallbackMs  wall-clock window after login after which the queue
	 *                    drains even if no StatChanged was ever seen
	 */
	public SkillSyncGate(BooleanSupplier loggedIn, LongSupplier nowMs, int settleTicks, long fallbackMs)
	{
		this.loggedIn = loggedIn;
		this.nowMs = nowMs;
		this.settleTicks = Math.max(1, settleTicks);
		this.fallbackMs = fallbackMs;
	}

	/** Call when the client transitions to the logged-in state. Re-arms the
	 *  gate: the new login must re-sync before deferred actions run. */
	public void onLogin()
	{
		sawStatSinceLogin = false;
		quietTicks = 0;
		fallbackAt = nowMs.getAsLong() + fallbackMs;
	}

	/** Call when the client leaves the logged-in state (login screen, hop,
	 *  connection lost). Drops any queued action so it can't seed into a
	 *  different account/profile on the next login. */
	public void onLogout()
	{
		sawStatSinceLogin = false;
		quietTicks = 0;
		fallbackAt = 0L;
		pending.clear();
	}

	/** Call on each StatChanged received while logged in. */
	public void onStatChanged()
	{
		sawStatSinceLogin = true;
		quietTicks = 0;
	}

	/** Call on each game tick while logged in. Advances the quiet-tick
	 *  counter and drains the queue if skills are now synced. */
	public void onTick()
	{
		// Cap the increment so a long session can't overflow the counter;
		// once it reaches the settle threshold the exact value is irrelevant.
		if (sawStatSinceLogin && quietTicks <= settleTicks)
		{
			quietTicks++;
		}
		drainIfSynced();
	}

	/** Whether the client's skill cache is considered synced and safe to read. */
	public boolean isSynced()
	{
		if (!loggedIn.getAsBoolean())
		{
			return false;
		}
		if (sawStatSinceLogin && quietTicks >= settleTicks)
		{
			return true;
		}
		return fallbackAt != 0L && nowMs.getAsLong() >= fallbackAt;
	}

	/**
	 * Run {@code action} immediately if skills are synced, otherwise queue
	 * it to run once they are. Queued actions drain on a later {@link
	 * #onTick()} (on the same thread that calls onTick - the client thread
	 * in production).
	 */
	public void runWhenSynced(Runnable action)
	{
		if (action == null)
		{
			return;
		}
		if (isSynced())
		{
			action.run();
			return;
		}
		pending.add(action);
	}

	/** Number of actions currently queued awaiting sync (test/diagnostic). */
	public int pendingCount()
	{
		return pending.size();
	}

	private void drainIfSynced()
	{
		if (pending.isEmpty() || !isSynced())
		{
			return;
		}
		// Snapshot before running so a re-entrant action that mutates the
		// queue (a follow-on add, or onLogout clearing it) can't disturb
		// iteration. While draining we are synced, so a re-entrant
		// runWhenSynced runs immediately rather than re-queuing.
		List<Runnable> drained = new ArrayList<>(pending);
		pending.clear();
		for (Runnable r : drained)
		{
			r.run();
		}
	}
}

package com.goalplanner;

import java.util.ArrayList;
import java.util.List;
import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;
import net.runelite.client.plugins.Plugin;

public class GoalPlannerPluginTest
{
	/**
	 * Companion hub plugins the dev client will also load IF their jar is on
	 * the classpath (drop it into dev-plugins/ - see build.gradle). Lets the
	 * cross-plugin link-ins (PluginMessage) be exercised end-to-end locally,
	 * e.g. against a patched Quest Helper before its upstream PR ships.
	 */
	private static final String[] COMPANION_PLUGINS = {
		"com.questhelper.QuestHelperPlugin",
		"inventorysetups.InventorySetupsPlugin",
		"com.loadoutlab.LoadoutLabPlugin",
	};

	public static void main(String[] args) throws Exception
	{
		List<Class<? extends Plugin>> plugins = new ArrayList<>();
		plugins.add(GoalPlannerPlugin.class);
		for (String className : COMPANION_PLUGINS)
		{
			try
			{
				@SuppressWarnings("unchecked")
				Class<? extends Plugin> plugin = (Class<? extends Plugin>) Class.forName(className);
				plugins.add(plugin);
				System.out.println("dev client: loading companion plugin " + className);
			}
			catch (ClassNotFoundException e)
			{
				// jar not in dev-plugins/ - run without it
			}
		}
		@SuppressWarnings("unchecked")
		Class<? extends Plugin>[] arr = plugins.toArray(new Class[0]);
		ExternalPluginManager.loadBuiltin(arr);
		RuneLite.main(args);
	}
}

package com.goalplanner.api;

import com.goalplanner.model.Goal;
import com.goalplanner.model.GoalType;
import com.goalplanner.persistence.GoalStore;
import com.goalplanner.service.GoalReorderingService;
import com.goalplanner.testsupport.DataResourcesInitExtension;
import com.goalplanner.testsupport.InMemoryConfigManager;
import com.goalplanner.testsupport.MockClientFactory;
import com.goalplanner.testsupport.MockGameState;
import com.goalplanner.data.WikiCaRepository;
import net.runelite.api.Client;
import net.runelite.client.game.ItemManager;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;

import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.Mockito.mock;

/**
 * Regression guard for the dock's diary-add path. The dock create form calls
 * {@link GoalPlannerApiImpl#addDiaryGoal}, which resolves diary requirements
 * against the live Client. When that ran on the EDT (no client-thread wrap) it
 * silently failed for every area/tier (dev-mode {@code -ea} client-thread
 * assert) - the reported "adding diaries is failing on all sections/levels" bug.
 *
 * <p>This test exercises the API layer directly (client-thread executor is a
 * no-op in tests) for every area x tier the dock offers, asserting a DIARY goal
 * is actually created each time. The UI-side fix wraps the create in
 * {@code runOnClientThread}; this locks the API contract the fix relies on.
 */
@ExtendWith(DataResourcesInitExtension.class)
class AddDiaryGoalAllAreasTest
{
	/** The exact area display names the dock's buildDiaryForm offers. */
	private static final String[] DIARY_AREAS = {
		"Ardougne", "Desert", "Falador", "Fremennik", "Kandarin", "Karamja",
		"Kourend & Kebos", "Lumbridge & Draynor", "Morytania", "Varrock",
		"Western Provinces", "Wilderness"
	};

	private GoalStore store;
	private GoalPlannerApiImpl api;

	@BeforeEach
	void setUp()
	{
		store = new GoalStore(InMemoryConfigManager.create(), new com.google.gson.Gson());
		store.load();
		// Fresh account (nothing complete) so every diary resolves to a real,
		// not-yet-complete goal with prereqs.
		Client client = MockClientFactory.createClient(new MockGameState());
		api = new GoalPlannerApiImpl(store, new GoalReorderingService(store),
			mock(ItemManager.class), mock(WikiCaRepository.class), client);
	}

	@Test
	@DisplayName("addDiaryGoal creates a DIARY goal for every area and tier")
	void addsDiaryGoalForEveryAreaAndTier()
	{
		for (String area : DIARY_AREAS)
		{
			for (GoalPlannerApi.DiaryTier tier : GoalPlannerApi.DiaryTier.values())
			{
				String id = api.addDiaryGoal(area, tier);
				assertNotNull(id, "addDiaryGoal returned null for " + area + " " + tier
					+ " - the diary-add regression is back");

				Goal created = api.findGoal(id);
				assertNotNull(created, "no goal found for returned id (" + area + " " + tier + ")");

				// The gesture may return the diary goal itself or, for an already-met
				// tier, reconcile it complete; either way a DIARY goal must exist in
				// the store for this area/tier gesture.
				boolean hasDiaryGoal = store.getGoals().stream()
					.anyMatch(g -> g.getType() == GoalType.DIARY);
				assertTrue(hasDiaryGoal, "no DIARY goal in store after add for " + area + " " + tier);
			}
		}
	}
}

package com.goalplanner.api;

import com.goalplanner.data.QuestRequirementResolver;
import com.goalplanner.data.WikiCaRepository;
import com.goalplanner.model.Goal;
import com.goalplanner.model.GoalType;
import com.goalplanner.model.Tag;
import com.goalplanner.model.TagCategory;
import com.goalplanner.persistence.GoalStore;
import com.goalplanner.service.GoalReorderingService;
import com.goalplanner.testsupport.InMemoryConfigManager;
import java.util.Arrays;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.Experience;
import net.runelite.api.Quest;
import net.runelite.api.Skill;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

/**
 * Tests for {@link GoalPlannerApiImpl#addQuestGoalWithPrereqs}, the
 * compound-command entry point used by the "Add Goal with
 * Requirements" menu.
 *
 * <p>Covers the full vertical slice:
 * <ul>
 *   <li>Fresh add: quest goal + seeded skill prereqs + seeded quest
 *       prereqs are all created and linked as one compound.</li>
 *   <li>Existing-goal reuse: a pre-existing goal that satisfies a
 *       template (higher-target skill goal, same-name quest goal) is
 *       linked as the prerequisite rather than duplicated.</li>
 *   <li>Empty templates: equivalent to the plain {@code addQuestGoal}.</li>
 *   <li>Undo/redo: one {@code api.undo()} reverses the whole gesture
 *       (quest goal + every seed + every edge), and {@code api.redo()}
 *       replays it.</li>
 * </ul>
 */
class AddQuestGoalWithPrereqsTest
{
	private GoalStore store;
	private GoalPlannerApiImpl api;

	@BeforeEach
	void setUp()
	{
		ConfigManager configManager = InMemoryConfigManager.create();
		store = new GoalStore(configManager, new com.google.gson.Gson());
		store.load();

		ItemManager itemManager = mock(ItemManager.class);
		WikiCaRepository wikiCaRepository = mock(WikiCaRepository.class);
		GoalReorderingService reorderingService = new GoalReorderingService(store);
		api = new GoalPlannerApiImpl(store, reorderingService, itemManager, wikiCaRepository);
		api.setOnGoalsChanged(() -> {});
	}

	// ---- helpers -----------------------------------------------------------

	/** Build a SKILL goal template at the given level. */
	private static Goal skillTemplate(Skill skill, int level)
	{
		return Goal.builder()
			.type(GoalType.SKILL)
			.name(skill.getName() + " \u2192 Level " + level)
			.skillName(skill.name())
			.targetValue(Experience.getXpForLevel(level))
			.build();
	}

	/** Build a QUEST goal template for the given quest. */
	private static Goal questTemplate(Quest quest)
	{
		return Goal.builder()
			.type(GoalType.QUEST)
			.name(quest.getName())
			.description("Quest")
			.questName(quest.name())
			.targetValue(1)
			.build();
	}

	private Goal findById(String id)
	{
		return store.getGoals().stream()
			.filter(g -> g.getId().equals(id))
			.findFirst()
			.orElse(null);
	}

	private Goal findByType(GoalType type, String identity)
	{
		for (Goal g : store.getGoals())
		{
			if (g.getType() != type) continue;
			if (type == GoalType.SKILL && identity.equals(g.getSkillName())) return g;
			if (type == GoalType.QUEST && identity.equals(g.getQuestName())) return g;
		}
		return null;
	}

	// ---- fresh add ---------------------------------------------------------

	@Test
	@DisplayName("creates quest goal + seeds skill prereqs + wires edges")
	void freshAddSeedsSkillPrereqs()
	{
		List<Goal> templates = Arrays.asList(
			skillTemplate(Skill.AGILITY, 35));
		String questId = api.addQuestGoalWithPrereqs(Quest.HORROR_FROM_THE_DEEP, templates);

		assertNotNull(questId);
		// One quest goal + one seeded skill goal.
		assertEquals(2, store.getGoals().size());

		Goal quest = findByType(GoalType.QUEST, "HORROR_FROM_THE_DEEP");
		assertNotNull(quest);
		assertEquals(questId, quest.getId());

		Goal skill = findByType(GoalType.SKILL, "AGILITY");
		assertNotNull(skill);
		// Skill seeds now go through addSkillGoal (public API), which
		// does NOT set autoSeeded. That's OK — autoSeeded is only needed
		// for the future same-skill absorption rule, and skill goals
		// seeded via quest-requirements benefit more from being first-
		// class goals (chain-linked, proper name/sprite).
		assertEquals(Experience.getXpForLevel(35), skill.getTargetValue());

		// Edge wired from quest → skill.
		assertTrue(quest.getRequiredGoalIds().contains(skill.getId()),
			"quest should require the seeded skill goal");
	}

	@Test
	@DisplayName("seeds multiple skill + quest prereqs in one gesture")
	void freshAddMultipleTemplates()
	{
		List<Goal> templates = Arrays.asList(
			skillTemplate(Skill.MAGIC, 75),
			skillTemplate(Skill.SMITHING, 70),
			questTemplate(Quest.LEGENDS_QUEST));
		String questId = api.addQuestGoalWithPrereqs(Quest.DRAGON_SLAYER_II, templates);

		assertNotNull(questId);
		// 1 DS2 + 2 skill seeds + 1 quest seed = 4.
		assertEquals(4, store.getGoals().size());

		Goal quest = findByType(GoalType.QUEST, "DRAGON_SLAYER_II");
		assertEquals(3, quest.getRequiredGoalIds().size());
	}

	// ---- existing-goal reuse -----------------------------------------------

	@Test
	@DisplayName("existing skill goal with higher target is reused, not duplicated")
	void reusesExistingSkillGoalWithHigherTarget()
	{
		// Player already has a level-99 Agility goal.
		String existingAgilityId = api.addSkillGoalForLevel(Skill.AGILITY, 99);
		assertNotNull(existingAgilityId);
		assertEquals(1, store.getGoals().size());

		// Adding HFTD (Agility 35 req) should LINK to the existing 99 goal.
		List<Goal> templates = Arrays.asList(skillTemplate(Skill.AGILITY, 35));
		String questId = api.addQuestGoalWithPrereqs(Quest.HORROR_FROM_THE_DEEP, templates);

		// Still only 2 goals: existing 99 Agility + the new quest. No seed.
		assertEquals(2, store.getGoals().size());

		Goal quest = findByType(GoalType.QUEST, "HORROR_FROM_THE_DEEP");
		assertTrue(quest.getRequiredGoalIds().contains(existingAgilityId),
			"quest should require the pre-existing higher-target agility goal");

		// The existing goal wasn't mutated into autoSeeded.
		Goal agility = findById(existingAgilityId);
		assertFalse(agility.isAutoSeeded(),
			"pre-existing user goal must not be flipped to autoSeeded by find-or-create");
	}

	@Test
	@DisplayName("existing quest goal is reused by name equality")
	void reusesExistingQuestGoalByName()
	{
		// Player already has Legends' Quest on their list.
		String existingLegendsId = api.addQuestGoal(Quest.LEGENDS_QUEST);
		assertNotNull(existingLegendsId);

		List<Goal> templates = Arrays.asList(questTemplate(Quest.LEGENDS_QUEST));
		String questId = api.addQuestGoalWithPrereqs(Quest.DRAGON_SLAYER_II, templates);

		// Only 2 goals: the existing Legends' Quest + DS2. No duplicate seed.
		assertEquals(2, store.getGoals().size());

		Goal ds2 = findById(questId);
		assertTrue(ds2.getRequiredGoalIds().contains(existingLegendsId));
	}

	// ---- empty-templates degenerate case -----------------------------------

	@Test
	@DisplayName("empty templates list behaves like plain addQuestGoal")
	void emptyTemplatesIsPlainAdd()
	{
		String id = api.addQuestGoalWithPrereqs(Quest.COOKS_ASSISTANT, List.of());
		assertNotNull(id);
		assertEquals(1, store.getGoals().size());
		Goal quest = findByType(GoalType.QUEST, "COOKS_ASSISTANT");
		assertEquals(id, quest.getId());
		assertTrue(quest.getRequiredGoalIds().isEmpty());
	}

	// ---- compound undo -----------------------------------------------------

	@Test
	@DisplayName("one undo reverses the entire gesture (quest + seeds + edges)")
	void singleUndoReversesEntireGesture()
	{
		List<Goal> templates = Arrays.asList(
			skillTemplate(Skill.MAGIC, 75),
			skillTemplate(Skill.SMITHING, 70),
			questTemplate(Quest.LEGENDS_QUEST));
		String questId = api.addQuestGoalWithPrereqs(Quest.DRAGON_SLAYER_II, templates);
		assertEquals(4, store.getGoals().size());

		boolean undone = api.undo();
		assertTrue(undone, "undo should succeed");
		assertEquals(0, store.getGoals().size(),
			"undo should remove the quest goal AND all three seeded prereqs");

		// Redo replays the whole gesture.
		boolean redone = api.redo();
		assertTrue(redone, "redo should succeed");
		assertEquals(4, store.getGoals().size());
		Goal replayed = findByType(GoalType.QUEST, "DRAGON_SLAYER_II");
		assertNotNull(replayed);
		assertEquals(3, replayed.getRequiredGoalIds().size());
	}

	// ---- API: resolveQuestRequirements -------------------------------------

	@Test
	@DisplayName("api.resolveQuestRequirements routes to the resolver with the injected client")
	void resolveQuestRequirementsRoutesToResolver()
	{
		// Build a second api instance with a mocked Client — the shared
		// `api` field uses the null-client test constructor.
		Client client = mock(Client.class);
		when(client.getRealSkillLevel(Skill.AGILITY)).thenReturn(30);
		GoalPlannerApiImpl apiWithClient = new GoalPlannerApiImpl(
			store,
			new GoalReorderingService(store),
			mock(ItemManager.class),
			mock(WikiCaRepository.class),
			client);

		QuestRequirementResolver.Resolved out =
			apiWithClient.resolveQuestRequirements(Quest.HORROR_FROM_THE_DEEP);
		assertNotNull(out);
		// 1 unmet skill req (Agility 30 < 35) + 1 unmet quest prereq
		// (Alfred Grimhand's Barcrawl) + 1 optional combat recommendation = 3 templates.
		assertEquals(3, out.templates.size(),
			"HFTD should produce skill + Barcrawl + optional combat templates");
	}

	@Test
	@DisplayName("api.resolveQuestRequirements returns empty for null quest")
	void resolveQuestRequirementsNullQuest()
	{
		QuestRequirementResolver.Resolved out = api.resolveQuestRequirements(null);
		assertNotNull(out);
		assertTrue(out.isEmpty());
	}

	// ---- tagging -----------------------------------------------------------

	/** Find the QUEST-category tag with the given label, or null. */
	private Tag findQuestTag(String label)
	{
		return store.getTags().stream()
			.filter(t -> t.getCategory() == TagCategory.QUEST)
			.filter(t -> label.equalsIgnoreCase(t.getLabel()))
			.findFirst()
			.orElse(null);
	}

	/** True iff the goal with {@code goalId} carries the given tag id. */
	private boolean goalHasTag(String goalId, String tagId)
	{
		Goal g = findById(goalId);
		return g != null && g.getTagIds() != null && g.getTagIds().contains(tagId);
	}

	@Test
	@DisplayName("every prereq gets the quest-name tag; the quest goal itself does NOT")
	void questTagAppliedToPrereqsOnly()
	{
		List<Goal> templates = Arrays.asList(
			skillTemplate(Skill.MAGIC, 75),
			skillTemplate(Skill.SMITHING, 70),
			questTemplate(Quest.LEGENDS_QUEST));
		String questId = api.addQuestGoalWithPrereqs(Quest.DRAGON_SLAYER_II, templates);

		Tag tag = findQuestTag(Quest.DRAGON_SLAYER_II.getName());
		assertNotNull(tag, "QUEST-category tag named after the quest must exist");

		// The quest goal itself is NOT tagged — it already identifies
		// itself by name, the tag would just be noise.
		assertFalse(goalHasTag(questId, tag.getId()),
			"quest goal must NOT carry its own quest-name tag");

		// Every seeded prereq is tagged.
		for (Goal g : store.getGoals())
		{
			if (g.getId().equals(questId)) continue;
			assertTrue(g.getTagIds().contains(tag.getId()),
				"seeded prereq " + g.getName() + " must carry the quest tag");
		}
	}

	@Test
	@DisplayName("pre-existing reused goals also receive the quest tag")
	void questTagAppliedToReusedGoals()
	{
		// Pre-existing Agility 99 goal — will be reused for HFTD's 35 req.
		String existingAgilityId = api.addSkillGoalForLevel(Skill.AGILITY, 99);

		api.addQuestGoalWithPrereqs(Quest.HORROR_FROM_THE_DEEP,
			Arrays.asList(skillTemplate(Skill.AGILITY, 35)));

		Tag tag = findQuestTag(Quest.HORROR_FROM_THE_DEEP.getName());
		assertNotNull(tag);
		assertTrue(goalHasTag(existingAgilityId, tag.getId()),
			"pre-existing reused goal must carry the new quest tag");
	}

	@Test
	@DisplayName("undo reverses tag attachments along with everything else")
	void undoReversesTagging()
	{
		List<Goal> templates = Arrays.asList(skillTemplate(Skill.AGILITY, 35));
		String questId = api.addQuestGoalWithPrereqs(Quest.HORROR_FROM_THE_DEEP, templates);

		Tag tag = findQuestTag(Quest.HORROR_FROM_THE_DEEP.getName());
		assertNotNull(tag);

		api.undo();

		// Quest goal is gone; skill seed is gone; no goal should carry the tag.
		for (Goal g : store.getGoals())
		{
			assertFalse(g.getTagIds().contains(tag.getId()),
				"after undo, no goal should carry the quest tag");
		}
		// The Tag entity itself may still exist (createUserTag is not
		// command-wrapped) — we don't assert on it. Orphan tags are
		// tolerated by the existing infra.
	}

	@Test
	@DisplayName("undo preserves pre-existing goals when reuse matched them")
	void undoPreservesPreExistingMatches()
	{
		// Pre-existing 99 Agility — a USER goal, not autoSeeded.
		String existingAgilityId = api.addSkillGoalForLevel(Skill.AGILITY, 99);
		assertEquals(1, store.getGoals().size());

		// Add HFTD with the Agility 35 template — should reuse the 99 goal.
		api.addQuestGoalWithPrereqs(Quest.HORROR_FROM_THE_DEEP,
			Arrays.asList(skillTemplate(Skill.AGILITY, 35)));
		assertEquals(2, store.getGoals().size());

		// Undo ONLY the quest-add gesture.
		boolean undone = api.undo();
		assertTrue(undone);

		// The pre-existing 99 Agility goal must survive — the compound
		// should only revert what it actually created (quest goal + edge),
		// not the find-or-create match.
		assertEquals(1, store.getGoals().size());
		Goal survivor = findById(existingAgilityId);
		assertNotNull(survivor, "pre-existing agility goal must survive undo of quest-add");
	}
}

package com.goalplanner.api;

