		private void makeChunkGoal(int chunk)
		{
			api = apiWith(MockClientFactory.createClient(
				new MockGameState().skillXp(Skill.PRAYER, 9_800_000)));
			Goal parent = addSkillGoal("PRAYER");
			derived = store.findGoalById(
