	@org.junit.jupiter.api.Nested
	@DisplayName("OR-unlock cascade is order-independent")
	class OrCascadeOrder
	{
		@Test
		@DisplayName("the parent completes even when the AND-prereq finishes last")
		void andPrereqLastStillCascades()
		{
			// Warriors-style: unlock requires quest AND (99 Attack OR 99 Strength).
			Goal quest = Goal.builder().type(GoalType.QUEST).name("Bone Voyage")
				.questName("BONE_VOYAGE").targetValue(1).build();
			Goal att = Goal.builder().type(GoalType.SKILL).name("99 Attack")
				.skillName("ATTACK").targetValue(13_034_431).build();
			Goal unlock = Goal.builder().type(GoalType.CUSTOM).name("Unlock").build();
			store.addGoal(quest); store.addGoal(att); store.addGoal(unlock);
			api.addRequirement(unlock.getId(), quest.getId());
			api.addOrRequirement(unlock.getId(), att.getId());

			// Tracker order in the real drain: skills BEFORE quests.
			api.recordGoalProgress(att.getId(), 13_034_431);
			assertFalse(unlock.isComplete(), "AND-prereq still open - must not complete yet");
			api.recordGoalProgress(quest.getId(), 1);

			assertTrue(unlock.isComplete(),
				"the AND-prereq finishing last must still trigger the OR-unlock cascade");
		}

		@Test
		@DisplayName("removeRequirement refuses an OR-only edge, which getDependents still lists")
		void removeRequirementRefusesOrOnlyEdge()
		{
			// A boss whose skill prereq is an ALTERNATIVE (OR) unlock, the shape the
			// boss/quest seeders produce. The dock's relations list renders this edge
			// from the SKILL side ("Required by: Boss"), because the reverse index
			// carries OR edges too - but no API can drop it, so the row must render
			// WITHOUT an X (see GoalPanel.isAndRequirementOf).
			Goal boss = Goal.builder().type(GoalType.BOSS).name("Boss")
				.bossName("Zulrah").targetValue(1).build();
			Goal skill = Goal.builder().type(GoalType.SKILL).name("Skill")
				.skillName("SLAYER").targetValue(1000).build();
			store.addGoal(boss); store.addGoal(skill);
			assertTrue(api.addOrRequirement(boss.getId(), skill.getId()));

			assertTrue(api.getDependents(skill.getId()).contains(boss.getId()),
				"the reverse index lists OR-edge dependents, so the row is rendered");
			assertFalse(api.getRequirements(boss.getId()).contains(skill.getId()),
				"an OR edge is not an AND requirement");

			assertFalse(api.removeRequirement(boss.getId(), skill.getId()),
				"removeRequirement only drops AND edges - the X would be a silent no-op");
			assertTrue(api.getDependents(skill.getId()).contains(boss.getId()),
				"the OR edge survives the refused removal");
		}

		@Test
		@DisplayName("removeRequirement drops an AND edge, and one undo restores it")
		void removeRequirementDropsAndEdge()
		{
			Goal parent = Goal.builder().type(GoalType.CUSTOM).name("Parent").build();
			Goal prereq = Goal.builder().type(GoalType.CUSTOM).name("Prereq").build();
			store.addGoal(parent); store.addGoal(prereq);
			assertTrue(api.addRequirement(parent.getId(), prereq.getId()));

			assertTrue(api.removeRequirement(parent.getId(), prereq.getId()));
			assertFalse(api.getDependents(prereq.getId()).contains(parent.getId()));

			api.undo();
			assertTrue(api.getRequirements(parent.getId()).contains(prereq.getId()),
				"one undo restores the removed AND edge");
		}

		@Test
		@DisplayName("a plain AND-only parent never auto-completes from its prereqs")
		void andOnlyParentUntouched()
		{
			Goal quest = Goal.builder().type(GoalType.QUEST).name("Q")
				.questName("BONE_VOYAGE").targetValue(1).build();
			Goal parent = Goal.builder().type(GoalType.CUSTOM).name("Manual step").build();
			store.addGoal(quest); store.addGoal(parent);
			api.addRequirement(parent.getId(), quest.getId());

			api.recordGoalProgress(quest.getId(), 1);

			assertFalse(parent.isComplete(),
				"completing prerequisites must never auto-complete a non-OR goal");
		}
	}
}

package com.goalplanner.api;

import com.goalplanner.data.WikiCaRepository;
import com.goalplanner.model.Goal;
import com.goalplanner.model.GoalStatus;
import com.goalplanner.model.GoalType;
import com.goalplanner.persistence.GoalStore;
import com.goalplanner.service.GoalReorderingService;
import com.goalplanner.testsupport.InMemoryConfigManager;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.mock;

/**
 * Repro harness for "Move to Section → Move to New Section…" doing nothing.
 * Mirrors the exact UI flow: api.createSection(name) then
 * api.moveGoalToSection(goalId, newId), across the scenarios a user testing
 * the new delete-section paradigm would hit.
 */
class MoveToNewSectionReproTest
{
	private GoalStore store;
	private GoalPlannerApiImpl api;

	@BeforeEach
	void setUp()
	{
		ConfigManager configManager = InMemoryConfigManager.create();
		store = new GoalStore(configManager, new com.google.gson.Gson());
		store.load();
		GoalReorderingService reordering = new GoalReorderingService(store);
		api = new GoalPlannerApiImpl(store, reordering,
			mock(ItemManager.class), mock(WikiCaRepository.class));
		api.setOnGoalsChanged(() -> {});
	}

	@Test
	@DisplayName("plain: incomplete default goal → new section")
	void plainMove()
	{
		String goalId = api.addCustomGoal("Test", "");
		String newId = api.createSection("Fresh");
		assertNotNull(newId, "createSection returned null");
		assertTrue(api.moveGoalToSection(goalId, newId), "move returned false");
		assertEquals(newId, api.findGoal(goalId).getSectionId());
	}

	@Test
	@DisplayName("completed goal → new section")
	void completedMove()
	{
		Goal done = Goal.builder().type(GoalType.CUSTOM).name("done")
			.completedAt(123L).status(GoalStatus.COMPLETE)
			.sectionId(null).build();
		store.addGoal(done);
		store.reconcileDerivedSections();
		String newId = api.createSection("Fresh");
		assertNotNull(newId);
		assertTrue(api.moveGoalToSection(done.getId(), newId), "completed move returned false");
		assertEquals(newId, done.getSectionId());
	}

	@Test
	@DisplayName("after deleting a section, move to a new section with the SAME name")
	void moveAfterDeleteReusingName()
	{
		String goalId = api.addCustomGoal("Survivor", "");
		String doomed = api.createSection("PvM");
		assertTrue(api.deleteSection(doomed));
		String newId = api.createSection("PvM");
		assertNotNull(newId, "createSection(\"PvM\") after delete returned null");
		assertTrue(api.moveGoalToSection(goalId, newId), "move returned false");
		assertEquals(newId, api.findGoal(goalId).getSectionId());
	}

	@Test
	@DisplayName("after delete-section UNDO, move another goal to a new section")
	void moveAfterDeleteUndo()
	{
		String inDoomed = api.addCustomGoal("In doomed", "");
		String doomed = api.createSection("Doomed");
		api.moveGoalToSection(inDoomed, doomed);
		assertTrue(api.deleteSection(doomed));
		api.undo();

		String goalId = api.addCustomGoal("Mover", "");
		String newId = api.createSection("Fresh");
		assertNotNull(newId);
		assertTrue(api.moveGoalToSection(goalId, newId), "move after undo returned false");
		assertEquals(newId, api.findGoal(goalId).getSectionId());
	}
}

package com.goalplanner.api;

import com.goalplanner.data.WikiCaRepository;
import com.goalplanner.model.Goal;
import com.goalplanner.persistence.GoalStore;
import com.goalplanner.service.GoalReorderingService;
import com.goalplanner.testsupport.InMemoryConfigManager;
import net.runelite.api.Quest;
import net.runelite.api.Skill;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

/**
 * Tests for {@link GoalPlannerApiImpl#seedRequirementsForGoal}, the "Add
 * requirements to this section" action. The "All" path (includeMet=true) uses
 * floor lookups and needs no live client, so it's deterministic in tests.
 */
@DisplayName("seedRequirementsForGoal — populate a quest/diary goal's section with its requirements")
class SeedRequirementsForGoalTest
{
	private GoalStore store;
	private GoalPlannerApiImpl api;

	@BeforeEach
	void setUp()
	{
		ConfigManager configManager = InMemoryConfigManager.create();
		store = new GoalStore(configManager, new com.google.gson.Gson());
		store.load();
		ItemManager itemManager = mock(ItemManager.class);
		WikiCaRepository wikiCaRepository = mock(WikiCaRepository.class);
		GoalReorderingService reorderingService = new GoalReorderingService(store);
		api = new GoalPlannerApiImpl(store, reorderingService, itemManager, wikiCaRepository);
		api.setOnGoalsChanged(() -> {});
	}

	@Test
	@DisplayName("a non-quest goal is a no-op")
	void nonQuestGoalIsNoOp()
	{
		String skillId = api.addSkillGoalForLevel(Skill.ATTACK, 50);
		int before = store.getGoals().size();
		int seeded = api.seedRequirementsForGoal(skillId, true);
		assertEquals(0, seeded);
		assertEquals(before, store.getGoals().size());
	}

	@Test
	@DisplayName("an unknown goal id is a no-op")
	void unknownGoalIsNoOp()
	{
		assertEquals(0, api.seedRequirementsForGoal("does-not-exist", true));
	}

	@Test
	@DisplayName("'All' seeds the requirement tree into the quest goal's own section and links it")
	void allSeedsRequirementTreeIntoSection()
	{
		// Put the quest in a USER section (not the default Incomplete) so the test
		// actually catches seeds that strand in the default section.
		String sectionId = api.createSection("Guide");
		String questId = api.addQuestGoal(Quest.DRAGON_SLAYER_II);
		assertNotNull(questId);
		api.moveGoalToSection(questId, sectionId);

		int seeded = api.seedRequirementsForGoal(questId, true);
		assertTrue(seeded > 0, "expected DS2 to seed at least one prerequisite");

		// The quest goal is now linked to in-section prerequisites.
		Goal quest = store.findGoalById(questId);
		assertFalse(quest.getRequiredGoalIds().isEmpty(), "quest goal should gain requirement edges");

		// EVERY seeded goal (skill/quest/account/…) lands in the quest's user
		// section, not the default Incomplete section.
		for (Goal g : store.getGoals())
		{
			assertEquals(sectionId, g.getSectionId(),
				"seeded goal " + g.getName() + " should share the quest's section");
		}

		// No goal is duplicated: cross-section dedup reuses an equivalent already
		// in the target section instead of spawning a fresh copy on the 2nd+ path.
		assertNoDuplicateIdentities();
	}

	@Test
	@DisplayName("'All' reuses a shared transitive prereq once (no stranded duplicate) and reaches under completed quests")
	void allSeedsSharedTransitivePrereqExactlyOnce()
	{
		// Desert Treasure II reaches Troll Stronghold via TWO paths:
		//   DT2 → Desert Treasure I → Troll Stronghold
		//   DT2 → Secrets of the North → Devious Minds → Troll Stronghold
		// and Death Plateau sits transitively UNDER Troll Stronghold. Full-tree
		// (floor-lookup) recursion must reach Death Plateau, and the shared Troll
		// Stronghold must be reused — not duplicated and stranded in Incomplete.
		String sectionId = api.createSection("Guide");
		String questId = api.addQuestGoal(Quest.DESERT_TREASURE_II__THE_FALLEN_EMPIRE);
		assertNotNull(questId);
		api.moveGoalToSection(questId, sectionId);

		int seeded = api.seedRequirementsForGoal(questId, true);
		assertTrue(seeded > 0, "expected DT2 to seed prerequisites");

		// (a) The shared transitive prereq exists EXACTLY once.
		assertEquals(1, countByQuestName("TROLL_STRONGHOLD"),
			"shared transitive prereq Troll Stronghold should be seeded exactly once");

		// (b) Every seeded goal lives in the target section — nothing stranded in
		//     the default Incomplete by a blocked cross-namespace move.
		for (Goal g : store.getGoals())
		{
			assertEquals(sectionId, g.getSectionId(),
				"seeded goal " + g.getName() + " should share the quest's section");
		}
		assertNoDuplicateIdentities();

		// (c) A prereq sitting transitively under Troll Stronghold is present —
		//     proves full-tree recursion descends past it.
		assertEquals(1, countByQuestName("DEATH_PLATEAU"),
			"transitive prereq Death Plateau (under Troll Stronghold) should be seeded");
	}

	/** Count goals whose questName matches (QUEST goals only). */
	private long countByQuestName(String questEnumName)
	{
		return store.getGoals().stream()
			.filter(g -> questEnumName.equals(g.getQuestName()))
			.count();
	}

	/** Fail if any two goals denote the same objective (per {@link com.goalplanner.model.GoalIdentity}). */
	private void assertNoDuplicateIdentities()
	{
		java.util.List<Goal> goals = new java.util.ArrayList<>(store.getGoals());
		for (int i = 0; i < goals.size(); i++)
		{
			for (int j = i + 1; j < goals.size(); j++)
			{
				assertFalse(
					com.goalplanner.model.GoalIdentity.sameIdentity(goals.get(i), goals.get(j)),
					"duplicate goal identity: '" + goals.get(i).getName()
						+ "' and '" + goals.get(j).getName() + "'");
			}
		}
	}

	@Test
	@DisplayName("running 'All' twice reuses existing goals instead of duplicating")
	void rerunReusesGoals()
	{
		String questId = api.addQuestGoal(Quest.DRAGON_SLAYER_II);
		api.seedRequirementsForGoal(questId, true);
		int afterFirst = store.getGoals().size();
		api.seedRequirementsForGoal(questId, true);
		int afterSecond = store.getGoals().size();
		assertEquals(afterFirst, afterSecond, "re-running should not create duplicate goals");
	}

	@Test
	@DisplayName("'All' sets the section to keep completed goals inline (so they render as cards, not ghosts)")
	void allKeepsCompletedInline()
	{
		String sectionId = api.createSection("Guide");
		String questId = api.addQuestGoal(Quest.DRAGON_SLAYER_II);
		api.moveGoalToSection(questId, sectionId);

		api.seedRequirementsForGoal(questId, true);

		com.goalplanner.model.Section sec = store.findSection(sectionId);
		assertEquals(Boolean.FALSE, sec.getAutoArchiveOverride(),
			"'All' should flip the section to keep-inline so met requirements stay as cards");
	}

	@Test
	@DisplayName("'Incomplete only' leaves the section's auto-archive setting untouched")
	void incompleteOnlyLeavesArchiveUntouched()
	{
		String sectionId = api.createSection("Guide");
		String questId = api.addQuestGoal(Quest.DRAGON_SLAYER_II);
		api.moveGoalToSection(questId, sectionId);

		api.seedRequirementsForGoal(questId, false);

		com.goalplanner.model.Section sec = store.findSection(sectionId);
		assertNull(sec.getAutoArchiveOverride(), "incomplete-only must not change the archive override");
	}

	@Test
	@DisplayName("one undo reverses the whole seeding gesture")
	void undoReversesSeeding()
	{
		String questId = api.addQuestGoal(Quest.DRAGON_SLAYER_II);
		int beforeSeed = store.getGoals().size();
		api.seedRequirementsForGoal(questId, true);
		assertTrue(store.getGoals().size() > beforeSeed);
		api.undo();
		assertEquals(beforeSeed, store.getGoals().size(), "undo should remove every seeded goal");
	}

	// ---- Diary goals (seedDiaryRequirementsForGoal) -------------------------
	// Ardougne Medium has skills + prereq quests + the Fairy Rings unlock (a CUSTOM
	// goal with its own quest prereqs), so it exercises both the shared section-aware
	// BFS (seedPrereqsInto) and the unlock/boss/account direct creations that go
	// through reuseOrCreateInSection. "All" uses floor lookups → no live Client.

	@Test
	@DisplayName("a diary goal is recognised (no longer a no-op for the add-requirements action)")
	void diaryGoalSeedsRequirements()
	{
		String diaryId = api.addDiaryGoalNoPrereqs("Ardougne", GoalPlannerApi.DiaryTier.MEDIUM);
		assertNotNull(diaryId);
		int seeded = api.seedDiaryRequirementsForGoal(diaryId, true);
		assertTrue(seeded > 0, "expected Ardougne Medium to seed at least one prerequisite");
	}

	@Test
	@DisplayName("diary 'All' seeds the requirement tree into the diary goal's own section and links it")
	void diaryAllSeedsRequirementTreeIntoSection()
	{
		String sectionId = api.createSection("Guide");
		String diaryId = api.addDiaryGoalNoPrereqs("Ardougne", GoalPlannerApi.DiaryTier.MEDIUM);
		assertNotNull(diaryId);
		api.moveGoalToSection(diaryId, sectionId);

		int seeded = api.seedDiaryRequirementsForGoal(diaryId, true);
		assertTrue(seeded > 0, "expected Ardougne Medium to seed prerequisites");

		// The diary goal is now linked to in-section prerequisites.
		Goal diary = store.findGoalById(diaryId);
		assertFalse(diary.getRequiredGoalIds().isEmpty(), "diary goal should gain requirement edges");

		// EVERY seeded goal (skill/quest/unlock/…) lands in the diary's user section,
		// not the default Incomplete — boss/account/quest/unlock direct creations are
		// section-aware via reuseOrCreateInSection.
		for (Goal g : store.getGoals())
		{
			assertEquals(sectionId, g.getSectionId(),
				"seeded goal " + g.getName() + " should share the diary's section");
		}

		// The Fairy Rings unlock (a CUSTOM milestone created outside the BFS) seeded
		// into the section — proves the unlock path is section-aware.
		assertTrue(store.getGoals().stream()
				.anyMatch(g -> "Fairy Rings Unlocked".equalsIgnoreCase(g.getName())),
			"the Fairy Rings unlock goal should be seeded");

		// Cross-section dedup: a shared prereq reached via multiple paths is reused,
		// not duplicated and stranded.
		assertNoDuplicateIdentities();
	}

	@Test
	@DisplayName("running diary 'All' twice reuses existing goals instead of duplicating")
	void diaryRerunReusesGoals()
	{
		String sectionId = api.createSection("Guide");
		String diaryId = api.addDiaryGoalNoPrereqs("Ardougne", GoalPlannerApi.DiaryTier.MEDIUM);
		api.moveGoalToSection(diaryId, sectionId);

		api.seedDiaryRequirementsForGoal(diaryId, true);
		int afterFirst = store.getGoals().size();
		api.seedDiaryRequirementsForGoal(diaryId, true);
		int afterSecond = store.getGoals().size();
		assertEquals(afterFirst, afterSecond, "re-running should not create duplicate goals");
		assertNoDuplicateIdentities();
	}

	@Test
	@DisplayName("diary 'All' sets the section to keep completed goals inline")
	void diaryAllKeepsCompletedInline()
	{
		String sectionId = api.createSection("Guide");
		String diaryId = api.addDiaryGoalNoPrereqs("Ardougne", GoalPlannerApi.DiaryTier.MEDIUM);
		api.moveGoalToSection(diaryId, sectionId);

		api.seedDiaryRequirementsForGoal(diaryId, true);

		com.goalplanner.model.Section sec = store.findSection(sectionId);
		assertEquals(Boolean.FALSE, sec.getAutoArchiveOverride(),
			"'All' should flip the section to keep-inline so met requirements stay as cards");
	}

	@Test
	@DisplayName("one undo reverses the whole diary seeding gesture")
	void diaryUndoReversesSeeding()
	{
		String diaryId = api.addDiaryGoalNoPrereqs("Ardougne", GoalPlannerApi.DiaryTier.MEDIUM);
		int beforeSeed = store.getGoals().size();
		api.seedDiaryRequirementsForGoal(diaryId, true);
		assertTrue(store.getGoals().size() > beforeSeed);
		api.undo();
		assertEquals(beforeSeed, store.getGoals().size(), "undo should remove every seeded diary prerequisite");
	}
}

package com.goalplanner.api;

import com.goalplanner.data.WikiCaRepository;
import com.goalplanner.model.Goal;
import com.goalplanner.model.GoalType;
import com.goalplanner.model.Section;
import com.goalplanner.model.Tag;
import com.goalplanner.model.TagCategory;
import com.goalplanner.persistence.GoalStore;
import com.goalplanner.service.GoalReorderingService;
import com.goalplanner.share.ShareBundle;
import com.goalplanner.share.ShareCodec;
import com.goalplanner.testsupport.InMemoryConfigManager;
import com.google.gson.Gson;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

/**
 * Export side: store goals → {@link ShareBundle}, plus a full cross-store
 * round-trip (export → encode → decode → import into a second store) that
 * exercises the entire share pipeline end to end.
 */
class ShareExportServiceTest
{
	/** A fresh, isolated store + api. */
	private static final class Env
	{
		final GoalStore store;
		final GoalPlannerApiImpl api;

		Env()
		{
			ConfigManager cm = InMemoryConfigManager.create();
			store = new GoalStore(cm, new Gson());
			store.load();
			ItemManager itemManager = mock(ItemManager.class);
			WikiCaRepository wikiCaRepository = mock(WikiCaRepository.class);
			GoalReorderingService reordering = new GoalReorderingService(store);
			api = new GoalPlannerApiImpl(store, reordering, itemManager, wikiCaRepository);
			api.setOnGoalsChanged(() -> {});
		}
	}

	/** Seed a section "Inferno Prep" with a tagged Ranged goal that Zuk requires. */
	private static String seedInfernoSection(Env env)
	{
		Section section = env.store.createUserSection("Inferno Prep");
		Tag tag = env.store.createUserTag("Inferno", TagCategory.OTHER);

		Goal ranged = Goal.builder().type(GoalType.SKILL).name("Ranged - Level 75")
			.skillName("RANGED").targetValue(1_210_421).sectionId(section.getId())
			.build();
		ranged.getTagIds().add(tag.getId());
		Goal zuk = Goal.builder().type(GoalType.BOSS).name("TzKal-Zuk")
			.bossName("TzKal-Zuk").targetValue(1).sectionId(section.getId())
			.build();
		env.store.addGoal(ranged);
		env.store.addGoal(zuk);
		env.store.addRequirement(zuk.getId(), ranged.getId());
		return section.getId();
	}

	@Test
	void exportSectionReflectsItsGoalsTagsAndRelations()
	{
		Env env = new Env();
		String sectionId = seedInfernoSection(env);

		ShareBundle bundle = env.api.exportSectionBundle(sectionId, "Andrew");

		assertNotNull(bundle);
		assertEquals(ShareBundle.Kind.SECTION, bundle.getKind());
		assertEquals("Inferno Prep", bundle.getSectionName());
		assertEquals("Andrew", bundle.getSharedBy());
		assertEquals(2, bundle.getGoals().size());
		// The Ranged goal carries its resolved tag.
		assertTrue(bundle.getGoals().stream()
			.anyMatch(g -> "Ranged - Level 75".equals(g.getName())
				&& g.getTags().size() == 1
				&& "Inferno".equals(g.getTags().get(0).getLabel())));
		// Zuk's requirement is encoded as an in-bundle ref.
		assertTrue(bundle.getGoals().stream()
			.anyMatch(g -> "TzKal-Zuk".equals(g.getName()) && g.getRequires().size() == 1));
	}

	@Test
	void fullRoundTripExportEncodeDecodeImportIntoASecondStore()
	{
		Env sender = new Env();
		String sectionId = seedInfernoSection(sender);

		ShareCodec codec = new ShareCodec(new Gson());
		String code = codec.encode(sender.api.exportSectionBundle(sectionId, "Andrew"));

		Env receiver = new Env();
		int before = receiver.store.getGoals().size();
		receiver.api.importShareBundle(codec.decode(code));

		assertEquals(before + 2, receiver.store.getGoals().size());
		Goal importedRanged = receiver.store.getGoals().stream()
			.filter(g -> "Ranged - Level 75".equals(g.getName())).findFirst().orElseThrow();
		Goal importedZuk = receiver.store.getGoals().stream()
			.filter(g -> "TzKal-Zuk".equals(g.getName())).findFirst().orElseThrow();
		// Relation survived the round-trip, rewired to the receiver's fresh ids.
		assertTrue(importedZuk.getRequiredGoalIds().contains(importedRanged.getId()));
		// Tag came across.
		assertEquals(1, importedRanged.getTagIds().size());
	}

	@Test
	void exportGoalsBundleCoversExplicitIdsOnlyAndKeepsTheSourceSection()
	{
		Env env = new Env();
		String sectionId = seedInfernoSection(env);
		Goal zuk = env.store.getGoals().stream()
			.filter(g -> "TzKal-Zuk".equals(g.getName())).findFirst().orElseThrow();

		ShareBundle bundle = env.api.exportGoalsBundle(
			java.util.Collections.singletonList(zuk.getId()), "Andrew");

		assertNotNull(bundle);
		// A selection entirely inside one user section keeps that section's
		// identity (still the v1 wire — older builds can import it).
		assertEquals(ShareBundle.Kind.SECTION, bundle.getKind());
		assertEquals("Inferno Prep", bundle.getSectionName());
		assertEquals(1, bundle.getGoals().size());
		assertEquals("TzKal-Zuk", bundle.getGoals().get(0).getName());
		// The unselected Ranged goal means Zuk's requirement edge is dropped.
		assertTrue(bundle.getGoals().get(0).getRequires().isEmpty());
	}

	@Test
	void exportGoalsFromDefaultPlanStaysALooseGoalsBundle()
	{
		Env env = new Env();
		Goal loose = Goal.builder().type(GoalType.CUSTOM).name("Loose").build();
		env.store.addGoal(loose); // lands in Incomplete

		ShareBundle bundle = env.api.exportGoalsBundle(
			java.util.Collections.singletonList(loose.getId()), "Andrew");

		assertNotNull(bundle);
		assertEquals(ShareBundle.Kind.GOALS, bundle.getKind());
		assertNull(bundle.getSectionName());
		assertFalse(bundle.needsV2());
	}

	@Test
	void exportGoalsSpanningSectionsPreservesEachSourceSection()
	{
		Env env = new Env();
		Section pvm = env.store.createUserSection("PvM");
		env.store.findSection(pvm.getId()).setColorRgb(0x336699);
		Section skills = env.store.createUserSection("Skills");
		Goal zulrah = Goal.builder().type(GoalType.BOSS).name("Zulrah")
			.bossName("Zulrah").targetValue(50).sectionId(pvm.getId()).build();
		Goal agility = Goal.builder().type(GoalType.SKILL).name("Agility - Level 70")
			.skillName("AGILITY").targetValue(737_627).sectionId(skills.getId()).build();
		Goal loose = Goal.builder().type(GoalType.CUSTOM).name("Loose").build();
		env.store.addGoal(zulrah);
		env.store.addGoal(agility);
		env.store.addGoal(loose);
		// Dependency across the selection's sections — must survive the trip.
		env.store.addRequirement(zulrah.getId(), agility.getId());

		ShareBundle bundle = env.api.exportGoalsBundle(
			java.util.Arrays.asList(zulrah.getId(), agility.getId(), loose.getId()), "Andrew");

		assertNotNull(bundle);
		assertTrue(bundle.needsV2());
		assertEquals(3, bundle.totalGoalCount());
		java.util.List<com.goalplanner.share.SectionShareDto> secs = bundle.effectiveSections();
		assertEquals(3, secs.size());
		assertEquals("PvM", secs.get(0).getName());
		assertEquals(0x336699, secs.get(0).getColorRgb());
		assertEquals("Zulrah", secs.get(0).getGoals().get(0).getName());
		assertEquals("Skills", secs.get(1).getName());
		// The default-plan goal rides along as a targetDefault entry.
		assertTrue(secs.get(2).isTargetDefault());
		assertEquals("Loose", secs.get(2).getGoals().get(0).getName());

		// Round-trip: the receiver gets BOTH sections back, not one blob.
		// (Imported sections keep their own name verbatim - no sharer suffix.)
		ShareCodec codec = new ShareCodec(new Gson());
		Env receiver = new Env();
		receiver.api.importShareBundle(codec.decode(codec.encode(bundle)));
		assertNotNull(receiver.store.getSections().stream()
			.filter(s -> s.getName() != null && s.getName().startsWith("PvM")).findFirst().orElse(null));
		assertNotNull(receiver.store.getSections().stream()
			.filter(s -> s.getName() != null && s.getName().startsWith("Skills")).findFirst().orElse(null));
		Goal importedZulrah = receiver.store.getGoals().stream()
			.filter(g -> "Zulrah".equals(g.getName())).findFirst().orElseThrow();
		assertTrue(receiver.store.findSection(importedZulrah.getSectionId()).getName().startsWith("PvM"));
		Goal importedLoose = receiver.store.getGoals().stream()
			.filter(g -> "Loose".equals(g.getName())).findFirst().orElseThrow();
		assertEquals(receiver.store.getIncompleteSection().getId(), importedLoose.getSectionId());
		// The cross-section dependency came back, rewired to fresh ids.
		Goal importedAgility = receiver.store.getGoals().stream()
			.filter(g -> "Agility - Level 70".equals(g.getName())).findFirst().orElseThrow();
		assertTrue(importedZulrah.getRequiredGoalIds().contains(importedAgility.getId()));
	}

	@Test
	void exportSectionReturnsNullForUnknownSection()
	{
		Env env = new Env();
		assertNull(env.api.exportSectionBundle("no-such-section", "Andrew"));
	}

	@Test
	void exportAllSectionsCarriesCrossSectionEdgesAndImportRestoresThem()
	{
		Env env = new Env();
		Section skills = env.store.createUserSection("Skills");
		Section quests = env.store.createUserSection("Quests");

		Goal agility = Goal.builder().type(GoalType.SKILL).name("Agility - Level 70")
			.skillName("AGILITY").targetValue(737_627).sectionId(skills.getId()).build();
		Goal sote = Goal.builder().type(GoalType.QUEST).name("Song of the Elves")
			.questName("SONG_OF_THE_ELVES").sectionId(quests.getId()).build();
		env.store.addGoal(agility);
		env.store.addGoal(sote);
		// Cross-section dependency: rides on the bundle's crossEdges list.
		env.store.addRequirement(sote.getId(), agility.getId());

		ShareBundle bundle = env.api.exportAllSectionsBundle("Andrew");

		assertNotNull(bundle);
		assertEquals(2, bundle.totalGoalCount());
		assertEquals(1, bundle.getCrossEdges().size());
		// Section-scoped refs stay clean — the edge is NOT in the per-goal lists.
		assertTrue(bundle.effectiveSections().stream()
			.flatMap(s -> s.getGoals().stream())
			.allMatch(g -> g.getRequires().isEmpty() && g.getOrRequires().isEmpty()));

		// Round-trip through the codec into a second store: the dependency
		// comes back, rewired to the receiver's fresh ids across sections.
		ShareCodec codec = new ShareCodec(new Gson());
		Env receiver = new Env();
		receiver.api.importShareBundle(codec.decode(codec.encode(bundle)));
		Goal importedSote = receiver.store.getGoals().stream()
			.filter(g -> "Song of the Elves".equals(g.getName())).findFirst().orElseThrow();
		Goal importedAgility = receiver.store.getGoals().stream()
			.filter(g -> "Agility - Level 70".equals(g.getName())).findFirst().orElseThrow();
		assertNotEquals(importedSote.getSectionId(), importedAgility.getSectionId());
		assertTrue(importedSote.getRequiredGoalIds().contains(importedAgility.getId()));
	}

	@Test
	void exportAllSectionsHasNoCrossEdgesWhenRelationsAreSectionLocal()
	{
		Env env = new Env();
		seedInfernoSection(env); // Zuk requires Ranged, both in one section

		ShareBundle bundle = env.api.exportAllSectionsBundle("Andrew");

		assertNotNull(bundle);
		assertTrue(bundle.getCrossEdges().isEmpty());
		assertEquals(2, bundle.totalGoalCount());
	}
}

package com.goalplanner.api;

import com.goalplanner.data.WikiCaRepository;
import com.goalplanner.model.Goal;
import com.goalplanner.model.GoalType;
import com.goalplanner.model.Section;
import com.goalplanner.model.Tag;
import com.goalplanner.model.TagCategory;
import com.goalplanner.persistence.GoalStore;
import com.goalplanner.service.GoalReorderingService;
import com.goalplanner.share.GoalShareDto;
import com.goalplanner.share.ShareBundle;
import com.goalplanner.share.ShareCodec;
import com.goalplanner.share.ShareMapper;
import com.goalplanner.share.TagShareDto;
import com.goalplanner.testsupport.InMemoryConfigManager;
import com.google.gson.Gson;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

/**
 * Import side: a decoded {@link ShareBundle} → real {@link GoalStore}. Run
 * against a real store (not a mock) per the stateful-store testing rule.
 */
class ShareImportServiceTest
{
	private GoalStore store;
	private GoalPlannerApiImpl api;

	@BeforeEach
	void setUp()
	{
		ConfigManager configManager = InMemoryConfigManager.create();
		store = new GoalStore(configManager, new Gson());
		store.load();

		ItemManager itemManager = mock(ItemManager.class);
		WikiCaRepository wikiCaRepository = mock(WikiCaRepository.class);
		GoalReorderingService reorderingService = new GoalReorderingService(store);
		api = new GoalPlannerApiImpl(store, reorderingService, itemManager, wikiCaRepository);
		api.setOnGoalsChanged(() -> {});
	}

	private static ShareBundle sampleBundle()
	{
		TagShareDto tag = new TagShareDto();
		tag.setLabel("Inferno");
		tag.setCategory("OTHER");
		tag.setColorRgb(0xAA3322);

		GoalShareDto ranged = new GoalShareDto();
		ranged.setRef(0);
		ranged.setType("SKILL");
		ranged.setName("Ranged - Level 75");
		ranged.setSkillName("RANGED");
		ranged.setTargetValue(1_210_421);
		ranged.setTags(Collections.singletonList(tag));

		GoalShareDto zuk = new GoalShareDto();
		zuk.setRef(1);
		zuk.setType("BOSS");
		zuk.setName("TzKal-Zuk");
		zuk.setBossName("TzKal-Zuk");
		zuk.setTargetValue(1);
		zuk.setRequires(Collections.singletonList(0));

		ShareBundle bundle = new ShareBundle();
		bundle.setKind(ShareBundle.Kind.SECTION);
		bundle.setSectionName("Inferno Prep");
		bundle.setSharedBy("Andrew");
		bundle.setGoals(Arrays.asList(ranged, zuk));
		return bundle;
	}

	private Goal goalNamed(String name)
	{
		return store.getGoals().stream()
			.filter(g -> name.equals(g.getName())).findFirst().orElseThrow();
	}

	@Test
	void importsBundleIntoNewSectionWithGoalsTagsAndRelations()
	{
		String sectionId = api.importShareBundle(sampleBundle());

		assertNotNull(sectionId);
		Section section = store.getSections().stream()
			.filter(s -> sectionId.equals(s.getId())).findFirst().orElse(null);
		assertNotNull(section);
		assertEquals("Inferno Prep", section.getName());
		// Imports land in their own user section, forced KEEP-INLINE (overriding
		// the global auto-archive default) so the recipient sees it as a checklist
		// against their account.
		assertFalse(section.isBuiltIn());
		assertEquals(Boolean.FALSE, section.getAutoArchiveOverride());

		Goal ranged = goalNamed("Ranged - Level 75");
		Goal zuk = goalNamed("TzKal-Zuk");

		assertEquals(GoalType.SKILL, ranged.getType());
		assertEquals("RANGED", ranged.getSkillName());
		assertEquals(1_210_421, ranged.getTargetValue());
		assertEquals(sectionId, ranged.getSectionId());
		// Fresh, unstarted goal — recipient's progress, not the sharer's.
		assertEquals(0, ranged.getCurrentValue());
		assertEquals(0L, ranged.getCompletedAt());

		// Tag find-or-created and attached.
		assertEquals(1, ranged.getTagIds().size());
		Tag tag = store.findTag(ranged.getTagIds().get(0));
		assertNotNull(tag);
		assertEquals("Inferno", tag.getLabel());

		// Relation remapped to the fresh ids.
		assertTrue(zuk.getRequiredGoalIds().contains(ranged.getId()));
	}

	@Test
	void importAppliesSharedSectionColor()
	{
		GoalShareDto g = new GoalShareDto();
		g.setRef(0);
		g.setType("CUSTOM");
		g.setName("X");
		ShareBundle bundle = new ShareBundle();
		bundle.setKind(ShareBundle.Kind.SECTION);
		bundle.setSectionName("Themed");
		bundle.setSectionColorRgb(0x3366CC);
		bundle.setGoals(java.util.Collections.singletonList(g));

		String sectionId = api.importShareBundle(bundle);
		Section section = store.findSection(sectionId);
		assertNotNull(section);
		assertEquals(0x3366CC, section.getColorRgb()); // shared colour carried over
	}

	@Test
	void undoReversesTheEntireImportAndRedoReplaysIt()
	{
		int goalsBefore = store.getGoals().size();
		int sectionsBefore = store.getSections().size();

		api.importShareBundle(sampleBundle());
		assertEquals(2, store.getGoals().size());

		assertTrue(api.undo());
		assertEquals(goalsBefore, store.getGoals().size(), "undo removes the imported goals");
		assertEquals(sectionsBefore, store.getSections().size(), "undo removes the imported section");

		assertTrue(api.redo());
		assertEquals(2, store.getGoals().size(), "redo re-imports");
	}

	@Test
	void skipsGoalsWithAnUnknownType()
	{
		GoalShareDto bad = new GoalShareDto();
		bad.setRef(0);
		bad.setType("TOTALLY_NOT_A_TYPE");
		bad.setName("hostile");

		GoalShareDto good = new GoalShareDto();
		good.setRef(1);
		good.setType("SKILL");
		good.setName("Cooking - Level 50");
		good.setSkillName("COOKING");
		good.setTargetValue(101_333);

		ShareBundle bundle = new ShareBundle();
		bundle.setKind(ShareBundle.Kind.GOALS);
		bundle.setGoals(Arrays.asList(bad, good));

		api.importShareBundle(bundle);

		assertEquals(1, store.getGoals().size());
		assertEquals("Cooking - Level 50", store.getGoals().get(0).getName());
	}

	@Test
	void roundTripsFromRealGoalsViaMapperAndCodec()
	{
		Tag inferno = Tag.builder()
			.id("t1").label("Inferno").category(TagCategory.OTHER).colorRgb(0xAA3322).build();
		Map<String, Tag> tags = Collections.singletonMap("t1", inferno);

		Goal ranged = Goal.builder().id("a").type(GoalType.SKILL).name("Ranged")
			.skillName("RANGED").targetValue(1_210_421)
			.tagIds(Collections.singletonList("t1")).build();
		Goal zuk = Goal.builder().id("b").type(GoalType.BOSS).name("TzKal-Zuk")
			.bossName("TzKal-Zuk").targetValue(1)
			.requiredGoalIds(Collections.singletonList("a")).build();

		ShareBundle bundle = ShareMapper.toBundle(
			ShareBundle.Kind.SECTION, "Inferno Prep", -1,
			Arrays.asList(ranged, zuk), tags::get, "Andrew");

		ShareCodec codec = new ShareCodec(new Gson());
		api.importShareBundle(codec.decode(codec.encode(bundle)));

		assertEquals(2, store.getGoals().size());
		Goal importedRanged = goalNamed("Ranged");
		Goal importedZuk = goalNamed("TzKal-Zuk");
		assertTrue(importedZuk.getRequiredGoalIds().contains(importedRanged.getId()));
	}

	@Test
	void ignoresNullOrEmptyBundle()
	{
		assertNull(api.importShareBundle(null));
		ShareBundle empty = new ShareBundle();
		empty.setKind(ShareBundle.Kind.GOALS);
		assertNull(api.importShareBundle(empty));
		assertEquals(0, store.getGoals().size());
	}

	@Test
	void looseGoalsImportIntoANewUserSectionStartingIncomplete()
	{
		GoalShareDto g = new GoalShareDto();
		g.setRef(0);
		g.setType("SKILL");
		g.setName("Cooking - Level 50");
		g.setSkillName("COOKING");
		g.setTargetValue(101_333);
		ShareBundle bundle = new ShareBundle();
		bundle.setKind(ShareBundle.Kind.GOALS);
		bundle.setGoals(java.util.Collections.singletonList(g));

		String landedSectionId = api.importShareBundle(bundle);

		// A loose selection lands in its own NEW user section (not Incomplete),
		// so the recipient sees it as a checklist against their account.
		assertNotEquals(store.getIncompleteSection().getId(), landedSectionId);
		Section landed = store.findSection(landedSectionId);
		assertNotNull(landed);
		assertFalse(landed.isBuiltIn());

		Goal imported = goalNamed("Cooking - Level 50");
		assertEquals(landedSectionId, imported.getSectionId());
		assertFalse(imported.isComplete());
		assertEquals(0, imported.getCurrentValue());
	}

	@Test
	void longSectionNameStillImports()
	{
		// A section name longer than the 40-char cap must be clamped, not rejected
		// (createUserSection THROWS on over-length names and CommandHistory swallows
		// it, silently failing the whole import).
		GoalShareDto g = new GoalShareDto();
		g.setRef(0);
		g.setType("SKILL");
		g.setName("Ranged");
		g.setSkillName("RANGED");
		g.setTargetValue(1_210_421);

		ShareBundle bundle = new ShareBundle();
		bundle.setKind(ShareBundle.Kind.SECTION);
		bundle.setSectionName("A really long shared section name that exceeds the cap"); // 53 chars
		bundle.setGoals(java.util.Collections.singletonList(g));

		String sectionId = api.importShareBundle(bundle);

		assertNotNull(sectionId, "long section name must not silently fail the import");
		Section section = store.getSections().stream()
			.filter(s -> sectionId.equals(s.getId())).findFirst().orElseThrow();
		assertTrue(section.getName().length() <= 40);
		assertEquals(1, store.getGoals().size());
	}
}

package com.goalplanner.api;

import com.goalplanner.data.WikiCaRepository;
import com.goalplanner.model.Goal;
import com.goalplanner.model.GoalType;
import com.goalplanner.model.Section;
import com.goalplanner.persistence.GoalStore;
import com.goalplanner.service.GoalReorderingService;
import com.goalplanner.share.GoalShareDto;
import com.goalplanner.share.SectionShareDto;
import com.goalplanner.share.ShareBundle;
import com.goalplanner.testsupport.InMemoryConfigManager;
import com.google.gson.Gson;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.stream.Collectors;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

/**
 * Schema-v2 import behaviour: multiple sections from one bundle, and
 * default-target sections that REUSE existing equivalents instead of
 * duplicating. Real {@link GoalStore} per the stateful-store testing rule.
 */
class ShareImportV2Test
{
	private GoalStore store;
	private GoalPlannerApiImpl api;

	@BeforeEach
	void setUp()
	{
		ConfigManager configManager = InMemoryConfigManager.create();
		store = new GoalStore(configManager, new Gson());
		store.load();

		ItemManager itemManager = mock(ItemManager.class);
		WikiCaRepository wikiCaRepository = mock(WikiCaRepository.class);
		GoalReorderingService reorderingService = new GoalReorderingService(store);
		api = new GoalPlannerApiImpl(store, reorderingService, itemManager, wikiCaRepository);
		api.setOnGoalsChanged(() -> {});
	}

	private static GoalShareDto skillDto(int ref, String name, String skill, int xp)
	{
		GoalShareDto dto = new GoalShareDto();
		dto.setRef(ref);
		dto.setType("SKILL");
		dto.setName(name);
		dto.setSkillName(skill);
		dto.setTargetValue(xp);
		return dto;
	}

	private static GoalShareDto bossDto(int ref, String bossName, int kc, Integer requiresRef)
	{
		GoalShareDto dto = new GoalShareDto();
		dto.setRef(ref);
		dto.setType("BOSS");
		dto.setName(bossName);
		dto.setBossName(bossName);
		dto.setTargetValue(kc);
		if (requiresRef != null)
		{
			dto.setRequires(Collections.singletonList(requiresRef));
		}
		return dto;
	}

	private static SectionShareDto section(String name, boolean targetDefault, GoalShareDto... goals)
	{
		SectionShareDto s = new SectionShareDto();
		s.setName(name);
		s.setTargetDefault(targetDefault);
		s.setGoals(Arrays.asList(goals));
		return s;
	}

	private static ShareBundle v2Bundle(String sharedBy, SectionShareDto... sections)
	{
		ShareBundle bundle = new ShareBundle();
		bundle.setSharedBy(sharedBy);
		bundle.setSections(Arrays.asList(sections));
		return bundle;
	}

	private List<Goal> goalsInSection(String sectionId)
	{
		return store.getGoals().stream()
			.filter(g -> sectionId.equals(g.getSectionId()))
			.collect(Collectors.toList());
	}

	private List<Section> userSections()
	{
		return store.getSections().stream()
			.filter(s -> !s.isBuiltIn())
			.collect(Collectors.toList());
	}

	@Test
	@DisplayName("v2 item goal keeps its system BOSS source tag, visible on the card")
	void v2ImportAppliesItemSourceTag()
	{
		// Mirror an MCP source-tagged item goal: ITEM_GRIND + a system BOSS tag,
		// in a multi-section (v2) bundle - the combination the in-app tests missed.
		com.goalplanner.share.TagShareDto cerb = new com.goalplanner.share.TagShareDto();
		cerb.setLabel("Cerberus");
		cerb.setCategory("BOSS");
		cerb.setColorRgb(-1);
		cerb.setSystem(true);

		GoalShareDto peg = new GoalShareDto();
		peg.setRef(0);
		peg.setType("ITEM_GRIND");
		peg.setName("Pegasian crystal");
		peg.setItemId(13227);
		peg.setTargetValue(1);
		peg.setTags(Collections.singletonList(cerb));

		String sectionId = api.importShareBundle(v2Bundle("Tag Test", section("Cerberus", false, peg)));
		assertNotNull(sectionId);

		Goal g = goalsInSection(sectionId).stream()
			.filter(x -> "Pegasian crystal".equals(x.getName())).findFirst().orElseThrow();

		// Model: tag find-or-created as a system BOSS tag and attached.
		assertEquals(1, g.getTagIds().size(), "item goal should carry its source tag");
		com.goalplanner.model.Tag tag = store.findTag(g.getTagIds().get(0));
		assertNotNull(tag);
		assertEquals("Cerberus", tag.getLabel());
		assertEquals(com.goalplanner.model.TagCategory.BOSS, tag.getCategory());

		// Render path: the tag surfaces in the card's render lists (customTags,
		// since import sets tagIds but not defaultTagIds).
		GoalView gv = api.queryGoalView(g.getId());
		assertNotNull(gv);
		boolean shown =
			(gv.defaultTags != null && gv.defaultTags.stream().anyMatch(t -> "Cerberus".equals(t.label)))
			|| (gv.customTags != null && gv.customTags.stream().anyMatch(t -> "Cerberus".equals(t.label)));
		assertTrue(shown, "Cerberus source tag should appear on the imported card");
	}

	@Test
	@DisplayName("imported QUEST and BOSS goals get enriched icon fields the wire omits")
	void importEnrichesQuestAndBossIcons()
	{
		GoalShareDto quest = new GoalShareDto();
		quest.setRef(0);
		quest.setType("QUEST");
		quest.setName("Dragon Slayer II");
		quest.setQuestName("Dragon Slayer II");

		ShareBundle bundle = v2Bundle("Andrew",
			section("Quests", false, quest),
			section("Bossing", false, bossDto(0, "Zulrah", 100, null)));

		String firstSection = api.importShareBundle(bundle);
		assertNotNull(firstSection);

		Goal q = store.getGoals().stream()
			.filter(g -> g.getType() == GoalType.QUEST).findFirst().orElseThrow();
		assertEquals(GoalPlannerApiImpl.QUEST_SPRITE_ID, q.getSpriteId(),
			"a QUEST goal with no wire sprite should get the quest journal sprite");

		Goal boss = store.getGoals().stream()
			.filter(g -> g.getType() == GoalType.BOSS).findFirst().orElseThrow();
		assertEquals(com.goalplanner.data.BossKillData.getPetItemId("Zulrah"), boss.getItemId(),
			"a BOSS goal with no wire item should get its pet item id for the card icon");
		assertTrue(boss.getItemId() > 0, "Zulrah should resolve to a real pet item id");
	}

	@Test
	@DisplayName("import carries a section's nested-view preference")
	void importCarriesNestedOverride()
	{
		SectionShareDto sec = section("Tree", false, skillDto(0, "Attack 90", "ATTACK", 5_346_332));
		sec.setNestedOverride(Boolean.TRUE);
		String landed = api.importShareBundle(v2Bundle("Andrew", sec));

		assertNotNull(landed);
		Section created = userSections().get(0);
		assertEquals(Boolean.TRUE, created.getNestedOverride());
	}

	@Test
	@DisplayName("a multi-section bundle imports each section as its own user section")
	void multiSectionImportsEachSection()
	{
		ShareBundle bundle = v2Bundle("Andrew",
			section("Slayer", false, skillDto(0, "Slayer 93", "SLAYER", 7_195_629)),
			section("Raids", false,
				skillDto(0, "Ranged 90", "RANGED", 5_346_332),
				bossDto(1, "TzKal-Zuk", 1, 0)));

		String landed = api.importShareBundle(bundle);

		assertNotNull(landed);
		List<Section> created = userSections();
		assertEquals(2, created.size());
		assertEquals("Slayer", created.get(0).getName());
		assertEquals("Raids", created.get(1).getName());
		assertEquals(1, goalsInSection(created.get(0).getId()).size());

		List<Goal> raids = goalsInSection(created.get(1).getId());
		assertEquals(2, raids.size());
		Goal zuk = raids.stream().filter(g -> g.getType() == GoalType.BOSS).findFirst().orElseThrow();
		Goal ranged = raids.stream().filter(g -> g.getType() == GoalType.SKILL).findFirst().orElseThrow();
		assertEquals(Collections.singletonList(ranged.getId()), zuk.getRequiredGoalIds());
	}

	@Test
	@DisplayName("relation refs are scoped per section — same ref index in two sections never cross-wires")
	void refsAreSectionScoped()
	{
		ShareBundle bundle = v2Bundle(null,
			section("A", false, skillDto(0, "Attack 99", "ATTACK", 13_034_431)),
			section("B", false, bossDto(0, "Zulrah", 100, null)));

		api.importShareBundle(bundle);

		for (Goal g : store.getGoals())
		{
			if (g.getType() == GoalType.BOSS)
			{
				assertTrue(g.getRequiredGoalIds().isEmpty(),
					"ref 0 in section B must not link to ref 0 of section A");
			}
		}
	}

	@Test
	@DisplayName("a default-target section lands goals in the Incomplete built-in, not a new section")
	void defaultTargetLandsInDefaultPlan()
	{
		ShareBundle bundle = v2Bundle("Andrew",
			section(null, true, skillDto(0, "Mining 99", "MINING", 13_034_431)));

		String landed = api.importShareBundle(bundle);

		assertEquals(store.getIncompleteSection().getId(), landed);
		assertTrue(userSections().isEmpty(), "no user section should be created");
		assertEquals(1, goalsInSection(store.getIncompleteSection().getId()).size());
