		bundle.setKind(ShareBundle.Kind.SECTION);
		bundle.setSectionName("Inferno Prep");
		bundle.setSharedBy("Andrew");
		bundle.setGoals(Arrays.asList(
			skillDto(0, "Ranged 90", "RANGED", 5_346_332),
			bossDto(1, "TzKal-Zuk", 1, 0)));

		String landed = api.importShareBundle(bundle);

		assertNotNull(landed);
		assertEquals(1, userSections().size());
		assertEquals("Inferno Prep", userSections().get(0).getName());
		assertEquals(2, goalsInSection(landed).size());
	}

	@org.junit.jupiter.api.Test
	@org.junit.jupiter.api.DisplayName("an imported section keeps its completed goals inline - it is a checklist")
	void importedSectionKeepsCompletedInline()
	{
		com.goalplanner.share.ShareBundle bundle = new com.goalplanner.share.ShareBundle();
		com.goalplanner.share.SectionShareDto sec = new com.goalplanner.share.SectionShareDto();
		sec.setName("Imported");
		com.goalplanner.share.GoalShareDto dto = new com.goalplanner.share.GoalShareDto();
		dto.setRef(0);
		dto.setType("QUEST");
		dto.setName("Bone Voyage");
		dto.setQuestName("BONE_VOYAGE");
		dto.setTargetValue(1);
		sec.setGoals(java.util.List.of(dto));
		bundle.setSections(java.util.List.of(sec));
		bundle.setV(com.goalplanner.share.ShareBundle.SCHEMA_VERSION);

		api.importShareBundle(bundle);
		com.goalplanner.model.Goal imported = store.getGoals().stream()
			.filter(g -> "Bone Voyage".equals(g.getName())).findFirst().orElseThrow();

		// The recipient has the quest done: first tracker read completes it.
		api.recordGoalProgress(imported.getId(), 1);
		store.reconcileDerivedSections();

		// DELIBERATE (ShareImportService sets autoArchiveOverride=false on the
		// new section): the recipient sees the shared set as a checklist, with
		// what they have already done ticked in place - even when the global
		// auto-archive default is on. First surprised a user during 0.5.0
		// stress testing; pinned here so the next surprise reads this instead.
		org.junit.jupiter.api.Assertions.assertNotEquals(
			store.getCompletedSection().getId(), imported.getSectionId(),
			"imported sections keep completed goals inline by design");
		org.junit.jupiter.api.Assertions.assertTrue(imported.isComplete());
	}
}

package com.goalplanner.command;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import java.util.ArrayList;
import java.util.List;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Unit tests for {@link CommandHistory}.
 *
 * <p>Uses a tiny stub Command that pushes/pops to a shared list so we can
 * verify exactly which commands ran (and in which direction) without
 * touching the real GoalStore.
 */
class CommandHistoryTest
{
	private CommandHistory history;
	/** Trace of "apply:N" / "revert:N" calls in the order they happened. */
	private List<String> trace;

	@BeforeEach
	void setUp()
	{
		history = new CommandHistory();
		trace = new ArrayList<>();
	}

	private Command stubCmd(int id)
	{
		return new Command()
		{
			@Override public boolean apply() { trace.add("apply:" + id); return true; }
			@Override public boolean revert() { trace.add("revert:" + id); return true; }
			@Override public String getDescription() { return "cmd-" + id; }
		};
	}

	private Command failingApply(int id)
	{
		return new Command()
		{
			@Override public boolean apply() { trace.add("apply:" + id); return false; }
			@Override public boolean revert() { trace.add("revert:" + id); return true; }
			@Override public String getDescription() { return "cmd-" + id; }
		};
	}

	private Command failingRevert(int id)
	{
		return new Command()
		{
			@Override public boolean apply() { trace.add("apply:" + id); return true; }
			@Override public boolean revert() { trace.add("revert:" + id); return false; }
			@Override public String getDescription() { return "cmd-" + id; }
		};
	}

	private Command throwingRevert(int id)
	{
		return new Command()
		{
			@Override public boolean apply() { trace.add("apply:" + id); return true; }
			@Override public boolean revert() { throw new RuntimeException("boom"); }
			@Override public String getDescription() { return "cmd-" + id; }
		};
	}

	@Test
	@DisplayName("execute runs apply and pushes onto undo stack")
	void executePushes()
	{
		assertTrue(history.execute(stubCmd(1)));
		assertEquals(List.of("apply:1"), trace);
		assertTrue(history.canUndo());
		assertFalse(history.canRedo());
		assertEquals("cmd-1", history.peekUndoDescription());
	}

	@Test
	@DisplayName("undo pops the most recent entry and reverts it, moving to redo stack")
	void undoMovesToRedo()
	{
		history.execute(stubCmd(1));
		history.execute(stubCmd(2));
		assertTrue(history.undo());
		assertEquals(List.of("apply:1", "apply:2", "revert:2"), trace);
		assertTrue(history.canUndo());
		assertTrue(history.canRedo());
		assertEquals("cmd-1", history.peekUndoDescription());
		assertEquals("cmd-2", history.peekRedoDescription());
	}

	@Test
	@DisplayName("redo re-applies the entry and moves it back to undo stack")
	void redoMovesBack()
	{
		history.execute(stubCmd(1));
		history.undo();
		assertTrue(history.redo());
		assertEquals(List.of("apply:1", "revert:1", "apply:1"), trace);
		assertTrue(history.canUndo());
		assertFalse(history.canRedo());
	}

	@Test
	@DisplayName("a new execute clears the redo stack (forking history)")
	void newExecuteClearsRedo()
	{
		history.execute(stubCmd(1));
		history.execute(stubCmd(2));
		history.undo(); // 2 → redo
		assertTrue(history.canRedo());
		history.execute(stubCmd(3)); // forks: redo cleared
		assertFalse(history.canRedo());
	}

	@Test
	@DisplayName("undo on empty stack returns false")
	void emptyUndo()
	{
		assertFalse(history.undo());
	}

	@Test
	@DisplayName("redo on empty stack returns false")
	void emptyRedo()
	{
		assertFalse(history.redo());
	}

	@Test
	@DisplayName("execute returning false (no-op) is not pushed onto the stack")
	void failingApplyNotPushed()
	{
		assertFalse(history.execute(failingApply(1)));
		assertFalse(history.canUndo());
	}

	@Test
	@DisplayName("undo with failing revert drops the entry and returns false")
	void failingRevertDropped()
	{
		history.execute(stubCmd(1));
		history.execute(failingRevert(2));
		assertFalse(history.undo()); // revert returned false
		// Entry 2 dropped — undo stack now has 1 only, redo empty
		assertEquals(1, history.undoSize());
		assertEquals(0, history.redoSize());
	}

	@Test
	@DisplayName("undo with throwing revert drops the entry and returns false")
	void throwingRevertDropped()
	{
		history.execute(stubCmd(1));
		history.execute(throwingRevert(2));
		assertFalse(history.undo());
		assertEquals(1, history.undoSize());
		assertEquals(0, history.redoSize());
	}

	@Test
	@DisplayName("undo stack is bounded at CAP entries — oldest are trimmed")
	void capTrim()
	{
		for (int i = 0; i < CommandHistory.CAP + 5; i++)
		{
			history.execute(stubCmd(i));
		}
		assertEquals(CommandHistory.CAP, history.undoSize());
	}

	@Test
	@DisplayName("clear wipes both stacks")
	void clearWipes()
	{
		history.execute(stubCmd(1));
		history.execute(stubCmd(2));
		history.undo();
		history.clear();
		assertFalse(history.canUndo());
		assertFalse(history.canRedo());
	}

	@Test
	@DisplayName("multi-step undo/redo round-trip preserves order")
	void roundTrip()
	{
		history.execute(stubCmd(1));
		history.execute(stubCmd(2));
		history.execute(stubCmd(3));
		history.undo();
		history.undo();
		history.redo();
		// Sequence: apply 1,2,3 → revert 3, revert 2 → apply 2
		assertEquals(List.of("apply:1", "apply:2", "apply:3",
			"revert:3", "revert:2", "apply:2"), trace);
		assertTrue(history.canUndo()); // 1, 2 remain
		assertTrue(history.canRedo()); // 3 in redo
	}

	// ====================================================================
	// Compound commands
	// ====================================================================

	@Test
	@DisplayName("compound: multiple executes between begin/end land as a single undo entry")
	void compoundCollapsesToOne()
	{
		history.beginCompound("batch");
		history.execute(stubCmd(1));
		history.execute(stubCmd(2));
		history.execute(stubCmd(3));
		history.endCompound();
		assertEquals(1, history.undoSize());
		assertEquals("batch", history.peekUndoDescription());
	}

	@Test
	@DisplayName("compound: undo reverts all sub-commands in reverse order")
	void compoundUndoReversesOrder()
	{
		history.beginCompound("batch");
		history.execute(stubCmd(1));
		history.execute(stubCmd(2));
		history.execute(stubCmd(3));
		history.endCompound();
		history.undo();
		// applies in 1,2,3, reverts in 3,2,1
		assertEquals(List.of("apply:1", "apply:2", "apply:3",
			"revert:3", "revert:2", "revert:1"), trace);
	}

	@Test
	@DisplayName("compound: redo re-applies all sub-commands in original order")
	void compoundRedoReplaysOrder()
	{
		history.beginCompound("batch");
		history.execute(stubCmd(1));
		history.execute(stubCmd(2));
		history.endCompound();
		history.undo();
		trace.clear();
		history.redo();
		assertEquals(List.of("apply:1", "apply:2"), trace);
	}

	@Test
	@DisplayName("compound: empty compound is a no-op")
	void compoundEmptyNoop()
	{
		history.beginCompound("nothing");
		history.endCompound();
		assertFalse(history.canUndo());
	}

	@Test
	@DisplayName("compound: nested begin/endCompound is ref-counted — inner end does not close outer")
	void compoundNestedRefCounted()
	{
		history.beginCompound("outer");
		history.execute(stubCmd(1));
		history.beginCompound("inner"); // bumps depth, buffer stays the same
		history.execute(stubCmd(2));
		history.endCompound(); // decrements depth, does NOT close
		assertTrue(history.isInCompound(), "outer compound should still be active");
		assertEquals(0, history.undoSize(), "nothing pushed to undo yet — compound is open");

		history.endCompound(); // now the outer closes
		assertFalse(history.isInCompound());
		assertEquals(1, history.undoSize());
		assertEquals("outer", history.peekUndoDescription());
	}

	@Test
	@DisplayName("compound: regular execute outside any compound still works normally")
	void compoundDoesNotLeak()
	{
		history.beginCompound("batch");
		history.execute(stubCmd(1));
		history.endCompound();
		history.execute(stubCmd(2)); // outside compound
		assertEquals(2, history.undoSize());
	}
}

package com.goalplanner.command;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import java.util.ArrayList;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

@DisplayName("SaveBatchingCommand")
class SaveBatchingCommandTest
{
	/** Records the call order of begin/end/apply/revert. */
	private static final class Trace
	{
		final List<String> log = new ArrayList<>();
	}

	private static Command tracingInner(Trace t, boolean applyResult)
	{
		return new Command()
		{
			@Override public boolean apply() { t.log.add("apply"); return applyResult; }
			@Override public boolean revert() { t.log.add("revert"); return true; }
			@Override public String getDescription() { return "inner"; }
		};
	}

	@Test
	@DisplayName("brackets apply with begin/end and returns the inner result")
	void bracketsApply()
	{
		Trace t = new Trace();
		Command cmd = new SaveBatchingCommand(
			() -> t.log.add("begin"), () -> t.log.add("end"), tracingInner(t, true));

		assertTrue(cmd.apply());
		assertEquals(List.of("begin", "apply", "end"), t.log);
	}

	@Test
	@DisplayName("brackets revert with begin/end")
	void bracketsRevert()
	{
		Trace t = new Trace();
		Command cmd = new SaveBatchingCommand(
			() -> t.log.add("begin"), () -> t.log.add("end"), tracingInner(t, true));

		assertTrue(cmd.revert());
		assertEquals(List.of("begin", "revert", "end"), t.log);
	}

	@Test
	@DisplayName("runs end even when the inner command throws (no stuck suspend)")
	void endRunsOnThrow()
	{
		Trace t = new Trace();
		Command throwing = new Command()
		{
			@Override public boolean apply() { t.log.add("apply"); throw new RuntimeException("boom"); }
			@Override public boolean revert() { return true; }
			@Override public String getDescription() { return "boom"; }
		};
		Command cmd = new SaveBatchingCommand(
			() -> t.log.add("begin"), () -> t.log.add("end"), throwing);

		assertThrows(RuntimeException.class, cmd::apply);
		assertEquals(List.of("begin", "apply", "end"), t.log);
	}

	@Test
	@DisplayName("delegates description to the inner command")
	void delegatesDescription()
	{
		Command cmd = new SaveBatchingCommand(() -> {}, () -> {}, tracingInner(new Trace(), true));
		assertEquals("inner", cmd.getDescription());
	}
}

package com.goalplanner.data;

import net.runelite.api.gameval.VarbitID;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;

import java.util.HashMap;
import java.util.Map;
import java.util.function.IntUnaryOperator;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Tests for the {@link AchievementDiaryData} tier-count helpers used by
 * the DIARY_TIERS_COMPLETED account metric.
 */
class AchievementDiaryDataTest
{
	/** Varbit reader backed by a plain map; unset varbits read 0. */
	private static IntUnaryOperator reader(Map<Integer, Integer> varbits)
	{
		return id -> varbits.getOrDefault(id, 0);
	}

	@Nested
	@DisplayName("Tier enumeration")
	class TierEnumeration
	{
		@Test
		@DisplayName("covers exactly 48 tiers (12 areas x 4 tiers)")
		void totalTierCount()
		{
			assertEquals(48, AchievementDiaryData.TOTAL_TIER_COUNT);
			assertEquals(12, AchievementDiaryData.AREA_KEYS.length);
		}

		@Test
		@DisplayName("every area/tier pair resolves a tracking spec")
		void everyPairHasTracking()
		{
			for (String area : AchievementDiaryData.AREA_KEYS)
			{
				for (AchievementDiaryData.Tier tier : AchievementDiaryData.Tier.values())
				{
					assertNotNull(AchievementDiaryData.tracking(area, tier),
						"missing tracking for " + area + " " + tier);
				}
			}
		}
	}

	@Nested
	@DisplayName("countCompletedTiers")
	class CountCompletedTiers
	{
		@Test
		@DisplayName("returns 0 when no varbits are set")
		void zeroWhenNothingSet()
		{
			assertEquals(0, AchievementDiaryData.countCompletedTiers(reader(new HashMap<>())));
		}

		@Test
		@DisplayName("counts boolean COMPLETE varbits set to 1")
		void countsBooleanCompletes()
		{
			Map<Integer, Integer> varbits = new HashMap<>();
			varbits.put(VarbitID.ARDOUGNE_DIARY_EASY_COMPLETE, 1);
			varbits.put(VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE, 1);
			varbits.put(VarbitID.WILDERNESS_DIARY_HARD_COMPLETE, 1);

			assertEquals(3, AchievementDiaryData.countCompletedTiers(reader(varbits)));
		}

		@Test
		@DisplayName("counts Karamja count varbits only at or above the tier task total")
		void countsKaramjaByTaskTotal()
		{
			Map<Integer, Integer> varbits = new HashMap<>();
			varbits.put(VarbitID.KARAMJA_EASY_COUNT, 10);  // complete (10 tasks)
			varbits.put(VarbitID.KARAMJA_MED_COUNT, 18);   // 18/19 — incomplete
			varbits.put(VarbitID.KARAMJA_HARD_COUNT, 10);  // complete (10 tasks)

			assertEquals(2, AchievementDiaryData.countCompletedTiers(reader(varbits)));
		}

		@Test
		@DisplayName("counts all 48 tiers when every tracking varbit is at its required value")
		void countsAllTiers()
		{
			Map<Integer, Integer> varbits = new HashMap<>();
			for (String area : AchievementDiaryData.AREA_KEYS)
			{
				for (AchievementDiaryData.Tier tier : AchievementDiaryData.Tier.values())
				{
					AchievementDiaryData.Tracking t = AchievementDiaryData.tracking(area, tier);
					varbits.put(t.varbitId, t.requiredValue);
				}
			}

			assertEquals(AchievementDiaryData.TOTAL_TIER_COUNT,
				AchievementDiaryData.countCompletedTiers(reader(varbits)));
		}

		@Test
		@DisplayName("ignores stray varbit values below the required completion value")
		void ignoresBelowRequired()
		{
			Map<Integer, Integer> varbits = new HashMap<>();
			// Boolean COMPLETE varbits are 0/1; 0 stays incomplete.
			varbits.put(VarbitID.DESERT_DIARY_MEDIUM_COMPLETE, 0);
			varbits.put(VarbitID.KARAMJA_MED_COUNT, 5);

			assertEquals(0, AchievementDiaryData.countCompletedTiers(reader(varbits)));
		}
	}
}

package com.goalplanner.data;

import com.goalplanner.api.GoalPlannerApiImpl;
import com.goalplanner.data.BossKillData.Alternative;
import com.goalplanner.data.BossKillData.BossPrereqs;
import com.goalplanner.data.BossKillData.BossReq;
import com.goalplanner.data.BossKillData.SkillReq;
import com.goalplanner.model.Goal;
import com.goalplanner.model.GoalType;
import com.goalplanner.persistence.GoalStore;
import com.goalplanner.service.GoalReorderingService;
import com.goalplanner.testsupport.InMemoryConfigManager;
import com.goalplanner.testsupport.MockClientFactory;
import com.goalplanner.testsupport.MockGameState;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.Experience;
import net.runelite.api.Skill;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.mock;

/**
 * End-to-end test that {@code addBossGoal} seeds
 * {@link BossPrereqs#alternatives} as OR-prereqs on the boss goal,
 * mirroring the diary-unlock alternative path.
 *
 * <p>No production boss currently carries alternatives, so this test
 * swaps in a synthetic {@link BossPrereqs} for an existing boss via the
 * package-private {@link BossKillData#swapPrereqsForTest} hook and
 * restores the original in {@link #restoreOriginal} after each test.
 */
class BossAlternativeSeedingTest
{
	/** Target boss name used for swapping — picks a simple entry. */
	private static final String BOSS = "Zulrah";

	private GoalStore store;
	private GoalPlannerApiImpl api;
	private BossPrereqs originalPrereqs;

	@BeforeEach
	void setUp()
	{
		ConfigManager configManager = InMemoryConfigManager.create();
		store = new GoalStore(configManager, new com.google.gson.Gson());
		store.load();

		MockGameState freshState = new MockGameState();
		Client client = MockClientFactory.createClient(freshState);

		ItemManager itemManager = mock(ItemManager.class);
		WikiCaRepository wikiCaRepository = mock(WikiCaRepository.class);
		GoalReorderingService reorderingService = new GoalReorderingService(store);
		api = new GoalPlannerApiImpl(store, reorderingService, itemManager,
			wikiCaRepository, client);
	}

	@AfterEach
	void restoreOriginal()
	{
		// Always restore so cross-test state doesn't leak.
		BossKillData.swapPrereqsForTest(BOSS, originalPrereqs);
	}

	@Test
	@DisplayName("skill alternatives become OR-prereqs on the boss goal")
	void skillAlternativesBecomeOrPrereqs()
	{
		// Synthetic: BOSS gated by (Attack 99) OR (Strength 99).
		BossPrereqs synthetic = new BossPrereqs(
			List.of(),                // no AND skills
			List.of(),                // no unlocks
			List.of(),                // no AND quests
			List.of(),                // no AND bossKills
			List.of(),                // no itemReqs
			List.of(),                // no accountReqs
			List.of(
				new Alternative("99 Attack",
					List.of(new SkillReq(Skill.ATTACK, 99)),
					List.of()),
				new Alternative("99 Strength",
					List.of(new SkillReq(Skill.STRENGTH, 99)),
					List.of())));
		originalPrereqs = BossKillData.swapPrereqsForTest(BOSS, synthetic);

		String bossId = api.addBossGoal(BOSS, 10);
		assertNotNull(bossId);

		Goal boss = findById(bossId);
		assertNotNull(boss);
		List<String> orIds = boss.getOrRequiredGoalIds();
		assertNotNull(orIds, "boss should have OR-prereqs list");
		assertEquals(2, orIds.size(),
			"both skill alternatives should be linked as OR-prereqs");

		// The OR-children must be SKILL goals at 99.
		for (String id : orIds)
		{
			Goal g = findById(id);
			assertNotNull(g);
			assertEquals(GoalType.SKILL, g.getType());
			assertEquals(Experience.getXpForLevel(99), g.getTargetValue());
		}

		// AND-list should be empty for this synthetic entry.
		assertTrue(boss.getRequiredGoalIds() == null
			|| boss.getRequiredGoalIds().isEmpty(),
			"AND-prereqs should be empty for an alternatives-only entry");
	}

	@Test
	@DisplayName("mixed AND + OR: AND-prereqs stay on requiredGoalIds, alts on orRequiredGoalIds")
	void mixedAndOrSeparation()
	{
		// Synthetic: BOSS gated by (70 Ranged AND (99 Magic OR 99 Attack)).
		BossPrereqs synthetic = new BossPrereqs(
			List.of(new SkillReq(Skill.RANGED, 70)),    // AND
			List.of(), List.of(), List.of(), List.of(), List.of(),
			List.of(
				new Alternative("99 Magic",
					List.of(new SkillReq(Skill.MAGIC, 99)),
					List.of()),
				new Alternative("99 Attack",
					List.of(new SkillReq(Skill.ATTACK, 99)),
					List.of())));
		originalPrereqs = BossKillData.swapPrereqsForTest(BOSS, synthetic);

		String bossId = api.addBossGoal(BOSS, 10);
		Goal boss = findById(bossId);
		assertNotNull(boss);

		assertEquals(1, boss.getRequiredGoalIds().size(),
			"AND-prereqs should only contain the 70 Ranged goal");
		assertEquals(2, boss.getOrRequiredGoalIds().size(),
			"OR-prereqs should contain both alternatives");

		// Sanity: 70 Ranged on AND, 99 Magic / 99 Attack on OR
		Goal andChild = findById(boss.getRequiredGoalIds().get(0));
		assertEquals("RANGED", andChild.getSkillName());
		assertEquals(Experience.getXpForLevel(70), andChild.getTargetValue());
	}

	@Test
	@DisplayName("boss-kill alternatives become OR-prereqs (recursive addBossGoal)")
	void bossKillAlternativesBecomeOrPrereqs()
	{
		// Synthetic: BOSS unlocked by a Vorkath or Vardorvis kill.
		BossPrereqs synthetic = new BossPrereqs(
			List.of(), List.of(), List.of(), List.of(), List.of(), List.of(),
			List.of(
				new Alternative("Vorkath kill",
					List.of(), List.of(),
					List.of(new BossReq("Vorkath", 1))),
				new Alternative("Vardorvis kill",
					List.of(), List.of(),
					List.of(new BossReq("Vardorvis", 1)))));
		originalPrereqs = BossKillData.swapPrereqsForTest(BOSS, synthetic);

		String bossId = api.addBossGoal(BOSS, 10);
		Goal boss = findById(bossId);
		assertNotNull(boss);

		assertEquals(2, boss.getOrRequiredGoalIds().size());
		long bossChildren = boss.getOrRequiredGoalIds().stream()
			.map(this::findById)
			.filter(g -> g != null && g.getType() == GoalType.BOSS)
			.count();
		assertEquals(2, bossChildren,
			"both boss-kill alternatives should be linked as OR-prereq BOSS goals");
	}

	private Goal findById(String id)
	{
		for (Goal g : store.getGoals())
		{
			if (g.getId().equals(id)) return g;
		}
		return null;
	}
}

