	@Nested
	@DisplayName("QuestRequirementResolver.resolve (with injected lookups)")
	class ResolverTests
	{
		/** Default skill-level lookup: player is level 1 in everything. */
		private final ToIntFunction<Skill> NO_SKILLS = s -> 1;
		/** Default quest-state lookup: player has not started any quest. */
		private final Function<Quest, QuestState> NO_QUESTS = q -> QuestState.NOT_STARTED;

		@Test
		@DisplayName("returns an empty Resolved for a quest not in the table")
		void emptyForMissingQuest()
		{
			// null quest → empty resolved
			QuestRequirementResolver.Resolved out =
				QuestRequirementResolver.resolve(null, NO_SKILLS, NO_QUESTS);
			assertTrue(out.isEmpty());
			assertEquals(0, out.templates.size());
			assertEquals(0, out.stubbedQuestPoints);
		}

		@Test
		@DisplayName("skill req already met → skipped, counted (Barcrawl prereq still yields a template)")
		void skillReqAlreadyMet()
		{
			// Player has Agility 50 — HFTD's 35 req is skipped. The
			// Barcrawl miniquest prereq is still produced as a template
			// because NO_QUESTS treats everything as NOT_STARTED.
			Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
			levels.put(Skill.AGILITY, 50);
			ToIntFunction<Skill> skills = s -> levels.getOrDefault(s, 1);

			QuestRequirementResolver.Resolved out =
				QuestRequirementResolver.resolve(Quest.HORROR_FROM_THE_DEEP, skills, NO_QUESTS);

			assertEquals(1, out.skippedSkills);
			assertEquals(0, out.skippedQuests);
			// Barcrawl template + optional combat recommendation.
			assertEquals(2, out.templates.size());
			Goal questT = out.templates.stream()
				.filter(g -> g.getType() == GoalType.QUEST)
				.findFirst().orElseThrow();
			assertEquals("ALFRED_GRIMHANDS_BARCRAWL", questT.getQuestName());
		}

		@Test
		@DisplayName("skill req not yet met → template built with correct XP target")
		void skillReqNotMetYieldsTemplate()
		{
			// Player has Agility 30 — below the 35 requirement. Barcrawl
			// also produces a template (not finished).
			Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
			levels.put(Skill.AGILITY, 30);
			ToIntFunction<Skill> skills = s -> levels.getOrDefault(s, 1);

			QuestRequirementResolver.Resolved out =
				QuestRequirementResolver.resolve(Quest.HORROR_FROM_THE_DEEP, skills, NO_QUESTS);

			// 1 skill + 1 quest prereq + 1 optional combat = 3 templates.
			assertEquals(3, out.templates.size());
			Goal skillT = out.templates.stream()
				.filter(g -> g.getType() == GoalType.SKILL)
				.findFirst().orElseThrow();
			assertEquals("AGILITY", skillT.getSkillName());
			assertEquals(Experience.getXpForLevel(35), skillT.getTargetValue());
			assertEquals(0, out.skippedSkills);
		}

		@Test
		@DisplayName("quest prereq already finished → skipped, counted")
		void questPrereqAlreadyFinished()
		{
			// MM1 requires Tree Gnome Village + Grand Tree. Both done.
			Map<Quest, QuestState> states = new EnumMap<>(Quest.class);
			states.put(Quest.TREE_GNOME_VILLAGE, QuestState.FINISHED);
			states.put(Quest.THE_GRAND_TREE, QuestState.FINISHED);
			Function<Quest, QuestState> quests = q -> states.getOrDefault(q, QuestState.NOT_STARTED);

			QuestRequirementResolver.Resolved out =
				QuestRequirementResolver.resolve(Quest.MONKEY_MADNESS_I, NO_SKILLS, quests);

			// Both quest prereqs skipped; only the optional combat recommendation remains.
			assertEquals(1, out.templates.size());
			assertTrue(out.templates.get(0).isOptional());
			assertEquals(2, out.skippedQuests);
		}

		@Test
		@DisplayName("quest prereq in progress → still seeded as template")
		void questPrereqInProgressYieldsTemplate()
		{
			Map<Quest, QuestState> states = new EnumMap<>(Quest.class);
			states.put(Quest.TREE_GNOME_VILLAGE, QuestState.IN_PROGRESS);
			states.put(Quest.THE_GRAND_TREE, QuestState.NOT_STARTED);
			Function<Quest, QuestState> quests = q -> states.getOrDefault(q, QuestState.NOT_STARTED);

			QuestRequirementResolver.Resolved out =
				QuestRequirementResolver.resolve(Quest.MONKEY_MADNESS_I, NO_SKILLS, quests);

			// 2 quest prereqs + 1 optional combat recommendation.
			assertEquals(3, out.templates.size());
			assertEquals(2, out.templates.stream().filter(g -> g.getType() == GoalType.QUEST).count());
			assertEquals(0, out.skippedQuests);
		}

		@Test
		@DisplayName("combatLevel produces an ACCOUNT goal template")
		void combatLevelProducesAccountGoal()
		{
			// Dream Mentor's only hard gate is 85 Combat. Mark its quest
			// prereqs finished so we can isolate the combat-level template.
			Map<Quest, QuestState> states = new EnumMap<>(Quest.class);
			states.put(Quest.LUNAR_DIPLOMACY, QuestState.FINISHED);
			states.put(Quest.EADGARS_RUSE, QuestState.FINISHED);
			Function<Quest, QuestState> quests = q -> states.getOrDefault(q, QuestState.NOT_STARTED);

			QuestRequirementResolver.Resolved out =
				QuestRequirementResolver.resolve(Quest.DREAM_MENTOR, NO_SKILLS, quests);

			assertEquals(1, out.templates.size());
			assertEquals(GoalType.ACCOUNT, out.templates.get(0).getType());
			assertEquals("COMBAT_LEVEL", out.templates.get(0).getAccountMetric());
			assertEquals(85, out.templates.get(0).getTargetValue());
			assertEquals(85, out.stubbedCombatLevel);
			assertFalse(out.isEmpty());
		}

		@Test
		@DisplayName("questPoints produces an ACCOUNT goal template (DS2 has 200 QP)")
		void questPointsProducesAccountGoal()
		{
			// Mark every quest as finished and every skill high enough
			// so only the QP template remains.
			ToIntFunction<Skill> maxed = s -> 99;
			Function<Quest, QuestState> allFinished = q -> QuestState.FINISHED;

			QuestRequirementResolver.Resolved out =
				QuestRequirementResolver.resolve(Quest.DRAGON_SLAYER_II, maxed, allFinished);

			// QP template + optional combat recommendation.
			assertEquals(2, out.templates.size());
			Goal qpTemplate = out.templates.stream()
				.filter(g -> "QUEST_POINTS".equals(g.getAccountMetric()))
				.findFirst().orElseThrow();
			assertEquals(GoalType.ACCOUNT, qpTemplate.getType());
			assertEquals(200, qpTemplate.getTargetValue());
			assertFalse(qpTemplate.isOptional());
			assertEquals(200, out.stubbedQuestPoints);
			assertFalse(out.isEmpty());
		}

		@Test
		@DisplayName("a met QP requirement is pre-filtered out (5-arg account lookup)")
		void metQuestPointsRequirementSkipped()
		{
			// DS2 needs 200 QP. A player already at 250 QP, everything else met:
			// the QP template must NOT be emitted (it would auto-complete and
			// show as a freshly-seeded completed card — the bug this guards).
			ToIntFunction<Skill> maxed = s -> 99;
			Function<Quest, QuestState> allFinished = q -> QuestState.FINISHED;
			java.util.function.ToIntFunction<com.goalplanner.model.AccountMetric> have250Qp =
				m -> m == com.goalplanner.model.AccountMetric.QUEST_POINTS ? 250 : 0;

			QuestRequirementResolver.Resolved out = QuestRequirementResolver.resolve(
				Quest.DRAGON_SLAYER_II, maxed, allFinished, () -> 126, have250Qp);

			assertTrue(out.templates.stream().noneMatch(g -> "QUEST_POINTS".equals(g.getAccountMetric())),
				"already-met QP requirement should be skipped");
		}

		@Test
		@DisplayName("an unmet QP requirement is still emitted (5-arg account lookup)")
		void unmetQuestPointsRequirementEmitted()
		{
			ToIntFunction<Skill> maxed = s -> 99;
			Function<Quest, QuestState> allFinished = q -> QuestState.FINISHED;
			java.util.function.ToIntFunction<com.goalplanner.model.AccountMetric> have10Qp =
				m -> m == com.goalplanner.model.AccountMetric.QUEST_POINTS ? 10 : 0;

			QuestRequirementResolver.Resolved out = QuestRequirementResolver.resolve(
				Quest.DRAGON_SLAYER_II, maxed, allFinished, () -> 126, have10Qp);

			assertTrue(out.templates.stream().anyMatch(g ->
					"QUEST_POINTS".equals(g.getAccountMetric()) && g.getTargetValue() == 200),
				"unmet QP requirement should still be emitted");
		}

		@Test
		@DisplayName("null quest-state lookup result is treated as NOT_STARTED")
		void nullStateIsNotStarted()
		{
			Function<Quest, QuestState> quests = q -> null;

			QuestRequirementResolver.Resolved out =
				QuestRequirementResolver.resolve(Quest.MONKEY_MADNESS_I, NO_SKILLS, quests);

			// Both prereqs treated as unfinished + optional combat = 3 templates.
			assertEquals(3, out.templates.size());
			assertEquals(0, out.skippedQuests);
		}

		@Test
		@DisplayName("exception from quest-state lookup is treated as NOT_STARTED")
		void exceptionFromLookupIsNotStarted()
		{
			Function<Quest, QuestState> quests = q ->
			{
				throw new RuntimeException("varp blew up");
			};

			QuestRequirementResolver.Resolved out =
				QuestRequirementResolver.resolve(Quest.MONKEY_MADNESS_I, NO_SKILLS, quests);

			assertEquals(3, out.templates.size());
		}

		@Test
		@DisplayName("recommended combat already met → template NOT emitted (regression: pre-completed cards)")
		void recommendedCombatAlreadyMet()
		{
			// DS2 recommends 100 Combat. Player is at 110 — recommendation
			// should be pre-filtered out, not seeded as a pre-completed
			// card. Mark all skills/quests as met so only the QP template
			// is expected (no combat recommendation).
			ToIntFunction<Skill> maxed = s -> 99;
			Function<Quest, QuestState> allFinished = q -> QuestState.FINISHED;
			java.util.function.IntSupplier combat110 = () -> 110;

			QuestRequirementResolver.Resolved out =
				QuestRequirementResolver.resolve(Quest.DRAGON_SLAYER_II,
					maxed, allFinished, combat110);

			// Only the QP template; the recommended combat should be absent.
			assertEquals(1, out.templates.size());
			assertEquals("QUEST_POINTS", out.templates.get(0).getAccountMetric());
			assertTrue(out.templates.stream()
				.noneMatch(g -> "COMBAT_LEVEL".equals(g.getAccountMetric())
					&& g.isOptional()),
				"optional recommended combat template should not be emitted when already met");
		}

		@Test
		@DisplayName("recommended combat not yet met → template IS emitted")
		void recommendedCombatNotMet()
		{
			ToIntFunction<Skill> maxed = s -> 99;
			Function<Quest, QuestState> allFinished = q -> QuestState.FINISHED;
			java.util.function.IntSupplier combat80 = () -> 80;

			QuestRequirementResolver.Resolved out =
				QuestRequirementResolver.resolve(Quest.DRAGON_SLAYER_II,
					maxed, allFinished, combat80);

			// QP template + recommended combat template (player is below 100).
			assertEquals(2, out.templates.size());
			Goal combatT = out.templates.stream()
				.filter(g -> "COMBAT_LEVEL".equals(g.getAccountMetric()))
				.findFirst().orElseThrow();
			assertTrue(combatT.isOptional(), "recommendation is always optional");
			assertEquals(100, combatT.getTargetValue());
		}

		@Test
		@DisplayName("recommended combat exactly at threshold (equal) → template NOT emitted")
		void recommendedCombatExactlyAtThreshold()
		{
			ToIntFunction<Skill> maxed = s -> 99;
			Function<Quest, QuestState> allFinished = q -> QuestState.FINISHED;
			java.util.function.IntSupplier combat100 = () -> 100;

			QuestRequirementResolver.Resolved out =
				QuestRequirementResolver.resolve(Quest.DRAGON_SLAYER_II,
					maxed, allFinished, combat100);

			// QP template only — 100 >= 100 means recommendation is met.
			assertTrue(out.templates.stream()
				.noneMatch(g -> "COMBAT_LEVEL".equals(g.getAccountMetric())
					&& g.isOptional()),
				"recommendation met at exact threshold should not be emitted");
		}

		@Test
		@DisplayName("hard combat req takes precedence even when player exceeds it")
		void hardCombatReqAlwaysEmitted()
		{
			// Dream Mentor has a HARD 85 combat req (not recommended).
			// Hard reqs always emit — the bug fix only affects the
			// RECOMMENDED path.
			Map<Quest, QuestState> states = new EnumMap<>(Quest.class);
			states.put(Quest.LUNAR_DIPLOMACY, QuestState.FINISHED);
			states.put(Quest.EADGARS_RUSE, QuestState.FINISHED);
			Function<Quest, QuestState> quests = q -> states.getOrDefault(q, QuestState.NOT_STARTED);
			java.util.function.IntSupplier combat126 = () -> 126;

			QuestRequirementResolver.Resolved out =
				QuestRequirementResolver.resolve(Quest.DREAM_MENTOR,
					NO_SKILLS, quests, combat126);

			// Hard combat template still present despite player being at 126.
			assertEquals(1, out.templates.size());
			Goal hard = out.templates.get(0);
			assertEquals("COMBAT_LEVEL", hard.getAccountMetric());
			assertEquals(85, hard.getTargetValue());
			assertFalse(hard.isOptional(), "hard req is never optional");
		}

		@Test
		@DisplayName("backwards-compat 3-arg overload defaults combat to 3 (fresh account)")
		void threeArgOverloadDefaultsToFreshAccountCombat()
		{
			// Using the 3-arg overload (no combat supplier) should still
			// emit the recommended combat template for any quest whose
			// recommendation is > 3. Ensures existing callers don't break.
			ToIntFunction<Skill> maxed = s -> 99;
			Function<Quest, QuestState> allFinished = q -> QuestState.FINISHED;

			QuestRequirementResolver.Resolved out =
				QuestRequirementResolver.resolve(Quest.DRAGON_SLAYER_II,
					maxed, allFinished);

			// Default combat 3 is below DS2's recommended 100, so template emits.
			assertTrue(out.templates.stream()
				.anyMatch(g -> "COMBAT_LEVEL".equals(g.getAccountMetric())
					&& g.isOptional()));
		}
	}
}

package com.goalplanner.integration;

import com.goalplanner.api.GoalPlannerApiImpl;
import com.goalplanner.data.WikiCaRepository;
import com.goalplanner.model.Goal;
import com.goalplanner.model.GoalType;
import com.goalplanner.persistence.GoalStore;
import com.goalplanner.service.GoalReorderingService;
import com.goalplanner.testsupport.InMemoryConfigManager;
import com.goalplanner.testsupport.MockClientFactory;
import com.goalplanner.testsupport.MockGameState;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;
import net.runelite.api.Client;
import net.runelite.api.Quest;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.mock;

/**
 * Integration tests for {@code addBossGoal}'s prereq-seeding behavior.
 *
 * <p>Validates that when a boss has a quest prereq, the quest's OWN
 * prereqs are transitively seeded — same chain-through behavior as
 * {@code addQuestGoalWithPrereqs} and {@code addDiaryGoalWithPrereqs}.
 * Without this chain, the card list would display the boss's quest as a
 * goal but none of the deeper skill/quest requirements underneath it.
 */
class BossGoalPrereqSeedingTest
{
	private GoalStore store;
	private GoalPlannerApiImpl api;

	@BeforeEach
	void setUp()
	{
		ConfigManager configManager = InMemoryConfigManager.create();
		store = new GoalStore(configManager, new com.google.gson.Gson());
		store.load();

		MockGameState freshState = new MockGameState();
		Client client = MockClientFactory.createClient(freshState);

		ItemManager itemManager = mock(ItemManager.class);
		WikiCaRepository wikiCaRepository = mock(WikiCaRepository.class);
		GoalReorderingService reorderingService = new GoalReorderingService(store);
		api = new GoalPlannerApiImpl(store, reorderingService, itemManager,
			wikiCaRepository, client);
	}

	private Set<String> questNames()
	{
		return store.getGoals().stream()
			.filter(g -> g.getType() == GoalType.QUEST)
			.map(Goal::getQuestName)
			.collect(Collectors.toSet());
	}

	private List<Goal> skillGoals()
	{
		return store.getGoals().stream()
			.filter(g -> g.getType() == GoalType.SKILL)
			.collect(Collectors.toList());
	}

	@Test
	@DisplayName("Amoxliatl seeds Heart of Darkness AND its transitive prereqs")
	void amoxliatlChainsThroughHeartOfDarkness()
	{
		String bossId = api.addBossGoal("Amoxliatl", 50);
		assertNotNull(bossId, "boss goal should be created");

		Set<String> quests = questNames();
		assertTrue(quests.contains(Quest.THE_HEART_OF_DARKNESS.name()),
			"direct quest prereq should be seeded: " + quests);
		// HoD's own quest prereq per QuestRequirements.java:1466
		assertTrue(quests.contains(Quest.TWILIGHTS_PROMISE.name()),
			"transitive quest prereq (HoD → Twilight's Promise) should be seeded: " + quests);

		// HoD's skill prereqs per QuestRequirements.java:1460-1467
		// (Mining 55, Thieving 48, Slayer 48, Agility 46)
		List<Goal> skills = skillGoals();
		assertFalse(skills.isEmpty(),
			"HoD's own skill prereqs should be seeded transitively");
		Set<String> skillNames = skills.stream()
			.map(Goal::getSkillName).collect(Collectors.toSet());
		assertTrue(skillNames.contains("MINING"), "Mining 55 from HoD");
		assertTrue(skillNames.contains("THIEVING"), "Thieving 48 from HoD");
		assertTrue(skillNames.contains("SLAYER"), "Slayer 48 from HoD");
		assertTrue(skillNames.contains("AGILITY"), "Agility 46 from HoD");
	}

	@Test
	@DisplayName("Vorkath seeds Dragon Slayer II AND chain of DS2 prereq quests")
	void vorkathChainsThroughDragonSlayerII()
	{
		String bossId = api.addBossGoal("Vorkath", 100);
		assertNotNull(bossId);

		Set<String> quests = questNames();
		assertTrue(quests.contains(Quest.DRAGON_SLAYER_II.name()),
			"direct DS2 quest prereq: " + quests);
		// DS2's own prereq chain should be seeded; Bone Voyage is a
		// well-known DS2 prereq per QuestRequirements.java:409.
		assertTrue(quests.contains(Quest.BONE_VOYAGE.name()),
			"transitive DS2 → Bone Voyage prereq: " + quests);
	}

	@Test
	@DisplayName("Zalcano seeds SotE chain plus 70/70/70 skill reqs")
	void zalcanoChainsQuestsAndSkills()
	{
		String bossId = api.addBossGoal("Zalcano", 50);
		assertNotNull(bossId);

		Set<String> quests = questNames();
		assertTrue(quests.contains(Quest.SONG_OF_THE_ELVES.name()),
			"direct SotE prereq: " + quests);
		// SotE has many quest prereqs; assert the chain extends beyond
		// just the direct quest.
		assertTrue(quests.size() >= 2,
			"SotE's prereq chain should add quests beyond SotE itself: " + quests);

		// Zalcano's direct skill prereqs (70 Mining, 70 Smithing, 70 Runecraft)
		Set<String> skillNames = skillGoals().stream()
			.map(Goal::getSkillName).collect(Collectors.toSet());
		assertTrue(skillNames.contains("MINING"));
		assertTrue(skillNames.contains("SMITHING"));
		assertTrue(skillNames.contains("RUNECRAFT"));
	}

	@Test
	@DisplayName("The Gauntlet seeds SotE chain (deepest elf questline)")
	void gauntletChainsThroughSotE()
	{
		String bossId = api.addBossGoal("The Gauntlet", 100);
		assertNotNull(bossId);

		Set<String> quests = questNames();
		assertTrue(quests.contains(Quest.SONG_OF_THE_ELVES.name()),
			"direct SotE prereq: " + quests);
		// SotE requires the full elf chain. Sanity-check a few deep
		// prereqs are seeded (e.g. Regicide, Waterfall Quest).
		assertTrue(quests.contains(Quest.REGICIDE.name()),
			"deep prereq Regicide should be seeded: " + quests);
	}

	@Test
	@DisplayName("Corrupted Gauntlet seeds SotE chain AND base Gauntlet kill")
	void corruptedGauntletRequiresStandardKill()
	{
		String bossId = api.addBossGoal("Corrupted Gauntlet", 100);
		assertNotNull(bossId);

		// Should have seeded the standard Gauntlet boss as a prereq.
		boolean hasGauntletPrereq = store.getGoals().stream()
			.anyMatch(g -> g.getType() == com.goalplanner.model.GoalType.BOSS
				&& "The Gauntlet".equals(g.getBossName()));
		assertTrue(hasGauntletPrereq,
			"Corrupted Gauntlet should seed 'The Gauntlet' as a boss prereq");

		// And SotE itself is in the quest chain.
		assertTrue(questNames().contains(Quest.SONG_OF_THE_ELVES.name()));
	}

	@Test
	@DisplayName("Demonic Brutus requires Brutus kill AND Defender of Varrock")
	void demonicBrutusChain()
	{
		String bossId = api.addBossGoal("Demonic Brutus", 50);
		assertNotNull(bossId);

		Set<String> quests = questNames();
		assertTrue(quests.contains(Quest.DEFENDER_OF_VARROCK.name()),
			"Defender of Varrock should be seeded: " + quests);

		boolean hasBrutusPrereq = store.getGoals().stream()
			.anyMatch(g -> g.getType() == com.goalplanner.model.GoalType.BOSS
				&& "Brutus".equals(g.getBossName()));
		assertTrue(hasBrutusPrereq,
			"Demonic Brutus should seed 'Brutus' as a boss prereq");
	}

	@Test
	@DisplayName("addBossGoalNoPrereqs creates just the boss goal, no prereq tree")
	void bareAddSeedsNoPrereqs()
	{
		// Amoxliatl normally chains Heart of Darkness + its transitive skills/quests
		// (see amoxliatlChainsThroughHeartOfDarkness). The bare add (Task 4's
		// unchecked "Add prerequisites") must create ONLY the boss goal.
		String bossId = api.addBossGoalNoPrereqs("Amoxliatl", 50);
		assertNotNull(bossId, "bare boss goal should be created");

		List<Goal> bossGoals = store.getGoals().stream()
			.filter(g -> g.getType() == GoalType.BOSS)
			.collect(Collectors.toList());
		assertEquals(1, bossGoals.size(),
			"bare add should create exactly one BOSS goal, no boss prereqs: "
				+ bossGoals.stream().map(Goal::getBossName).collect(Collectors.toList()));
		assertEquals("Amoxliatl", bossGoals.get(0).getBossName());

		assertTrue(questNames().isEmpty(),
			"bare add must not seed quest prereqs: " + questNames());
		assertTrue(skillGoals().isEmpty(),
			"bare add must not seed skill prereqs");
	}
}

package com.goalplanner.integration;

import com.goalplanner.api.GoalPlannerApi;
import com.goalplanner.api.GoalPlannerApiImpl;
import com.goalplanner.data.AchievementDiaryData;
import com.goalplanner.data.DiaryRequirementResolver;
import com.goalplanner.data.WikiCaRepository;
import com.goalplanner.model.Goal;
import com.goalplanner.model.GoalType;
import com.goalplanner.persistence.GoalStore;
import com.goalplanner.service.GoalReorderingService;
import com.goalplanner.testsupport.InMemoryConfigManager;
import com.goalplanner.testsupport.MockClientFactory;
import com.goalplanner.testsupport.MockGameState;
import com.goalplanner.tracker.DiaryTracker;
import com.goalplanner.tracker.QuestTracker;
import com.goalplanner.tracker.SkillTracker;
import net.runelite.api.Client;
import net.runelite.api.Experience;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemID;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import java.util.List;
import java.util.stream.Collectors;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Integration test: simulate a fresh account completing the Ardougne Easy
 * diary by progressing through all prerequisites (skills + quests), then
 * completing the diary itself. Verifies that all goals move through
 * ACTIVE → COMPLETE and into the Completed section.
 *
 * <p>Ardougne Easy requires: Thieving 5, Quest Rune Mysteries, Quest Biohazard.
 * Biohazard itself requires Plague City, which requires no additional skills.
 */
class DiaryCompletionIntegrationTest
{
	private GoalStore store;
	private GoalPlannerApiImpl api;

	@BeforeEach
	void setUp()
	{
		ConfigManager configManager = InMemoryConfigManager.create();
		store = new GoalStore(configManager, new com.google.gson.Gson());
		store.load();

		// Use a Client mock for the API so resolveQuestRequirements works
		// (it needs client != null to resolve quest prereq trees).
		// Fresh account: all quests NOT_STARTED.
		MockGameState freshState = new MockGameState();
		Client client = MockClientFactory.createClient(freshState);

		ItemManager itemManager = mock(ItemManager.class);
		// Stub item compositions for item goals used in diary prereqs
		ItemComposition kqHeadComp = mock(ItemComposition.class);
		when(kqHeadComp.getName()).thenReturn("KQ head");
		when(itemManager.getItemComposition(ItemID.KQ_HEAD)).thenReturn(kqHeadComp);

		ItemComposition crystalKeyComp = mock(ItemComposition.class);
		when(crystalKeyComp.getName()).thenReturn("Crystal key");
		when(itemManager.getItemComposition(ItemID.CRYSTAL_KEY)).thenReturn(crystalKeyComp);

		WikiCaRepository wikiCaRepository = mock(WikiCaRepository.class);
		GoalReorderingService reorderingService = new GoalReorderingService(store);
		api = new GoalPlannerApiImpl(store, reorderingService, itemManager, wikiCaRepository, client);
	}

	/**
	 * Run all relevant trackers against the current goal list using the
	 * given game state. Returns true if any tracker detected a change.
	 */
	private boolean runAllTrackers(MockGameState state)
	{
		Client client = MockClientFactory.createClient(state);
		boolean changed = false;
		changed |= new SkillTracker(client, api).checkGoals(store.getGoals());
		changed |= new QuestTracker(client, api).checkGoals(store.getGoals());
		changed |= new DiaryTracker(client, api).checkGoals(store.getGoals());
		return changed;
	}

	private List<Goal> goalsOfType(GoalType type)
	{
		return store.getGoals().stream()
			.filter(g -> g.getType() == type)
			.collect(Collectors.toList());
	}

	private List<Goal> completedGoals()
	{
		return store.getGoals().stream()
			.filter(Goal::isComplete)
			.collect(Collectors.toList());
	}

	private List<Goal> activeGoals()
	{
		return store.getGoals().stream()
			.filter(g -> !g.isComplete())
			.collect(Collectors.toList());
	}

	private String completedSectionId()
	{
		return store.getCompletedSection().getId();
	}

	// ================================================================
	// Full diary lifecycle: fresh account → all prereqs → diary done
	// ================================================================

	@Test
	@DisplayName("fresh account completes Ardougne Easy diary through full prerequisite chain")
	void freshAccountCompletesArdougneEasy()
	{
		// ---- Phase 1: Resolve requirements for a brand-new account ----
		DiaryRequirementResolver.Resolved resolved = DiaryRequirementResolver.resolve(
			"Ardougne", AchievementDiaryData.Tier.EASY,
			skill -> 1,  // all skills at level 1
			quest -> QuestState.NOT_STARTED);

		// Seed the diary goal with all prerequisites
		api.addDiaryGoalWithPrereqs(
			"Ardougne", GoalPlannerApi.DiaryTier.EASY, resolved);

		// Find the diary goal by type (ID lookup is unreliable across compounds)
		Goal diaryGoal = store.getGoals().stream()
			.filter(g -> g.getType() == GoalType.DIARY)
			.findFirst().orElse(null);
		assertNotNull(diaryGoal, "diary goal should exist in store");
		assertTrue(diaryGoal.getRequiredGoalIds().size() > 0,
			"diary should have prerequisite links");

		List<Goal> allGoals = store.getGoals();
		assertTrue(allGoals.size() > 1,
			"should have diary + at least skill/quest prereqs");

		// Identify the prerequisite goals
		List<Goal> skillGoals = goalsOfType(GoalType.SKILL);
		List<Goal> questGoals = goalsOfType(GoalType.QUEST);

		// Ardougne Easy requires: Thieving 5, Rune Mysteries, Biohazard
		// Biohazard requires Plague City (seeded via quest prereq resolution)
		assertTrue(skillGoals.size() >= 1, "should have at least 1 skill prereq (Thieving)");
		assertTrue(questGoals.size() >= 2, "should have at least 2 quest prereqs");

		// Verify all goals start incomplete
		for (Goal g : allGoals)
		{
			assertFalse(g.isComplete(), "all goals should start incomplete: " + g.getName());
		}

		// ---- Phase 2: Fresh account, no progress ----
		MockGameState freshAccount = new MockGameState()
			.combatLevel(3)
			.totalLevel(32);

		runAllTrackers(freshAccount);

		// Nothing should be complete yet
		assertEquals(0, completedGoals().size(), "no goals complete on fresh account");

		// ---- Phase 3: Train Thieving to 5 ----
		int thievingXpTarget = Experience.getXpForLevel(5);
		MockGameState afterThieving = freshAccount.copy()
			.skillXp(Skill.THIEVING, thievingXpTarget);

		runAllTrackers(afterThieving);

		// The Thieving skill goal should now be complete
		Goal thievingGoal = skillGoals.stream()
			.filter(g -> g.getSkillName() != null && g.getSkillName().equals("THIEVING"))
			.findFirst().orElse(null);
		assertNotNull(thievingGoal, "should have a Thieving goal");
		assertTrue(thievingGoal.isComplete(),
			"Thieving goal should be complete at level 5 XP");

		// ---- Phase 4: Complete quest prerequisites ----
		// Plague City is a prereq of Biohazard, Rune Mysteries is standalone
		MockGameState afterQuests = afterThieving.copy()
			.questFinished(Quest.PLAGUE_CITY)
			.questFinished(Quest.RUNE_MYSTERIES)
			.questFinished(Quest.BIOHAZARD);

		runAllTrackers(afterQuests);

		// All quest goals should now be complete
		for (Goal q : questGoals)
		{
			assertTrue(q.isComplete(), "quest goal should be complete: " + q.getName());
		}

		// All prereqs done, but diary itself is NOT complete yet
		// (diary completion comes from the varbit, not from prereqs)
		assertFalse(diaryGoal.isComplete(),
			"diary goal should NOT be complete until varbit fires");

		// ---- Phase 5: Complete the diary in-game (varbit fires) ----
		MockGameState afterDiary = afterQuests.copy()
			.diaryComplete("Ardougne", AchievementDiaryData.Tier.EASY);

		runAllTrackers(afterDiary);

		// NOW the diary goal should be complete
		assertTrue(diaryGoal.isComplete(),
			"diary goal should be complete after varbit fires");

		// ---- Phase 6: Reconcile sections ----
		store.reconcileDerivedSections();

		// All completed goals should be in the Completed section
		String completedId = completedSectionId();
		for (Goal g : completedGoals())
		{
			assertEquals(completedId, g.getSectionId(),
				"completed goal should be in Completed section: " + g.getName());
		}

		// No active goals should remain in the Completed section
		for (Goal g : activeGoals())
		{
			assertNotEquals(completedId, g.getSectionId(),
				"active goal should NOT be in Completed section: " + g.getName());
		}
	}

