package com.goalplanner.integration;

import com.goalplanner.model.Goal;
import com.goalplanner.model.GoalType;
import com.goalplanner.testsupport.MockGameState;
import com.goalplanner.testsupport.TrackerTestHarness;
import com.goalplanner.tracker.BossKillTracker;
import com.goalplanner.tracker.SkillTracker;
import com.goalplanner.util.AccountBindingGate;
import com.goalplanner.util.AccountBindingGate.Decision;
import net.runelite.api.Skill;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * End-to-end cover for the reported bug: one account's goals completing
 * themselves against another account's stats.
 *
 * <p>These tests run the REAL store, API and trackers. They reconstruct the
 * plugin's drain guard rather than calling {@code GoalPlannerPlugin} directly,
 * because instantiating the plugin needs RuneLite's injector; the guard
 * expression here is the same one the plugin applies before
 * {@code drainTrackerUpdates()}. What that leaves unproven is only that the
 * plugin calls it - the guard's effect on real trackers is exercised for real.
 *
 * <p>The first test in each pair deliberately reproduces the corruption with
 * the gate absent. If those ever stop failing-open, the gate is being tested
 * against a bug that no longer exists and these need revisiting.
 */
class WrongAccountTrackingTest
{
	private static final long MAIN = 111_111L;
	private static final long ALT = 222_222L;

	/** Exactly what the plugin evaluates before letting the trackers run. */
	private static boolean drainAllowed(AccountBindingGate gate, long live, long bound)
	{
		return AccountBindingGate.allowsTracking(gate.evaluate(live, bound));
	}

	private static Goal prayerGoal()
	{
		return Goal.builder().type(GoalType.SKILL).name("Prayer - Level 99")
			.skillName("PRAYER").targetValue(13_034_431).build();
	}

	private static Goal graardorGoal()
	{
		return Goal.builder().type(GoalType.BOSS).name("General Graardor")
			.bossName("General Graardor").targetValue(50).build();
	}

	@Test
	@DisplayName("REPRODUCES THE BUG: ungated, another account's stats complete these goals")
	void ungatedTrackingCorrupts()
	{
		// The alt's plan is loaded, but the MAIN is logged in with 99 Prayer.
		TrackerTestHarness<SkillTracker> h = TrackerTestHarness.forSkills(
			new MockGameState().skillXp(Skill.PRAYER, 13_034_431));
		Goal altGoal = prayerGoal();
		h.store().addGoal(altGoal);

		h.tracker().checkGoals(h.store().getGoals());

		assertTrue(altGoal.isComplete(),
			"this is the reported bug reproduced - the alt's goal completed off the main's XP");
	}

	@Test
	@DisplayName("gated, the same pairing never reaches the tracker and nothing completes")
	void gatedTrackingIsRefused()
	{
		TrackerTestHarness<SkillTracker> h = TrackerTestHarness.forSkills(
			new MockGameState().skillXp(Skill.PRAYER, 13_034_431));
		Goal altGoal = prayerGoal();
		h.store().addGoal(altGoal);
		h.store().setBoundAccountHash(ALT);

		AccountBindingGate gate = new AccountBindingGate();
		if (drainAllowed(gate, MAIN, h.store().getBoundAccountHash()))
		{
			h.tracker().checkGoals(h.store().getGoals());
		}

		assertFalse(altGoal.isComplete(),
			"the alt's goal must survive the main being logged in");
		assertEquals(0, altGoal.getCurrentValue(),
			"and must not even record the wrong account's progress");
	}

	@Test
	@DisplayName("boss kill counts are protected the same way")
	void bossKillCountsGated()
	{
		TrackerTestHarness<BossKillTracker> h = TrackerTestHarness.forBossKills(
			new MockGameState().bossKills("General Graardor", 1847));
		Goal altGoal = graardorGoal();
		h.store().addGoal(altGoal);
		h.store().setBoundAccountHash(ALT);

		AccountBindingGate gate = new AccountBindingGate();
		if (drainAllowed(gate, MAIN, h.store().getBoundAccountHash()))
		{
			h.tracker().checkGoals(h.store().getGoals());
		}

		assertFalse(altGoal.isComplete(), "1,847 lifetime kills must not complete the alt's 50-kill goal");
	}

	@Test
	@DisplayName("the right account still tracks normally - the gate must not break the common case")
	void matchingAccountStillTracks()
	{
		TrackerTestHarness<SkillTracker> h = TrackerTestHarness.forSkills(
			new MockGameState().skillXp(Skill.PRAYER, 13_034_431));
		Goal ownGoal = prayerGoal();
		h.store().addGoal(ownGoal);
		h.store().setBoundAccountHash(MAIN);

		AccountBindingGate gate = new AccountBindingGate();
		if (drainAllowed(gate, MAIN, h.store().getBoundAccountHash()))
		{
			h.tracker().checkGoals(h.store().getGoals());
		}

		assertTrue(ownGoal.isComplete(), "a matching account must track exactly as before");
	}

	@Test
	@DisplayName("an unbound goal set adopts the logged-in account and tracks it")
	void unboundSetAdoptsAndTracks()
	{
		TrackerTestHarness<SkillTracker> h = TrackerTestHarness.forSkills(
			new MockGameState().skillXp(Skill.PRAYER, 13_034_431));
		Goal goal = prayerGoal();
		h.store().addGoal(goal);
		assertEquals(0L, h.store().getBoundAccountHash(), "starts unbound, as an upgrading user would");

		AccountBindingGate gate = new AccountBindingGate();
		Decision decision = gate.evaluate(MAIN, h.store().getBoundAccountHash());
		if (decision == Decision.ADOPT)
		{
			h.store().setBoundAccountHash(MAIN);
		}
		if (AccountBindingGate.allowsTracking(decision))
		{
			h.tracker().checkGoals(h.store().getGoals());
		}

		assertEquals(MAIN, h.store().getBoundAccountHash(), "existing users migrate with no action");
		assertTrue(goal.isComplete(), "and tracking is not interrupted by the migration");
	}

	@Test
	@DisplayName("once adopted, the OTHER account is locked out - the full astrasin sequence")
	void adoptThenSwitchAccountsIsRefused()
	{
		// Day 1: play the main, goals bind to it and track.
		TrackerTestHarness<SkillTracker> h = TrackerTestHarness.forSkills(
			new MockGameState().skillXp(Skill.PRAYER, 13_034_431));
		Goal goal = prayerGoal();
		h.store().addGoal(goal);

		AccountBindingGate gate = new AccountBindingGate();
		if (gate.evaluate(MAIN, h.store().getBoundAccountHash()) == Decision.ADOPT)
		{
			h.store().setBoundAccountHash(MAIN);
		}
		h.tracker().checkGoals(h.store().getGoals());
		assertTrue(goal.isComplete());

		// Day 2: same profile, the ALT logs in. Reset the goal as the recovery
		// flow would, then confirm the alt cannot re-complete it.
		goal.setCompletedAt(0);
		goal.setStatus(com.goalplanner.model.GoalStatus.ACTIVE);

		assertFalse(drainAllowed(gate, ALT, h.store().getBoundAccountHash()),
			"the alt must be refused on a profile bound to the main");
		assertTrue(gate.shouldAnnounceMismatch(), "and the user must be told why tracking stopped");
	}
}

package com.goalplanner.model;

import java.util.EnumMap;
import java.util.EnumSet;
import java.util.Map;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * AccountMetric.decays() - the classification that decides whether a goal's
 * completion is sticky or is re-derived from the live value every tick.
 *
 * <p>The expectation table below is deliberately exhaustive: adding a metric
 * without classifying it fails {@link #everyMetricIsClassified()}, so nobody
 * inherits "monotonic" by accident.
 */
class AccountMetricDecayTest
{
	private static Map<AccountMetric, Boolean> expected()
	{
		Map<AccountMetric, Boolean> m = new EnumMap<>(AccountMetric.class);
		// Falls during normal play.
		m.put(AccountMetric.MISC_APPROVAL, true);   // favour decays daily
		m.put(AccountMetric.SLAYER_POINTS, true);   // spendable balance
		// Counters of things done/obtained - the game never takes them back.
		m.put(AccountMetric.QUEST_POINTS, false);
		m.put(AccountMetric.CA_POINTS, false);
		m.put(AccountMetric.KUDOS, false);
		m.put(AccountMetric.CHOMPY_KILLS, false);
		m.put(AccountMetric.COLLECTION_LOG_SLOTS, false);
		m.put(AccountMetric.DIARY_TIERS_COMPLETED, false);
		m.put(AccountMetric.LEAGUE_TASKS, false);
		// Lifetime EARNED, not the spendable balance.
		m.put(AccountMetric.LEAGUE_POINTS, false);
		// Real (unboosted) levels.
		m.put(AccountMetric.TOTAL_LEVEL, false);
		m.put(AccountMetric.COMBAT_LEVEL, false);
		m.put(AccountMetric.ATT_STR_COMBINED, false);
		// Personal bests - a worse run does not lower the record.
		m.put(AccountMetric.TOG_MAX_TEARS, false);
		m.put(AccountMetric.COLOSSEUM_GLORY, false);
		m.put(AccountMetric.DOM_DEEPEST_LEVEL, false);
		return m;
	}

	@Test
	@DisplayName("every metric is explicitly classified as decaying or monotonic")
	void everyMetricIsClassified()
	{
		assertEquals(EnumSet.allOf(AccountMetric.class), expected().keySet(),
			"a new AccountMetric must be added to this table with a justification");
	}

	@Test
	@DisplayName("only Miscellania favour and slayer points can lose value")
	void classificationMatches()
	{
		for (Map.Entry<AccountMetric, Boolean> e : expected().entrySet())
		{
			assertEquals(e.getValue(), e.getKey().decays(), e.getKey().name());
		}
	}

	@Test
	@DisplayName("Miscellania favour decays; quest points do not")
	void spotCheck()
	{
		assertTrue(AccountMetric.MISC_APPROVAL.decays());
		assertFalse(AccountMetric.QUEST_POINTS.decays());
	}
}

package com.goalplanner.model;

import net.runelite.api.Client;
import net.runelite.api.gameval.VarPlayerID;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * AccountMetric.effectiveMaxTarget — the live collection-log slot ceiling,
 * and the static fallback for every other metric (quest points / ToG PB
 * intentionally stay static and wiki-authoritative).
 */
class AccountMetricMaxTest
{
	@Test
	@DisplayName("collection log slots prefers the live in-game slot total when synced")
	void collectionLogPrefersLiveSlotTotal()
	{
		Client client = mock(Client.class);
		when(client.getVarpValue(eq(VarPlayerID.COLLECTION_COUNT_MAX))).thenReturn(1750);
		assertEquals(1750, AccountMetric.COLLECTION_LOG_SLOTS.effectiveMaxTarget(client));
	}

	@Test
	@DisplayName("collection log slots falls back to the static when the live read is 0")
	void collectionLogFallsBackWhenUnsynced()
	{
		Client client = mock(Client.class);
		when(client.getVarpValue(anyInt())).thenReturn(0);
		assertEquals(AccountMetric.COLLECTION_LOG_SLOTS.getMaxTarget(),
			AccountMetric.COLLECTION_LOG_SLOTS.effectiveMaxTarget(client));
	}

	@Test
	@DisplayName("quest points / ToG PB use the static ceiling, never a live sum")
	void questPointsStayStatic()
	{
		// Even with a fully-populated client, QP/ToG must return the static
		// (the live DB-table sum over-counted; wiki static is authoritative).
		Client client = mock(Client.class);
		when(client.getVarpValue(anyInt())).thenReturn(99999);
		assertEquals(341, AccountMetric.QUEST_POINTS.effectiveMaxTarget(client));
		assertEquals(341, AccountMetric.TOG_MAX_TEARS.effectiveMaxTarget(client));
		assertEquals(AccountMetric.QUEST_POINTS.getMaxTarget(),
			AccountMetric.QUEST_POINTS.effectiveMaxTarget(client));
	}

	@Test
	@DisplayName("null client returns the static max for every metric")
	void nullClientUsesStatics()
	{
		for (AccountMetric m : AccountMetric.values())
		{
			assertEquals(m.getMaxTarget(), m.effectiveMaxTarget(null));
		}
	}

	@Test
	@DisplayName("quest point and ToG PB statics are equal (cape == full tears window)")
	void staticsAgree()
	{
		assertEquals(AccountMetric.QUEST_POINTS.getMaxTarget(),
			AccountMetric.TOG_MAX_TEARS.getMaxTarget());
	}

	@Test
	@DisplayName("an off-thread collection-log read (AssertionError) degrades to the static")
	void clientThreadAssertDegradesToStatic()
	{
		// The live varp read off the client thread raises AssertionError under
		// -ea — effectiveMaxTarget must swallow it and return the static, not
		// let it escape into the calling UI action (the Max-button bug).
		Client throwing = mock(Client.class);
		when(throwing.getVarpValue(anyInt()))
			.thenThrow(new AssertionError("must be called on client thread"));
		assertEquals(AccountMetric.COLLECTION_LOG_SLOTS.getMaxTarget(),
			AccountMetric.COLLECTION_LOG_SLOTS.effectiveMaxTarget(throwing));
	}
}

package com.goalplanner.model;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * The per-type "same objective" predicate that defines a duplicate. Mirrors the
 * conditions the creation-layer duplicate guards used to inline.
 */
class GoalIdentityTest
{
	private static Goal skill(String name, int target)
	{
		return Goal.builder().type(GoalType.SKILL).skillName(name).targetValue(target).build();
	}

	@Test
	@DisplayName("different types are never the same identity")
	void differentTypesNeverMatch()
	{
		Goal s = skill("RANGED", 100);
		Goal b = Goal.builder().type(GoalType.BOSS).bossName("RANGED").build();
		assertFalse(GoalIdentity.sameIdentity(s, b));
		assertFalse(GoalIdentity.sameIdentity(null, s));
		assertFalse(GoalIdentity.sameIdentity(s, null));
	}

	@Test
	@DisplayName("SKILL: same skill name + target XP; differing skill or target do not match")
	void skillIdentity()
	{
		assertTrue(GoalIdentity.sameIdentity(skill("RANGED", 100), skill("RANGED", 100)));
		assertFalse(GoalIdentity.sameIdentity(skill("RANGED", 100), skill("RANGED", 200)));
		assertFalse(GoalIdentity.sameIdentity(skill("RANGED", 100), skill("ATTACK", 100)));
	}

	@Test
	@DisplayName("QUEST matches by exact name; BOSS by exact name")
	void questAndBossIdentity()
	{
		Goal q1 = Goal.builder().type(GoalType.QUEST).questName("SONG_OF_THE_ELVES").build();
		Goal q2 = Goal.builder().type(GoalType.QUEST).questName("SONG_OF_THE_ELVES").build();
		Goal q3 = Goal.builder().type(GoalType.QUEST).questName("DRAGON_SLAYER_II").build();
		assertTrue(GoalIdentity.sameIdentity(q1, q2));
		assertFalse(GoalIdentity.sameIdentity(q1, q3));

		Goal b1 = Goal.builder().type(GoalType.BOSS).bossName("Zulrah").build();
		Goal b2 = Goal.builder().type(GoalType.BOSS).bossName("Zulrah").build();
		Goal b3 = Goal.builder().type(GoalType.BOSS).bossName("Vorkath").build();
		assertTrue(GoalIdentity.sameIdentity(b1, b2));
		assertFalse(GoalIdentity.sameIdentity(b1, b3));
	}

	@Test
	@DisplayName("DIARY matches area name + tier description case-insensitively")
	void diaryIdentity()
	{
		Goal d1 = Goal.builder().type(GoalType.DIARY).name("Varrock").description("Hard Achievement Diary").build();
		Goal d2 = Goal.builder().type(GoalType.DIARY).name("varrock").description("hard achievement diary").build();
		Goal d3 = Goal.builder().type(GoalType.DIARY).name("Varrock").description("Elite Achievement Diary").build();
		assertTrue(GoalIdentity.sameIdentity(d1, d2));
		assertFalse(GoalIdentity.sameIdentity(d1, d3));
	}

	@Test
	@DisplayName("COMBAT_ACHIEVEMENT matches by task id, or by name when ids differ")
	void caIdentity()
	{
		Goal a = Goal.builder().type(GoalType.COMBAT_ACHIEVEMENT).caTaskId(5).name("Kill Zuk").build();
		Goal sameId = Goal.builder().type(GoalType.COMBAT_ACHIEVEMENT).caTaskId(5).name("different label").build();
		Goal sameName = Goal.builder().type(GoalType.COMBAT_ACHIEVEMENT).caTaskId(6).name("kill zuk").build();
		Goal neither = Goal.builder().type(GoalType.COMBAT_ACHIEVEMENT).caTaskId(6).name("Kill Jad").build();
		assertTrue(GoalIdentity.sameIdentity(a, sameId));
		assertTrue(GoalIdentity.sameIdentity(a, sameName));
		assertFalse(GoalIdentity.sameIdentity(a, neither));
	}

	@Test
	@DisplayName("ITEM_GRIND by item id; ACCOUNT by metric+target; CUSTOM by name (case-insensitive)")
	void itemAccountCustomIdentity()
	{
		Goal i1 = Goal.builder().type(GoalType.ITEM_GRIND).itemId(995).build();
		Goal i2 = Goal.builder().type(GoalType.ITEM_GRIND).itemId(995).targetValue(50).build();
		Goal i3 = Goal.builder().type(GoalType.ITEM_GRIND).itemId(1234).build();
		assertTrue(GoalIdentity.sameIdentity(i1, i2)); // qty ignored
		assertFalse(GoalIdentity.sameIdentity(i1, i3));

		Goal a1 = Goal.builder().type(GoalType.ACCOUNT).accountMetric("QUEST_POINTS").targetValue(100).build();
		Goal a2 = Goal.builder().type(GoalType.ACCOUNT).accountMetric("QUEST_POINTS").targetValue(100).build();
		Goal a3 = Goal.builder().type(GoalType.ACCOUNT).accountMetric("QUEST_POINTS").targetValue(200).build();
		assertTrue(GoalIdentity.sameIdentity(a1, a2));
		assertFalse(GoalIdentity.sameIdentity(a1, a3));

		Goal c1 = Goal.builder().type(GoalType.CUSTOM).name("Buy a bond").build();
		Goal c2 = Goal.builder().type(GoalType.CUSTOM).name("BUY A BOND").build();
		Goal c3 = Goal.builder().type(GoalType.CUSTOM).name("Sell a bond").build();
		assertTrue(GoalIdentity.sameIdentity(c1, c2));
		assertFalse(GoalIdentity.sameIdentity(c1, c3));
	}
}

package com.goalplanner.model;

import org.junit.Test;

import static org.junit.Assert.*;

public class GoalTest
{
	@Test
	public void testProgressPercentZeroTarget()
	{
		Goal goal = Goal.builder().type(GoalType.CUSTOM).name("Test").targetValue(0).build();
		assertEquals(0.0, goal.getProgressPercent(), 0.01);
	}

	@Test
	public void testProgressPercentCompleteCustom()
	{
		// Completion is canonically tracked by completedAt > 0, not
		// status. Build the goal with both for clarity.
		Goal goal = Goal.builder().type(GoalType.CUSTOM).name("Test").targetValue(0)
			.status(GoalStatus.COMPLETE).completedAt(System.currentTimeMillis()).build();
		assertEquals(100.0, goal.getProgressPercent(), 0.01);
	}

	@Test
	public void testProgressPercentPartial()
	{
		Goal goal = Goal.builder().type(GoalType.SKILL).name("Attack").targetValue(1000)
			.currentValue(500).build();
		assertEquals(50.0, goal.getProgressPercent(), 0.01);
	}

	@Test
	public void testProgressPercentOver100()
	{
		Goal goal = Goal.builder().type(GoalType.ITEM_GRIND).name("Coal").targetValue(100)
			.currentValue(200).build();
		assertEquals(100.0, goal.getProgressPercent(), 0.01);
	}

	@Test
	public void testIsCompleteByCompletedAt()
	{
		// Completion is iff completedAt > 0. The tracker's
		// recordGoalProgress sets this when meetsTarget() flips true.
		Goal goal = Goal.builder().type(GoalType.SKILL).name("Mining").targetValue(100)
			.currentValue(100).completedAt(System.currentTimeMillis()).build();
		assertTrue(goal.isComplete());
	}

	@Test
	public void testMeetsTargetWithoutCompletedAt()
	{
		// A goal that meets its target but hasn't been stamped (e.g. before the
		// next tracker tick) is NOT considered complete. meetsTarget and
		// isComplete are intentionally separate concerns.
		Goal goal = Goal.builder().type(GoalType.SKILL).name("Mining").targetValue(100)
			.currentValue(100).build();
		assertTrue(goal.meetsTarget());
		assertFalse(goal.isComplete());
	}

	@Test
	public void testIsCompleteByCompletedAtCustom()
	{
		// Custom goals are marked complete via the API which stamps completedAt.
		Goal goal = Goal.builder().type(GoalType.CUSTOM).name("Test")
			.status(GoalStatus.COMPLETE).completedAt(System.currentTimeMillis()).build();
		assertTrue(goal.isComplete());
	}

	@Test
	public void testIsNotComplete()
	{
		Goal goal = Goal.builder().type(GoalType.SKILL).name("Mining").targetValue(100)
			.currentValue(50).build();
		assertFalse(goal.isComplete());
	}

	@Test
	public void testUnscannedItemGoal()
	{
