	// Relations — load-time cycle / dangling edge scrub
	// ====================================================================

	@Test
	@DisplayName("Load scrub: drops dangling requirement edges pointing at missing goals")
	void scrubDanglingEdges()
	{
		Goal a = Goal.builder().type(GoalType.CUSTOM).name("A")
			.requiredGoalIds(new java.util.ArrayList<>(java.util.List.of("ghost-id"))).build();
		store.addGoal(a);
		store.save();

		GoalStore reloaded = new GoalStore(configManager, new com.google.gson.Gson());
		reloaded.load();
		Goal loaded = reloaded.getGoals().stream()
			.filter(g -> "A".equals(g.getName())).findFirst().orElseThrow();
		assertTrue(loaded.getRequiredGoalIds().isEmpty());
	}

	@Test
	@DisplayName("Load scrub: drops self-loop edges")
	void scrubSelfLoops()
	{
		Goal a = Goal.builder().type(GoalType.CUSTOM).name("A").build();
		// Use builder's id for the self-loop reference
		a.getRequiredGoalIds().add(a.getId());
		store.addGoal(a);
		store.save();

		GoalStore reloaded = new GoalStore(configManager, new com.google.gson.Gson());
		reloaded.load();
		Goal loaded = reloaded.getGoals().stream()
			.filter(g -> "A".equals(g.getName())).findFirst().orElseThrow();
		assertTrue(loaded.getRequiredGoalIds().isEmpty());
	}

	@Test
	@DisplayName("Load scrub: drops cycle-forming edges, keeps acyclic ones")
	void scrubCycleEdges()
	{
		Goal a = Goal.builder().type(GoalType.CUSTOM).name("A").build();
		Goal b = Goal.builder().type(GoalType.CUSTOM).name("B").build();
		Goal c = Goal.builder().type(GoalType.CUSTOM).name("C").build();
		// Build a 3-cycle A→B→C→A by directly manipulating the fields.
		a.getRequiredGoalIds().add(b.getId());
		b.getRequiredGoalIds().add(c.getId());
		c.getRequiredGoalIds().add(a.getId());
		store.addGoal(a);
		store.addGoal(b);
		store.addGoal(c);
		store.save();

		GoalStore reloaded = new GoalStore(configManager, new com.google.gson.Gson());
		reloaded.load();
		Goal la = reloaded.getGoals().stream()
			.filter(g -> "A".equals(g.getName())).findFirst().orElseThrow();
		Goal lb = reloaded.getGoals().stream()
			.filter(g -> "B".equals(g.getName())).findFirst().orElseThrow();
		Goal lc = reloaded.getGoals().stream()
			.filter(g -> "C".equals(g.getName())).findFirst().orElseThrow();
		// Exactly one of the three cycle-forming edges was dropped; the graph
		// is now a 2-edge chain with no cycle. Which specific edge gets
		// dropped depends on iteration order, but the total count is fixed.
		int totalEdges = la.getRequiredGoalIds().size()
			+ lb.getRequiredGoalIds().size()
			+ lc.getRequiredGoalIds().size();
		assertEquals(2, totalEdges);
		// After scrub, no pair of goals can close a cycle via a new edge
		// unless it would re-create the one that was dropped. Verify
		// acyclicity by confirming that adding ANY new edge to the graph
		// requires no more than 1 attempt to succeed (i.e. there IS at least
		// one ordered pair that wouldn't close a cycle). This is a weaker
		// but sound acyclicity check.
		String[] ids = {la.getId(), lb.getId(), lc.getId()};
		boolean atLeastOneAcyclicAdd = false;
		for (String from : ids)
		{
			for (String to : ids)
			{
				if (from.equals(to)) continue;
				if (!reloaded.wouldCreateCycle(from, to))
				{
					atLeastOneAcyclicAdd = true;
					break;
				}
			}
			if (atLeastOneAcyclicAdd) break;
		}
		assertTrue(atLeastOneAcyclicAdd);
	}

	// ====================================================================
	// Account binding — the guard against goals completing themselves
	// against the wrong account
	// ====================================================================

	@Test
	@DisplayName("a fresh goal set is unbound, so it can adopt whoever logs in first")
	void accountHashStartsUnbound()
	{
		assertEquals(0L, store.getBoundAccountHash());
	}

	@Test
	@DisplayName("a bound account round-trips through config")
	void accountHashRoundTrips()
	{
		store.setBoundAccountHash(1234567890123L);
		assertEquals(1234567890123L, store.getBoundAccountHash());

		GoalStore reloaded = new GoalStore(configManager, new com.google.gson.Gson());
		reloaded.load();
		assertEquals(1234567890123L, reloaded.getBoundAccountHash(),
			"the binding must survive a restart or it guards nothing");
	}

	@Test
	@DisplayName("binding is per profile, so two accounts on one machine do not share it")
	void accountHashIsPerProfile()
	{
		store.setBoundAccountHash(1111L);
		store.setProfile("leagues");
		assertEquals(0L, store.getBoundAccountHash(),
			"a different profile must not inherit another account's binding");

		store.setBoundAccountHash(2222L);
		store.setProfile("main");
		assertEquals(1111L, store.getBoundAccountHash(), "and the original must survive");
	}

	@Test
	@DisplayName("unbinding clears it rather than storing zero")
	void accountHashUnbinds()
	{
		store.setBoundAccountHash(4242L);
		store.setBoundAccountHash(0L);
		assertEquals(0L, store.getBoundAccountHash());
	}

	@Test
	@DisplayName("a corrupt stored value reads as unbound rather than throwing")
	void accountHashCorruptValue()
	{
		configManager.setConfiguration("goalplanner", "main.accountHash", "not-a-number");
		assertEquals(0L, store.getBoundAccountHash(),
			"a garbled binding must fail open to adoption, not crash the tracker gate");
	}

	@Test
	@DisplayName("binding rejects non-positive hashes, so a logged-out sentinel cannot unbind a goal set")
	void accountHashIgnoresSentinels()
	{
		store.setBoundAccountHash(9999L);
		// -1 and 0 are both "no account" shapes. Neither should be storable as a
		// real binding; setBoundAccountHash(0) is the explicit unbind.
		store.setBoundAccountHash(0L);
		assertEquals(0L, store.getBoundAccountHash(), "0 unbinds");

		store.setBoundAccountHash(9999L);
		assertEquals(9999L, store.getBoundAccountHash(), "a real hash still binds");
	}

	// ====================================================================
	// Per-character namespaces — profile + account as the key to everything
	// ====================================================================

	@Test
	@DisplayName("two characters on one profile keep fully separate plans")
	void accountsAreSeparate()
	{
		store.setAccount(111L);
		Goal mains = Goal.builder().type(GoalType.CUSTOM).name("Main's goal").build();
		store.addGoal(mains);

		store.setAccount(222L);
		assertNull(store.findGoalById(mains.getId()),
			"testpurr must not see the main's goals");
		Goal alts = Goal.builder().type(GoalType.CUSTOM).name("Alt's goal").build();
		store.addGoal(alts);

		store.setAccount(111L);
		assertNotNull(store.findGoalById(mains.getId()), "switching back restores the main's plan");
		assertNull(store.findGoalById(alts.getId()));
	}

	@Test
	@DisplayName("the first character to log in adopts the pre-account plan; the second starts fresh")
	void firstLoginAdoptsExistingPlan()
	{
		// Pre-upgrade state: goals live profile-scoped, no account dimension.
		Goal existing = Goal.builder().type(GoalType.CUSTOM).name("Pre-upgrade goal").build();
		store.addGoal(existing);
		store.save();

		store.setAccount(111L);
		assertNotNull(store.findGoalById(existing.getId()),
			"the existing plan must survive the upgrade - losing it is the one unforgivable failure");

		// The adopt-then-delete is what makes the second character fresh:
		// if the profile-scoped source were left behind, every new character
		// would re-adopt the same goals.
		store.setAccount(222L);
		assertNull(store.findGoalById(existing.getId()),
			"the second character must not re-adopt the first one's plan");
	}

	@Test
	@DisplayName("adopted data survives a full reload from disk")
	void adoptionIsPersistent()
	{
		Goal existing = Goal.builder().type(GoalType.CUSTOM).name("Persistent").build();
		store.addGoal(existing);
		store.save();
		store.setAccount(111L);

		GoalStore fresh = new GoalStore(configManager, new com.google.gson.Gson());
		fresh.load();
		fresh.setAccount(111L);
		assertNotNull(fresh.findGoalById(existing.getId()),
			"migration must move the persisted keys, not just the in-memory list");
	}

	@Test
	@DisplayName("the last character is remembered per profile, so startup can restore it")
	void lastAccountPointer()
	{
		assertEquals(0L, store.getLastAccount(), "fresh install: nothing recorded");
		store.setAccount(111L);
		assertEquals(111L, store.getLastAccount());

		GoalStore fresh = new GoalStore(configManager, new com.google.gson.Gson());
		fresh.load();
		assertEquals(111L, fresh.getLastAccount(), "the pointer must survive a restart");
	}

	@Test
	@DisplayName("non-positive hashes never switch the namespace")
	void sentinelsIgnored()
	{
		store.setAccount(111L);
		Goal g = Goal.builder().type(GoalType.CUSTOM).name("Held").build();
		store.addGoal(g);

		store.setAccount(0L);
		store.setAccount(-1L);
		assertEquals(111L, store.getActiveAccount(),
			"a logged-out sentinel must not silently switch whose plan is in memory");
		assertNotNull(store.findGoalById(g.getId()));
	}

	@Test
	@DisplayName("profile and account compose: the same character has separate main and leagues plans")
	void profileAndAccountCompose()
	{
		store.setAccount(111L);
		Goal mainGoal = Goal.builder().type(GoalType.CUSTOM).name("Main-world goal").build();
		store.addGoal(mainGoal);

		store.setProfile("leagues");
		assertNull(store.findGoalById(mainGoal.getId()),
			"leagues.a111 is a different plan from main.a111");
		assertEquals(111L, store.getActiveAccount(),
			"a world hop changes the profile axis, not the character axis");

		store.setProfile("main");
		assertNotNull(store.findGoalById(mainGoal.getId()));
	}

	// ====================================================================
	// Re-import protection — per-character import history
	// ====================================================================

	@Test
	@DisplayName("an imported code is remembered; an unseen one is not")
	void importHistoryRemembers()
	{
		assertFalse(store.wasCodeImported("GPSHARE2:abc"));
		store.rememberImportedCode("GPSHARE2:abc");
		assertTrue(store.wasCodeImported("GPSHARE2:abc"));
		assertFalse(store.wasCodeImported("GPSHARE2:other"));

		GoalStore fresh = new GoalStore(configManager, new com.google.gson.Gson());
		fresh.load();
		assertTrue(fresh.wasCodeImported("GPSHARE2:abc"), "history must survive a restart");
	}

	@Test
	@DisplayName("import history is per character - your alt has not seen your main's codes")
	void importHistoryIsPerCharacter()
	{
		store.setAccount(111L);
		store.rememberImportedCode("GPSHARE2:routine");
		assertTrue(store.wasCodeImported("GPSHARE2:routine"));

		store.setAccount(222L);
		assertFalse(store.wasCodeImported("GPSHARE2:routine"),
			"a code imported on the main is fresh for the alt - its plan never saw it");

		store.setAccount(111L);
		assertTrue(store.wasCodeImported("GPSHARE2:routine"));
	}

	@Test
	@DisplayName("history is capped, oldest first out")
	void importHistoryCapped()
	{
		for (int i = 0; i < 55; i++) store.rememberImportedCode("code-" + i);
		assertFalse(store.wasCodeImported("code-0"), "oldest must have fallen off the cap");
		assertTrue(store.wasCodeImported("code-54"));
	}

	@Test
	@DisplayName("null, empty, and corrupt stored history all fail open")
	void importHistoryFailsOpen()
	{
		assertFalse(store.wasCodeImported(null));
		assertFalse(store.wasCodeImported(""));
		store.rememberImportedCode(null); // no-op, no throw

		configManager.setConfiguration("goalplanner", "main.importedCodes", "not-json[");
		assertFalse(store.wasCodeImported("GPSHARE2:abc"),
			"corrupt history means one missed warning, never a crash");
	}
}

package com.goalplanner.persistence;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import com.goalplanner.testsupport.InMemoryConfigManager;
import com.google.gson.Gson;
import java.util.Arrays;
import java.util.List;
import net.runelite.client.config.ConfigManager;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

@DisplayName("SavedPlanStore — saved share-code library (per config profile)")
class SavedPlanStoreTest
{
	private ConfigManager config;
	private SavedPlanStore store;

	@BeforeEach
	void setUp()
	{
		config = InMemoryConfigManager.create();
		store = new SavedPlanStore(config, new Gson());
		store.load();
	}

	@Test
	@DisplayName("add() stores a plan, assigns an id, and keeps fields")
	void addStores()
	{
		SavedPlan p = store.add("Inferno prep", "GPSHARE1:abc", Arrays.asList("Slayer"));
		assertNotNull(p.getId());
		assertEquals(1, store.getPlans().size());
		SavedPlan got = store.getPlans().get(0);
		assertEquals("Inferno prep", got.getName());
		assertEquals("GPSHARE1:abc", got.getCode());
		assertEquals(List.of("Slayer"), got.getSectionNames());
	}

	@Test
	@DisplayName("persists across a fresh load (key not prefixed with main/leagues)")
	void persistsAcrossReload()
	{
		store.add("Plan A", "GPSHARE1:aaa", Arrays.asList("A"));
		store.add("Plan B", "GPSHARE1:bbb", Arrays.asList("B"));

		SavedPlanStore reopened = new SavedPlanStore(config, new Gson());
		reopened.load();
		assertEquals(2, reopened.getPlans().size());
		assertEquals("Plan A", reopened.getPlans().get(0).getName());
		assertEquals("Plan B", reopened.getPlans().get(1).getName());
	}

	@Test
	@DisplayName("reload() re-reads the library after the backing store changes (profile switch)")
	void reloadRereadsLibrary()
	{
		SavedPlan a = store.add("Plan A", "GPSHARE1:aaa", null);

		// A second store on the SAME config stands in for RuneLite swapping the
		// active profile's backing store underneath us: it removes A and adds B.
		SavedPlanStore other = new SavedPlanStore(config, new Gson());
		other.load();
		other.remove(a.getId());
		other.add("Plan B", "GPSHARE1:bbb", null);

		// Stale until reload: our store still shows A and has never seen B.
		assertEquals(1, store.getPlans().size());
		assertEquals("Plan A", store.getPlans().get(0).getName());

		store.reload();

		assertEquals(1, store.getPlans().size());
		assertEquals("Plan B", store.getPlans().get(0).getName());
	}

	@Test
	@DisplayName("rename and setSectionNames mutate and persist")
	void renameAndOverridesPersist()
	{
		SavedPlan p = store.add("old", "GPSHARE1:x", Arrays.asList("S1"));
		assertTrue(store.rename(p.getId(), "new name"));
		assertTrue(store.setSectionNames(p.getId(), Arrays.asList("Renamed Section")));

		SavedPlanStore reopened = new SavedPlanStore(config, new Gson());
		reopened.load();
		SavedPlan loaded = reopened.getPlans().get(0);
		assertEquals("new name", loaded.getName());
		assertEquals(List.of("Renamed Section"), loaded.getSectionNames());
	}

	@Test
	@DisplayName("rename/setSectionNames on an unknown id is a no-op returning false")
	void unknownIdNoOp()
	{
		assertFalse(store.rename("nope", "x"));
		assertFalse(store.setSectionNames("nope", Arrays.asList("y")));
	}

	@Test
	@DisplayName("remove deletes by id; unknown id returns false")
	void removeById()
	{
		SavedPlan p = store.add("x", "GPSHARE1:x", null);
		assertFalse(store.remove("nope"));
		assertEquals(1, store.getPlans().size());
		assertTrue(store.remove(p.getId()));
		assertTrue(store.getPlans().isEmpty());
	}

	@Test
	@DisplayName("corrupt config value loads an empty library without throwing")
	void corruptLoadsEmpty()
	{
		config.setConfiguration("goalplanner", "savedPlans", "{not valid json");
		SavedPlanStore s = new SavedPlanStore(config, new Gson());
		s.load();
		assertTrue(s.getPlans().isEmpty());
	}
}

package com.goalplanner.prototype;

import com.goalplanner.share.GoalShareDto;
import com.goalplanner.share.ShareBundle;
import com.goalplanner.share.ShareCodec;
import com.google.gson.Gson;
import org.junit.jupiter.api.Test;

import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.Arrays;
import java.util.List;

/**
 * Generator (not a real assertion test) — emits a GPSHARE1 share code for the
 * dependency-rail example (diamond + OR) so it can be imported into the live
 * plugin. Writes the code to build/share-code.txt and prints it.
 */
class ShareCodeGenTest
{
	private static GoalShareDto custom(int ref, String name, List<Integer> requires, List<Integer> orRequires)
	{
		GoalShareDto d = new GoalShareDto();
		d.setRef(ref);
		d.setType("CUSTOM");
		d.setName(name);
		d.setTargetValue(1);
		if (requires != null) d.setRequires(requires);
		if (orRequires != null) d.setOrRequires(orRequires);
		return d;
	}

	@Test
	void generate() throws Exception
	{
		// Interconnected diamonds: 3 skills each feed 2 of 3 quests, all merge
		// into Quest Cape; Grandmaster CA needs that AND (Fire OR Infernal).
		List<GoalShareDto> goals = Arrays.asList(
			custom(0, "70 Agility", null, null),
			custom(1, "100 Combat", null, null),
			custom(2, "75 Ranged", null, null),
			custom(3, "Monkey Madness II", Arrays.asList(0, 1), null),     // Agility + Combat
			custom(4, "Desert Treasure II", Arrays.asList(1, 2), null),    // Combat + Ranged
			custom(5, "Song of the Elves", Arrays.asList(0, 2), null),     // Agility + Ranged
			custom(6, "Quest Point Cape", Arrays.asList(3, 4, 5), null),   // merge of all three
			custom(7, "Fire Cape", null, null),
			custom(8, "Infernal Cape", null, null),
			custom(9, "Grandmaster CA", Arrays.asList(6), Arrays.asList(7, 8)) // QPC AND (Fire OR Infernal)
		);

		ShareBundle bundle = new ShareBundle();
		bundle.setKind(ShareBundle.Kind.SECTION);
		bundle.setSectionName("Dependency Demo");
		bundle.setSharedBy("rail prototype");
		bundle.setGoals(goals);

		String code = new ShareCodec(new Gson()).encode(bundle);

		Path out = Paths.get("build", "share-code.txt");
		Files.createDirectories(out.getParent());
		Files.write(out, code.getBytes());
		System.out.println("SHARE_CODE=" + code);
	}
}

package com.goalplanner.service;

import com.goalplanner.model.Goal;
import com.goalplanner.model.GoalStatus;
import com.goalplanner.model.GoalType;
import com.goalplanner.persistence.GoalStore;
import org.junit.Before;
import org.junit.Test;

import java.util.List;

import static org.junit.Assert.*;

/**
 * Tests for GoalReorderingService.
 * Uses a TestGoalStore that doesn't need ConfigManager.
 */
public class GoalReorderingServiceTest
{
	private TestGoalStore goalStore;
	private GoalReorderingService service;

	@Before
	public void setUp()
	{
		goalStore = new TestGoalStore();
		service = new GoalReorderingService(goalStore);
	}

	// ---- moveGoal: basic movement ----

	@Test
	public void testMoveGoalDown()
	{
		goalStore.addGoal(makeSkill("Prayer", 99));
		goalStore.addGoal(makeSkill("Attack", 94));
		goalStore.addGoal(makeCustom("Custom goal"));

		service.moveGoal(0, 1); // Move Prayer down

		List<Goal> goals = goalStore.getGoals();
		assertEquals("Attack", goals.get(0).getSkillName());
		assertEquals("Prayer", goals.get(1).getSkillName());
	}

	@Test
	public void testMoveGoalUp()
	{
		goalStore.addGoal(makeCustom("First"));
		goalStore.addGoal(makeCustom("Second"));
		goalStore.addGoal(makeCustom("Third"));

		service.moveGoal(2, 1); // Move Third up

		assertEquals("Third", goalStore.getGoals().get(1).getName());
		assertEquals("Second", goalStore.getGoals().get(2).getName());
	}

	// ---- moveGoal: skill chain behavior ----

	@Test
	public void testMoveSkillDownPastPartner()
	{
		// [Prayer99, Attack94, Attack99, Ranged99]
		goalStore.addGoal(makeSkill("Prayer", xpFor(99)));
		goalStore.addGoal(makeSkill("Attack", xpFor(94)));
		goalStore.addGoal(makeSkill("Attack", xpFor(99)));
		goalStore.addGoal(makeSkill("Ranged", xpFor(99)));

		// Click DOWN on Attack94 — should push Attack99 down first, then move Attack94
		service.moveGoal(1, 2);

		List<Goal> goals = goalStore.getGoals();
		// Expected: [Prayer99, Ranged99, Attack94, Attack99]
		assertEquals("Prayer", goals.get(0).getSkillName());
		assertEquals("Ranged", goals.get(1).getSkillName());
		assertEquals("Attack", goals.get(2).getSkillName());
		assertTrue(goals.get(2).getTargetValue() < goals.get(3).getTargetValue());
		assertEquals("Attack", goals.get(3).getSkillName());
	}

	@Test
	public void testMoveSkillUpPastPartner()
	{
		// [Prayer99, Attack94, Attack99, Ranged99]
		goalStore.addGoal(makeSkill("Prayer", xpFor(99)));
		goalStore.addGoal(makeSkill("Attack", xpFor(94)));
		goalStore.addGoal(makeSkill("Attack", xpFor(99)));
		goalStore.addGoal(makeSkill("Ranged", xpFor(99)));

		// Click UP on Attack99 — should push Attack94 up first, then move Attack99
		service.moveGoal(2, 1);

		List<Goal> goals = goalStore.getGoals();
		// Expected: [Attack94, Attack99, Prayer99, Ranged99]
		assertEquals("Attack", goals.get(0).getSkillName());
		assertEquals("Attack", goals.get(1).getSkillName());
		assertTrue(goals.get(0).getTargetValue() < goals.get(1).getTargetValue());
		assertEquals("Prayer", goals.get(2).getSkillName());
	}

	@Test
	public void testMoveUnrelatedGoalThroughChain()
	{
		// [Attack94, Attack99, Prayer99]
		goalStore.addGoal(makeSkill("Attack", xpFor(94)));
		goalStore.addGoal(makeSkill("Attack", xpFor(99)));
		goalStore.addGoal(makeSkill("Prayer", xpFor(99)));

		// Move Prayer up — should just swap with Attack99 (unrelated)
		service.moveGoal(2, 1);

		List<Goal> goals = goalStore.getGoals();
		assertEquals("Attack", goals.get(0).getSkillName());
		assertEquals("Prayer", goals.get(1).getSkillName());
		assertEquals("Attack", goals.get(2).getSkillName());
	}

	// ---- moveGoalTo: direct placement ----

	@Test
	public void testMoveToTopEnforcesOrdering()
	{
		goalStore.addGoal(makeSkill("Prayer", xpFor(99)));
		goalStore.addGoal(makeSkill("Attack", xpFor(94)));
		goalStore.addGoal(makeSkill("Attack", xpFor(99)));

		// Move Attack99 to top — should enforce Attack94 above Attack99
		service.moveGoalTo(2, 0);

		List<Goal> goals = goalStore.getGoals();
		// Attack94 must be above Attack99
		int idx94 = -1, idx99 = -1;
		for (int i = 0; i < goals.size(); i++)
		{
			if ("Attack".equals(goals.get(i).getSkillName()))
			{
				if (goals.get(i).getTargetValue() == xpFor(94)) idx94 = i;
				if (goals.get(i).getTargetValue() == xpFor(99)) idx99 = i;
			}
		}
		assertTrue("94 Attack should be above 99 Attack", idx94 < idx99);
	}

	// ---- findInsertionIndex ----

	@Test
	public void testFindInsertionIndex()
	{
		goalStore.addGoal(makeSkill("Prayer", xpFor(99)));
		goalStore.addGoal(makeSkill("Attack", xpFor(99)));

		// Adding Attack94 should go before Attack99 — same section as the
		// existing goals (Incomplete, the default for goalStore.addGoal).
		String sectionId = goalStore.getIncompleteSection().getId();
		int idx = service.findInsertionIndex("Attack", xpFor(94), sectionId);
		assertEquals(1, idx);
	}

	@Test
	public void testFindInsertionIndexNoMatch()
	{
		goalStore.addGoal(makeSkill("Prayer", xpFor(99)));

		// No existing Attack goals in the Incomplete section
		String sectionId = goalStore.getIncompleteSection().getId();
		int idx = service.findInsertionIndex("Attack", xpFor(94), sectionId);
		assertEquals(-1, idx);
	}

	// ---- Helpers ----

	private static int xpFor(int level)
	{
		// Simplified XP values for testing
		if (level == 94) return 8_771_558;
		if (level == 99) return 13_034_431;
		return level * 100_000;
	}

	private static Goal makeSkill(String skillName, int targetXp)
	{
		return Goal.builder()
			.type(GoalType.SKILL)
			.name(skillName + " goal")
			.skillName(skillName)
			.targetValue(targetXp)
			.build();
	}

	private static Goal makeCustom(String name)
	{
		return Goal.builder()
			.type(GoalType.CUSTOM)
			.name(name)
			.targetValue(1)
			.build();
	}

	/**
	 * Simple GoalStore for testing that doesn't need ConfigManager.
	 */
	private static class TestGoalStore extends GoalStore
	{
		private final java.util.List<Goal> goals = new java.util.ArrayList<>();

		public TestGoalStore()
		{
			super(null, new com.google.gson.Gson()); // no ConfigManager needed
		}

		@Override
		public void load() {}

		@Override
		public void save() {}

		@Override
		public java.util.List<Goal> getGoals()
		{
			return goals;
		}

		@Override
		public void addGoal(Goal goal)
		{
			// Mirror real GoalStore.addGoal: drop into Incomplete by default so
			// section-scoped reordering logic has a section to operate on.
			if (goal.getSectionId() == null)
			{
				goal.setSectionId(getIncompleteSection().getId());
			}
			goal.setPriority(goals.size());
			goals.add(goal);
		}

		@Override
		public void removeGoal(String goalId)
		{
			goals.removeIf(g -> g.getId().equals(goalId));
		}

		@Override
		public void reorder(int fromIndex, int toIndex)
		{
			if (fromIndex < 0 || fromIndex >= goals.size() || toIndex < 0 || toIndex >= goals.size())
			{
				return;
			}
			Goal moved = goals.remove(fromIndex);
			goals.add(toIndex, moved);
		}
	}
}

package com.goalplanner.service;

import com.goalplanner.ResetBoundary;
import com.goalplanner.model.Goal;
import com.goalplanner.model.GoalType;
import com.goalplanner.model.RepeatPeriod;
import com.goalplanner.model.Section;
import com.goalplanner.persistence.GoalStore;
import com.goalplanner.testsupport.InMemoryConfigManager;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneOffset;
import net.runelite.client.config.ConfigManager;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Rollover behaviour against the real {@link GoalStore}. The clock is passed
 * in, so "it is now tomorrow" is a parameter rather than a wait.
 */
class RepeatResetServiceTest
{
	private GoalStore store;
	private RepeatResetService service;

	private static final Instant MONDAY_NOON =
		LocalDate.of(2026, 7, 27).atTime(12, 0).atZone(ZoneOffset.UTC).toInstant();

	@BeforeEach
	void setUp()
	{
		ConfigManager configManager = InMemoryConfigManager.create();
		store = new GoalStore(configManager, new com.google.gson.Gson());
		store.load();
		service = new RepeatResetService(store);
	}

	private Goal dailyGoal(String name)
	{
		Goal g = Goal.builder()
			.type(GoalType.CUSTOM)
			.name(name)
			.repeatEvery(RepeatPeriod.DAILY)
			.build();
		store.addGoal(g);
		return g;
	}

	private int run(Instant now)
	{
		return service.applyResets(now, ResetBoundary.GAME_RESET, 0);
	}

	@Test
	@DisplayName("the first check stamps the period without reopening a done goal")
	void firstCheckStampsWithoutResetting()
	{
		Goal g = dailyGoal("5 Mahogany Homes contracts");
		g.setCompletedAt(MONDAY_NOON.toEpochMilli());

		assertEquals(0, run(MONDAY_NOON), "an unstamped goal must not reset on sight");
		assertTrue(g.isComplete(), "marking something repeatable while it is done leaves it done");
		assertTrue(g.getLastPeriodKey() != 0, "it should now be stamped");
	}

	@Test
	@DisplayName("crossing midnight reopens a completed daily")
	void rollsOverAtMidnight()
	{
		Goal g = dailyGoal("15 Pest Control games");
		run(MONDAY_NOON);
		g.setCompletedAt(MONDAY_NOON.toEpochMilli());

		assertEquals(1, run(MONDAY_NOON.plusSeconds(86_400)));
		assertFalse(g.isComplete(), "the next day it should be ready again");
	}

	@Test
	@DisplayName("running repeatedly inside one period does nothing")
	void idempotentWithinPeriod()
	{
		Goal g = dailyGoal("10 CG runs");
		run(MONDAY_NOON);
		g.setCompletedAt(MONDAY_NOON.toEpochMilli());

		assertEquals(0, run(MONDAY_NOON.plusSeconds(60)));
		assertEquals(0, run(MONDAY_NOON.plusSeconds(3600)));
		assertTrue(g.isComplete(), "a mid-period check must not disturb a completed goal");
	}

	@Test
	@DisplayName("five days offline reopens the goal once, not five times")
	void fiveDaysOfflineResetsOnce()
	{
		Goal g = dailyGoal("300 chinchompas");
		run(MONDAY_NOON);
		g.setCompletedAt(MONDAY_NOON.toEpochMilli());

		assertEquals(1, run(MONDAY_NOON.plusSeconds(5 * 86_400)));
		assertFalse(g.isComplete());
		// And the catch-up leaves it correctly stamped, not lagging four days.
		assertEquals(0, run(MONDAY_NOON.plusSeconds(5 * 86_400 + 60)));
	}

	@Test
	@DisplayName("an incomplete repeatable goal is left alone but still re-stamped")
	void incompleteGoalJustRestamps()
	{
		Goal g = dailyGoal("100 MTA points");
		run(MONDAY_NOON);
		long stamped = g.getLastPeriodKey();

		assertEquals(0, run(MONDAY_NOON.plusSeconds(86_400)),
			"nothing was completed, so nothing was reset");
		assertTrue(g.getLastPeriodKey() > stamped, "but the period did advance");
	}

	@Test
	@DisplayName("non-repeating goals are never touched")
	void oneShotGoalsUntouched()
	{
		Goal once = Goal.builder().type(GoalType.CUSTOM).name("Quest cape").build();
		store.addGoal(once);
		once.setCompletedAt(MONDAY_NOON.toEpochMilli());

		run(MONDAY_NOON);
		assertEquals(0, run(MONDAY_NOON.plusSeconds(30 * 86_400)));
		assertTrue(once.isComplete(), "a one-shot goal must stay completed forever");
	}

	@Test
	@DisplayName("a weekly goal survives a day rollover and resets on Wednesday")
	void weeklyIgnoresDailyBoundary()
	{
		Goal g = Goal.builder().type(GoalType.CUSTOM).name("Weekly raid")
			.repeatEvery(RepeatPeriod.WEEKLY).build();
		store.addGoal(g);
		run(MONDAY_NOON);
		g.setCompletedAt(MONDAY_NOON.toEpochMilli());

		// Tuesday: same week, still done.
		assertEquals(0, run(MONDAY_NOON.plusSeconds(86_400)));
		assertTrue(g.isComplete());

		// Wednesday: new week.
		assertEquals(1, run(MONDAY_NOON.plusSeconds(2 * 86_400)));
		assertFalse(g.isComplete());
	}

	@Test
	@DisplayName("a completed repeatable goal stays in Repeatable, never Completed")
	void completedRepeatableStaysPut()
	{
		Goal g = dailyGoal("5 Mahogany Homes contracts");
		store.reconcileDerivedSections();
		String repeatableId = store.getRepeatableSection().getId();
		assertEquals(repeatableId, g.getSectionId());

		g.setCompletedAt(MONDAY_NOON.toEpochMilli());
		store.reconcileDerivedSections();

		assertEquals(repeatableId, g.getSectionId(),
			"a checked-off daily must not graduate to Completed");
	}

	@Test
	@DisplayName("a repeatable goal never lands in Completed, which is what lets both mechanisms share archivedFromSectionId")
	void archivedFromInvariant()
	{
		Section home = store.createUserSection("Bossing");
		Goal g = Goal.builder().type(GoalType.CUSTOM).name("10 CG runs")
			.sectionId(home.getId()).repeatEvery(RepeatPeriod.DAILY).build();
		store.addGoal(g);

		store.reconcileDerivedSections();
		assertEquals(store.getRepeatableSection().getId(), g.getSectionId());
		assertEquals(home.getId(), g.getArchivedFromSectionId(),
			"the home section must be remembered so turning repeat off can restore it");

		// Complete it, then confirm it still is not in Completed - if it ever
		// were, the shared home-memory field would be serving two masters.
		g.setCompletedAt(MONDAY_NOON.toEpochMilli());
		store.reconcileDerivedSections();
		assertEquals(store.getRepeatableSection().getId(), g.getSectionId());
		assertEquals(home.getId(), g.getArchivedFromSectionId());
	}

	@Test
	@DisplayName("turning repeat off returns the goal to the section it came from")
	void repeatOffRestoresHome()
	{
		Section home = store.createUserSection("Bossing");
		Goal g = Goal.builder().type(GoalType.CUSTOM).name("10 CG runs")
			.sectionId(home.getId()).repeatEvery(RepeatPeriod.DAILY).build();
		store.addGoal(g);
		store.reconcileDerivedSections();

		g.setRepeatEvery(RepeatPeriod.NONE);
		store.reconcileDerivedSections();

		assertEquals(home.getId(), g.getSectionId());
	}

	@Test
	@DisplayName("a goal persisted before repetition existed deserializes as non-repeating, not null")
	void legacyGoalHasNoNullPeriod()
	{
		// Gson bypasses Lombok's @Builder.Default and leaves absent fields null.
		Goal legacy = Goal.builder().type(GoalType.CUSTOM).name("Old goal").build();
		legacy.setRepeatEvery(null);
		store.addGoal(legacy);

		assertEquals(RepeatPeriod.NONE, legacy.getRepeatEvery());
		assertFalse(legacy.isRepeating());
		assertEquals(0, run(MONDAY_NOON), "a legacy goal must not be swept into rollover");
	}

	// ====================================================================
	// Derived "gain N per period" goals over a cumulative counter
	// ====================================================================

	/** A daily "gain N more" goal sitting on a cumulative tracker value. */
	private Goal chunkGoal(int alreadyAt, int chunk)
	{
		Goal g = Goal.builder()
			.type(GoalType.BOSS)
			.name("Kill General Graardor")
			.bossName("General Graardor")
			.repeatEvery(RepeatPeriod.DAILY)
			.repeatChunk(chunk)
			.currentValue(alreadyAt)
			.targetValue(alreadyAt + chunk)
			.build();
		store.addGoal(g);
		return g;
	}

	@Test
	@DisplayName("rollover moves the target forward instead of clearing cumulative progress")
	void chunkGoalRebasesTarget()
	{
		Goal g = chunkGoal(1847, 20);
		run(MONDAY_NOON);                    // first stamp, no rollover
		g.setCurrentValue(1867);             // player got their 20 kills
		g.setCompletedAt(System.currentTimeMillis());
		g.setStatus(com.goalplanner.model.GoalStatus.COMPLETE);

		assertEquals(1, run(MONDAY_NOON.plus(java.time.Duration.ofDays(1))));

		assertEquals(1867, g.getCurrentValue(),
			"lifetime kill count must NOT be cleared - the tracker would just write it back");
		assertEquals(1887, g.getTargetValue(), "target must re-base to current + chunk");
		assertFalse(g.isComplete(), "re-basing past the progress must reopen the goal");
	}

	@Test
	@DisplayName("an untouched chunk goal still re-bases, so a skipped day is not owed back")
	void chunkGoalRebasesEvenWhenIgnored()
	{
		Goal g = chunkGoal(1000, 50);
		run(MONDAY_NOON);
		// Player never logs in; progress stays at 1000.
		run(MONDAY_NOON.plus(java.time.Duration.ofDays(1)));

		assertEquals(1050, g.getTargetValue(),
			"a missed day re-bases to today's 50, it does not accumulate to 100");
	}

	@Test
	@DisplayName("a plain manual repeat still clears its progress")
	void manualRepeatStillClears()
	{
		Goal g = dailyGoal("5 Mahogany Homes contracts");
		run(MONDAY_NOON);
		g.setCurrentValue(5);
		g.setCompletedAt(System.currentTimeMillis());
		g.setStatus(com.goalplanner.model.GoalStatus.COMPLETE);

		run(MONDAY_NOON.plus(java.time.Duration.ofDays(1)));

		assertEquals(0, g.getCurrentValue(), "a chunk-less repeat has nothing cumulative to keep");
		assertFalse(g.isComplete());
	}

	@Test
	@DisplayName("a repeatable goal displays progress within the period, not the lifetime total")
	void chunkGoalDisplaysPeriodProgress()
	{
		// 9.8M XP account, daily 10k chunk: the day's work must be visible.
		Goal g = Goal.builder()
			.type(GoalType.SKILL).name("Woodcutting +10,000 XP").skillName("WOODCUTTING")
			.repeatEvery(RepeatPeriod.DAILY).repeatChunk(10_000)
			.currentValue(9_800_000).targetValue(9_810_000)
			.build();
		store.addGoal(g);

		assertEquals(0, g.getDisplayCurrent(), "fresh period reads 0, not 9.8M");
		assertEquals(10_000, g.getDisplayTarget());

		g.setCurrentValue(9_803_500);
		assertEquals(3_500, g.getDisplayCurrent());

		g.setCurrentValue(9_810_000);
		assertEquals(10_000, g.getDisplayCurrent(), "a finished period reads full");
	}

	@Test
	@DisplayName("display progress clamps rather than going negative or overflowing")
	void chunkDisplayClamps()
	{
		Goal g = Goal.builder()
			.type(GoalType.BOSS).name("General Graardor x20").bossName("General Graardor")
			.repeatEvery(RepeatPeriod.DAILY).repeatChunk(20)
			.currentValue(1847).targetValue(1867)
			.build();
		store.addGoal(g);

		// Overshoot: the tracker can report past the target between ticks.
		g.setCurrentValue(1875);
		assertEquals(20, g.getDisplayCurrent(), "must not read above the chunk");

		// Below the period start, which a stale read can produce.
		g.setCurrentValue(1800);
		assertEquals(0, g.getDisplayCurrent(), "must not read negative");
	}

	@Test
	@DisplayName("a non-chunk goal displays its raw values unchanged")
	void plainGoalDisplayUnchanged()
	{
		Goal g = Goal.builder()
			.type(GoalType.SKILL).name("Woodcutting - Level 99").skillName("WOODCUTTING")
			.currentValue(9_800_000).targetValue(13_034_431)
			.build();
		store.addGoal(g);

		assertEquals(9_800_000, g.getDisplayCurrent());
		assertEquals(13_034_431, g.getDisplayTarget());
	}

	@Test
	@DisplayName("after a rollover the display resets to zero of the new chunk")
	void displayResetsAfterRollover()
	{
		Goal g = chunkGoal(1847, 20);
		run(MONDAY_NOON);
		g.setCurrentValue(1867);
		assertEquals(20, g.getDisplayCurrent(), "period complete");

		run(MONDAY_NOON.plus(java.time.Duration.ofDays(1)));

		assertEquals(0, g.getDisplayCurrent(), "new period starts empty");
		assertEquals(20, g.getDisplayTarget());
	}

	// ====================================================================
	// An imported repeatable sizes itself against the RECIPIENT
	// ====================================================================

	@Test
	@DisplayName("an imported repeatable sizes itself off the recipient's progress, not the sender's")
	void importedRepeatableSizesToRecipient()
	{
		// Shape a share code from someone at 9.8M Prayer with a 10k daily
		// produces: chunk travels, target arrives as 0 ("not yet sized").
		Goal imported = Goal.builder()
			.type(GoalType.SKILL).name("Prayer +10K XP").skillName("PRAYER")
			.repeatEvery(RepeatPeriod.DAILY).repeatChunk(10_000)
			.targetValue(0).currentValue(0)
			.build();
		store.addGoal(imported);
		assertFalse(imported.meetsTarget(), "an unsized goal must never look complete");

		// The recipient has 2M Prayer XP. First tracker read sizes it.
		com.goalplanner.api.GoalPlannerApiImpl api = new com.goalplanner.api.GoalPlannerApiImpl(
			store, new com.goalplanner.service.GoalReorderingService(store),
			org.mockito.Mockito.mock(net.runelite.client.game.ItemManager.class),
			org.mockito.Mockito.mock(com.goalplanner.data.WikiCaRepository.class));
		api.recordGoalProgress(imported.getId(), 2_000_000);

		assertEquals(2_010_000, imported.getTargetValue(),
			"must be THEIR 2M + 10k, never the sender's 9,810,000");
		assertEquals(10_000, imported.getDisplayTarget());
		assertEquals(0, imported.getDisplayCurrent(), "they start the period at zero");
		assertFalse(imported.isComplete());
	}

	@Test
	@DisplayName("a boss repeatable imported at zero kills sizes to the chunk itself")
	void importedBossFromZero()
	{
		Goal imported = Goal.builder()
			.type(GoalType.BOSS).name("General Graardor x20").bossName("General Graardor")
			.repeatEvery(RepeatPeriod.DAILY).repeatChunk(20)
			.targetValue(0).currentValue(0)
			.build();
		store.addGoal(imported);

		com.goalplanner.api.GoalPlannerApiImpl api = new com.goalplanner.api.GoalPlannerApiImpl(
			store, new com.goalplanner.service.GoalReorderingService(store),
			org.mockito.Mockito.mock(net.runelite.client.game.ItemManager.class),
			org.mockito.Mockito.mock(com.goalplanner.data.WikiCaRepository.class));
		api.recordGoalProgress(imported.getId(), 0);

		assertEquals(20, imported.getTargetValue(), "never killed it: the next 20 is just 20");
		assertFalse(imported.isComplete());
	}

	@Test
	@DisplayName("sizing happens once - a later read does not re-size and wipe progress")
	void sizingIsOneShot()
	{
		Goal imported = Goal.builder()
			.type(GoalType.SKILL).name("Prayer +10K XP").skillName("PRAYER")
			.repeatEvery(RepeatPeriod.DAILY).repeatChunk(10_000)
			.targetValue(0).currentValue(0)
			.build();
		store.addGoal(imported);

		com.goalplanner.api.GoalPlannerApiImpl api = new com.goalplanner.api.GoalPlannerApiImpl(
			store, new com.goalplanner.service.GoalReorderingService(store),
			org.mockito.Mockito.mock(net.runelite.client.game.ItemManager.class),
			org.mockito.Mockito.mock(com.goalplanner.data.WikiCaRepository.class));
		api.recordGoalProgress(imported.getId(), 2_000_000);
		api.recordGoalProgress(imported.getId(), 2_004_000);

		assertEquals(2_010_000, imported.getTargetValue(), "the target must not chase the progress");
		assertEquals(4_000, imported.getDisplayCurrent(), "and the period's progress accrues");
	}
}

package com.goalplanner.share;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

@DisplayName("SavedPlanSections — read & override a bundle's section display names")
class SavedPlanSectionsTest
{
	private static SectionShareDto section(String name)
	{
		SectionShareDto s = new SectionShareDto();
		s.setName(name);
		s.setGoals(new ArrayList<>());
		return s;
	}

	@Test
	@DisplayName("reads names from a v2 multi-section bundle")
	void readsV2Names()
	{
		ShareBundle b = new ShareBundle();
		b.setSections(Arrays.asList(section("Slayer"), section("Bossing")));
		assertEquals(Arrays.asList("Slayer", "Bossing"), SavedPlanSections.sectionNamesOf(b));
	}

	@Test
	@DisplayName("overrides per-section names in a v2 bundle; blank entry keeps original")
	void overridesV2()
	{
		ShareBundle b = new ShareBundle();
		b.setSections(Arrays.asList(section("Slayer"), section("Bossing")));
		SavedPlanSections.applySectionNames(b, Arrays.asList("My Slayer", "  "));
		assertEquals(Arrays.asList("My Slayer", "Bossing"), SavedPlanSections.sectionNamesOf(b));
	}

	@Test
	@DisplayName("overrides the section name of a v1 single-section bundle")
	void overridesV1Section()
	{
		ShareBundle b = new ShareBundle();
		b.setKind(ShareBundle.Kind.SECTION);
		b.setSectionName("Original");
		SavedPlanSections.applySectionNames(b, Arrays.asList("Renamed"));
		assertEquals(List.of("Renamed"), SavedPlanSections.sectionNamesOf(b));
		assertEquals("Renamed", b.getSectionName());
	}

	@Test
	@DisplayName("naming a loose-goals bundle promotes it to a named section")
	void promotesGoalsToNamedSection()
	{
		ShareBundle b = new ShareBundle();
		b.setKind(ShareBundle.Kind.GOALS);
		b.setGoals(new ArrayList<>());
		// before: effective section name is null (loose goals)
		assertEquals(java.util.Collections.singletonList(null), SavedPlanSections.sectionNamesOf(b));
		SavedPlanSections.applySectionNames(b, Arrays.asList("Banked Plan"));
		assertEquals(ShareBundle.Kind.SECTION, b.getKind());
		assertEquals(List.of("Banked Plan"), SavedPlanSections.sectionNamesOf(b));
	}

	@Test
	@DisplayName("null/empty overrides are a no-op")
	void noOpOnEmpty()
	{
		ShareBundle b = new ShareBundle();
		b.setSections(Arrays.asList(section("Keep")));
		SavedPlanSections.applySectionNames(b, null);
		SavedPlanSections.applySectionNames(b, new ArrayList<>());
		assertEquals(List.of("Keep"), SavedPlanSections.sectionNamesOf(b));
	}
}

package com.goalplanner.share;

import com.google.gson.Gson;
import java.util.Arrays;
import java.util.Base64;
import java.util.Collections;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

/**
 * Round-trip and rejection behaviour for the share-code codec — the
 * compress/uncompress layer that the copy/paste
 * export sit on top of.
 */
public class ShareCodecTest
{
	// new Gson() is forbidden in shipped plugin code but fine in tests.
	private final ShareCodec codec = new ShareCodec(new Gson());

	private static ShareBundle sampleSection()
	{
		TagShareDto tag = new TagShareDto();
		tag.setLabel("Inferno");
		tag.setCategory("OTHER");
		tag.setColorRgb(0xAA3322);

		GoalShareDto ranged = new GoalShareDto();
		ranged.setRef(0);
		ranged.setType("SKILL");
		ranged.setName("Ranged - Level 75");
		ranged.setSkillName("RANGED");
		ranged.setTargetValue(1_210_421);
		ranged.setTags(Collections.singletonList(tag));

		GoalShareDto zuk = new GoalShareDto();
		zuk.setRef(1);
		zuk.setType("BOSS");
		zuk.setName("TzKal-Zuk");
		zuk.setBossName("TzKal-Zuk");
		zuk.setTargetValue(1);
		zuk.setOptional(false);
		// Zuk depends on the Ranged goal — encoded as a bundle-local ref.
		zuk.setRequires(Collections.singletonList(0));

		ShareBundle bundle = new ShareBundle();
		bundle.setKind(ShareBundle.Kind.SECTION);
		bundle.setSharedBy("Andrew");
		bundle.setSectionName("Inferno Prep");
		bundle.setSectionColorRgb(0x112233);
		bundle.setGoals(Arrays.asList(ranged, zuk));
		return bundle;
	}

	@Test
	public void roundTripsASectionBundleLosslessly()
	{
		ShareBundle original = sampleSection();
		ShareBundle decoded = codec.decode(codec.encode(original));
		assertEquals(original, decoded);
	}

	@Test
	public void decodesDespiteEmbeddedWhitespaceFromWrappedPaste()
	{
		// A long code pasted from chat often wraps; the body arrives with newlines
		// and spaces interspersed. Decode must skip them, not truncate at the first.
		String code = codec.encode(sampleSection());
		int p = code.indexOf(':') + 1;
		String wrapped = code.substring(0, p)
			+ code.substring(p, p + 10) + "\n"
			+ code.substring(p + 10, p + 25) + "  \r\n"
			+ code.substring(p + 25) + "\n";
		ShareBundle decoded = codec.decode(wrapped);
		assertNotNull(decoded);
		assertEquals(codec.decode(code), decoded);
	}

	@Test
	public void encodedStringCarriesTheMagicVersionPrefix()
	{
		String code = codec.encode(sampleSection());
		assertTrue("expected GPSHARE1: prefix, got: " + code.substring(0, 12),
			code.startsWith("GPSHARE1:"));
	}

	@Test
	public void compressesRatherThanInflating()
	{
		// gzip should make the encoded blob meaningfully smaller than the raw JSON.
		ShareBundle bundle = sampleSection();
		int rawJsonLen = new Gson().toJson(bundle).length();
		int encodedLen = codec.encode(bundle).length();
		assertTrue("encoded (" + encodedLen + ") should be smaller than raw JSON (" + rawJsonLen + ")",
			encodedLen < rawJsonLen);
	}

	@Test
	public void emptyGoalListIsValid()
	{
		ShareBundle empty = new ShareBundle();
		empty.setKind(ShareBundle.Kind.GOALS);
		ShareBundle decoded = codec.decode(codec.encode(empty));
		assertNotNull(decoded.getGoals());
		assertTrue(decoded.getGoals().isEmpty());
	}

	@Test
	public void rejectsNullAndBlankInput()
	{
		assertRejected(null);
		assertRejected("");
		assertRejected("   ");
	}

	@Test
	public void rejectsTextWithoutThePrefix()
	{
		assertRejected("hello, this is not a share code");
		// Right payload, missing/foreign prefix.
		assertRejected("GPSHARE9:" + "abc");
	}

	@Test
	public void rejectsCorruptBase64AfterPrefix()
	{
		// A lone marker followed by a single base64 char can't form a valid
		// group — the surrounding text is ignored, the token "A" is corrupt.
		assertRejected("GPSHARE1:A and then some words");
	}

	@Test
	public void extractsCodeFromSurroundingInstructionText()
	{
		// The "get the plugin to import this" chat/Discord line wraps the code
		// in human text — decode must still find and read it.
		String code = codec.encode(sampleSection());
		String line = "Get the Goal Planner RuneLite plugin to import this: " + code + " :)";
		assertEquals(sampleSection(), codec.decode(line));
	}

	@Test
	public void rejectsValidBase64ThatIsNotGzip()
	{
		String notGzip = Base64.getUrlEncoder().withoutPadding()
			.encodeToString("just some bytes".getBytes());
		assertRejected("GPSHARE1:" + notGzip);
	}

	@Test
	public void rejectsAnIncompatibleSchemaVersion()
	{
		// encode() normalizes the version from the bundle shape, so a forged
		// version has to be smuggled in as a hand-built wire payload.
		ShareBundle bundle = sampleSection();
		bundle.setV(999);  // payload claims a future schema version
		byte[] json = new Gson().toJson(bundle).getBytes(java.nio.charset.StandardCharsets.UTF_8);
		java.io.ByteArrayOutputStream out = new java.io.ByteArrayOutputStream();
		try (java.util.zip.GZIPOutputStream gz = new java.util.zip.GZIPOutputStream(out))
		{
			gz.write(json);
		}
		catch (java.io.IOException e)
		{
			throw new AssertionError(e);
		}
		String code = "GPSHARE1:" + Base64.getUrlEncoder().withoutPadding()
			.encodeToString(out.toByteArray());
		assertRejected(code);
	}

	private void assertRejected(String input)
	{
		try
		{
			codec.decode(input);
			fail("expected ShareFormatException for: " + input);
		}
		catch (ShareFormatException expected)
		{
			// good
		}
	}
}

package com.goalplanner.share;

import com.google.gson.Gson;
import java.util.Arrays;
import java.util.Collections;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Schema-v2 codec behaviour: version selection on encode (plain single-section
 * bundles stay on the v1 wire for older builds), dual-version decode, and the
 * version-neutral {@link ShareBundle#effectiveSections()} view.
 */
class ShareCodecV2Test
{
	private final ShareCodec codec = new ShareCodec(new Gson());

	private static GoalShareDto goal(int ref, String name)
	{
		GoalShareDto dto = new GoalShareDto();
		dto.setRef(ref);
		dto.setType("SKILL");
		dto.setName(name);
		dto.setSkillName("ATTACK");
		dto.setTargetValue(1_000_000);
		return dto;
	}

	private static SectionShareDto section(String name, boolean targetDefault, GoalShareDto... goals)
	{
		SectionShareDto s = new SectionShareDto();
		s.setName(name);
		s.setTargetDefault(targetDefault);
		s.setGoals(Arrays.asList(goals));
		return s;
	}

	@Test
	@DisplayName("a plain single-section bundle still emits the v1 wire so older builds import it")
	void plainSingleSectionStaysV1()
	{
		ShareBundle bundle = new ShareBundle();
		bundle.setSections(Collections.singletonList(section("Inferno", false, goal(0, "Ranged"))));

		String code = codec.encode(bundle);

		assertTrue(code.startsWith("GPSHARE1:"), code.substring(0, 12));
		ShareBundle decoded = codec.decode(code);
		assertEquals(1, decoded.getV());
		assertEquals(ShareBundle.Kind.SECTION, decoded.getKind());
		assertEquals("Inferno", decoded.getSectionName());
		assertEquals(1, decoded.effectiveSections().size());
		assertEquals("Inferno", decoded.effectiveSections().get(0).getName());
	}

	@Test
	@DisplayName("a legacy-built bundle (kind + flat goals) round-trips on the v1 wire")
	void legacyBuiltBundleRoundTripsV1()
	{
		ShareBundle bundle = new ShareBundle();
		bundle.setKind(ShareBundle.Kind.GOALS);
		bundle.setGoals(Collections.singletonList(goal(0, "Attack 99")));

		String code = codec.encode(bundle);

		assertTrue(code.startsWith("GPSHARE1:"));
		ShareBundle decoded = codec.decode(code);
		assertEquals(1, decoded.getGoals().size());
		assertNull(decoded.getSections());
	}

	@Test
	@DisplayName("a multi-section bundle emits GPSHARE2 and round-trips all sections")
	void multiSectionRoundTripsV2()
	{
		ShareBundle bundle = ShareMapper.toMultiBundle(Arrays.asList(
			section("Slayer", false, goal(0, "Slayer 93")),
			section("Raids", false, goal(0, "Ranged 90"), goal(1, "Defence 70"))), "Andrew");

		String code = codec.encode(bundle);

		assertTrue(code.startsWith("GPSHARE2:"), code.substring(0, 12));
		ShareBundle decoded = codec.decode(code);
		assertEquals(2, decoded.getV());
		assertEquals("Andrew", decoded.getSharedBy());
		assertEquals(2, decoded.getSections().size());
		assertEquals("Slayer", decoded.getSections().get(0).getName());
		assertEquals(2, decoded.getSections().get(1).getGoals().size());
	}

	@Test
	@DisplayName("a single default-target section needs the v2 wire")
	void defaultTargetNeedsV2()
	{
		ShareBundle bundle = new ShareBundle();
		bundle.setSections(Collections.singletonList(section(null, true, goal(0, "Mining 99"))));

		String code = codec.encode(bundle);

		assertTrue(code.startsWith("GPSHARE2:"));
		assertTrue(codec.decode(code).getSections().get(0).isTargetDefault());
	}

	@Test
	@DisplayName("a v2 code embedded in chat text decodes (marker scan)")
	void v2EmbeddedInTextDecodes()
	{
		ShareBundle bundle = ShareMapper.toMultiBundle(Arrays.asList(
			section("A", false, goal(0, "x")),
			section("B", false, goal(0, "y"))), null);
		String code = codec.encode(bundle);
		String chat = "[Goal Planner] someone shared 2 sections — import it: " + code + " enjoy!";

		assertEquals(2, codec.decode(chat).getSections().size());
	}

	@Test
	@DisplayName("a v2 payload with no sections is rejected")
	void emptyV2Rejected()
	{
		// Hand-build a v2 wire payload with an empty section list.
		ShareBundle bad = new ShareBundle();
		bad.setV(ShareBundle.SCHEMA_VERSION);
		bad.setGoals(null);
		bad.setSections(Collections.emptyList());
		String code = "GPSHARE2:" + java.util.Base64.getUrlEncoder().withoutPadding()
			.encodeToString(gzip(new Gson().toJson(bad)));

		assertThrows(ShareFormatException.class, () -> codec.decode(code));
	}

	@Test
	@DisplayName("the import-count description counts goals across every section")
	void inviteLineDescribesMultiSection()
	{
		ShareBundle bundle = ShareMapper.toMultiBundle(Arrays.asList(
			section("A", false, goal(0, "x")),
			section("B", false, goal(0, "y"), goal(1, "z"))), "Andrew");

		String line = ShareText.invite(bundle, codec.encode(bundle));

		assertTrue(line.contains("2 sections (3 goals)"), line);
	}

	private static byte[] gzip(String json)
	{
		try
		{
			java.io.ByteArrayOutputStream out = new java.io.ByteArrayOutputStream();
			try (java.util.zip.GZIPOutputStream gz = new java.util.zip.GZIPOutputStream(out))
			{
				gz.write(json.getBytes(java.nio.charset.StandardCharsets.UTF_8));
			}
			return out.toByteArray();
		}
		catch (java.io.IOException e)
		{
			throw new AssertionError(e);
		}
	}
}

package com.goalplanner.share;

import com.goalplanner.model.Goal;
import com.goalplanner.model.GoalType;
import com.goalplanner.model.Tag;
import com.goalplanner.model.TagCategory;
import com.google.gson.Gson;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.function.Function;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Export-side mapping: real Goal/Tag objects → ShareBundle. Verifies field
 * copy, ref indexing, tag resolution, relation remap, the recipient-state
 * strip, and a round-trip back through {@link ShareCodec}.
 */
public class ShareMapperTest
{
	private final Map<String, Tag> tags = new HashMap<>();
	private final Function<String, Tag> lookup = tags::get;

	private Tag infernoTag()
	{
		Tag t = Tag.builder()
			.id("t1").label("Inferno").category(TagCategory.OTHER)
			.colorRgb(0xAA3322).system(false).build();
		tags.put("t1", t);
		return t;
	}

	@Test
	public void mapsDefinitionFieldsAndAssignsRefIndices()
	{
		infernoTag();
		Goal ranged = Goal.builder()
			.id("a").type(GoalType.SKILL).name("Ranged - Level 75")
			.skillName("RANGED").targetValue(1_210_421)
			.tagIds(Collections.singletonList("t1"))
			.currentValue(500_000)           // recipient state — must not travel
			.build();

		ShareBundle bundle = ShareMapper.toBundle(
			ShareBundle.Kind.SECTION, "Inferno Prep", 0x112233,
			Collections.singletonList(ranged), lookup, "Andrew");

		assertEquals(ShareBundle.Kind.SECTION, bundle.getKind());
		assertEquals("Inferno Prep", bundle.getSectionName());
		assertEquals("Andrew", bundle.getSharedBy());
		assertEquals(1, bundle.getGoals().size());

		GoalShareDto dto = bundle.getGoals().get(0);
		assertEquals(0, dto.getRef());
		assertEquals("SKILL", dto.getType());
		assertEquals("Ranged - Level 75", dto.getName());
		assertEquals("RANGED", dto.getSkillName());
		assertEquals(1_210_421, dto.getTargetValue());
		assertEquals(1, dto.getTags().size());
		assertEquals("Inferno", dto.getTags().get(0).getLabel());
		assertEquals("OTHER", dto.getTags().get(0).getCategory());
	}

	@Test
	public void resolvesTagsAndDropsDanglingTagRefs()
	{
		infernoTag();   // only "t1" resolves; "ghost" does not
		Goal g = Goal.builder()
			.id("a").type(GoalType.BOSS).name("TzKal-Zuk").bossName("TzKal-Zuk")
			.targetValue(1).tagIds(Arrays.asList("t1", "ghost"))
			.build();

		ShareBundle bundle = ShareMapper.toBundle(
			ShareBundle.Kind.GOALS, null, -1,
			Collections.singletonList(g), lookup, "Andrew");

		GoalShareDto dto = bundle.getGoals().get(0);
		assertEquals("only the resolvable tag survives", 1, dto.getTags().size());
		assertEquals("Inferno", dto.getTags().get(0).getLabel());
	}

	@Test
	public void remapsInternalRelationsAndDropsExternalEdges()
	{
		Goal ranged = Goal.builder().id("a").type(GoalType.SKILL).name("Ranged").build();
		Goal zuk = Goal.builder()
			.id("b").type(GoalType.BOSS).name("TzKal-Zuk")
			// requires the in-bundle Ranged goal AND an out-of-bundle goal.
			.requiredGoalIds(Arrays.asList("a", "not-in-bundle"))
			.build();

		ShareBundle bundle = ShareMapper.toBundle(
			ShareBundle.Kind.SECTION, "Inferno Prep", -1,
			Arrays.asList(ranged, zuk), lookup, "Andrew");

		GoalShareDto zukDto = bundle.getGoals().get(1);
		assertEquals("external edge dropped, internal kept", 1, zukDto.getRequires().size());
		assertEquals("points at Ranged's ref index (0)", Integer.valueOf(0), zukDto.getRequires().get(0));
	}

	@Test
	public void recipientStateDoesNotAffectTheBundle()
	{
		// Same definition, different recipient-specific state → identical DTO.
		Goal trained = Goal.builder()
			.id("x1").type(GoalType.SKILL).name("Ranged").skillName("RANGED")
			.targetValue(1_210_421).currentValue(1_210_421).completedAt(123_456L)
			.build();
		Goal fresh = Goal.builder()
			.id("x2").type(GoalType.SKILL).name("Ranged").skillName("RANGED")
			.targetValue(1_210_421).currentValue(0).completedAt(0)
			.build();

		GoalShareDto a = ShareMapper.toBundle(ShareBundle.Kind.GOALS, null, -1,
			Collections.singletonList(trained), lookup, "A").getGoals().get(0);
		GoalShareDto b = ShareMapper.toBundle(ShareBundle.Kind.GOALS, null, -1,
			Collections.singletonList(fresh), lookup, "A").getGoals().get(0);
		assertEquals(a, b);
	}

	@Test
	public void roundTripsThroughTheCodec()
	{
		infernoTag();
		Goal ranged = Goal.builder().id("a").type(GoalType.SKILL).name("Ranged")
			.skillName("RANGED").targetValue(1_210_421)
			.tagIds(Collections.singletonList("t1")).build();
		Goal zuk = Goal.builder().id("b").type(GoalType.BOSS).name("TzKal-Zuk")
			.bossName("TzKal-Zuk").targetValue(1)
			.requiredGoalIds(Collections.singletonList("a")).build();

		ShareBundle bundle = ShareMapper.toBundle(
			ShareBundle.Kind.SECTION, "Inferno Prep", 0x112233,
			Arrays.asList(ranged, zuk), lookup, "Andrew");

		ShareCodec codec = new ShareCodec(new Gson());
		assertEquals(bundle, codec.decode(codec.encode(bundle)));
	}

	@Test
	public void toleratesNullAndEmptyInput()
	{
		ShareBundle bundle = ShareMapper.toBundle(
			ShareBundle.Kind.GOALS, null, -1, null, lookup, null);
		assertTrue(bundle.getGoals().isEmpty());
		assertNull(bundle.getSectionName());
	}

	// ---- repeat fields on the wire ----

	/** A repeatable goal must carry its period and chunk, or a shared daily
	 *  routine silently imports as a set of one-shots. */
	@Test
	public void repeatFieldsExported()
	{
		Goal g = Goal.builder()
			.type(GoalType.SKILL).name("Prayer +10K XP").skillName("PRAYER")
			.targetValue(9_810_000)
			.repeatEvery(com.goalplanner.model.RepeatPeriod.WEEKLY)
			.repeatChunk(10_000)
			.build();

		GoalShareDto dto = ShareMapper.toBundle(ShareBundle.Kind.GOALS, null, -1,
			Collections.singletonList(g), id -> null, "tester").getGoals().get(0);

		assertEquals("WEEKLY", dto.getRepeatEvery());
		assertEquals(10_000, dto.getRepeatChunk());
	}

	@Test
	public void plainGoalExportsNone()
	{
		Goal g = Goal.builder()
			.type(GoalType.SKILL).name("Prayer - Level 99").skillName("PRAYER")
			.targetValue(13_034_431).build();

		GoalShareDto dto = ShareMapper.toBundle(ShareBundle.Kind.GOALS, null, -1,
			Collections.singletonList(g), id -> null, "tester").getGoals().get(0);

		assertEquals("NONE", dto.getRepeatEvery());
		assertEquals(0, dto.getRepeatChunk());
	}

	/** Gson leaves repeatEvery null on goals persisted before the feature; the
	 *  null-guarding getter must keep that off the wire. */
	@Test
	public void legacyGoalExportsNone()
	{
		Goal legacy = Goal.builder().type(GoalType.CUSTOM).name("Old").build();
		legacy.setRepeatEvery(null);

		GoalShareDto dto = ShareMapper.toBundle(ShareBundle.Kind.GOALS, null, -1,
			Collections.singletonList(legacy), id -> null, "tester").getGoals().get(0);

		assertEquals("NONE", dto.getRepeatEvery());
	}
}

package com.goalplanner.share;

import com.google.gson.Gson;
import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * The instruction-led invite line: readable for non-plugin users, and still
 * decodable back to the bundle by a plugin user.
 */
public class ShareTextTest
{
	private final ShareCodec codec = new ShareCodec(new Gson());

	private static ShareBundle sectionBundle()
	{
		GoalShareDto a = new GoalShareDto();
		a.setRef(0);
		a.setType("SKILL");
		a.setName("Ranged - Level 75");
		GoalShareDto b = new GoalShareDto();
		b.setRef(1);
		b.setType("BOSS");
		b.setName("TzKal-Zuk");

		ShareBundle bundle = new ShareBundle();
		bundle.setKind(ShareBundle.Kind.SECTION);
		bundle.setSectionName("Inferno Prep");
		bundle.setSharedBy("Andrew");
		bundle.setGoals(Arrays.asList(a, b));
		return bundle;
	}

	@Test
	public void inviteLineReadsAsAnInstructionForNonPluginUsers()
	{
		String line = ShareText.invite(sectionBundle(), codec.encode(sectionBundle()));
		assertTrue(line.startsWith("[Goal Planner]"));
		assertTrue(line.contains("Andrew shared"));
		assertTrue(line.contains("\"Inferno Prep\""));
		assertTrue(line.contains("2 goals"));
		assertTrue(line.contains("get the Goal Planner RuneLite plugin to import"));
	}

	@Test
	public void inviteLineRemainsDecodableByPluginUsers()
	{
		ShareBundle bundle = sectionBundle();
		String line = ShareText.invite(bundle, codec.encode(bundle));
		// A plugin user pastes the whole line; the code is still recovered.
		assertEquals(bundle, codec.decode(line));
	}

	@Test
	public void fallsBackToSomeoneWhenSharerUnknown()
	{
		ShareBundle bundle = sectionBundle();
		bundle.setSharedBy(null);
		assertTrue(ShareText.invite(bundle, "GPSHARE1:x").contains("Someone shared"));
	}

	@Test
	public void summarisesLooseGoalsWithoutASectionName()
	{
		GoalShareDto only = new GoalShareDto();
		only.setRef(0);
		only.setType("SKILL");
		only.setName("Cooking - Level 50");
		ShareBundle bundle = new ShareBundle();
		bundle.setKind(ShareBundle.Kind.GOALS);
		bundle.setGoals(Collections.singletonList(only));

		String line = ShareText.invite(bundle, "GPSHARE1:x");
		assertTrue("singular goal count", line.contains("1 goal"));
		assertTrue("no section quoting for loose goals", !line.contains("\""));
	}
}

package com.goalplanner.testsupport;

import com.goalplanner.data.BossKillData;
import com.goalplanner.data.DiaryRequirements;
import com.google.gson.Gson;
import org.junit.jupiter.api.extension.BeforeAllCallback;
import org.junit.jupiter.api.extension.ExtensionContext;

/**
 * Primes the bundled requirement tables once, before any test class runs.
 *
 * <p>In production the plugin loads {@link DiaryRequirements} and
 * {@link BossKillData} from their JSON resources using the client's
 * <em>injected</em> {@link Gson} (the plugin-hub forbids plugins from
 * constructing their own Gson). Tests have no injector, so this extension
 * primes the same static tables with a plain {@code new Gson()} — allowed
 * here because the hub's forbidden-API check scans main source only.
 *
 * <p>Auto-registered for every test via the JUnit Jupiter {@code ServiceLoader}
 * mechanism: it is listed in
 * {@code META-INF/services/org.junit.jupiter.api.extension.Extension} and
 * {@code junit-platform.properties} enables
 * {@code junit.jupiter.extensions.autodetection.enabled}. No per-class wiring
 * is needed, and the {@code init} calls are idempotent.
 */
public final class DataResourcesInitExtension implements BeforeAllCallback
{
	@Override
	public void beforeAll(ExtensionContext context)
	{
		Gson gson = new Gson();
		DiaryRequirements.init(gson);
		BossKillData.init(gson);
	}
}

package com.goalplanner.testsupport;

import net.runelite.client.config.ConfigManager;
import org.mockito.Mockito;

import java.util.HashMap;
import java.util.Map;

/**
 * Test fake for {@link ConfigManager}: returns a Mockito spy whose
 * {@code getConfiguration} / {@code setConfiguration} methods are backed by an
 * in-memory {@code Map<String, String>}. The real GoalStore uses these two
 * methods only — everything else on ConfigManager is irrelevant for our tests.
 *
 * <p>Typical usage:
 * <pre>
 *   ConfigManager configManager = InMemoryConfigManager.create();
 *   GoalStore store = new GoalStore(configManager, new com.google.gson.Gson());
 *   store.load();
 * </pre>
 *
 * <p>This is a "spy on a mock" rather than a hand-rolled fake because
 * ConfigManager's constructor takes ~10 RuneLite singletons that we don't want
 * to wire up. Mockito's deep stubs would also work but explicit method stubs
 * are clearer.
 */
public final class InMemoryConfigManager
{
	private InMemoryConfigManager() {}

	public static ConfigManager create()
	{
		ConfigManager mock = Mockito.mock(ConfigManager.class);
		Map<String, String> store = new HashMap<>();

		Mockito.when(mock.getConfiguration(Mockito.anyString(), Mockito.anyString()))
			.thenAnswer(inv -> store.get(key(inv.getArgument(0), inv.getArgument(1))));

		Mockito.doAnswer(inv -> {
			Object value = inv.getArgument(2);
			store.put(key(inv.getArgument(0), inv.getArgument(1)),
				value == null ? null : value.toString());
			return null;
		}).when(mock).setConfiguration(Mockito.anyString(), Mockito.anyString(), Mockito.any());

		Mockito.doAnswer(inv -> {
			store.remove(key(inv.getArgument(0), inv.getArgument(1)));
			return null;
		}).when(mock).unsetConfiguration(Mockito.anyString(), Mockito.anyString());

		return mock;
	}

	private static String key(String group, String configKey)
	{
		return group + "." + configKey;
	}
}

