import net.runelite.api.Skill;
import net.runelite.api.WorldType;

import java.util.EnumSet;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Converts a {@link MockGameState} into a fully-configured Mockito
 * {@link Client} mock. All VarPlayer/Varbit/Skill/Quest/Item reads
 * are stubbed to return the values defined in the state snapshot.
 *
 * <p>Typical usage:
 * <pre>
 *   MockGameState state = new MockGameState().bossKills("Zulrah", 150);
 *   Client client = MockClientFactory.createClient(state);
 *   int kc = client.getVarpValue(VarPlayerID.TOTAL_ZULRAH_KILLS); // 150
 * </pre>
 */
public final class MockClientFactory
{
	private MockClientFactory() {}

	/**
	 * Create a Client mock configured to return values from the given state.
	 */
	public static Client createClient(MockGameState state)
	{
		Client client = mock(Client.class);

		// Game state: default to LOGGED_IN so trackers don't skip
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);

		// VarPlayer values
		for (Map.Entry<Integer, Integer> entry : state.getVarps().entrySet())
		{
			when(client.getVarpValue(entry.getKey())).thenReturn(entry.getValue());
		}

		// Varbit values
		for (Map.Entry<Integer, Integer> entry : state.getVarbits().entrySet())
		{
			when(client.getVarbitValue(entry.getKey())).thenReturn(entry.getValue());
		}

		// Skill XP and derived levels
		for (Map.Entry<Skill, Integer> entry : state.getSkillXp().entrySet())
		{
			when(client.getSkillExperience(entry.getKey())).thenReturn(entry.getValue());
			// Derive level from XP for getRealSkillLevel (used by ATT_STR_COMBINED etc.)
			int level = Experience.getLevelForXp(entry.getValue());
			when(client.getRealSkillLevel(entry.getKey())).thenReturn(level);
		}

		// Account scalars
		when(client.getTotalLevel()).thenReturn(state.getTotalLevel());
		Player localPlayer = mock(Player.class);
		when(localPlayer.getCombatLevel()).thenReturn(state.getCombatLevel());
		when(client.getLocalPlayer()).thenReturn(localPlayer);

		// World type — empty set means main (non-seasonal). Trackers read
		// this to decide whether to track leagues goals or main goals.
		when(client.getWorldType()).thenReturn(state.isSeasonal()
			? EnumSet.of(WorldType.SEASONAL)
			: EnumSet.noneOf(WorldType.class));

		// Quest states via runScript/getIntStack
		stubQuestStates(client, state);

		// Item containers
		stubItemContainers(client, state);

		return client;
	}

	/**
	 * Quest.getState(client) internally calls:
	 *   client.runScript(4029, quest.getId())
	 *   return client.getIntStack()[0]  // 2=FINISHED, 1=NOT_STARTED, else IN_PROGRESS
	 *
	 * We intercept runScript to populate a shared intStack array based on
	 * the quest ID argument. Because runScript is varargs (Object...),
	 * Mockito expands the arguments — inv.getArguments() returns the
	 * individual elements, not a wrapped array.
	 */
	private static void stubQuestStates(Client client, MockGameState state)
	{
		Map<Integer, Integer> questIdToIntStackValue = new HashMap<>();
		for (Map.Entry<Quest, QuestState> entry : state.getQuestStates().entrySet())
		{
			int intStackValue;
			switch (entry.getValue())
			{
				case FINISHED:
					intStackValue = 2;
					break;
				case NOT_STARTED:
					intStackValue = 1;
					break;
				default:
					intStackValue = 0; // IN_PROGRESS
					break;
			}
			questIdToIntStackValue.put(entry.getKey().getId(), intStackValue);
		}

		int[] intStack = new int[1];
		when(client.getIntStack()).thenReturn(intStack);

		// runScript is varargs (Object...). Quest.getState creates an
		// Object[]{4029, questId} and passes it directly. We intercept
		// all runScript calls and check the arguments manually.
		doAnswer(inv ->
		{
			Object[] rawArgs = inv.getArguments();
			// Varargs are received as a single Object[] element
			Object[] scriptArgs = rawArgs;
			if (rawArgs.length == 1 && rawArgs[0] instanceof Object[])
			{
				scriptArgs = (Object[]) rawArgs[0];
			}
			if (scriptArgs.length >= 2
				&& scriptArgs[0] instanceof Integer
				&& (int) scriptArgs[0] == 4029
				&& scriptArgs[1] instanceof Integer)
			{
				int questId = (int) scriptArgs[1];
				intStack[0] = questIdToIntStackValue.getOrDefault(questId, 1);
			}
			return null;
		}).when(client).runScript(any(Object[].class));
	}

	/**
	 * Stub getItemContainer for each container defined in the state.
	 * Containers not in the state return null (Mockito default).
	 */
	private static void stubItemContainers(Client client, MockGameState state)
	{
		for (Map.Entry<InventoryID, List<MockGameState.MockItem>> entry
			: state.getItemContainers().entrySet())
		{
			ItemContainer container = mock(ItemContainer.class);
			Item[] items = entry.getValue().stream()
				.map(mi ->
				{
					Item item = mock(Item.class);
					when(item.getId()).thenReturn(mi.itemId);
					when(item.getQuantity()).thenReturn(mi.quantity);
					return item;
				})
				.toArray(Item[]::new);
			when(container.getItems()).thenReturn(items);
			when(client.getItemContainer(entry.getKey())).thenReturn(container);
		}
	}
}

package com.goalplanner.testsupport;

import com.goalplanner.data.AchievementDiaryData;
import com.goalplanner.data.BossKillData;
import net.runelite.api.InventoryID;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.gameval.VarPlayerID;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Mutable snapshot of OSRS game state for testing. Represents a player's
 * complete state (varps, varbits, skills, quests, items) as a data object
 * that can be copied and modified for before/after test scenarios.
 *
 * <p>Typical usage:
 * <pre>
 *   MockGameState before = new MockGameState().bossKills("Zulrah", 99);
 *   MockGameState after = before.copy().bossKills("Zulrah", 100);
 * </pre>
 *
 * <p>All fluent methods return {@code this} for chaining.
 */
public final class MockGameState
{
	/** VarPlayerID → value. Covers boss kills, quest points, CA packed varps. */
	private final Map<Integer, Integer> varps = new HashMap<>();

	/** VarbitID → value. Covers diaries, CA points, slayer points, kudos. */
	private final Map<Integer, Integer> varbits = new HashMap<>();

	/** Skill → XP. */
	private final Map<Skill, Integer> skillXp = new HashMap<>();

	/** Quest → state. */
	private final Map<Quest, QuestState> questStates = new HashMap<>();

	/** InventoryID → list of item stacks. */
	private final Map<InventoryID, List<MockItem>> itemContainers = new HashMap<>();

	private int totalLevel = 0;
	private int combatLevel = 3; // OSRS starting combat level
	private boolean seasonal = false; // true = WorldType.SEASONAL (leagues world)

	// -----------------------------------------------------------------
	// Item stack record
	// -----------------------------------------------------------------

	public static final class MockItem
	{
		public final int itemId;
		public final int quantity;

		public MockItem(int itemId, int quantity)
		{
			this.itemId = itemId;
			this.quantity = quantity;
		}
	}

	// -----------------------------------------------------------------
	// Raw state setters
	// -----------------------------------------------------------------

	/** Set a VarPlayer value directly. */
	public MockGameState varp(int varpId, int value)
	{
		varps.put(varpId, value);
		return this;
	}

	/** Set a Varbit value directly. */
	public MockGameState varbit(int varbitId, int value)
	{
		varbits.put(varbitId, value);
		return this;
	}

	// -----------------------------------------------------------------
	// Boss kill convenience
	// -----------------------------------------------------------------

	/**
	 * Set kill count for a boss by display name.
	 * Looks up the VarPlayerID via {@link BossKillData}.
	 *
	 * @throws IllegalArgumentException if the boss name is unknown
	 */
	public MockGameState bossKills(String bossName, int killCount)
	{
		int varpId = BossKillData.getVarpId(bossName);
		if (varpId < 0)
		{
			throw new IllegalArgumentException("Unknown boss: " + bossName);
		}
		return varp(varpId, killCount);
	}

	// -----------------------------------------------------------------
	// Diary convenience
	// -----------------------------------------------------------------

	/**
	 * Mark a diary tier as complete by area display name and tier.
	 * Looks up the tracking spec via {@link AchievementDiaryData} and sets
	 * the varbit to the required completion value (1 for boolean COMPLETE
	 * varbits, the tier task count for Karamja count varbits).
	 *
	 * @throws IllegalArgumentException if no tracking varbit exists for this diary
	 */
	public MockGameState diaryComplete(String areaDisplayName, AchievementDiaryData.Tier tier)
	{
		AchievementDiaryData.Tracking tracking = AchievementDiaryData.tracking(areaDisplayName, tier);
		if (tracking == null)
		{
			throw new IllegalArgumentException(
				"No tracking varbit for diary: " + areaDisplayName + " " + tier);
		}
		return varbit(tracking.varbitId, tracking.requiredValue);
	}

	// -----------------------------------------------------------------
	// Combat Achievement convenience
	// -----------------------------------------------------------------

	/**
	 * Mark a CA task as complete by task ID.
	 * Handles the bit-packing into the correct CA_TASK_COMPLETED varp.
	 */
	public MockGameState caTaskComplete(int caTaskId)
	{
		int varpIndex = caTaskId / 32;
		int bitIndex = caTaskId % 32;
		int varpId = getCaVarpId(varpIndex);
		int current = varps.getOrDefault(varpId, 0);
		return varp(varpId, current | (1 << bitIndex));
	}

	private static int getCaVarpId(int index)
	{
		// Mirror the CA_VARPS array from CombatAchievementTracker
		switch (index)
		{
			case 0: return VarPlayerID.CA_TASK_COMPLETED_0;
			case 1: return VarPlayerID.CA_TASK_COMPLETED_1;
			case 2: return VarPlayerID.CA_TASK_COMPLETED_2;
			case 3: return VarPlayerID.CA_TASK_COMPLETED_3;
			case 4: return VarPlayerID.CA_TASK_COMPLETED_4;
			case 5: return VarPlayerID.CA_TASK_COMPLETED_5;
			case 6: return VarPlayerID.CA_TASK_COMPLETED_6;
			case 7: return VarPlayerID.CA_TASK_COMPLETED_7;
			case 8: return VarPlayerID.CA_TASK_COMPLETED_8;
			case 9: return VarPlayerID.CA_TASK_COMPLETED_9;
			case 10: return VarPlayerID.CA_TASK_COMPLETED_10;
			case 11: return VarPlayerID.CA_TASK_COMPLETED_11;
			case 12: return VarPlayerID.CA_TASK_COMPLETED_12;
			case 13: return VarPlayerID.CA_TASK_COMPLETED_13;
			case 14: return VarPlayerID.CA_TASK_COMPLETED_14;
			case 15: return VarPlayerID.CA_TASK_COMPLETED_15;
			case 16: return VarPlayerID.CA_TASK_COMPLETED_16;
			case 17: return VarPlayerID.CA_TASK_COMPLETED_17;
			case 18: return VarPlayerID.CA_TASK_COMPLETED_18;
			case 19: return VarPlayerID.CA_TASK_COMPLETED_19;
			default:
				throw new IllegalArgumentException("CA varp index out of range: " + index);
		}
	}

	// -----------------------------------------------------------------
	// Skill convenience
	// -----------------------------------------------------------------

	/** Set XP for a skill. */
	public MockGameState skillXp(Skill skill, int xp)
	{
		this.skillXp.put(skill, xp);
		return this;
	}

	// -----------------------------------------------------------------
	// Quest convenience
	// -----------------------------------------------------------------

	/** Set a quest to a specific state. */
	public MockGameState questState(Quest quest, QuestState state)
	{
		questStates.put(quest, state);
		return this;
	}

	/** Shorthand for marking a quest FINISHED. */
	public MockGameState questFinished(Quest quest)
	{
		return questState(quest, QuestState.FINISHED);
	}

	// -----------------------------------------------------------------
	// Item convenience
	// -----------------------------------------------------------------

	/** Add an item stack to a specific container. */
	public MockGameState addItem(InventoryID container, int itemId, int quantity)
	{
		itemContainers
			.computeIfAbsent(container, k -> new ArrayList<>())
			.add(new MockItem(itemId, quantity));
		return this;
	}

	/** Shorthand: add to inventory. */
	public MockGameState inventory(int itemId, int quantity)
	{
		return addItem(InventoryID.INVENTORY, itemId, quantity);
	}

	/** Shorthand: add to bank. */
	public MockGameState bank(int itemId, int quantity)
	{
		return addItem(InventoryID.BANK, itemId, quantity);
	}

	// -----------------------------------------------------------------
	// Account-level scalars
	// -----------------------------------------------------------------

	public MockGameState totalLevel(int level)
	{
		this.totalLevel = level;
		return this;
	}

	public MockGameState combatLevel(int level)
	{
		this.combatLevel = level;
		return this;
	}

	/** Set quest points via the QP VarPlayer. */
	public MockGameState questPoints(int qp)
	{
		return varp(VarPlayerID.QP, qp);
	}

	/**
	 * Mark this state as on a SEASONAL (leagues) world. Default is main.
	 * Used by the tracker's world-scope guard to decide which goals to
	 * track (leagues metrics on seasonal, everything else on main).
	 */
	public MockGameState seasonal(boolean seasonal)
	{
		this.seasonal = seasonal;
		return this;
	}

	// -----------------------------------------------------------------
	// Copy (for before/after scenarios)
	// -----------------------------------------------------------------

	/**
	 * Deep copy this state. The returned copy can be modified independently
	 * without affecting the original.
	 */
	public MockGameState copy()
	{
		MockGameState clone = new MockGameState();
		clone.varps.putAll(this.varps);
		clone.varbits.putAll(this.varbits);
		clone.skillXp.putAll(this.skillXp);
		clone.questStates.putAll(this.questStates);
		for (Map.Entry<InventoryID, List<MockItem>> e : this.itemContainers.entrySet())
		{
			clone.itemContainers.put(e.getKey(), new ArrayList<>(e.getValue()));
		}
		clone.totalLevel = this.totalLevel;
		clone.combatLevel = this.combatLevel;
		clone.seasonal = this.seasonal;
		return clone;
	}

	// -----------------------------------------------------------------
	// Accessors (package-private, used by MockClientFactory)
	// -----------------------------------------------------------------

	Map<Integer, Integer> getVarps() { return varps; }
	Map<Integer, Integer> getVarbits() { return varbits; }
	Map<Skill, Integer> getSkillXp() { return skillXp; }
	Map<Quest, QuestState> getQuestStates() { return questStates; }
	Map<InventoryID, List<MockItem>> getItemContainers() { return itemContainers; }
	int getTotalLevel() { return totalLevel; }
	int getCombatLevel() { return combatLevel; }
	boolean isSeasonal() { return seasonal; }
}

package com.goalplanner.testsupport;

import com.goalplanner.api.GoalPlannerApiImpl;
import com.goalplanner.data.WikiCaRepository;
import com.goalplanner.persistence.GoalStore;
import com.goalplanner.service.GoalReorderingService;
import com.goalplanner.tracker.AbstractTracker;
import com.goalplanner.tracker.AccountTracker;
import com.goalplanner.tracker.BossKillTracker;
import com.goalplanner.tracker.CombatAchievementTracker;
import com.goalplanner.tracker.DiaryTracker;
import com.goalplanner.tracker.ItemTracker;
import com.goalplanner.tracker.QuestTracker;
import com.goalplanner.tracker.SkillTracker;
import net.runelite.api.Client;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;

import java.util.function.BiFunction;

import static org.mockito.Mockito.mock;

/**
 * Wires up the full GoalStore + GoalPlannerApiImpl + Tracker stack
 * against a {@link MockGameState}-derived Client mock. Follows the
 * same pattern as {@code ItemTrackerTest.setUp()} but is reusable
 * across all tracker types.
 *
 * <p>Factory methods create the entire stack from a state snapshot:
 * <pre>
 *   var h = TrackerTestHarness.forBossKills(state);
 *   h.store().addGoal(goal);
 *   h.tracker().checkGoals(h.store().getGoals());
 *   assertEquals(150, goal.getCurrentValue());
 * </pre>
 *
 * <p>For before/after scenarios, use {@link #withNewState(MockGameState)}
 * to swap the Client and tracker while keeping the same GoalStore/API:
 * <pre>
 *   h = h.withNewState(afterState);
 *   h.tracker().checkGoals(h.store().getGoals());
 * </pre>
 *
 * @param <T> the tracker type
 */
public final class TrackerTestHarness<T extends AbstractTracker>
{
	private final GoalStore store;
	private final GoalPlannerApiImpl api;
	private final T tracker;
	private final Client client;
	private final BiFunction<Client, GoalPlannerApiImpl, T> trackerFactory;

	private TrackerTestHarness(
		GoalStore store,
		GoalPlannerApiImpl api,
		T tracker,
		Client client,
		BiFunction<Client, GoalPlannerApiImpl, T> trackerFactory)
	{
		this.store = store;
		this.api = api;
		this.tracker = tracker;
		this.client = client;
		this.trackerFactory = trackerFactory;
	}

	// -----------------------------------------------------------------
	// Factory methods — one per tracker type
	// -----------------------------------------------------------------

	public static TrackerTestHarness<BossKillTracker> forBossKills(MockGameState state)
	{
		return create(state, BossKillTracker::new);
	}

	public static TrackerTestHarness<SkillTracker> forSkills(MockGameState state)
	{
		return create(state, SkillTracker::new);
	}

	public static TrackerTestHarness<QuestTracker> forQuests(MockGameState state)
	{
		return create(state, QuestTracker::new);
	}

	public static TrackerTestHarness<DiaryTracker> forDiaries(MockGameState state)
	{
		return create(state, DiaryTracker::new);
	}

	public static TrackerTestHarness<CombatAchievementTracker> forCombatAchievements(MockGameState state)
	{
		return create(state, CombatAchievementTracker::new);
	}

	public static TrackerTestHarness<AccountTracker> forAccount(MockGameState state)
	{
		return create(state, AccountTracker::new);
	}

	public static TrackerTestHarness<ItemTracker> forItems(MockGameState state)
	{
		return create(state, ItemTracker::new);
	}

	// -----------------------------------------------------------------
	// State change support
	// -----------------------------------------------------------------

	/**
	 * Create a new harness with a different game state but the same
	 * GoalStore and API. Goal progress persists across the transition.
	 * A fresh tracker instance is created against the new Client mock.
	 */
	public TrackerTestHarness<T> withNewState(MockGameState newState)
	{
		Client newClient = MockClientFactory.createClient(newState);
		T newTracker = trackerFactory.apply(newClient, this.api);
		return new TrackerTestHarness<>(this.store, this.api, newTracker, newClient, this.trackerFactory);
	}

	// -----------------------------------------------------------------
	// Accessors
	// -----------------------------------------------------------------

	public GoalStore store() { return store; }
	public GoalPlannerApiImpl api() { return api; }
	public T tracker() { return tracker; }
	public Client client() { return client; }

	// -----------------------------------------------------------------
	// Internal wiring
	// -----------------------------------------------------------------

	private static <T extends AbstractTracker> TrackerTestHarness<T> create(
		MockGameState state,
		BiFunction<Client, GoalPlannerApiImpl, T> trackerFactory)
	{
		Client client = MockClientFactory.createClient(state);

		ConfigManager configManager = InMemoryConfigManager.create();
		GoalStore store = new GoalStore(configManager, new com.google.gson.Gson());
		store.load();

		ItemManager itemManager = mock(ItemManager.class);
		WikiCaRepository wikiCaRepository = mock(WikiCaRepository.class);
		GoalReorderingService reorderingService = new GoalReorderingService(store);
		GoalPlannerApiImpl api = new GoalPlannerApiImpl(
			store, reorderingService, itemManager, wikiCaRepository);

		T tracker = trackerFactory.apply(client, api);

		return new TrackerTestHarness<>(store, api, tracker, client, trackerFactory);
	}
}

package com.goalplanner.tracker;

import com.goalplanner.data.AchievementDiaryData;
import com.goalplanner.model.AccountMetric;
import com.goalplanner.model.Goal;
import com.goalplanner.model.GoalStatus;
import com.goalplanner.model.GoalType;
import com.goalplanner.testsupport.MockClientFactory;
import com.goalplanner.testsupport.MockGameState;
import com.goalplanner.testsupport.TrackerTestHarness;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Tests for {@link AccountTracker} using the MockGameState framework.
 * Covers all account metrics: quest points, combat level, total level,
 * CA points, slayer points, and museum kudos.
 */
class AccountTrackerTest
{
	private Goal makeAccountGoal(AccountMetric metric, int target)
	{
		return Goal.builder()
			.type(GoalType.ACCOUNT)
			.name(metric.getDisplayName() + " goal")
			.accountMetric(metric.name())
			.targetValue(target)
			.currentValue(0)
			.build();
	}

	@Nested
	@DisplayName("Quest Points")
	class QuestPointTests
	{
		@Test
		@DisplayName("reads quest points from VarPlayer")
		void readsQuestPoints()
		{
			MockGameState state = new MockGameState().questPoints(150);

			var h = TrackerTestHarness.forAccount(state);
			Goal goal = makeAccountGoal(AccountMetric.QUEST_POINTS, 200);
			h.store().addGoal(goal);

			assertTrue(h.tracker().checkGoals(h.store().getGoals()));
			assertEquals(150, goal.getCurrentValue());
		}

		@Test
		@DisplayName("detects QP increase between snapshots")
		void detectsQpIncrease()
		{
			MockGameState before = new MockGameState().questPoints(199);
			MockGameState after = before.copy().questPoints(200);

			var h = TrackerTestHarness.forAccount(before);
			Goal goal = makeAccountGoal(AccountMetric.QUEST_POINTS, 200);
			h.store().addGoal(goal);

			h.tracker().checkGoals(h.store().getGoals());
			assertFalse(goal.isComplete());

			h = h.withNewState(after);
			h.tracker().checkGoals(h.store().getGoals());
			assertTrue(goal.isComplete());
		}
	}

	@Nested
	@DisplayName("Combat Level")
	class CombatLevelTests
	{
		@Test
		@DisplayName("reads combat level from player")
		void readsCombatLevel()
		{
			MockGameState state = new MockGameState().combatLevel(85);

			var h = TrackerTestHarness.forAccount(state);
			Goal goal = makeAccountGoal(AccountMetric.COMBAT_LEVEL, 100);
			h.store().addGoal(goal);

			assertTrue(h.tracker().checkGoals(h.store().getGoals()));
			assertEquals(85, goal.getCurrentValue());
		}
	}

	@Nested
	@DisplayName("Total Level")
	class TotalLevelTests
	{
		@Test
		@DisplayName("reads total level from client")
		void readsTotalLevel()
		{
			MockGameState state = new MockGameState().totalLevel(1500);

			var h = TrackerTestHarness.forAccount(state);
			Goal goal = makeAccountGoal(AccountMetric.TOTAL_LEVEL, 2000);
			h.store().addGoal(goal);

			assertTrue(h.tracker().checkGoals(h.store().getGoals()));
			assertEquals(1500, goal.getCurrentValue());
		}
	}

	@Nested
	@DisplayName("CA Points")
	class CaPointTests
	{
		@Test
		@DisplayName("reads CA points from varbit")
		void readsCaPoints()
		{
			MockGameState state = new MockGameState()
				.varbit(VarbitID.CA_POINTS, 500);

			var h = TrackerTestHarness.forAccount(state);
			Goal goal = makeAccountGoal(AccountMetric.CA_POINTS, 1000);
			h.store().addGoal(goal);

			assertTrue(h.tracker().checkGoals(h.store().getGoals()));
			assertEquals(500, goal.getCurrentValue());
		}
	}

	@Nested
	@DisplayName("Slayer Points")
	class SlayerPointTests
	{
		@Test
		@DisplayName("reads slayer points from varbit")
		void readsSlayerPoints()
		{
			MockGameState state = new MockGameState()
				.varbit(VarbitID.SLAYER_POINTS, 2000);

			var h = TrackerTestHarness.forAccount(state);
