import static org.junit.jupiter.api.Assertions.*;

/**
 * Tests for {@link DiaryTracker} using the MockGameState framework.
 * Validates that the tracker correctly reads diary completion varbits.
 */
class DiaryTrackerTest
{
	private Goal makeDiaryGoal(String area, AchievementDiaryData.Tier tier)
	{
		AchievementDiaryData.Tracking tracking = AchievementDiaryData.tracking(area, tier);
		return Goal.builder()
			.type(GoalType.DIARY)
			.name(area + " " + tier.getDisplayName() + " Diary")
			.varbitId(tracking != null ? tracking.varbitId : 0)
			.targetValue(tracking != null ? tracking.requiredValue : 1)
			.currentValue(0)
			.build();
	}

	@Test
	@DisplayName("detects diary completion from varbit")
	void detectsDiaryCompletion()
	{
		MockGameState state = new MockGameState()
			.diaryComplete("Ardougne", AchievementDiaryData.Tier.EASY);

		var h = TrackerTestHarness.forDiaries(state);
		Goal goal = makeDiaryGoal("Ardougne", AchievementDiaryData.Tier.EASY);
		h.store().addGoal(goal);

		assertTrue(h.tracker().checkGoals(h.store().getGoals()));
		assertEquals(1, goal.getCurrentValue());
		assertTrue(goal.isComplete());
	}

	@Test
	@DisplayName("incomplete diary reads as 0")
	void incompleteDiaryReadsZero()
	{
		// State with no diary completions
		MockGameState state = new MockGameState();

		var h = TrackerTestHarness.forDiaries(state);
		Goal goal = makeDiaryGoal("Falador", AchievementDiaryData.Tier.HARD);
		h.store().addGoal(goal);

		assertFalse(h.tracker().checkGoals(h.store().getGoals()),
			"no change from initial 0 value");
		assertEquals(0, goal.getCurrentValue());
	}

	@Test
	@DisplayName("detects diary completion between snapshots")
	void detectsCompletionBetweenSnapshots()
	{
		MockGameState before = new MockGameState();
		MockGameState after = before.copy()
			.diaryComplete("Desert", AchievementDiaryData.Tier.MEDIUM);

		var h = TrackerTestHarness.forDiaries(before);
		Goal goal = makeDiaryGoal("Desert", AchievementDiaryData.Tier.MEDIUM);
		h.store().addGoal(goal);

		h.tracker().checkGoals(h.store().getGoals());
		assertFalse(goal.isComplete());

		h = h.withNewState(after);
		h.tracker().checkGoals(h.store().getGoals());
		assertTrue(goal.isComplete());
	}

	@Test
	@DisplayName("skips goals with varbitId <= 0 (manual tracking)")
	void skipsManualDiaries()
	{
		MockGameState state = new MockGameState();
		var h = TrackerTestHarness.forDiaries(state);

		// Custom diary entry with no tracking varbit available — caller built
		// the goal without a varbit, so the tracker must leave it manual.
		Goal goal = Goal.builder()
			.type(GoalType.DIARY)
			.name("Custom Diary")
			.varbitId(0)
			.targetValue(1)
			.currentValue(0)
			.build();
		h.store().addGoal(goal);

		assertFalse(h.tracker().checkGoals(h.store().getGoals()),
			"goals with varbitId <= 0 should be skipped");
	}

	@Test
	@DisplayName("Karamja Medium completes via count varbit reaching 19")
	void karamjaMediumCompletesViaCountVarbit()
	{
		MockGameState state = new MockGameState()
			.diaryComplete("Karamja", AchievementDiaryData.Tier.MEDIUM);

		var h = TrackerTestHarness.forDiaries(state);
		Goal goal = makeDiaryGoal("Karamja", AchievementDiaryData.Tier.MEDIUM);
		assertEquals(19, goal.getTargetValue(),
			"Karamja Medium should track against the 19-task count");
		h.store().addGoal(goal);

		assertTrue(h.tracker().checkGoals(h.store().getGoals()));
		assertEquals(19, goal.getCurrentValue());
		assertTrue(goal.isComplete());
	}

	@Test
	@DisplayName("Karamja Hard partial progress doesn't complete")
	void karamjaHardPartialProgress()
	{
		// 9 of 10 tasks done — should track progress but not complete
		MockGameState state = new MockGameState()
			.varbit(net.runelite.api.gameval.VarbitID.KARAMJA_HARD_COUNT, 9);

		var h = TrackerTestHarness.forDiaries(state);
		Goal goal = makeDiaryGoal("Karamja", AchievementDiaryData.Tier.HARD);
		h.store().addGoal(goal);

		h.tracker().checkGoals(h.store().getGoals());
		assertEquals(9, goal.getCurrentValue());
		assertFalse(goal.isComplete(), "9/10 tasks should not be complete");
	}

	@Test
	@DisplayName("tracks multiple diary tiers independently")
	void tracksMultipleTiers()
	{
		MockGameState state = new MockGameState()
			.diaryComplete("Ardougne", AchievementDiaryData.Tier.EASY)
			.diaryComplete("Ardougne", AchievementDiaryData.Tier.MEDIUM);

		var h = TrackerTestHarness.forDiaries(state);
		Goal easy = makeDiaryGoal("Ardougne", AchievementDiaryData.Tier.EASY);
		Goal medium = makeDiaryGoal("Ardougne", AchievementDiaryData.Tier.MEDIUM);
		Goal hard = makeDiaryGoal("Ardougne", AchievementDiaryData.Tier.HARD);
		h.store().addGoal(easy);
		h.store().addGoal(medium);
		h.store().addGoal(hard);

		h.tracker().checkGoals(h.store().getGoals());
		assertTrue(easy.isComplete(), "easy should be complete");
		assertTrue(medium.isComplete(), "medium should be complete");
		assertFalse(hard.isComplete(), "hard should not be complete");
	}
}

package com.goalplanner.tracker;

import com.goalplanner.api.GoalPlannerApiImpl;
import com.goalplanner.data.WikiCaRepository;
import com.goalplanner.model.Goal;
import com.goalplanner.model.GoalType;
import com.goalplanner.persistence.GoalStore;
import com.goalplanner.service.GoalReorderingService;
import com.goalplanner.testsupport.InMemoryConfigManager;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import java.util.List;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

/**
 * Tests for {@link ItemTracker}, the inventory+bank quantity tracker.
 *
 * <p>Covers the bank-null guard: pre-bank-visit, only growth past the
 * persisted value is allowed (so a partial inventory snapshot can't
 * wipe a persisted higher value). After the first bank visit, full
 * bank+inventory counts apply normally.
 *
 * <p>Uses a real GoalStore + GoalPlannerApiImpl + ItemTracker against
 * Mockito-mocked Client / ItemContainer. The api is the canonical
 * mutation surface — trackers go through recordGoalProgress.
 */
class ItemTrackerTest
{
	private static final int CANNONBALL_ID = 2;

	private Client client;
	private ItemContainer inventoryContainer;
	private ItemContainer bankContainer;
	private GoalStore store;
	private GoalPlannerApiImpl api;
	private ItemTracker tracker;

	@BeforeEach
	void setUp()
	{
		client = mock(Client.class);
		inventoryContainer = mock(ItemContainer.class);
		bankContainer = mock(ItemContainer.class);

		ConfigManager configManager = InMemoryConfigManager.create();
		store = new GoalStore(configManager, new com.google.gson.Gson());
		store.load();

		ItemManager itemManager = mock(ItemManager.class);
		WikiCaRepository wikiCaRepository = mock(WikiCaRepository.class);
		GoalReorderingService reorderingService = new GoalReorderingService(store);
		api = new GoalPlannerApiImpl(store, reorderingService, itemManager, wikiCaRepository);

		tracker = new ItemTracker(client, api);
	}

	private Goal makeItemGoal(int itemId, int target)
	{
		Goal g = Goal.builder()
			.type(GoalType.ITEM_GRIND)
			.name("Cannonballs")
			.itemId(itemId)
			.targetValue(target)
			.currentValue(0)
			.build();
		store.addGoal(g);
		return g;
	}

	private Item mockItem(int id, int qty)
	{
		Item item = mock(Item.class);
		when(item.getId()).thenReturn(id);
		when(item.getQuantity()).thenReturn(qty);
		return item;
	}

	private void stubInventoryItems(Item... items)
	{
		when(client.getItemContainer(InventoryID.INVENTORY)).thenReturn(inventoryContainer);
		when(inventoryContainer.getItems()).thenReturn(items);
	}

	private void stubBankItems(Item... items)
	{
		when(client.getItemContainer(InventoryID.BANK)).thenReturn(bankContainer);
		when(bankContainer.getItems()).thenReturn(items);
	}

	private void stubBankNull()
	{
		when(client.getItemContainer(InventoryID.BANK)).thenReturn(null);
	}

	// ====================================================================
	// Bank loaded — full count behavior
	// ====================================================================

	@Test
	@DisplayName("With bank loaded, total count is inventory + bank")
	void fullCountSumsContainers()
	{
		Goal g = makeItemGoal(CANNONBALL_ID, 200);
		stubInventoryItems(mockItem(CANNONBALL_ID, 50));
		stubBankItems(mockItem(CANNONBALL_ID, 100));

		assertTrue(tracker.checkGoals(store.getGoals()));
		assertEquals(150, g.getCurrentValue());
	}

	@Test
	@DisplayName("With bank loaded, hitting target marks the goal complete")
	void fullCountFlipsCompleteOnTarget()
	{
		Goal g = makeItemGoal(CANNONBALL_ID, 200);
		stubInventoryItems(mockItem(CANNONBALL_ID, 100));
		stubBankItems(mockItem(CANNONBALL_ID, 100));

		assertTrue(tracker.checkGoals(store.getGoals()));
		assertEquals(200, g.getCurrentValue());
		assertTrue(g.isComplete());
	}

	@Test
	@DisplayName("After logout, a bank-less relog does not reset a persisted goal to 0")
	void logoutReArmsBankGuard()
	{
		Goal g = makeItemGoal(CANNONBALL_ID, 200);
		// Session 1: bank seen, goal reaches 150 (50 inventory + 100 bank).
		stubInventoryItems(mockItem(CANNONBALL_ID, 50));
		stubBankItems(mockItem(CANNONBALL_ID, 100));
		assertTrue(tracker.checkGoals(store.getGoals()));
		assertEquals(150, g.getCurrentValue());

		// Relog: the bank container is cleared (null) and the items live in the
		// bank, so a count now sees only the (empty) inventory = 0.
		tracker.onLogout();
		stubBankNull();
		stubInventoryItems();

		// Without the re-armed guard this records 0; with it, the persisted 150 holds.
		tracker.checkGoals(store.getGoals());
		assertEquals(150, g.getCurrentValue());
	}

	@Test
	@DisplayName("A degraded/charge variant counts toward a goal for the base item")
	void variantCountsTowardGoal()
	{
		final int PRISTINE = 29025; // Blood moon tassets
		final int DEGRADED = 29045; // Blood moon tassets (degraded)
		// Precondition: RuneLite's variation data groups these under one base.
		assertEquals(
			net.runelite.client.game.ItemVariationMapping.map(PRISTINE),
			net.runelite.client.game.ItemVariationMapping.map(DEGRADED),
			"expected Blood moon tassets variants to share a variation base");

		Goal g = makeItemGoal(PRISTINE, 1);
		stubInventoryItems();
		stubBankItems(mockItem(DEGRADED, 1)); // owns only the degraded copy

		assertTrue(tracker.checkGoals(store.getGoals()));
		assertEquals(1, g.getCurrentValue());
		assertTrue(g.isComplete());
	}

	@Test
	@DisplayName("completed item goals are sticky and do not revert on drop")
	void completedItemGoalIsSticky()
	{
		Goal g = makeItemGoal(CANNONBALL_ID, 200);
		// First pass: full target
		stubInventoryItems(mockItem(CANNONBALL_ID, 100));
		stubBankItems(mockItem(CANNONBALL_ID, 100));
		tracker.checkGoals(store.getGoals());
		assertTrue(g.isComplete());
		assertEquals(200, g.getCurrentValue());

		// Second pass: dropped to 150 — goal should STAY complete and frozen at 200
		stubInventoryItems(mockItem(CANNONBALL_ID, 50));
		stubBankItems(mockItem(CANNONBALL_ID, 100));
		assertFalse(tracker.checkGoals(store.getGoals()));
		assertEquals(200, g.getCurrentValue());
		assertTrue(g.isComplete());
	}

	// ====================================================================
	// Pre-bank-visit guard — growth-only updates
	// ====================================================================

	@Test
	@DisplayName("Before first bank visit, allow growth from inventory-only")
	void preBankVisitAllowsGrowth()
	{
		Goal g = makeItemGoal(CANNONBALL_ID, 200);
		assertEquals(0, g.getCurrentValue());

		// Bank null, inventory has 50 — growth from 0 → 50 should land
		stubBankNull();
		stubInventoryItems(mockItem(CANNONBALL_ID, 50));

		assertTrue(tracker.checkGoals(store.getGoals()));
		assertEquals(50, g.getCurrentValue());
	}

	@Test
	@DisplayName("Before first bank visit, reject decreases (protects persisted value)")
	void preBankVisitRejectsDecrease()
	{
		Goal g = makeItemGoal(CANNONBALL_ID, 200);
		// Pretend the persisted value from a previous session was 1000
		g.setCurrentValue(1000);

		stubBankNull();
		stubInventoryItems(mockItem(CANNONBALL_ID, 50));

		assertFalse(tracker.checkGoals(store.getGoals()));
		assertEquals(1000, g.getCurrentValue()); // unchanged
	}

	@Test
	@DisplayName("After first bank visit, full counts apply (sticky)")
	void bankSeenIsSticky()
	{
		Goal g = makeItemGoal(CANNONBALL_ID, 200);
		// First call: bank present → flag flips
		stubInventoryItems(mockItem(CANNONBALL_ID, 50));
		stubBankItems(mockItem(CANNONBALL_ID, 100));
		tracker.checkGoals(store.getGoals());
		assertEquals(150, g.getCurrentValue());

		// Second call: bank container would return null (edge case) but the
		// session flag should stay true
		stubBankNull();
		stubInventoryItems(mockItem(CANNONBALL_ID, 30));
		// countItem returns 30 from inventory, 0 from bank (null) = 30.
		// canTrustFullCount is true (sticky), so the update applies even though
		// it's a decrease — bank is just empty as far as the tracker can see.
		assertTrue(tracker.checkGoals(store.getGoals()));
		assertEquals(30, g.getCurrentValue());
	}

	// ====================================================================
	// Filtering / no-op cases
	// ====================================================================

	@Test
	@DisplayName("Skips non-ITEM_GRIND goals")
	void skipsNonItemGoals()
	{
		Goal skill = Goal.builder().type(GoalType.SKILL).name("Mining")
			.skillName("MINING").targetValue(100).build();
		store.addGoal(skill);

		stubInventoryItems();
		stubBankItems();

		assertFalse(tracker.checkGoals(store.getGoals()));
		assertEquals(0, skill.getCurrentValue());
	}

	@Test
	@DisplayName("Skips item goals with itemId <= 0")
	void skipsUnboundItemGoals()
	{
		Goal g = Goal.builder().type(GoalType.ITEM_GRIND).name("Unbound")
			.itemId(0).targetValue(100).build();
		store.addGoal(g);

		stubInventoryItems();
		stubBankItems();

		assertFalse(tracker.checkGoals(store.getGoals()));
	}

	@Test
	@DisplayName("Returns false when nothing changes (no-op detection)")
	void noopWhenCountUnchanged()
	{
		Goal g = makeItemGoal(CANNONBALL_ID, 200);
		stubInventoryItems(mockItem(CANNONBALL_ID, 50));
		stubBankItems(mockItem(CANNONBALL_ID, 100));

		// First pass: 0 → 150
		assertTrue(tracker.checkGoals(store.getGoals()));
		// Second pass with identical containers: should be no-op
		assertFalse(tracker.checkGoals(store.getGoals()));
	}

	// ====================================================================
	// Comprehensive container counting
	// ====================================================================

	private void stubContainer(InventoryID id, Item... items)
	{
		ItemContainer c = mock(ItemContainer.class);
		when(c.getItems()).thenReturn(items);
		when(client.getItemContainer(id)).thenReturn(c);
	}

	@Test
	@DisplayName("countItem sums equipment + seed vault + group storage when present")
	void countItemSumsAllContainers()
	{
		stubInventoryItems(mockItem(CANNONBALL_ID, 10));
		stubBankItems(mockItem(CANNONBALL_ID, 20));
		stubContainer(InventoryID.EQUIPMENT, mockItem(CANNONBALL_ID, 5));
		stubContainer(InventoryID.SEED_VAULT, mockItem(CANNONBALL_ID, 100));
		stubContainer(InventoryID.GROUP_STORAGE, mockItem(CANNONBALL_ID, 200));
		stubContainer(InventoryID.KINGDOM_OF_MISCELLANIA, mockItem(CANNONBALL_ID, 3));

		assertEquals(338, tracker.countItem(CANNONBALL_ID));
	}

	@Test
	@DisplayName("countItem ignores containers that return null")
	void countItemIgnoresMissingContainers()
	{
		// Only inventory + equipment populated; bank/seed/group/misc all null.
		stubInventoryItems(mockItem(CANNONBALL_ID, 7));
		stubContainer(InventoryID.EQUIPMENT, mockItem(CANNONBALL_ID, 1));

		assertEquals(8, tracker.countItem(CANNONBALL_ID));
	}

	@Test
	@DisplayName("countItem returns 0 when no containers populated")
	void countItemZeroWhenAllNull()
	{
		assertEquals(0, tracker.countItem(CANNONBALL_ID));
	}

	@Test
	@DisplayName("countItem only counts matching itemId, ignores other items in containers")
	void countItemFiltersById()
	{
		stubInventoryItems(mockItem(CANNONBALL_ID, 50), mockItem(999, 1000));
		stubContainer(InventoryID.EQUIPMENT, mockItem(999, 1));
		assertEquals(50, tracker.countItem(CANNONBALL_ID));
	}
}

package com.goalplanner.tracker;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

@DisplayName("MiscellaniaAutoGoal.shouldAdd — when to auto-add a 100% approval goal")
class MiscellaniaAutoGoalTest
{
	private static boolean add(int prev, int cur, int increases, boolean enabled, boolean hasGoal)
	{
		return MiscellaniaAutoGoal.shouldAdd(prev, cur, increases, enabled, hasGoal);
	}

	@Test
	@DisplayName("fires on the 2nd+ increase (a real favour gain), not the 1st")
	void firesOnSecondIncrease()
	{
		assertFalse(add(50, 60, 1, true, false)); // 1st increase = login data sync
		assertTrue(add(50, 60, 2, true, false));  // 2nd increase = real gain
		assertTrue(add(50, 51, 3, true, false));  // later gains keep firing (re-add)
	}

	@Test
	@DisplayName("does not fire on the login baseline read (previous == -1)")
	void noFireOnBaseline()
	{
		assertFalse(add(-1, 127, 0, true, false));
		assertFalse(add(-1, 0, 0, true, false));
	}

	@Test
	@DisplayName("does not fire without an increase (same or lower)")
	void noFireWithoutIncrease()
	{
		assertFalse(add(60, 60, 2, true, false));
		assertFalse(add(60, 50, 2, true, false));
	}

	@Test
	@DisplayName("respects the toggle and an existing goal, but re-adds whenever missing")
	void respectsGuards()
	{
		assertFalse(add(50, 60, 2, false, false)); // toggle off
		assertFalse(add(50, 60, 2, true, true));   // a Misc. Approval goal already exists
		assertTrue(add(50, 60, 2, true, false));   // missing + 2nd increase -> re-add
	}

	@Test
	@DisplayName("FULL_APPROVAL is 127 (100%)")
	void fullApprovalConstant()
	{
		assertTrue(MiscellaniaAutoGoal.FULL_APPROVAL == 127);
	}
}

package com.goalplanner.tracker;

import com.goalplanner.model.Goal;
import com.goalplanner.model.GoalType;
import com.goalplanner.testsupport.MockGameState;
import com.goalplanner.testsupport.TrackerTestHarness;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Tests for {@link QuestTracker} using the MockGameState framework.
 * Validates that the tracker correctly reads quest completion state
 * via Quest.getState(client) (which internally uses runScript/getIntStack).
 */
class QuestTrackerTest
{
	private Goal makeQuestGoal(Quest quest)
	{
		return Goal.builder()
			.type(GoalType.QUEST)
			.name(quest.getName())
			.questName(quest.name())
			.targetValue(1)
			.currentValue(0)
			.build();
	}

	@Test
	@DisplayName("detects finished quest")
	void detectsFinishedQuest()
	{
