package com.goalplanner.tracker;

import com.goalplanner.model.Goal;
import com.goalplanner.model.GoalType;
import com.goalplanner.testsupport.MockGameState;
import com.goalplanner.testsupport.TrackerTestHarness;
import net.runelite.api.Skill;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Tests for {@link SkillTracker} using the MockGameState framework.
 * Validates that the tracker correctly reads skill XP from the client
 * and records goal progress.
 */
class SkillTrackerTest
{
	private Goal makeSkillGoal(Skill skill, int targetXp)
	{
		return Goal.builder()
			.type(GoalType.SKILL)
			.name(skill.getName() + " goal")
			.skillName(skill.name())
			.targetValue(targetXp)
			.currentValue(0)
			.build();
	}

	@Test
	@DisplayName("reads skill XP from client and records progress")
	void readsSkillXp()
	{
		MockGameState state = new MockGameState()
			.skillXp(Skill.WOODCUTTING, 500_000);

		var h = TrackerTestHarness.forSkills(state);
		Goal goal = makeSkillGoal(Skill.WOODCUTTING, 1_000_000);
		h.store().addGoal(goal);

		assertTrue(h.tracker().checkGoals(h.store().getGoals()));
		assertEquals(500_000, goal.getCurrentValue());
		assertFalse(goal.isComplete());
	}

	@Test
	@DisplayName("detects XP gain between snapshots")
	void detectsXpGain()
	{
		MockGameState before = new MockGameState().skillXp(Skill.MINING, 100_000);
		MockGameState after = before.copy().skillXp(Skill.MINING, 150_000);

		var h = TrackerTestHarness.forSkills(before);
		Goal goal = makeSkillGoal(Skill.MINING, 150_000);
		h.store().addGoal(goal);

		h.tracker().checkGoals(h.store().getGoals());
		assertEquals(100_000, goal.getCurrentValue());
		assertFalse(goal.isComplete());

		h = h.withNewState(after);
		h.tracker().checkGoals(h.store().getGoals());
		assertEquals(150_000, goal.getCurrentValue());
		assertTrue(goal.isComplete());
	}

	@Test
	@DisplayName("a completed 99 goal stays complete when a lower XP value is reported")
	void completedSkillGoalIsSticky()
	{
		MockGameState maxed = new MockGameState().skillXp(Skill.ATTACK, 13_034_431);
		MockGameState unsynced = new MockGameState().skillXp(Skill.ATTACK, 0);

		var h = TrackerTestHarness.forSkills(maxed);
		Goal goal = makeSkillGoal(Skill.ATTACK, 13_034_431);
		h.store().addGoal(goal);
		h.tracker().checkGoals(h.store().getGoals());
		assertTrue(goal.isComplete());
		long completedAt = goal.getCompletedAt();

		// XP is monotonic in game, so a lower read is a stale client, never a
		// loss: the goal is not re-read and its completion date is preserved.
		h = h.withNewState(unsynced);
		assertFalse(h.tracker().checkGoals(h.store().getGoals()));
		assertTrue(goal.isComplete());
		assertEquals(completedAt, goal.getCompletedAt());
		assertEquals(13_034_431, goal.getCurrentValue());
	}

	@Test
	@DisplayName("tracks multiple skills independently")
	void tracksMultipleSkills()
	{
		MockGameState state = new MockGameState()
			.skillXp(Skill.ATTACK, 50_000)
			.skillXp(Skill.STRENGTH, 75_000)
			.skillXp(Skill.FISHING, 200_000);

		var h = TrackerTestHarness.forSkills(state);
		Goal attack = makeSkillGoal(Skill.ATTACK, 100_000);
		Goal strength = makeSkillGoal(Skill.STRENGTH, 100_000);
		Goal fishing = makeSkillGoal(Skill.FISHING, 200_000);
		h.store().addGoal(attack);
		h.store().addGoal(strength);
		h.store().addGoal(fishing);

		h.tracker().checkGoals(h.store().getGoals());
		assertEquals(50_000, attack.getCurrentValue());
		assertEquals(75_000, strength.getCurrentValue());
		assertEquals(200_000, fishing.getCurrentValue());
		assertTrue(fishing.isComplete());
	}

	@Test
	@DisplayName("skips goals with null skillName")
	void skipsNullSkillName()
	{
		MockGameState state = new MockGameState();
		var h = TrackerTestHarness.forSkills(state);

		Goal goal = Goal.builder()
			.type(GoalType.SKILL)
			.name("Bad skill goal")
			.skillName(null)
			.targetValue(100)
			.build();
		h.store().addGoal(goal);

		assertFalse(h.tracker().checkGoals(h.store().getGoals()));
	}

	@Test
	@DisplayName("no-op when XP unchanged between checks")
	void noOpWhenUnchanged()
	{
		MockGameState state = new MockGameState().skillXp(Skill.AGILITY, 300_000);
		var h = TrackerTestHarness.forSkills(state);
		Goal goal = makeSkillGoal(Skill.AGILITY, 1_000_000);
		h.store().addGoal(goal);

		assertTrue(h.tracker().checkGoals(h.store().getGoals()));
		assertFalse(h.tracker().checkGoals(h.store().getGoals()),
			"second check with same XP should be no-op");
	}
}

package com.goalplanner.ui;

import com.goalplanner.model.AccountMetric;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Pure quick-fill preset math for account-metric goals (Task 3). The presets are
 * data-driven off {@link AccountMetric#getMaxTarget()}, so these lock the
 * "max always last, fractions nice-rounded and de-duplicated" contract the dock's
 * account form relies on.
 */
class AccountTargetPresetsTest
{
	@Test
	@DisplayName("every metric offers presets ending in its max, all within [min, max]")
	void everyMetricEndsInMaxAndStaysInRange()
	{
		for (AccountMetric m : AccountMetric.values())
		{
			int[] presets = AccountTargetPresets.presetsFor(m);
			assertTrue(presets.length >= 1, m + " produced no presets");
			assertEquals(m.getMaxTarget(), presets[presets.length - 1],
				m + " last preset should be the max");
			for (int v : presets)
			{
				assertTrue(v >= m.getMinTarget() && v <= m.getMaxTarget(),
					m + " preset " + v + " out of [" + m.getMinTarget() + ", " + m.getMaxTarget() + "]");
			}
			// Strictly ascending (a byproduct of dedup + clamp + max-last).
			for (int i = 1; i < presets.length; i++)
			{
				assertTrue(presets[i] > presets[i - 1],
					m + " presets not strictly ascending: " + java.util.Arrays.toString(presets));
			}
		}
	}

	@Test
	@DisplayName("a small ceiling still yields distinct quarter/half/three-quarter steps")
	void smallCeilingStaysDistinct()
	{
		// DOM_DEEPEST_LEVEL max = 8 -> 2, 4, 6, 8.
		assertArrayEquals(new int[] { 2, 4, 6, 8 },
			AccountTargetPresets.presetsFor(AccountMetric.DOM_DEEPEST_LEVEL));
	}

	@Test
	@DisplayName("nice-round scales the step to the magnitude")
	void niceRoundScales()
	{
		assertEquals(31, AccountTargetPresets.niceRound(31));       // < 50 exact
		assertEquals(170, AccountTargetPresets.niceRound(169));     // step 5
		assertEquals(1190, AccountTargetPresets.niceRound(1188));   // step 10
		assertEquals(16000, AccountTargetPresets.niceRound(16000)); // step 100
		assertEquals(125000, AccountTargetPresets.niceRound(125000)); // step 1000
	}
}

package com.goalplanner.ui;

import java.awt.Component;
import java.awt.Container;
import javax.swing.AbstractButton;
import javax.swing.SwingUtilities;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Field report 2026-08-27 (screenshot): the Options surface showed "Join our
 * Discord | Import shared goals... | Sav" - every chip past the dock edge was
 * simply CLIPPED. The expanded surface rode a HORIZONTAL_SCROLLBAR_NEVER
 * viewport as a plain panel, which does not track viewport width, so
 * WrapLayout measured against MAX_VALUE and laid one endless row.
 *
 * <p>The tree harness cannot see this - the chips exist and carry the right
 * text - so this net asserts GEOMETRY: after a real layout at panel width,
 * every visible button in the dock must fit inside the panel's bounds.
 */
class DockSurfaceWidthTest extends HeadlessRenderTest
{
	@Test
	@DisplayName("every chip on a wide choice surface stays inside the panel")
	void wideChoiceSurfaceWraps() throws Exception
	{
		SwingUtilities.invokeAndWait(() ->
		{
			Object[] holder = seeded();
			GoalPanel panel = (GoalPanel) holder[0];
			// The Options list: six chips, the widest choice surface shipped.
			panel.openChoiceSurface("Options", new String[]{
				"Join our Discord", "Import shared goals...", "Saved plans...",
				"Remove duplicate goals", "Delete empty sections",
				"Delete all goals and sections"}, -1, i -> { });
			panel.setSize(WIDTH, 520);
			layoutDeep(panel);

			int overflow = 0;
			StringBuilder out = new StringBuilder();
			for (AbstractButton b : buttonsOf(panel))
			{
				if (!b.isShowing() && b.getWidth() == 0)
				{
					continue;
				}
				java.awt.Point p = SwingUtilities.convertPoint(
					b.getParent(), b.getLocation(), panel);
				// Only the RIGHT edge: a wrap failure clips rightward, while a
				// negative x is viewport-scrolled content, not clipping.
				if (p.x + b.getWidth() > WIDTH)
				{
					overflow++;
					out.append("\n  ").append(b.getText())
						.append(" @x=").append(p.x)
						.append(" w=").append(b.getWidth());
				}
			}
			assertEquals(0, overflow,
				"chips clipped past the dock edge (panel width " + WIDTH + "):" + out);
		});
	}

	private static java.util.List<AbstractButton> buttonsOf(Container root)
	{
		java.util.List<AbstractButton> out = new java.util.ArrayList<>();
		for (Component c : root.getComponents())
		{
			if (c instanceof AbstractButton)
			{
				out.add((AbstractButton) c);
			}
			if (c instanceof Container)
			{
				out.addAll(buttonsOf((Container) c));
			}
		}
		return out;
	}
}

