				RelativeTargetResolver.resolveSkillXp(199_000_000, 5_000_000));
		}

		@Test
		@DisplayName("zero current XP is fine")
		void zeroCurrent()
		{
			assertEquals(1000, RelativeTargetResolver.resolveSkillXp(0, 1000));
		}

