package com.goalplanner.ui.dock;

import java.util.Set;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;

/**
 * The dock's state decision (ADR-0007). Small on purpose - everything else
 * about the dock is render-path and verified by screenshot.
 */
class DockContextTest
{
	@Test
	@DisplayName("no selection is the panel-level state")
	void emptySelection()
	{
		assertEquals(DockContext.State.EMPTY, DockContext.of(Set.of()).getState());
		assertEquals(DockContext.State.EMPTY, DockContext.of(null).getState());
		assertNull(DockContext.of(Set.of()).getSoleGoalId());
	}

	@Test
	@DisplayName("one goal selected carries its id")
	void singleSelection()
	{
		DockContext ctx = DockContext.of(Set.of("g1"));
		assertEquals(DockContext.State.GOAL, ctx.getState());
		assertEquals("g1", ctx.getSoleGoalId());
		assertEquals(1, ctx.getCount());
	}

	@Test
	@DisplayName("several goals selected is the bulk state with a count")
	void multiSelection()
	{
		DockContext ctx = DockContext.of(Set.of("g1", "g2", "g3"));
		assertEquals(DockContext.State.MULTI, ctx.getState());
		assertNull(ctx.getSoleGoalId(), "no single target in bulk state");
		assertEquals(3, ctx.getCount());
	}

	@Test
	@DisplayName("a section selected with no goals is the section state carrying its id")
	void sectionSelection()
	{
		DockContext ctx = DockContext.of(Set.of(), "s1");
		assertEquals(DockContext.State.SECTION, ctx.getState());
		assertEquals("s1", ctx.getSectionId());
		assertNull(ctx.getSoleGoalId(), "no goal target in section state");
	}

	@Test
	@DisplayName("selected goals win over a section id")
	void goalsWinOverSection()
	{
		DockContext one = DockContext.of(Set.of("g1"), "s1");
		assertEquals(DockContext.State.GOAL, one.getState());
		assertEquals("g1", one.getSoleGoalId());
		assertNull(one.getSectionId(), "goal selection suppresses the section");

		DockContext many = DockContext.of(Set.of("g1", "g2"), "s1");
		assertEquals(DockContext.State.MULTI, many.getState());
		assertNull(many.getSectionId(), "bulk selection suppresses the section");
	}

	@Test
	@DisplayName("nothing selected and no section is the empty state")
	void nothingSelected()
	{
		assertEquals(DockContext.State.EMPTY, DockContext.of(Set.of(), null).getState());
		assertEquals(DockContext.State.EMPTY, DockContext.of(null, null).getState());
		assertNull(DockContext.of(Set.of(), null).getSectionId());
	}
}

package com.goalplanner.ui.nest;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

@DisplayName("NestIndentAssigner — outline-tree nesting from dependencies")
class NestIndentAssignerTest
{
	private static NestIndentAssigner.Node node(String id, String... prereqs)
	{
		return new NestIndentAssigner.Node(id, new ArrayList<>(Arrays.asList(prereqs)));
	}

	@Test
	@DisplayName("resolveVisiblePrereqs follows a chain through a hidden (completed) goal")
	void resolveVisiblePrereqsBridgesHiddenNode()
	{
		// a requires b, b requires c; b is hidden (completed) → a's visible prereq is c.
		java.util.Map<String, List<String>> edges = new java.util.HashMap<>();
		edges.put("a", Arrays.asList("b"));
		edges.put("b", Arrays.asList("c"));
		edges.put("c", new ArrayList<>());
		java.util.Set<String> hidden = new java.util.HashSet<>(Arrays.asList("b"));

		List<String> visible = NestIndentAssigner.resolveVisiblePrereqs(
			edges.get("a"), edges::get, hidden::contains);
		assertEquals(Arrays.asList("c"), visible);
	}

	@Test
	@DisplayName("resolveVisiblePrereqs keeps visible prereqs, drops fully-hidden chains, survives cycles")
	void resolveVisiblePrereqsMixedAndCycleSafe()
	{
		// a requires [b(hidden), d]; b requires c(hidden); c requires b (cycle) → just d.
		java.util.Map<String, List<String>> edges = new java.util.HashMap<>();
		edges.put("a", Arrays.asList("b", "d"));
		edges.put("b", Arrays.asList("c"));
		edges.put("c", Arrays.asList("b"));
		edges.put("d", new ArrayList<>());
		java.util.Set<String> hidden = new java.util.HashSet<>(Arrays.asList("b", "c"));

		List<String> visible = NestIndentAssigner.resolveVisiblePrereqs(
			edges.get("a"), edges::get, hidden::contains);
		assertEquals(Arrays.asList("d"), visible);
	}

	@Test
	@DisplayName("a chain through a completed goal still nests the dependent under its grandparent")
	void chainThroughCompletedGoalKeepsNesting()
	{
		// Section: c (incomplete), b (completed, requires c), a (requires b).
		// The completed b is excluded from the outline; expanding a's prereqs
		// through b must yield c, so a nests under c instead of flattening.
		java.util.Map<String, List<String>> edges = new java.util.HashMap<>();
		edges.put("c", new ArrayList<>());
		edges.put("b", Arrays.asList("c"));
		edges.put("a", Arrays.asList("b"));
		java.util.Set<String> completed = new java.util.HashSet<>(Arrays.asList("b"));

		List<NestIndentAssigner.Node> nodes = new ArrayList<>();
		for (String id : Arrays.asList("c", "a")) // topo order, completed excluded
		{
			nodes.add(new NestIndentAssigner.Node(id, NestIndentAssigner.resolveVisiblePrereqs(
				edges.get(id), edges::get, completed::contains)));
		}
		NestIndentAssigner.Result r = NestIndentAssigner.assign(nodes);
		assertEquals(Arrays.asList("c", "a"), r.ordered);
		assertEquals(0, r.level.get("c"));
		assertEquals(1, r.level.get("a"));
		assertEquals("c", r.primaryParent.get("a"));
	}

	@Test
	@DisplayName("a goal with no in-section prerequisites is a root at level 0")
	void rootsAreLevelZero()
	{
		NestIndentAssigner.Result r = NestIndentAssigner.assign(Arrays.asList(
			node("a"), node("b")));
		assertEquals(0, r.level.get("a"));
		assertEquals(0, r.level.get("b"));
		assertNull(r.primaryParent.get("a"));
	}

	@Test
	@DisplayName("a straight chain nests each goal under the one it needs")
	void chainNestsUnderParent()
	{
		NestIndentAssigner.Result r = NestIndentAssigner.assign(Arrays.asList(
			node("a"), node("b", "a"), node("c", "b")));
		assertEquals(Arrays.asList("a", "b", "c"), r.ordered);
		assertEquals(0, r.level.get("a"));
		assertEquals(1, r.level.get("b"));
		assertEquals(2, r.level.get("c"));
		assertEquals("a", r.primaryParent.get("b"));
		assertEquals("b", r.primaryParent.get("c"));
	}

	@Test
	@DisplayName("a child is emitted immediately after its parent (pre-order)")
	void preOrderPlacesChildUnderParent()
	{
		// two independent roots, each with a child — children follow their own parent
		NestIndentAssigner.Result r = NestIndentAssigner.assign(Arrays.asList(
			node("root1"), node("root2"), node("child1", "root1"), node("child2", "root2")));
		assertEquals(Arrays.asList("root1", "child1", "root2", "child2"), r.ordered);
	}

	@Test
	@DisplayName("a diamond goal nests under its deepest prerequisite; the rest are 'extra'")
	void diamondNestsUnderPrimaryAndCountsExtras()
	{
		NestIndentAssigner.Result r = NestIndentAssigner.assign(Arrays.asList(
			node("agility"), node("combat"), node("ranged"),
			node("mm2", "agility", "combat"),
			node("dt2", "combat", "ranged"),
			node("sote", "agility", "ranged"),
			node("qpc", "mm2", "dt2", "sote"),
			node("fire"), node("inferno"),
			node("gm", "qpc", "fire", "inferno")));

		// Quest Cape's three prereqs are all level 1 → primary is the first (mm2),
		// the other two are extras. It sits one level past mm2.
		assertEquals("mm2", r.primaryParent.get("qpc"));
		assertEquals(2, r.level.get("qpc"));
		assertEquals(2, r.extraPrereqs.get("qpc"));

		// Grandmaster nests under Quest Cape (depth 2), not Fire/Infernal (depth 0).
		assertEquals("qpc", r.primaryParent.get("gm"));
		assertEquals(3, r.level.get("gm"));
		assertEquals(2, r.extraPrereqs.get("gm")); // fire + inferno

		// Spine reads parent-then-child: agility → mm2 → qpc → gm.
		List<String> o = r.ordered;
		assertEquals(true, o.indexOf("agility") < o.indexOf("mm2"));
		assertEquals(true, o.indexOf("mm2") < o.indexOf("qpc"));
		assertEquals(true, o.indexOf("qpc") < o.indexOf("gm"));
	}

	@Test
	@DisplayName("OR prerequisites nest just like AND prerequisites")
	void orPrereqsNestToo()
	{
		NestIndentAssigner.Result r = NestIndentAssigner.assign(Arrays.asList(
			node("a"), node("b", "a"), node("gm", "b")));
		assertEquals(2, r.level.get("gm"));
		assertEquals("b", r.primaryParent.get("gm"));
	}

	@Test
	@DisplayName("prerequisites not present in the section are ignored")
	void crossSectionPrereqsIgnored()
	{
		NestIndentAssigner.Result r = NestIndentAssigner.assign(Arrays.asList(
			node("b", "external")));
		assertEquals(0, r.level.get("b"));
		assertNull(r.primaryParent.get("b"));
		assertEquals(0, r.extraPrereqs.get("b"));
	}

	@Test
	@DisplayName("every input goal appears exactly once in the order")
	void everyGoalEmittedOnce()
	{
		NestIndentAssigner.Result r = NestIndentAssigner.assign(Arrays.asList(
			node("a"), node("b", "a"), node("c", "a", "b")));
		assertEquals(3, r.ordered.size());
		assertEquals(3, r.level.size());
	}
}

package com.goalplanner.util;

import com.goalplanner.util.AccountBindingGate.Decision;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * The decision logic behind "may these goals be tracked against this account?".
 *
 * <p>This is the half that can fail silently: a gate that answers TRACK when it
 * should PAUSE re-enables the bug it was written to prevent, and one that
 * announces on every tick spams the chat box. Neither is visible from the store
 * tests, which only cover persistence.
 */
class AccountBindingGateTest
{
	private static final long MAIN = 111_111L;
	private static final long ALT = 222_222L;
	private static final long UNBOUND = 0L;

	@Nested
	@DisplayName("decisions")
	class Decisions
	{
		@Test
		@DisplayName("an unbound goal set adopts whoever is logged in")
		void unboundAdopts()
		{
			assertEquals(Decision.ADOPT, new AccountBindingGate().evaluate(MAIN, UNBOUND));
		}

		@Test
		@DisplayName("a matching account tracks")
		void matchTracks()
		{
			assertEquals(Decision.TRACK, new AccountBindingGate().evaluate(MAIN, MAIN));
		}

		@Test
		@DisplayName("a different account pauses - the whole point of the gate")
		void mismatchPauses()
		{
			assertEquals(Decision.PAUSE, new AccountBindingGate().evaluate(ALT, MAIN));
		}

		@Test
		@DisplayName("any non-positive live hash is 'no account', whatever sentinel the client uses")
		void nonPositiveIsNoAccount()
		{
			AccountBindingGate gate = new AccountBindingGate();
			for (long sentinel : new long[]{-1L, 0L, Long.MIN_VALUE})
			{
				assertEquals(Decision.NO_ACCOUNT, gate.evaluate(sentinel, MAIN),
					"sentinel " + sentinel + " must not fall through");
				assertEquals(Decision.NO_ACCOUNT, gate.evaluate(sentinel, UNBOUND),
					"and must never trigger adoption, which would unbind the goal set");
			}
		}

		@Test
		@DisplayName("only TRACK and ADOPT permit tracking")
		void allowsTracking()
		{
			assertTrue(AccountBindingGate.allowsTracking(Decision.TRACK));
			assertTrue(AccountBindingGate.allowsTracking(Decision.ADOPT));
			assertFalse(AccountBindingGate.allowsTracking(Decision.PAUSE));
			assertFalse(AccountBindingGate.allowsTracking(Decision.NO_ACCOUNT));
		}
	}

	@Nested
	@DisplayName("announcing a mismatch")
	class Announcing
	{
		@Test
		@DisplayName("announces once, then stays quiet across repeated drains")
		void announcesOnce()
		{
			AccountBindingGate gate = new AccountBindingGate();
			gate.evaluate(ALT, MAIN);

			assertTrue(gate.shouldAnnounceMismatch(), "the user must be told once");
			// A drain runs every tick; without the latch this is chat spam.
			for (int tick = 0; tick < 100; tick++)
			{
				gate.evaluate(ALT, MAIN);
				assertFalse(gate.shouldAnnounceMismatch(),
					"repeated at tick " + tick + " - the warning must not repeat per tick");
			}
		}

		@Test
		@DisplayName("a later mismatch announces again after the account comes back into line")
		void reAnnouncesAfterRecovery()
		{
			AccountBindingGate gate = new AccountBindingGate();
			gate.evaluate(ALT, MAIN);
			assertTrue(gate.shouldAnnounceMismatch());

			// User switches to the right profile.
			assertEquals(Decision.TRACK, gate.evaluate(MAIN, MAIN));

			// ...and later gets it wrong again. Silence here would hide a real problem.
			assertEquals(Decision.PAUSE, gate.evaluate(ALT, MAIN));
			assertTrue(gate.shouldAnnounceMismatch(), "a fresh mismatch is fresh news");
		}

		@Test
		@DisplayName("logging out does not clear the latch, so a relog on the wrong account stays quiet")
		void logoutDoesNotResetLatch()
		{
			AccountBindingGate gate = new AccountBindingGate();
			gate.evaluate(ALT, MAIN);
			assertTrue(gate.shouldAnnounceMismatch());

			// Log out, log back in on the same wrong account.
			assertEquals(Decision.NO_ACCOUNT, gate.evaluate(-1L, MAIN));
			assertEquals(Decision.PAUSE, gate.evaluate(ALT, MAIN));

			assertFalse(gate.shouldAnnounceMismatch(),
				"relogging on the same wrong account is the same episode, not a new one");
		}

		@Test
		@DisplayName("adoption clears the latch, so a rebound set can warn again later")
		void adoptionResetsLatch()
		{
			AccountBindingGate gate = new AccountBindingGate();
			gate.evaluate(ALT, MAIN);
			assertTrue(gate.shouldAnnounceMismatch());

			assertEquals(Decision.ADOPT, gate.evaluate(ALT, UNBOUND));
			assertEquals(Decision.PAUSE, gate.evaluate(MAIN, ALT));
			assertTrue(gate.shouldAnnounceMismatch());
		}
	}
}

package com.goalplanner.util;

import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class FormatUtilTest
{
	@Test
	public void testFormatNumberSmall()
	{
		assertEquals("0", FormatUtil.formatNumber(0));
		assertEquals("999", FormatUtil.formatNumber(999));
		assertEquals("1", FormatUtil.formatNumber(1));
	}

	@Test
	public void testFormatNumberThousands()
	{
		assertEquals("1K", FormatUtil.formatNumber(1_000));
		assertEquals("50K", FormatUtil.formatNumber(50_000));
		assertEquals("1000K", FormatUtil.formatNumber(999_999));
		assertEquals("500K", FormatUtil.formatNumber(500_000));
	}

	@Test
	public void testFormatNumberMillions()
	{
		assertEquals("1.0M", FormatUtil.formatNumber(1_000_000));
		assertEquals("13.0M", FormatUtil.formatNumber(13_034_431));
		assertEquals("200.0M", FormatUtil.formatNumber(200_000_000));
	}

	@Test
	public void testFormatXp()
	{
		assertEquals("0", FormatUtil.formatXp(0));
		assertEquals("1,234", FormatUtil.formatXp(1_234));
		assertEquals("13,034,431", FormatUtil.formatXp(13_034_431));
	}

	@Test
	public void testTruncate()
	{
		assertEquals("Hello", FormatUtil.truncate("Hello", 10));
		assertEquals("Hello W...", FormatUtil.truncate("Hello World", 10));
		assertEquals("", FormatUtil.truncate(null, 10));
		assertEquals("A", FormatUtil.truncate("A", 1));
	}

	@Test
	public void testFormatProgressPercentFloorsInsteadOfRounding()
	{
		// 126/127 Miscellania favour = 99.2% - used to round to a misleading "100%".
		assertEquals("99%", FormatUtil.formatProgressPercent(126, 127));
		// 99.6% floors to 99, not 100.
		assertEquals("99%", FormatUtil.formatProgressPercent(996, 1000));
		assertEquals("0%", FormatUtil.formatProgressPercent(9, 1000));
		assertEquals("50%", FormatUtil.formatProgressPercent(1, 2));
	}

	@Test
	public void testFormatProgressPercentNeverClaimsCompletion()
	{
		// Callers only render this for goals that are NOT complete.
		assertEquals("99%", FormatUtil.formatProgressPercent(127, 127));
		assertEquals("99%", FormatUtil.formatProgressPercent(500, 100));
	}

	@Test
	public void testFormatProgressPercentEdgeCases()
	{
		assertEquals("0%", FormatUtil.formatProgressPercent(50, 0));
		assertEquals("0%", FormatUtil.formatProgressPercent(-5, 100));
	}

	@Test
	public void testEscapeHtml()
	{
		assertEquals("hello", FormatUtil.escapeHtml("hello"));
		assertEquals("a &amp; b", FormatUtil.escapeHtml("a & b"));
		assertEquals("&lt;script&gt;", FormatUtil.escapeHtml("<script>"));
		assertEquals("", FormatUtil.escapeHtml(null));
	}
}

package com.goalplanner.util;

import com.goalplanner.ResetBoundary;
import com.goalplanner.model.RepeatPeriod;
import java.time.DayOfWeek;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.time.ZoneOffset;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Pure clock math for repeatable goals. No Swing, no client - every case here
 * is a date or an instant in, an integer or an instant out.
 */
class RepeatScheduleTest
{
	private static final ZoneId NEW_YORK = ZoneId.of("America/New_York");

	private static long dayKey(LocalDate d)
	{
		return RepeatSchedule.periodKey(RepeatPeriod.DAILY, d);
	}

	private static long weekKey(LocalDate d)
	{
		return RepeatSchedule.periodKey(RepeatPeriod.WEEKLY, d);
	}

	private static long monthKey(LocalDate d)
	{
		return RepeatSchedule.periodKey(RepeatPeriod.MONTHLY, d);
	}

	@Nested
	@DisplayName("daily period key")
	class Daily
	{
		@Test
		@DisplayName("consecutive days advance the key by exactly one")
		void consecutiveDays()
		{
			assertEquals(dayKey(LocalDate.of(2026, 7, 29)) + 1,
				dayKey(LocalDate.of(2026, 7, 30)));
		}

		@Test
		@DisplayName("the same date is the same period")
		void sameDay()
		{
			assertEquals(dayKey(LocalDate.of(2026, 7, 29)),
				dayKey(LocalDate.of(2026, 7, 29)));
		}

		@Test
		@DisplayName("five days offline is a five-key jump, not five separate rollovers")
		void fiveDaysOffline()
		{
			assertEquals(dayKey(LocalDate.of(2026, 7, 24)) + 5,
				dayKey(LocalDate.of(2026, 7, 29)));
		}
	}

	@Nested
	@DisplayName("weekly period key")
	class Weekly
	{
		@Test
		@DisplayName("the week rolls over on Wednesday, matching OSRS")
		void rollsOverOnWednesday()
		{
			LocalDate tuesday = LocalDate.of(2026, 7, 28);
			LocalDate wednesday = LocalDate.of(2026, 7, 29);
			LocalDate thursday = LocalDate.of(2026, 7, 30);
			// Pin the calendar assumption this test rests on.
			assertEquals(DayOfWeek.TUESDAY, tuesday.getDayOfWeek());
			assertEquals(DayOfWeek.WEDNESDAY, wednesday.getDayOfWeek());

			assertEquals(weekKey(tuesday) + 1, weekKey(wednesday),
				"Tuesday to Wednesday must cross a week boundary");
			assertEquals(weekKey(wednesday), weekKey(thursday),
				"Wednesday to Thursday must stay in the same week");
		}

		@Test
		@DisplayName("seven days on advances exactly one week")
		void sevenDays()
		{
			LocalDate d = LocalDate.of(2026, 7, 29);
			assertEquals(weekKey(d) + 1, weekKey(d.plusDays(7)));
		}

		@Test
		@DisplayName("keys before the 1970 epoch still advance monotonically")
		void beforeEpoch()
		{
			LocalDate d = LocalDate.of(1969, 5, 14);
			assertEquals(weekKey(d) + 1, weekKey(d.plusDays(7)));
		}
	}

	@Nested
	@DisplayName("monthly period key")
	class Monthly
	{
		@Test
		@DisplayName("a 31-day month advances the key by exactly one")
		void longMonth()
		{
			assertEquals(monthKey(LocalDate.of(2026, 1, 1)) + 1,
				monthKey(LocalDate.of(2026, 2, 1)));
		}

		@Test
		@DisplayName("a 30-day month advances the key by exactly one")
		void thirtyDayMonth()
		{
			assertEquals(monthKey(LocalDate.of(2026, 4, 30)) + 1,
				monthKey(LocalDate.of(2026, 5, 1)));
		}

		@Test
		@DisplayName("February in a leap year advances the key by exactly one")
		void leapFebruary()
		{
			assertEquals(LocalDate.of(2028, 2, 29).getDayOfMonth(), 29, "2028 is a leap year");
			assertEquals(monthKey(LocalDate.of(2028, 2, 29)) + 1,
				monthKey(LocalDate.of(2028, 3, 1)));
		}

		@Test
		@DisplayName("December to January advances by one across the year boundary")
		void yearRollover()
		{
			assertEquals(monthKey(LocalDate.of(2026, 12, 31)) + 1,
				monthKey(LocalDate.of(2027, 1, 1)));
		}

		@Test
		@DisplayName("the same month in different years is NOT the same period")
		void januarysDoNotCollide()
		{
			// Regression guard: a bare getMonthValue() would make these equal.
			assertNotEquals(monthKey(LocalDate.of(2026, 1, 15)),
				monthKey(LocalDate.of(2027, 1, 15)));
		}

		@Test
		@DisplayName("every day within a month shares one key")
		void withinMonth()
		{
			assertEquals(monthKey(LocalDate.of(2026, 7, 1)),
				monthKey(LocalDate.of(2026, 7, 31)));
		}
	}

	@Nested
	@DisplayName("boundary date")
	class BoundaryDate
	{
		@Test
		@DisplayName("before the custom hour, the moment still belongs to the previous day")
		void beforeCustomHour()
		{
			Instant at3am = LocalDate.of(2026, 7, 29).atTime(3, 0).atZone(NEW_YORK).toInstant();
			assertEquals(LocalDate.of(2026, 7, 28),
				RepeatSchedule.boundaryDate(at3am, NEW_YORK, 5));
		}

		@Test
		@DisplayName("after the custom hour, the moment belongs to the current day")
		void afterCustomHour()
		{
			Instant at6am = LocalDate.of(2026, 7, 29).atTime(6, 0).atZone(NEW_YORK).toInstant();
			assertEquals(LocalDate.of(2026, 7, 29),
				RepeatSchedule.boundaryDate(at6am, NEW_YORK, 5));
		}

		@Test
		@DisplayName("UTC and a western zone disagree about the date late in the evening")
		void zoneMatters()
		{
			// 22:00 New York on the 29th is already the 30th in UTC.
			Instant evening = LocalDate.of(2026, 7, 29).atTime(22, 0).atZone(NEW_YORK).toInstant();
			assertEquals(LocalDate.of(2026, 7, 29),
				RepeatSchedule.boundaryDate(evening, NEW_YORK, 0));
			assertEquals(LocalDate.of(2026, 7, 30),
				RepeatSchedule.boundaryDate(evening, ZoneOffset.UTC, 0));
		}
	}

	@Nested
	@DisplayName("next boundary")
	class NextBoundary
	{
		@Test
		@DisplayName("NONE never rolls over")
		void noneIsNull()
		{
			assertNull(RepeatSchedule.nextBoundary(
				RepeatPeriod.NONE, Instant.now(), ZoneOffset.UTC, 0));
		}

		@Test
		@DisplayName("daily lands on the next midnight UTC")
		void dailyBoundary()
		{
			Instant now = LocalDate.of(2026, 7, 29).atTime(13, 0).atZone(ZoneOffset.UTC).toInstant();
			Instant expected = LocalDate.of(2026, 7, 30).atStartOfDay(ZoneOffset.UTC).toInstant();
			assertEquals(expected,
				RepeatSchedule.nextBoundary(RepeatPeriod.DAILY, now, ZoneOffset.UTC, 0));
		}

		@Test
		@DisplayName("weekly lands on the next Wednesday")
		void weeklyBoundary()
		{
			// Thursday the 30th - the next Wednesday is 5 August.
			Instant now = LocalDate.of(2026, 7, 30).atTime(13, 0).atZone(ZoneOffset.UTC).toInstant();
			Instant boundary =
				RepeatSchedule.nextBoundary(RepeatPeriod.WEEKLY, now, ZoneOffset.UTC, 0);
			LocalDate landed = boundary.atZone(ZoneOffset.UTC).toLocalDate();
			assertEquals(DayOfWeek.WEDNESDAY, landed.getDayOfWeek());
			assertEquals(LocalDate.of(2026, 8, 5), landed);
		}

		@Test
		@DisplayName("monthly lands on the 1st of the next month, even from the 31st")
		void monthlyBoundary()
		{
			Instant now = LocalDate.of(2026, 7, 31).atTime(23, 0).atZone(ZoneOffset.UTC).toInstant();
			Instant expected = LocalDate.of(2026, 8, 1).atStartOfDay(ZoneOffset.UTC).toInstant();
			assertEquals(expected,
				RepeatSchedule.nextBoundary(RepeatPeriod.MONTHLY, now, ZoneOffset.UTC, 0));
		}

		@Test
		@DisplayName("monthly can fall sooner than weekly, so deadline order is not fixed")
		void monthlyCanBeatWeekly()
		{
			// 31 July 2026 is a Friday: the month rolls tomorrow, the week waits for Wednesday.
			LocalDate d = LocalDate.of(2026, 7, 31);
			assertEquals(DayOfWeek.FRIDAY, d.getDayOfWeek());
			Instant now = d.atTime(12, 0).atZone(ZoneOffset.UTC).toInstant();

			Instant monthly = RepeatSchedule.nextBoundary(RepeatPeriod.MONTHLY, now, ZoneOffset.UTC, 0);
			Instant weekly = RepeatSchedule.nextBoundary(RepeatPeriod.WEEKLY, now, ZoneOffset.UTC, 0);

			assertTrue(monthly.isBefore(weekly),
				"monthly must be able to precede weekly - the UI cannot order groups by enum");
		}

		@Test
		@DisplayName("a spring-forward DST day still advances exactly one day")
		void dstSpringForward()
		{
			// 8 March 2026, 02:00 does not exist in New York.
			Instant now = LocalDate.of(2026, 3, 7).atTime(12, 0).atZone(NEW_YORK).toInstant();
			Instant boundary =
				RepeatSchedule.nextBoundary(RepeatPeriod.DAILY, now, NEW_YORK, 0);
			assertEquals(LocalDate.of(2026, 3, 8),
				boundary.atZone(NEW_YORK).toLocalDate());
		}
	}

	@Nested
	@DisplayName("countdown and key stay consistent")
	class CountdownInvariant
	{
		/**
		 * The invariant the whole feature rests on: the moment the countdown
		 * reaches zero is exactly the moment the period key changes. If these
		 * ever drift, the panel shows "resets in 0m" while nothing resets.
		 */
		@Test
		@DisplayName("the key is unchanged just before the boundary and changed at it")
		void keyFlipsExactlyAtBoundary()
		{
			for (RepeatPeriod period : new RepeatPeriod[]{
				RepeatPeriod.DAILY, RepeatPeriod.WEEKLY, RepeatPeriod.MONTHLY})
			{
				for (int hour : new int[]{0, 5, 23})
				{
					Instant now = LocalDate.of(2026, 7, 29)
						.atTime(13, 0).atZone(NEW_YORK).toInstant();
					Instant boundary =
						RepeatSchedule.nextBoundary(period, now, NEW_YORK, hour);

					long keyNow = RepeatSchedule.periodKey(period,
						RepeatSchedule.boundaryDate(now, NEW_YORK, hour));
					long keyJustBefore = RepeatSchedule.periodKey(period,
						RepeatSchedule.boundaryDate(boundary.minusMillis(1), NEW_YORK, hour));
					long keyAt = RepeatSchedule.periodKey(period,
						RepeatSchedule.boundaryDate(boundary, NEW_YORK, hour));

					assertEquals(keyNow, keyJustBefore,
						period + " at hour " + hour + ": key must hold until the boundary");
					assertNotEquals(keyNow, keyAt,
						period + " at hour " + hour + ": key must change at the boundary");
				}
			}
		}
	}

	@Nested
	@DisplayName("changing the boundary")
	class BoundaryChange
	{
		/**
		 * Two consequences of one fact. Useful: changing the reset config is
		 * how you force a rollover on demand instead of waiting for midnight.
		 * Awkward: it means a user who changes the setting mid-period gets one
		 * unearned reset. Both follow from the key depending on the hour.
		 */
		@Test
		@DisplayName("the same instant falls in different periods under different boundary hours")
		void boundaryHourShiftsTheKey()
		{
			Instant t = LocalDate.of(2026, 7, 27).atTime(12, 0).atZone(ZoneOffset.UTC).toInstant();

			long atMidnight = RepeatSchedule.periodKey(RepeatPeriod.DAILY,
				RepeatSchedule.boundaryDate(t, ZoneOffset.UTC, 0));
			long atSix = RepeatSchedule.periodKey(RepeatPeriod.DAILY,
				RepeatSchedule.boundaryDate(t, ZoneOffset.UTC, 18));

			assertNotEquals(atMidnight, atSix,
				"noon belongs to the 27th under a midnight boundary but to the 26th under an 18:00 one");
		}
	}

	@Nested
	@DisplayName("boundary mode mapping")
	class BoundaryMode
	{
		@Test
		@DisplayName("game reset measures days in UTC at hour zero")
		void gameReset()
		{
			assertEquals(ZoneOffset.UTC, RepeatSchedule.zoneFor(ResetBoundary.GAME_RESET));
			assertEquals(0, RepeatSchedule.hourFor(ResetBoundary.GAME_RESET, 9));
		}

		@Test
		@DisplayName("local midnight ignores the configured hour")
		void localMidnight()
		{
			assertEquals(0, RepeatSchedule.hourFor(ResetBoundary.LOCAL_MIDNIGHT, 9));
		}

		@Test
		@DisplayName("custom hour uses the configured hour, clamped to 0-23")
		void customHour()
		{
			assertEquals(9, RepeatSchedule.hourFor(ResetBoundary.CUSTOM_HOUR, 9));
			assertEquals(23, RepeatSchedule.hourFor(ResetBoundary.CUSTOM_HOUR, 99));
			assertEquals(0, RepeatSchedule.hourFor(ResetBoundary.CUSTOM_HOUR, -3));
		}
	}

	@Nested
	@DisplayName("countdown formatting")
	class Countdown
	{
		@Test
		@DisplayName("under an hour shows minutes only")
		void minutesOnly()
		{
			assertEquals("42m", RepeatSchedule.formatCountdown(42 * 60_000L));
		}

		@Test
		@DisplayName("under a day shows hours and minutes")
		void hoursAndMinutes()
		{
			assertEquals("3h 42m", RepeatSchedule.formatCountdown((3 * 3600 + 42 * 60) * 1000L));
		}

		@Test
		@DisplayName("over a day shows days and hours, so monthly reads sensibly")
		void daysAndHours()
		{
			assertEquals("29d 03h",
				RepeatSchedule.formatCountdown((29 * 86_400L + 3 * 3600L) * 1000L));
		}

		@Test
		@DisplayName("zero and negative clamp to 0m rather than going negative")
		void nonNegative()
		{
			assertEquals("0m", RepeatSchedule.formatCountdown(0));
			assertEquals("0m", RepeatSchedule.formatCountdown(-5000));
		}

		@Test
		@DisplayName("output is ASCII only - Swing tofus symbol glyphs on macOS")
		void asciiOnly()
		{
			String s = RepeatSchedule.formatCountdown((2 * 86_400L + 5 * 3600L) * 1000L);
			assertTrue(s.chars().allMatch(c -> c < 128), "non-ASCII in countdown: " + s);
		}
	}

	@Nested
	@DisplayName("deadline stamp")
	class Deadline
	{
		private Instant boundary(RepeatPeriod period, java.time.LocalDate from)
		{
			return RepeatSchedule.nextBoundary(period,
				from.atTime(12, 0).atZone(ZoneOffset.UTC).toInstant(), ZoneOffset.UTC, 0);
		}

		@Test
		@DisplayName("a daily shows only a clock time")
		void daily()
		{
			assertEquals("00:00", RepeatSchedule.formatDeadline(
				boundary(RepeatPeriod.DAILY, LocalDate.of(2026, 7, 29)),
				ZoneOffset.UTC, RepeatPeriod.DAILY));
		}

		@Test
		@DisplayName("a weekly names the day it is due")
		void weekly()
		{
			assertEquals("Wed 00:00", RepeatSchedule.formatDeadline(
				boundary(RepeatPeriod.WEEKLY, LocalDate.of(2026, 7, 30)),
				ZoneOffset.UTC, RepeatPeriod.WEEKLY));
		}

		@Test
		@DisplayName("a monthly gives the date, since a weekday would be useless a month out")
		void monthly()
		{
			assertEquals("1 Aug", RepeatSchedule.formatDeadline(
				boundary(RepeatPeriod.MONTHLY, LocalDate.of(2026, 7, 31)),
				ZoneOffset.UTC, RepeatPeriod.MONTHLY));
		}

		@Test
		@DisplayName("a custom boundary hour is reflected, not assumed to be midnight")
		void customHour()
		{
			Instant now = LocalDate.of(2026, 7, 29).atTime(12, 0).atZone(ZoneOffset.UTC).toInstant();
			Instant b = RepeatSchedule.nextBoundary(RepeatPeriod.DAILY, now, ZoneOffset.UTC, 18);
			assertEquals("18:00",
				RepeatSchedule.formatDeadline(b, ZoneOffset.UTC, RepeatPeriod.DAILY));
		}

		@Test
		@DisplayName("a non-repeating goal has no deadline")
		void none()
		{
			assertEquals("", RepeatSchedule.formatDeadline(
				Instant.now(), ZoneOffset.UTC, RepeatPeriod.NONE));
			assertEquals("", RepeatSchedule.formatDeadline(null, ZoneOffset.UTC, RepeatPeriod.DAILY));
		}

		@Test
		@DisplayName("output is ASCII only")
		void ascii()
		{
			for (RepeatPeriod p : new RepeatPeriod[]{
				RepeatPeriod.DAILY, RepeatPeriod.WEEKLY, RepeatPeriod.MONTHLY})
			{
				String out = RepeatSchedule.formatDeadline(
					boundary(p, LocalDate.of(2026, 7, 29)), ZoneOffset.UTC, p);
				assertTrue(out.chars().allMatch(c -> c < 128), "non-ASCII: " + out);
			}
		}
	}

	@Nested
	@DisplayName("deadline stamp zone")
	class DeadlineZone
	{
		/**
		 * The bug behind "the resets timer seems wrong": a bare clock time reads
		 * as local, so rendering a UTC-defined boundary in UTC told a western
		 * player "00:00" when their day actually rolls at 17:00 or 20:00. The
		 * instant is identical - only the display zone was wrong.
		 */
		@Test
		@DisplayName("the same boundary shows a different clock time per zone")
		void zoneChangesTheClock()
		{
			Instant midnightUtc = LocalDate.of(2026, 8, 8)
				.atStartOfDay(ZoneOffset.UTC).toInstant();

			assertEquals("00:00", RepeatSchedule.formatDeadline(
				midnightUtc, ZoneOffset.UTC, RepeatPeriod.DAILY));
			assertEquals("20:00", RepeatSchedule.formatDeadline(
				midnightUtc, NEW_YORK, RepeatPeriod.DAILY),
				"a New York player's daily returns at 20:00, not 00:00");
		}
	}
}

package com.goalplanner.util;

import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicLong;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Exercises the deferral state machine that keeps goal prereq seeding
 * from reading the unsynced (default level-1) skill cache right after
 * login. Uses an injectable clock + logged-in flag so timing is exact.
 */
public class SkillSyncGateTest
{
	private final AtomicBoolean loggedIn = new AtomicBoolean(true);
	private final AtomicLong now = new AtomicLong(0);

	/** settleTicks=1, fallback=5000ms — production config. */
	private SkillSyncGate newGate()
	{
		return new SkillSyncGate(loggedIn::get, now::get, 1, 5_000);
	}

	@Test
	public void queuesActionWhileSkillCacheUnsyncedAfterLogin()
	{
		SkillSyncGate gate = newGate();
		gate.onLogin();   // stat block not yet arrived

		AtomicInteger ran = new AtomicInteger();
		gate.runWhenSynced(ran::incrementAndGet);

		assertFalse("not synced before the stat burst", gate.isSynced());
		assertEquals("action deferred, not run", 0, ran.get());
		assertEquals(1, gate.pendingCount());
	}

	@Test
	public void drainsQueuedActionOnceStatBurstSettles()
	{
		SkillSyncGate gate = newGate();
		gate.onLogin();

		AtomicInteger ran = new AtomicInteger();
		gate.runWhenSynced(ran::incrementAndGet);

		gate.onStatChanged();          // burst arrives
		assertFalse("still bursting on the same tick", gate.isSynced());
		assertEquals(0, ran.get());

		gate.onTick();                 // one quiet tick = settled
		assertTrue(gate.isSynced());
		assertEquals("deferred action runs on the settling tick", 1, ran.get());
		assertEquals(0, gate.pendingCount());
	}

	@Test
	public void runsImmediatelyWhenAlreadySynced()
	{
		SkillSyncGate gate = newGate();
		gate.onLogin();
		gate.onStatChanged();
		gate.onTick();                 // now synced

		AtomicInteger ran = new AtomicInteger();
		gate.runWhenSynced(ran::incrementAndGet);
		assertEquals("steady-state add runs without queuing", 1, ran.get());
		assertEquals(0, gate.pendingCount());
	}

	@Test
	public void anEmptyTickBeforeTheBurstDoesNotSatisfySync()
	{
		SkillSyncGate gate = newGate();
		gate.onLogin();
		gate.onTick();                 // tick with no stat yet
		assertFalse("a quiet tick before any StatChanged is not 'settled'", gate.isSynced());
	}

	@Test
	public void aLateStatChangedResetsTheSettleWindow()
	{
		SkillSyncGate gate = newGate();
		gate.onLogin();
		gate.onStatChanged();
		gate.onTick();                 // settled
		assertTrue(gate.isSynced());

		// A trailing stat update (e.g. a skill that synced a tick later)
		// re-opens the window until the next quiet tick.
		gate.onStatChanged();
		assertFalse("trailing stat re-opens the window", gate.isSynced());
		gate.onTick();
		assertTrue(gate.isSynced());
	}

	@Test
	public void fallbackDrainsWhenNoStatChangedEverArrives()
	{
		SkillSyncGate gate = newGate();
		gate.onLogin();                // fallbackAt = 5000

		AtomicInteger ran = new AtomicInteger();
		gate.runWhenSynced(ran::incrementAndGet);

		now.set(4_999);
		gate.onTick();
		assertEquals("before fallback deadline: still queued", 0, ran.get());

		now.set(5_000);
		gate.onTick();
		assertTrue("fallback considers skills synced", gate.isSynced());
		assertEquals("fallback drains the queue", 1, ran.get());
	}

	@Test
	public void neverSyncedWhileLoggedOut()
	{
		SkillSyncGate gate = newGate();
		gate.onLogin();
		gate.onStatChanged();
		gate.onTick();
		assertTrue(gate.isSynced());

		loggedIn.set(false);
		assertFalse("logged out is never synced", gate.isSynced());
	}

	@Test
	public void logoutDropsPendingSoItCannotSeedIntoAnotherProfile()
	{
		SkillSyncGate gate = newGate();
		gate.onLogin();

		AtomicInteger ran = new AtomicInteger();
		gate.runWhenSynced(ran::incrementAndGet);
		assertEquals(1, gate.pendingCount());

		gate.onLogout();
		assertEquals("queue cleared on logout", 0, gate.pendingCount());

		// A fresh login + sync must not resurrect the dropped action.
		gate.onLogin();
		gate.onStatChanged();
		gate.onTick();
		assertEquals("dropped action never runs", 0, ran.get());
	}

	@Test
	public void reloginReArmsTheGate()
	{
		SkillSyncGate gate = newGate();
		gate.onLogin();
		gate.onStatChanged();
		gate.onTick();
		assertTrue(gate.isSynced());

		gate.onLogout();
		loggedIn.set(true);
		gate.onLogin();                // new login: must re-sync
		assertFalse("re-login requires a fresh stat burst", gate.isSynced());

		gate.onStatChanged();
		gate.onTick();
		assertTrue(gate.isSynced());
	}

	@Test
	public void reEntrantAddDuringDrainRunsImmediatelyWhenSynced()
	{
		SkillSyncGate gate = newGate();
		gate.onLogin();

		AtomicInteger inner = new AtomicInteger();
		// A deferred action that itself adds a follow-on action (e.g. a
		// seed that triggers another add). By the time the outer runs we
		// are synced, so the inner add runs immediately rather than being
		// stranded — and iterating a snapshot keeps that safe.
		gate.runWhenSynced(() -> gate.runWhenSynced(inner::incrementAndGet));

		gate.onStatChanged();
		gate.onTick();

		assertEquals("re-entrant add runs in the same drain", 1, inner.get());
		assertEquals(0, gate.pendingCount());
	}

	@Test
	public void nullActionIsANoOp()
	{
		SkillSyncGate gate = newGate();
		gate.onLogin();
		gate.runWhenSynced(null);
		assertEquals(0, gate.pendingCount());
	}
